<?php
/**
 * Software CRM — Final Production Mobile Interface
 * Visual Specification: Attached Reference Image (Screens 1 to 10 Mobile Specification)
 * Stack: PHP 8.x PDO + MySQL (pocket_crm_db / u213657911_crm) + Alpine.js + Tailwind CSS
 * Security: Server-side Session Authorization + Mandatory 6-Digit Email OTP
 */

ini_set('display_errors', '0');
error_reporting(E_ALL);

header('X-Powered-By: Software-CRM-Mobile');
header('X-Frame-Options: SAMEORIGIN');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');

require_once __DIR__ . '/api/session_guard.php';
require_once __DIR__ . '/api/db.php';

$pdo = Database::getConnection();
$db_engine = Database::getEngine();
$db_connected = ($pdo !== null);

$isAuthenticated = SessionGuard::isAuthenticated();
$currentUser = null;

if ($isAuthenticated && $pdo) {
    $sessUser = SessionGuard::getUser();
    if (!empty($sessUser['id'])) {
        $uStmt = $pdo->prepare("SELECT `id`, `name`, `email`, `role`, `status`, `avatar_url` FROM `crm_users` WHERE `id` = ? LIMIT 1");
        $uStmt->execute([(int)$sessUser['id']]);
        $freshUser = $uStmt->fetch();
        if ($freshUser && $freshUser['status'] === 'active') {
            $_SESSION['auth_user'] = [
                'id'         => (int)$freshUser['id'],
                'name'       => $freshUser['name'],
                'email'      => $freshUser['email'],
                'role'       => $freshUser['role'],
                'avatar_url' => $freshUser['avatar_url'] ?? null
            ];
            $currentUser = $_SESSION['auth_user'];

            // Fetch authenticated user's persisted theme preference
            try {
                $tStmt = $pdo->prepare("SELECT `theme` FROM `crm_user_settings` WHERE `user_id` = ? LIMIT 1");
                $tStmt->execute([(int)$freshUser['id']]);
                $dbTheme = $tStmt->fetchColumn();
                if ($dbTheme && in_array($dbTheme, ['light', 'dark', 'system'], true)) {
                    $userThemePref = $dbTheme;
                } else {
                    $userThemePref = 'light';
                }
            } catch (Exception $e) {
                $userThemePref = 'light';
            }

            // Fetch authenticated user's initial notifications for instant zero-lag drawer display
            $userNotifications = [];
            $userUnreadCount = 0;
            try {
                $nStmt = $pdo->prepare("SELECT id, user_id, category, event_type, title, message, link_type, link_id, action_label, is_read, created_at FROM crm_notifications WHERE user_id = ? OR user_id = 0 ORDER BY id DESC LIMIT 20");
                $nStmt->execute([(int)$freshUser['id']]);
                $userNotifications = $nStmt->fetchAll(PDO::FETCH_ASSOC);
                foreach ($userNotifications as &$un) {
                    $un['is_read'] = (int)$un['is_read'];
                    $un['time_ago'] = '30m ago';
                    $un['formatted_date'] = 'Today';
                    if ($un['is_read'] === 0) $userUnreadCount++;
                }
                unset($un);
            } catch (Exception $e) {}
        } else {
            $_SESSION = [];
            session_destroy();
            $isAuthenticated = false;
        }
    }
}
if (isset($_GET['theme']) && in_array($_GET['theme'], ['light', 'dark', 'system'], true)) {
    $userThemePref = $_GET['theme'];
}
if (!isset($userThemePref)) {
    $userThemePref = 'light';
}

if (!function_exists('crmGetInitials')) {
    function crmGetInitials(?string $name): string {
        if (!$name) return 'U';
        $parts = preg_split('/\s+/', trim($name));
        if (empty($parts) || empty($parts[0])) return 'U';
        if (count($parts) === 1) return strtoupper(substr($parts[0], 0, 2));
        return strtoupper(substr($parts[0], 0, 1) . substr($parts[count($parts) - 1], 0, 1));
    }
}

$currentUserName = !empty($currentUser['name']) ? trim($currentUser['name']) : '';
$currentUserInitials = crmGetInitials($currentUserName);
$currentGreeting = $currentUserName !== '' ? "Good morning, {$currentUserName}!" : "Good morning!";
$csrfToken = SessionGuard::getCsrfToken();

// Explicit logout action via GET parameter
if (isset($_GET['logout'])) {
    $_SESSION = [];
    if (ini_get("session.use_cookies")) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params["path"], $params["domain"], $params["secure"], $params["httponly"]);
    }
    session_destroy();
    $isAuthenticated = false;
    $currentUser = null;
    header('Location: index.php?view=login#login');
    exit;
}

// Route Protection: Unauthenticated access to protected dashboard views redirects to login
$reqView = $_GET['view'] ?? '';
$protectedDashboardViews = ['dashboard', 'contacts', 'companies', 'projects', 'tasks', 'team', 'group_chart', 'invoices', 'reports', 'calendar', 'settings'];
if (!$isAuthenticated && in_array($reqView, $protectedDashboardViews, true)) {
    header('Location: index.php?view=login#login');
    exit;
}
