      --crm-btn-secondary-bg: #E9D5C2;
      --crm-btn-secondary-text: #651717;
      --crm-btn-secondary-hover: #D9C0AB;
      --crm-btn-tertiary-bg: #F1E7D9;
      --crm-btn-tertiary-text: #25211F;
      --crm-btn-tertiary-hover: #E9D5C2;

      /* Notification System Tokens (Light Theme) */
      --notification-bg: #FFFEFC;
      --notification-bg-read: #F8F4EC;
      --notification-title: #651717;
      --notification-text: #25211F;
      --notification-muted: #8A7D73;
      --notification-border: #E8DDD1;
      --notification-border-unread: #781B1B;
      --notification-drawer-bg: #FFFEFC;
      --notification-drawer-header-bg: #F8F4EC;
      --notification-drawer-body-bg: #F5EFE6;
      --notification-drawer-footer-bg: #FFFEFC;
      --notification-action-bg: #E9D5C2;
      --notification-action-hover-bg: #781B1B;
      --notification-action-text: #651717;
      --notification-action-hover-text: #FFFFFF;
      --notification-action-border: #D7C4B5;
      --notification-tab-inactive-bg: #FFFEFC;
      --notification-tab-inactive-text: #655A54;
      --notification-tab-inactive-border: #E8DDD1;
    }

    /* Design Tokens: Dark Theme (Rich dark base with burgundy, sage, and cream accents) */
    html.dark, html[data-theme="dark"] {
      color-scheme: dark;
      --color-warm-cream-beige: #E8D2B5;
      --color-muted-sage-grey: #A5A79B;
      --color-deep-burgundy: #8A1714;

      --crm-sage: #A5A79B;
      --crm-sage-hover: #8C8E82;
      --crm-cream: #E8D2B5;
      --crm-cream-hover: #DCBE97;
      --crm-burgundy: #8A1714;
      --crm-burgundy-hover: #A3201D;
      --crm-burgundy-active: #75110E;
      --crm-burgundy-light: #BF3936;
      --crm-burgundy-glow: rgba(138, 23, 20, 0.28);

      --crm-bg-body: #0E0708;
      --crm-bg-frame: #140A0C;
      --crm-bg-surface: #1A0F12;
      --crm-bg-surface-elevated: #241519;
      --crm-bg-subtle: #160C0E;
      --crm-bg-cream-accent: #221518;
      --crm-bg-sage-secondary: #1C191A;
      --crm-border-color: #382428;
      --crm-border-subtle: #29181C;
      --crm-border-sage: #4E5047;
      --crm-border-burgundy: #75110E;

      /* Typography & Metric Tokens (Dark Theme) */
      --crm-heading-color: #FAF6F0;
      --crm-metric-color: #E8D2B5;
      --crm-text-primary: #FAF6F0;
      --crm-text-secondary: #D8DBD2;
      --crm-text-muted: #A5A79B;
      --crm-input-bg: #160C0E;
      --crm-input-border: #382428;
      --crm-card-shadow: 0 4px 14px rgba(0, 0, 0, 0.55);

      /* Sidebar & Navigation (Dark Mode) */
      --crm-sidebar-bg: #100607;
      --crm-sidebar-border: #281014;
      --crm-sidebar-active-bg: #590907;
      --crm-sidebar-active-accent: #E8D2B5;
      --crm-sidebar-inactive: #A5A79B;
      --crm-sidebar-hover-bg: rgba(232, 210, 181, 0.15);
      --crm-sidebar-hover-text: #FAF6F0;

      /* Button Tokens (Dark Theme) */
      --crm-btn-primary-bg: #590907;
      --crm-btn-primary-text: #FFFFFF;
      --crm-btn-primary-hover: #75110E;
      --crm-btn-secondary-bg: #2A171A;
      --crm-btn-secondary-text: #E8D2B5;
      --crm-btn-secondary-hover: #381E23;
      --crm-btn-tertiary-bg: #2B2D29;
      --crm-btn-tertiary-text: #D8DBD2;
      --crm-btn-tertiary-hover: #3E413B;

      /* Notification System Tokens (Dark Theme) */
      --notification-bg: #1A0F12;
      --notification-bg-read: #130A0C;
      --notification-title: #FAF6F0;
      --notification-text: #D8DBD2;
      --notification-muted: #A5A79B;
      --notification-border: #382428;
      --notification-border-unread: #75110E;
      --notification-drawer-bg: #130A0C;
      --notification-drawer-header-bg: #180D10;
      --notification-drawer-body-bg: #0D0607;
      --notification-drawer-footer-bg: #130A0C;
      --notification-action-bg: #2A171A;
      --notification-action-hover-bg: #590907;
      --notification-action-text: #E8D2B5;
      --notification-action-hover-text: #FFFFFF;
      --notification-action-border: #382428;
      --notification-tab-inactive-bg: #1A0F12;
      --notification-tab-inactive-text: #D8DBD2;
      --notification-tab-inactive-border: #382428;
    }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      -webkit-font-smoothing: antialiased;
      -webkit-tap-highlight-color: transparent;
      user-select: none;
      background-color: var(--crm-bg-body);
      color: var(--crm-text-primary);
      transition: background-color 0.15s ease, color 0.15s ease;
    }

    #app-device-frame {
      background-color: var(--crm-bg-frame);
      transition: background-color 0.15s ease;
    }

    /* Dark Mode Core Components */
    html.dark body {
      background-color: var(--crm-bg-body) !important;
      color: var(--crm-text-primary) !important;
    }

    html.dark #app-device-frame {
      background-color: var(--crm-bg-frame) !important;
    }

    html.dark header {
      background-color: var(--crm-bg-surface) !important;
      border-color: var(--crm-border-color) !important;
      color: var(--crm-text-primary) !important;
    }

    html.dark nav {
      background-color: var(--crm-bg-surface) !important;
      border-color: var(--crm-border-color) !important;
    }

    html.dark main {
      background-color: var(--crm-bg-frame) !important;
    }

    /* Cards, Modals & Sheets */
    html.dark .bg-white,
    html.dark .bg-white\/90,
    html.dark .bg-white\/80 {
      background-color: var(--crm-bg-surface) !important;
      color: var(--crm-text-primary);
    }

    html.dark .bg-slate-50,
    html.dark .bg-slate-100 {
      background-color: var(--crm-bg-subtle) !important;
    }

    html.dark .bg-slate-50\/50,
    html.dark .bg-slate-50\/60,
    html.dark .bg-slate-50\/70,
    html.dark .bg-slate-100\/70,
    html.dark .bg-slate-100\/80 {
      background-color: var(--crm-bg-subtle) !important;
    }

    /* Borders in Dark Mode */
    html.dark .border-slate-100,
    html.dark .border-slate-200,
    html.dark .border-slate-200\/60,
    html.dark .border-slate-200\/80,
    html.dark .border-slate-300 {
      border-color: var(--crm-border-color) !important;
    }

    /* Typography in Dark Mode (High-contrast Warm Cream & Sage Palette) */
    html.dark .text-slate-900 {
      color: #FAF6F0 !important;
    }
    html.dark .text-slate-800 {
      color: #F5EFE5 !important;
    }
    html.dark .text-slate-700 {
      color: #D8DBD2 !important;
    }
    html.dark .text-slate-600 {
      color: #C0C4B7 !important;
    }
    html.dark .text-slate-500 {
      color: #A5A79B !important;
    }
    html.dark .text-slate-400 {
      color: #8C8E82 !important;
    }

    /* Form Controls in Dark Mode */
    html.dark input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]),
    html.dark select,
    html.dark textarea {
      background-color: var(--crm-input-bg) !important;
      border-color: var(--crm-input-border) !important;
      color: #FAF6F0 !important;
    }

    html.dark input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):focus,
    html.dark select:focus,
    html.dark textarea:focus {
      background-color: var(--crm-bg-surface-elevated) !important;
      border-color: #E8D2B5 !important;
      box-shadow: 0 0 0 3px rgba(232, 210, 181, 0.2) !important;
    }

    html.dark input::placeholder,
    html.dark textarea::placeholder {
      color: #716265 !important;
    }

    /* Modals & Popovers */
    html.dark .bg-white.rounded-3xl,
    html.dark .bg-white.rounded-2xl,
    html.dark .bg-white.rounded-t-3xl,
    html.dark .bg-white.rounded-xl {
      background-color: var(--crm-bg-surface) !important;
      border-color: var(--crm-border-color) !important;
      box-shadow: var(--crm-card-shadow) !important;
    }

    /* Status Badges */
    html.dark .bg-emerald-50,
    html.dark .bg-emerald-100 {
      background-color: rgba(16, 185, 129, 0.16) !important;
      color: #6ee7b7 !important;
      border-color: rgba(16, 185, 129, 0.3) !important;
    }

    html.dark .bg-amber-50,
    html.dark .bg-amber-100 {
      background-color: rgba(245, 158, 11, 0.16) !important;
      color: #fcd34d !important;
      border-color: rgba(245, 158, 11, 0.3) !important;
    }

    html.dark .bg-rose-50,
    html.dark .bg-rose-100 {
      background-color: rgba(89, 9, 7, 0.35) !important;
      color: #fda4af !important;
      border-color: rgba(89, 9, 7, 0.5) !important;
    }

    html.dark .bg-blue-50,
    html.dark .bg-blue-100 {
      background-color: rgba(89, 9, 7, 0.35) !important;
      color: #E8D2B5 !important;
      border-color: rgba(232, 210, 181, 0.25) !important;
    }

    /* Hover States in Dark Mode */
    html.dark .hover\:bg-slate-50:hover,
    html.dark .hover\:bg-slate-100:hover,
    html.dark .hover\:bg-slate-100\/70:hover {
      background-color: var(--crm-bg-surface-elevated) !important;
    }

    html.dark .hover\:bg-blue-50:hover,
    html.dark .hover\:bg-blue-50\/80:hover {
      background-color: rgba(89, 9, 7, 0.45) !important;
    }

    /* =========================================================================
       MASTER PALETTE COMPONENT DESIGN SYSTEM
       Primary Burgundy (#781B1B) | Warm Ivory (#F8F4EC) | Soft Champagne (#E9D5C2)
       ========================================================================= */

    /* 1. BUTTON DESIGN SYSTEM */
    /* Primary Buttons: Primary Burgundy (#781B1B) */
    .btn-primary,
    button.bg-blue-600,
    a.bg-blue-600,
    button[type="submit"]:not(.btn-secondary):not(.btn-tertiary):not(.bg-rose-600):not(.bg-emerald-600) {
      background-color: #781B1B !important;
      color: #FFFFFF !important;
      border: 1px solid rgba(120, 27, 27, 0.45) !important;
      box-shadow: 0 1px 3px rgba(120, 27, 27, 0.25) !important;
      transition: all 0.15s ease !important;
    }
    .btn-primary:hover,
    button.bg-blue-600:hover,
    a.bg-blue-600:hover,
    button[type="submit"]:not(.btn-secondary):not(.btn-tertiary):not(.bg-rose-600):not(.bg-emerald-600):hover {
      background-color: #922626 !important;
      color: #FFFFFF !important;
      box-shadow: 0 4px 12px rgba(120, 27, 27, 0.35) !important;
    }
    .btn-primary:active,
    button.bg-blue-600:active {
      background-color: #551414 !important;
      transform: scale(0.98);
    }
    .btn-primary:disabled,
    button.bg-blue-600:disabled {
      background-color: #8A7D73 !important;
      border-color: transparent !important;
      opacity: 0.6 !important;
    }

    /* Secondary Buttons: Soft Champagne (#E9D5C2) */
    .btn-secondary,
    .bg-blue-50,
    .bg-blue-100 {
      background-color: #E9D5C2 !important;
      color: #651717 !important;
      border: 1px solid #D7C4B5 !important;
      font-weight: 700 !important;
      transition: all 0.15s ease !important;
    }
    .btn-secondary:hover,
    .hover\:bg-blue-50:hover,
    .hover\:bg-blue-100:hover {
      background-color: #D9C0AB !important;
      color: #551414 !important;
      box-shadow: 0 2px 8px rgba(120, 27, 27, 0.12) !important;
    }

    /* Tertiary Buttons: Warm Neutral */
    .btn-tertiary,
    .badge-sage {
      background-color: #F1E7D9 !important;
      color: #25211F !important;
      border: 1px solid #E8DDD1 !important;
      font-weight: 600 !important;
      transition: all 0.15s ease !important;
    }
    .btn-tertiary:hover {
      background-color: #E9D5C2 !important;
      color: #25211F !important;
    }

    /* 2. SIDEBAR AND NAVIGATION */
    aside {
      background-color: var(--crm-sidebar-bg) !important;
      border-color: var(--crm-sidebar-border) !important;
      color: var(--crm-text-primary) !important;
    }
    aside .border-slate-800\/80 {
      border-color: var(--crm-sidebar-border) !important;
    }
    /* Inactive Navigation Elements */
    aside button:not(.bg-blue-600):not([class*="bg-blue-600"]),
    aside a:not(.bg-blue-600) {
      color: var(--crm-sidebar-inactive) !important;
      transition: all 0.15s ease !important;
    }
    aside button:not(.bg-blue-600) svg,
    aside a:not(.bg-blue-600) svg {
      color: var(--crm-text-muted) !important;
    }
    /* Hover Navigation Item: Warm Cream subtle background */
    aside button:not(.bg-blue-600):hover,
    aside a:not(.bg-blue-600):hover {
      background-color: var(--crm-sidebar-hover-bg) !important;
      color: var(--crm-sidebar-hover-text) !important;
    }
    aside button:not(.bg-blue-600):hover svg,
    aside a:not(.bg-blue-600):hover svg {
      color: #781B1B !important;
    }
    /* Active Navigation Item: Primary Burgundy (#781B1B) with Champagne (#E9D5C2) accent */
    aside button.bg-blue-600,
    aside button[class*="bg-blue-600"],
    aside a.bg-blue-600,
    #app-drawer-sidebar button.bg-blue-600 {
      background-color: #781B1B !important;
      color: #FFFFFF !important;
      border-left: 3.5px solid #E9D5C2 !important;
      box-shadow: 0 4px 12px rgba(120, 27, 27, 0.25) !important;
    }
    aside button.bg-blue-600 svg,
    aside button[class*="bg-blue-600"] svg,
    #app-drawer-sidebar button.bg-blue-600 svg {
      color: #E9D5C2 !important;
    }

    /* Mobile Bottom Navigation */
    nav.lg\:hidden {
      background-color: #FFFEFC !important;
      border-top-color: #E8DDD1 !important;
    }
    nav.lg\:hidden button.text-blue-600 {
      color: #781B1B !important;
    }
    html.dark nav.lg\:hidden button.text-blue-600 {
      color: #E9D5C2 !important;
    }
    nav.lg\:hidden button.text-slate-400 {
      color: #8A7D73 !important;
    }
    nav.lg\:hidden button:hover {
      color: #922626 !important;
    }

    /* 3. HEADINGS, ACTIVE TABS, METRICS & ACCENTS */
    .text-blue-600,
    .text-blue-700 {
      color: #781B1B !important;
    }
    .hover\:text-blue-700:hover,
    .hover\:text-blue-800:hover {
      color: #922626 !important;
    }
    html.dark .text-blue-600,
    html.dark .text-blue-700 {
      color: #E9D5C2 !important;
    }
    html.dark .hover\:text-blue-700:hover,
    html.dark .hover\:text-blue-800:hover {
      color: #FAF6F0 !important;
    }

    /* Primary Headings & Section Titles across all modules */
    h1, h2, h3, h4, h5,
    .crm-heading-fluid,
    .crm-brand-heading,
    .text-slate-900.font-black,
    .text-slate-900.font-extrabold,
    .text-slate-900.font-bold {
      color: var(--crm-heading-color) !important;
    }
    html.dark h1,
    html.dark h2,
    html.dark h3,
    html.dark h4,
    html.dark h5,
    html.dark .crm-heading-fluid,
    html.dark .crm-brand-heading,
    html.dark .text-slate-900.font-black,
    html.dark .text-slate-900.font-extrabold,
    html.dark .text-slate-900.font-bold {
      color: var(--crm-heading-color) !important;
    }

    /* Important Numbers and Dashboard Metrics */
    .metric-number,
    .text-2xl.font-black,
    .text-3xl.font-black,
    .text-4xl.font-black {
      color: var(--crm-metric-color) !important;
    }
    html.dark .metric-number,
    html.dark .text-2xl.font-black,
    html.dark .text-3xl.font-black,
    html.dark .text-4xl.font-black {
      color: var(--crm-metric-color) !important;
    }

    /* Cards, Highlighted Containers & Subtle Borders (Soft Border #E8DDD1) */
    .border-slate-200,
    .border-slate-200\/80,
    .border-slate-200\/90,
    .border-slate-200\/60,
    .border-slate-100 {
      border-color: #E8DDD1 !important;
    }
    .divide-slate-100 > :not([hidden]) ~ :not([hidden]),
    .divide-slate-200 > :not([hidden]) ~ :not([hidden]) {
      border-color: #EEE5DB !important;
    }

    /* Stronger Borders & Panels */
    .border-slate-300,
    .border-sage-accent {
      border-color: #D7C4B5 !important;
    }

    /* Cards with Subtle Shadows and Rounded Corners */
    .shadow-pocket,
    .shadow-card,
    .shadow-xs {
      box-shadow: 0 4px 20px -2px rgba(91, 20, 20, 0.08), 0 2px 6px -1px rgba(91, 20, 20, 0.04) !important;
    }

    html.dark .border-slate-100,
    html.dark .border-slate-200,
    html.dark .border-slate-200\/60,
    html.dark .border-slate-200\/80,
    html.dark .border-slate-200\/90,
    html.dark .border-slate-300 {
      border-color: var(--crm-border-color) !important;
    }
    html.dark .divide-slate-100 > :not([hidden]) ~ :not([hidden]),
    html.dark .divide-slate-200 > :not([hidden]) ~ :not([hidden]) {
      border-color: var(--crm-border-subtle) !important;
    }

    /* Active Selected Tabs (Projects, Contacts, Teams, Modals) */
    .border-blue-600 {
      border-color: #781B1B !important;
    }
    html.dark .border-blue-600 {
      border-color: #E9D5C2 !important;
    }

    /* Form Focus Rings */
    .focus\:border-blue-500:focus,
    .focus\:border-blue-600:focus {
      border-color: #781B1B !important;
    }
    .focus\:ring-blue-500\/20:focus,
    .focus\:ring-blue-600\/20:focus {
      --tw-ring-color: rgba(120, 27, 27, 0.22) !important;
    }
    input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):focus,
    select:focus,
    textarea:focus {
      border-color: #781B1B !important;
      outline: none !important;
      box-shadow: 0 0 0 3px rgba(120, 27, 27, 0.15) !important;
    }
    html.dark input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):focus,
    html.dark select:focus,
    html.dark textarea:focus {
      border-color: #E9D5C2 !important;
      box-shadow: 0 0 0 3px rgba(233, 213, 194, 0.20) !important;
    }
    input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):focus,
    select:focus,
    textarea:focus {
      border-color: #590907 !important;
      outline: none !important;
      box-shadow: 0 0 0 3px rgba(89, 9, 7, 0.15) !important;
    }
    html.dark input:not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):focus,
    html.dark select:focus,
    html.dark textarea:focus {
      border-color: #E8D2B5 !important;
      box-shadow: 0 0 0 3px rgba(232, 210, 181, 0.20) !important;
    }

    /* 4. TABLES AND DATA */
    table th {
      color: #57534E !important;
      border-color: var(--crm-border-color) !important;
      background-color: var(--crm-bg-subtle) !important;
      font-weight: 700 !important;
    }
    html.dark table th {
      color: #A5A79B !important;
    }
    table tr:hover td {
      background-color: rgba(232, 210, 181, 0.12) !important;
    }
    table td {
      border-color: var(--crm-border-color) !important;
    }

    html.dark .hover\:bg-rose-50:hover,
    html.dark .hover\:bg-rose-100\/70:hover {
      background-color: rgba(244, 63, 94, 0.22) !important;
    }

    /* Scrollbars in Dark Mode */
    html.dark ::-webkit-scrollbar-thumb {
      background: #334155;
    }
    html.dark ::-webkit-scrollbar-thumb:hover {
      background: #475569;
    }
    .no-scrollbar::-webkit-scrollbar { display: none; }
    .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
    .touch-press:active { transform: scale(0.97); transition: transform 0.06s ease; }
    
    ::-webkit-scrollbar { width: 4px; height: 4px; }
    ::-webkit-scrollbar-track { background: transparent; }
    ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 9999px; }

    /* Fluid Typography using clamp() */
    .crm-heading-fluid {
      font-size: clamp(1.125rem, 1.8vw + 0.5rem, 1.625rem);
      line-height: 1.25;
    }
    .crm-subheading-fluid {
      font-size: clamp(0.75rem, 0.8vw + 0.4rem, 0.875rem);
    }
    /* Safe table container & word wrapping */
    .crm-table-container {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      max-width: 100%;
    }
    .break-words-safe {
      overflow-wrap: anywhere;
      word-break: break-word;
    }

    /* =========================================================================
       NOTIFICATION SLIDE-OVER DRAWER & CARDS (ACCESSIBILITY & THEME COMPLIANCE)
       ========================================================================= */
    .crm-notification-panel {
      background-color: var(--notification-drawer-bg) !important;
      border-color: var(--notification-border) !important;
      color: var(--notification-title) !important;
    }

    .crm-notification-header {
      background-color: var(--notification-drawer-header-bg) !important;
      border-color: var(--notification-border) !important;
    }

    .crm-notification-body {
      background-color: var(--notification-drawer-body-bg) !important;
    }

    .crm-notification-footer {
      background-color: var(--notification-drawer-footer-bg) !important;
      border-color: var(--notification-border) !important;
    }

    /* Notification Cards (No opacity reduction on read cards) */
    .crm-notification-card {
      background-color: var(--notification-bg) !important;
      border: 1px solid var(--notification-border) !important;
      opacity: 1 !important;
      transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.08s ease;
    }

    .crm-notification-card.is-unread {
      background-color: var(--notification-bg) !important;
      border-color: var(--notification-border-unread) !important;
      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.05);
    }

    .crm-notification-card.is-read {
      background-color: var(--notification-bg-read) !important;
      border-color: var(--notification-border) !important;
      opacity: 1 !important;
