                  <rect class="crm-screen-bar-2" x="151" y="79" width="6" height="14" rx="1.5" fill="#E9D5C2"/>
                  <rect class="crm-screen-bar-3" x="161" y="69" width="6" height="24" rx="1.5" fill="#781B1B"/>
                  <rect class="crm-screen-bar-4" x="171" y="83" width="6" height="10" rx="1.5" fill="#551414"/>

