                  <!-- Dynamic Collaboration Wave / Connecting Line (Animated Flow) -->
                  <path class="crm-data-flow" d="M95 55 Q160 25 225 55" stroke="#781B1B" stroke-width="2" stroke-dasharray="6 4" fill="none" opacity="0.85"/>
                  <circle cx="160" cy="40" r="4" fill="#E9D5C2" stroke="#781B1B" stroke-width="1.5" class="crm-pulse-glow"/>

