              <span x-show="!sidebarCollapsed" class="whitespace-nowrap">Team</span>
            </button>

            <!-- 9b. Group Chart -->
            <button @click="navigateTo('group_chart')" 
              class="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all"
              :class="currentView === 'group_chart' ? 'bg-[#781B1B] text-white font-bold shadow-md shadow-[#781B1B]/20' : 'text-[#655A54] dark:text-[#D9C0AB] hover:bg-[#F1E7D9] dark:hover:bg-[#2B1317] hover:text-[#25211F] dark:hover:text-white'"
              :title="sidebarCollapsed ? 'Group Chart' : ''">
              <svg class="w-4 h-4 shrink-0" :class="currentView === 'group_chart' ? 'text-[#E9D5C2]' : 'text-[#8A7D73]'" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
              <span x-show="!sidebarCollapsed" class="whitespace-nowrap">Group Chart</span>
            </button>

            <!-- 10. Reports -->
            <button @click="navigateTo('reports')" 
              class="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all"
              :class="currentView === 'reports' ? 'bg-[#781B1B] text-white font-bold shadow-md shadow-[#781B1B]/20' : 'text-[#655A54] dark:text-[#D9C0AB] hover:bg-[#F1E7D9] dark:hover:bg-[#2B1317] hover:text-[#25211F] dark:hover:text-white'"
              :title="sidebarCollapsed ? 'Reports' : ''">
              <svg class="w-4 h-4 shrink-0" :class="currentView === 'reports' ? 'text-[#E9D5C2]' : 'text-[#8A7D73]'" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
              <span x-show="!sidebarCollapsed" class="whitespace-nowrap">Reports</span>
            </button>

            <!-- 11. Settings -->
            <button @click="navigateTo('settings')" 
              class="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all"
              :class="currentView === 'settings' ? 'bg-[#781B1B] text-white font-bold shadow-md shadow-[#781B1B]/20' : 'text-[#655A54] dark:text-[#D9C0AB] hover:bg-[#F1E7D9] dark:hover:bg-[#2B1317] hover:text-[#25211F] dark:hover:text-white'"
              :title="sidebarCollapsed ? 'Settings' : ''">
              <svg class="w-4 h-4 shrink-0" :class="currentView === 'settings' ? 'text-[#E9D5C2]' : 'text-[#8A7D73]'" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              <span x-show="!sidebarCollapsed" class="whitespace-nowrap">Settings</span>
            </button>

          </div>

          <!-- Sidebar Footer: Profile & Sign Out -->
          <div class="p-3 border-t border-[#E8DDD1] dark:border-[#2E1519] shrink-0 bg-[#F5EFE6] dark:bg-[#140708]">
            <div class="flex items-center justify-between text-xs">
              <div class="flex items-center gap-2.5 min-w-0 pr-1">
                <div class="w-8 h-8 rounded-full bg-[#781B1B] text-[#E9D5C2] flex items-center justify-center font-bold text-xs shrink-0 overflow-hidden ring-1 ring-[#D7C4B5]">
                  <template x-if="currentUser.avatar_url">
                    <img :src="currentUser.avatar_url" :alt="currentUser.name" class="w-full h-full object-cover rounded-full" />
                  </template>
                  <template x-if="!currentUser.avatar_url">
                    <span x-text="currentUser.initials || 'U'"><?= htmlspecialchars($currentUserInitials) ?></span>
                  </template>
                </div>
                <div class="min-w-0" x-show="!sidebarCollapsed">
                  <div class="font-bold text-[#25211F] dark:text-[#F8F4EC] truncate text-xs" x-text="currentUser.name || 'User'"><?= htmlspecialchars($currentUserName ?: 'User') ?></div>
                  <div class="text-[10px] text-[#655A54] dark:text-[#D9C0AB] truncate" x-text="currentUser.email || ''"><?= htmlspecialchars($currentUser['email'] ?? '') ?></div>
                </div>
              </div>
              <button @click="logout()" class="text-[#B42323] hover:text-[#781B1B] font-bold p-1 rounded-lg hover:bg-[#F1E7D9] dark:hover:bg-[#2B1317] transition touch-press shrink-0" :title="sidebarCollapsed ? 'Sign Out' : ''">
                <span x-show="!sidebarCollapsed" class="hover:underline">Sign Out</span>
                <svg x-show="sidebarCollapsed" class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
              </button>
            </div>
          </div>

        </aside>

        <!-- ===================================================================
             2. RIGHT CONTENT COLUMN (Header + Main Canvas + Mobile Bottom Nav)
             =================================================================== -->
        <div class="flex-1 flex flex-col h-full min-w-0 overflow-hidden relative bg-[#F8F4EC] dark:bg-[#140708]">

        <!-- ===================================================================
             TOP HEADER BAR (Responsive: Desktop, Laptop, Tablet, Mobile)
             =================================================================== -->
        <header class="h-14 sm:h-16 bg-white border-b border-slate-200/80 px-4 sm:px-6 flex items-center justify-between shrink-0 z-20 shadow-xs">
          
          <!-- Left: Desktop Toggle / Mobile Hamburger / Back Button / Title -->
          <div class="flex items-center gap-2.5">
            <!-- Desktop Sidebar Collapse Toggle Button -->
            <button @click="toggleSidebar()" class="hidden lg:flex p-1.5 rounded-lg text-slate-500 hover:text-slate-800 hover:bg-slate-100 transition touch-press" :title="sidebarCollapsed ? 'Expand Sidebar' : 'Collapse Sidebar'">
              <svg class="w-5 h-5 transition-transform duration-200" :class="sidebarCollapsed ? 'rotate-180' : ''" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 12h16M4 18h7"/></svg>
            </button>

            <!-- Bulk mode cancel button (Screen 7) -->
            <template x-if="bulkMode">
              <button @click="exitBulkMode()" class="p-1 text-slate-600 hover:text-slate-900 touch-press text-lg font-bold" title="Close Selection">
                &times;
              </button>
            </template>

            <!-- Standard Hamburger Menu (hidden on desktop lg+) -->
            <template x-if="!bulkMode && currentView !== 'contact_detail' && currentView !== 'project_detail' && currentView !== 'task_detail' && currentView !== 'task_add' && currentView !== 'task_edit' && currentView !== 'team_detail' && currentView !== 'company_detail' && currentView !== 'invoice_detail' && currentView !== 'payment_receipt'">
              <button @click="sideDrawerOpen = true" class="lg:hidden p-1 text-slate-600 hover:text-slate-900 touch-press" title="Menu">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M4 6h16M4 12h16M4 18h16"/></svg>
              </button>
            </template>

            <!-- Company Detail Back -->
            <template x-if="!bulkMode && currentView === 'company_detail'">
              <button @click="navigateTo('companies')" class="p-1 text-slate-600 hover:text-slate-900 touch-press" title="Back to Companies">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Contact Detail Back -->
            <template x-if="!bulkMode && currentView === 'contact_detail'">
              <button @click="contactReturnView === 'company_detail' ? (navigateTo('company_detail'), contactReturnView = 'contacts') : navigateTo('contacts')" class="p-1 text-slate-600 hover:text-slate-900 touch-press" title="Back">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Project Detail Back -->
            <template x-if="!bulkMode && currentView === 'project_detail'">
              <button @click="navigateTo('projects')" class="p-1 text-blue-600 hover:text-blue-800 touch-press" title="Back to Projects">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Task Detail / Add / Edit Back -->
            <template x-if="!bulkMode && (currentView === 'task_detail' || currentView === 'task_add' || currentView === 'task_edit')">
              <button @click="taskReturnView === 'project_detail' ? (navigateTo('project_detail'), projectDetailTab = 'tasks') : navigateTo('tasks')" class="p-1 text-slate-600 hover:text-slate-900 touch-press" title="Back">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Team Member Detail Back (Screen 2 Reference) -->
            <template x-if="!bulkMode && currentView === 'team_detail'">
              <button @click="teamMemberReturnView === 'project_detail' ? (navigateTo('project_detail'), projectDetailTab = 'team') : navigateTo('team')" class="p-1 text-blue-600 hover:text-blue-800 touch-press" title="Back">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Invoice Detail Back (Screen 2 Reference) -->
            <template x-if="!bulkMode && currentView === 'invoice_detail'">
              <button @click="navigateTo('invoices')" class="p-1 text-slate-600 hover:text-slate-900 touch-press" title="Back to Invoices">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Payment Receipt Back (Screen 3 Reference) -->
            <template x-if="!bulkMode && currentView === 'payment_receipt'">
              <button @click="activeInvoice ? navigateTo('invoice_detail') : navigateTo('invoices')" class="p-1 text-slate-600 hover:text-slate-900 touch-press" title="Back">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              </button>
            </template>

            <!-- Screen Title or Logo -->
            <template x-if="bulkMode">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight"><span x-text="selectedTaskIds.length + ' selected'"></span></h1>
            </template>

            <template x-if="!bulkMode && currentView === 'dashboard'">
              <div class="flex items-center gap-2">
                <div class="w-7 h-7 rounded-lg bg-[#590907]/10 dark:bg-[#590907]/30 border border-[#E8D2B5]/30 flex items-center justify-center text-[#590907] dark:text-[#E8D2B5]">
                  <svg class="w-4 h-4" viewBox="0 0 28 28" fill="none">
                    <rect x="4" y="14" width="4" height="10" rx="1.5" fill="#A5A79B"/>
                    <rect x="12" y="8" width="4" height="16" rx="1.5" fill="#E8D2B5"/>
                    <rect x="20" y="3" width="4" height="21" rx="1.5" fill="#590907"/>
                  </svg>
                </div>
                <span class="text-sm font-extrabold text-slate-900 tracking-tight">Software CRM</span>
              </div>
            </template>

            <template x-if="!bulkMode && currentView === 'project_detail'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Project Details</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'task_detail'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Task Details</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'task_add'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Add Task</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'task_edit'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Edit Task</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'team_detail'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Member Details</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'invoices'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Invoices</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'invoice_detail'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Invoice Details</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'payment_receipt'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Payment Receipt</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'company_detail'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Company Details</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'companies'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Companies</h1>
            </template>

            <template x-if="!bulkMode && currentView === 'group_chart'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight">Group Chart</h1>
            </template>

            <template x-if="!bulkMode && currentView !== 'dashboard' && currentView !== 'contact_detail' && currentView !== 'project_detail' && currentView !== 'task_detail' && currentView !== 'task_add' && currentView !== 'task_edit' && currentView !== 'team_detail' && currentView !== 'invoices' && currentView !== 'invoice_detail' && currentView !== 'payment_receipt' && currentView !== 'companies' && currentView !== 'company_detail' && currentView !== 'group_chart'">
              <h1 class="text-base font-extrabold text-slate-900 tracking-tight capitalize" x-text="currentView"></h1>
            </template>
          </div>

          <!-- Right: Contextual Actions -->
          <div class="flex items-center gap-2">
            <!-- Bulk mode cancel button (Screen 7) -->
            <template x-if="bulkMode">
              <button @click="exitBulkMode()" class="text-xs font-bold text-blue-600 hover:text-blue-800 touch-press px-1">
                Cancel
              </button>
            </template>

            <!-- Screen 2 / Dashboard Header Right: Bell + Avatar -->
            <template x-if="!bulkMode && currentView === 'dashboard'">
              <div class="flex items-center gap-2.5">
                <button @click="openNotificationsModal()" class="w-8 h-8 rounded-full bg-slate-50 border border-slate-200 flex items-center justify-center text-slate-600 relative touch-press hover:bg-slate-100 hover:text-slate-900 transition-colors" title="Notifications">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
                  <template x-if="unreadNotificationsCount > 0">
                    <span class="absolute -top-1 -right-1 min-w-[17px] h-[17px] px-1 rounded-full bg-rose-500 text-white font-extrabold text-[9px] flex items-center justify-center ring-2 ring-white leading-none shadow-xs" x-text="unreadNotificationsCount > 99 ? '99+' : unreadNotificationsCount"></span>
                  </template>
                </button>
                <button @click="sideDrawerOpen = true" class="w-8 h-8 rounded-full bg-[#590907] text-[#FAF6F0] flex items-center justify-center font-bold text-xs ring-2 ring-[#E8D2B5]/40 touch-press overflow-hidden">
                  <template x-if="currentUser.avatar_url">
                    <img :src="currentUser.avatar_url" :alt="currentUser.name" class="w-full h-full object-cover rounded-full" />
                  </template>
                  <template x-if="!currentUser.avatar_url">
                    <span x-text="currentUser.initials || 'U'"><?= htmlspecialchars($currentUserInitials) ?></span>
                  </template>
                </button>
              </div>
            </template>

            <!-- Screens: Circular Blue (+) Button -->
            <template x-if="!bulkMode && (currentView === 'contacts' || currentView === 'projects' || currentView === 'tasks' || currentView === 'calendar' || currentView === 'team' || currentView === 'companies')">
              <button @click="triggerHeaderPlusAction()" class="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center font-extrabold text-sm shadow-md shadow-blue-500/30 touch-press" title="Add New">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.8" d="M12 4v16m8-8H4"/></svg>
              </button>
            </template>

            <!-- Company Detail Action Menu / Quick Edit -->
            <template x-if="!bulkMode && currentView === 'company_detail'">
              <div class="flex items-center gap-1.5">
                <button @click="openEditCompanyModal(activeCompany)" class="w-8 h-8 rounded-full bg-slate-50 border border-slate-200 flex items-center justify-center text-slate-600 hover:text-blue-600 touch-press" title="Edit Company">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                </button>
              </div>
            </template>

            <!-- Screen 1: + New Invoice Button (Screen 1 Reference) -->
            <template x-if="!bulkMode && currentView === 'invoices'">
              <button @click="openAddInvoiceModal()" class="px-3.5 py-1.5 rounded-full bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-md shadow-blue-500/20 flex items-center gap-1.5 touch-press">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.8" d="M12 4v16m8-8H4"/></svg>
                <span>New Invoice</span>
              </button>
            </template>

            <!-- Screen 2 & 3: Three dots menu (Screens 2 & 3 Reference) -->
            <template x-if="!bulkMode && (currentView === 'invoice_detail' || currentView === 'payment_receipt')">
              <button @click="openInvoiceActionMenu(activeInvoice)" class="p-1.5 text-slate-500 hover:text-slate-800 touch-press">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
              </button>
            </template>

            <!-- Screen 4: Contact detail: Add Member, Delete Member & Three dots menu -->
            <template x-if="!bulkMode && currentView === 'contact_detail'">
              <div class="flex items-center gap-1 sm:gap-1.5">
                <!-- Add Member Button -->
                <button type="button" @click="openAddContactModal()" 
                  class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-xs flex items-center gap-1.5 touch-press transition" 
                  title="Add Member">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
                  <span class="text-[11px] font-bold">Add Member</span>
                </button>

                <!-- Delete Member Button -->
                <button type="button" @click="openDeleteContactModal(activeContact)" 
                  class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 border border-rose-200/80 font-bold text-xs flex items-center gap-1.5 touch-press transition" 
                  title="Delete Member">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                  <span class="text-[11px] font-bold">Delete</span>
                </button>

                <!-- Three dots action menu -->
                <button type="button" @click="openContactActionMenu(activeContact)" class="p-1.5 text-slate-500 hover:text-slate-800 touch-press rounded-lg" title="More Options">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                </button>
              </div>
            </template>

            <!-- Screen 5B: Project Details Three dots menu -->
            <template x-if="!bulkMode && currentView === 'project_detail'">
              <button @click="openProjectActionMenu(activeProject)" class="p-1.5 text-slate-500 hover:text-slate-800 touch-press" title="Project Actions">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
              </button>
            </template>

            <!-- Screen 3: Task Details Three dots menu (Matching Reference Image) -->
            <template x-if="!bulkMode && currentView === 'task_detail'">
              <button @click="openTaskActionMenu(activeTask)" class="p-1.5 text-slate-500 hover:text-slate-800 touch-press" title="Task Actions">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
              </button>
            </template>

            <!-- Screen 2: Team Member Details: Add Member, Delete Member & Three dots menu -->
            <template x-if="!bulkMode && currentView === 'team_detail'">
              <div class="flex items-center gap-1 sm:gap-1.5">
                <!-- Add Member Button -->
                <button type="button" @click="openAddTeamMemberModal()" 
                  class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-xs flex items-center gap-1.5 touch-press transition" 
                  title="Add Member">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
                  <span class="text-[11px] font-bold">Add Member</span>
                </button>

                <!-- Delete Member Button -->
                <button type="button" @click="deleteTeamMember(activeTeamMember)" 
                  class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 border border-rose-200/80 font-bold text-xs flex items-center gap-1.5 touch-press transition" 
                  title="Delete Member">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                  <span class="text-[11px] font-bold">Delete</span>
                </button>

                <!-- Three dots menu -->
                <button type="button" @click="openMemberActionMenu(activeTeamMember)" class="p-1.5 text-slate-500 hover:text-slate-800 touch-press rounded-lg" title="Member Actions">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                </button>
              </div>
            </template>
          </div>
        </header>


        <!-- ===================================================================
             SCREEN 10: MOBILE NAVIGATION MENU (DRAWER) (Exact Match Screen 10)
             =================================================================== -->
        <div x-show="sideDrawerOpen" class="fixed inset-0 z-50 flex lg:hidden" x-cloak>
          <!-- Backdrop -->
          <div @click="sideDrawerOpen = false" class="fixed inset-0 bg-slate-900/60 backdrop-blur-xs transition-opacity"></div>
          
          <!-- Dark Navy Drawer Panel (Exact Match Screen 10) -->
          <div class="relative w-64 max-w-[80%] bg-[#140708] text-white h-full flex flex-col justify-between p-4 shadow-drawer z-10 overflow-y-auto no-scrollbar border-r border-[#2B1114]">
            <div>
              <!-- Header with Brand & Close Button (✕) -->
              <div class="flex items-center justify-between pb-4 border-b border-[#2B1114]">
                <div class="flex items-center gap-2.5">
                  <div class="w-8 h-8 rounded-xl bg-[#590907]/30 border border-[#E8D2B5]/40 flex items-center justify-center text-[#E8D2B5] shadow-xs">
                    <svg class="w-5 h-5" viewBox="0 0 28 28" fill="none">
                      <rect x="4" y="14" width="4" height="10" rx="1.5" fill="#A5A79B"/>
                      <rect x="12" y="8" width="4" height="16" rx="1.5" fill="#E8D2B5"/>
                      <rect x="20" y="3" width="4" height="21" rx="1.5" fill="#590907"/>
                    </svg>
                  </div>
                  <span class="text-sm font-extrabold text-[#FAF6F0] tracking-tight">Software CRM</span>
                </div>
                <!-- ✕ Close Button -->
                <button @click="sideDrawerOpen = false" class="p-1 text-[#A5A79B] hover:text-white touch-press text-lg font-bold">
                  &times;
                </button>
              </div>

              <!-- Menu Items List (Exact Match Screen 10) -->
              <div class="mt-4 space-y-1 text-xs font-semibold">
                
                <!-- 1. Dashboard (Active Blue Pill) -->
                <button @click="navigateTo('dashboard'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'dashboard' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/></svg>
                  <span>Dashboard</span>
                </button>

                <!-- Notifications (Bell + Unread count) -->
                <button @click="openNotificationsModal(); sideDrawerOpen = false" 
                  class="w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl transition-all text-slate-400 hover:bg-slate-800 hover:text-white touch-press">
                  <div class="flex items-center gap-3">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
                    <span>Notifications</span>
                  </div>
                  <template x-if="unreadNotificationsCount > 0">
                    <span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-rose-500 text-white shadow-xs" x-text="unreadNotificationsCount > 99 ? '99+' : unreadNotificationsCount"></span>
                  </template>
                </button>

                <!-- 2. Contacts -->
                <button @click="navigateTo('contacts'); sideDrawerOpen = false" 
                  class="w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'contacts' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <div class="flex items-center gap-3">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                    <span>Contacts</span>
                  </div>
                  <span class="text-[10px] font-mono px-2 py-0.5 rounded-full bg-slate-800 text-slate-300" x-text="contacts.length">86</span>
                </button>

                <!-- 3. Companies -->
                <button @click="navigateTo('companies'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'companies' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                  <span>Companies</span>
                </button>

                <!-- 4. Projects -->
                <button @click="navigateTo('projects'); sideDrawerOpen = false" 
                  class="w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'projects' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <div class="flex items-center gap-3">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
                    <span>Projects</span>
                  </div>
                  <span class="text-[10px] font-mono px-2 py-0.5 rounded-full bg-slate-800 text-slate-300" x-text="projects.length">12</span>
                </button>

                <!-- 5. Tasks -->
                <button @click="navigateTo('tasks'); sideDrawerOpen = false" 
                  class="w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'tasks' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <div class="flex items-center gap-3">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                    <span>Tasks</span>
                  </div>
                  <span class="text-[10px] font-mono px-2 py-0.5 rounded-full bg-slate-800 text-slate-300" x-text="tasks.filter(t => !t.completed).length">8</span>
                </button>

                <!-- 6. Calendar -->
                <button @click="navigateTo('calendar'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'calendar' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                  <span>Calendar</span>
                </button>

                <!-- 7. Invoices -->
                <button @click="navigateTo('invoices'); sideDrawerOpen = false" 
                  class="w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'invoices' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <div class="flex items-center gap-3">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 14l6-6m-5.5.5h.01m4.99 5h.01M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16l3.5-2 3.5 2 3.5-2 3.5 2z"/></svg>
                    <span>Invoices</span>
                  </div>
                  <span class="text-[10px] font-mono px-2 py-0.5 rounded-full bg-slate-800 text-slate-300" x-text="invoices.length">15</span>
                </button>

                <!-- 8. Documents / Media Folders -->
                <button @click="openGlobalFolders(); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all text-slate-400 hover:bg-slate-800 hover:text-white">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                  <span>Documents & Folders</span>
                </button>

                <!-- 9. Team -->
                <button @click="navigateTo('team'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'team' || currentView === 'team_detail' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  <span>Team</span>
                </button>

                <!-- 9b. Group Chart -->
                <button @click="navigateTo('group_chart'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'group_chart' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
                  <span>Group Chart</span>
                </button>

                <!-- 10. Reports -->
                <button @click="navigateTo('reports'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all"
                  :class="currentView === 'reports' ? 'bg-blue-600 text-white font-bold shadow-sm' : 'text-slate-400 hover:bg-slate-800 hover:text-white'">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
                  <span>Reports</span>
                </button>

                <!-- 11. Settings -->
                <button @click="navigateTo('settings'); sideDrawerOpen = false" 
                  class="w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-all text-slate-400 hover:bg-slate-800 hover:text-white">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                  <span>Settings</span>
                </button>
              </div>
            </div>

            <!-- Footer: User & Sign Out -->
            <div class="pt-4 border-t border-slate-800 flex items-center justify-between text-xs">
              <div class="flex items-center gap-2.5 min-w-0 pr-2">
                <div class="w-8 h-8 rounded-full bg-slate-700 text-white flex items-center justify-center font-bold text-xs shrink-0 overflow-hidden ring-1 ring-slate-600">
                  <template x-if="currentUser.avatar_url">
                    <img :src="currentUser.avatar_url" :alt="currentUser.name" class="w-full h-full object-cover rounded-full" />
                  </template>
                  <template x-if="!currentUser.avatar_url">
                    <span x-text="currentUser.initials || 'U'"><?= htmlspecialchars($currentUserInitials) ?></span>
                  </template>
                </div>
                <div class="min-w-0">
                  <div class="font-bold text-white truncate" x-text="currentUser.name || 'User'"><?= htmlspecialchars($currentUserName ?: 'User') ?></div>
                  <div class="text-[10px] text-slate-400 truncate" x-text="currentUser.email || ''"><?= htmlspecialchars($currentUser['email'] ?? '') ?></div>
                </div>
              </div>
              <button @click="logout(); sideDrawerOpen = false" class="text-rose-400 font-bold hover:underline shrink-0">
                Sign Out
              </button>
            </div>
          </div>
        </div>


        <!-- =====================================================================
             MAIN SCROLLABLE CANVAS
             ===================================================================== -->
        <main class="flex-1 overflow-y-auto no-scrollbar p-3.5 sm:p-5 lg:p-6 space-y-4 sm:space-y-6 pb-20 lg:pb-8">
          <div class="max-w-7xl mx-auto w-full space-y-4 sm:space-y-6">

          <!-- ===================================================================
               SCREEN 2 & 9: MAIN DASHBOARD (Responsive)
               =================================================================== -->
          <div x-show="currentView === 'dashboard'" class="space-y-4 sm:space-y-6">
            
            <!-- Greeting & Subtitle (Exact Match Screen 2 & 9) -->
            <div>
              <h2 class="text-lg sm:text-xl font-extrabold text-slate-900 tracking-tight flex items-center gap-1.5 crm-heading-fluid">
                <span x-text="userGreeting()"><?= htmlspecialchars($currentGreeting) ?></span>
                <span class="inline-block animate-bounce">👋</span>
              </h2>
              <p class="text-xs sm:text-sm text-slate-500 font-medium mt-0.5 crm-subheading-fluid">Here's what's happening today</p>
            </div>

            <!-- 4 Metric KPI Cards (1-col mobile, 2-col tablet, 4-col laptop/desktop) -->
            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
              
              <!-- Card 1: Total Contacts -->
              <div @click="navigateTo('contacts')" class="p-4 bg-white dark:bg-[#1A0F12] rounded-2xl border border-[#E8D2B5]/80 dark:border-[#382428] shadow-pocket cursor-pointer touch-press hover:border-[#590907]/40 dark:hover:border-[#E8D2B5]/40 hover:shadow-md transition">
                <div class="flex items-center justify-between text-slate-400 dark:text-[#A5A79B] text-[11px] font-semibold">
                  <span>Total Contacts</span>
                  <div class="w-7 h-7 rounded-lg bg-[#E8D2B5]/50 text-[#590907] dark:bg-[#590907]/30 dark:text-[#E8D2B5] flex items-center justify-center font-bold">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  </div>
                </div>
                <div class="text-2xl sm:text-3xl font-black text-[#590907] dark:text-[#E8D2B5] mt-2" x-text="contacts.length">86</div>
                <div class="flex items-center gap-1 mt-1 text-[10px] font-bold text-emerald-600 dark:text-emerald-400">
                  <span>&uarr; +12%</span>
                </div>
              </div>

              <!-- Card 2: Active Projects -->
              <div @click="navigateTo('projects')" class="p-4 bg-white dark:bg-[#1A0F12] rounded-2xl border border-[#E8D2B5]/80 dark:border-[#382428] shadow-pocket cursor-pointer touch-press hover:border-[#590907]/40 dark:hover:border-[#E8D2B5]/40 hover:shadow-md transition">
                <div class="flex items-center justify-between text-slate-400 dark:text-[#A5A79B] text-[11px] font-semibold">
                  <span>Active Projects</span>
                  <div class="w-7 h-7 rounded-lg bg-[#A5A79B]/30 text-[#590907] dark:bg-[#A5A79B]/20 dark:text-[#E8D2B5] flex items-center justify-center font-bold">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
                  </div>
                </div>
                <div class="text-2xl sm:text-3xl font-black text-[#590907] dark:text-[#E8D2B5] mt-2" x-text="projects.length">12</div>
                <div class="flex items-center gap-1 mt-1 text-[10px] font-bold text-emerald-600 dark:text-emerald-400">
                  <span>&uarr; +20%</span>
                </div>
              </div>

              <!-- Card 3: Pending Tasks -->
              <div @click="navigateTo('tasks')" class="p-4 bg-white dark:bg-[#1A0F12] rounded-2xl border border-[#E8D2B5]/80 dark:border-[#382428] shadow-pocket cursor-pointer touch-press hover:border-[#590907]/40 dark:hover:border-[#E8D2B5]/40 hover:shadow-md transition">
                <div class="flex items-center justify-between text-slate-400 dark:text-[#A5A79B] text-[11px] font-semibold">
                  <span>Pending Tasks</span>
                  <div class="w-7 h-7 rounded-lg bg-[#E8D2B5]/50 text-[#590907] dark:bg-[#590907]/30 dark:text-[#E8D2B5] flex items-center justify-center font-bold">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                  </div>
                </div>
                <div class="text-2xl sm:text-3xl font-black text-[#590907] dark:text-[#E8D2B5] mt-2" x-text="tasks.filter(t => !t.completed).length">8</div>
                <div class="flex items-center gap-1 mt-1 text-[10px] font-bold text-rose-600 dark:text-rose-400">
                  <span>&darr; -14%</span>
                </div>
              </div>

              <!-- Card 4: Total Revenue -->
              <div @click="navigateTo('invoices')" class="p-4 bg-white dark:bg-[#1A0F12] rounded-2xl border border-[#E8D2B5]/80 dark:border-[#382428] shadow-pocket cursor-pointer touch-press hover:border-[#590907]/40 dark:hover:border-[#E8D2B5]/40 hover:shadow-md transition">
                <div class="flex items-center justify-between text-slate-400 dark:text-[#A5A79B] text-[11px] font-semibold">
                  <span>Total Revenue</span>
                  <div class="w-7 h-7 rounded-lg bg-[#A5A79B]/30 text-[#590907] dark:bg-[#A5A79B]/20 dark:text-[#E8D2B5] flex items-center justify-center font-bold">
                    $
                  </div>
                </div>
                <div class="text-2xl sm:text-3xl font-black text-[#590907] dark:text-[#E8D2B5] mt-2" x-text="'$' + (revenueTotal >= 1000 ? (revenueTotal / 1000).toFixed(1) + 'K' : revenueTotal)">$12,450</div>
                <div class="flex items-center gap-1 mt-1 text-[10px] font-bold text-emerald-600 dark:text-emerald-400">
                  <span>&uarr; +32%</span>
                </div>
              </div>

            </div>

            <!-- Dashboard 2-Column Responsive Row: Recent Activity & Upcoming Tasks -->
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6">

            <!-- Recent Activity Feed (Exact Match Screen 2 & 9) -->
            <div class="bg-gradient-to-b from-[#FAF6EE] to-white dark:from-[#221518] dark:to-[#1A0F12] rounded-2xl border border-[#E8D2B5]/80 dark:border-[#382428] p-4 shadow-pocket">
              <div class="flex items-center justify-between pb-3 border-b border-[#E8D2B5]/40 dark:border-[#29181C]">
                <h3 class="text-xs font-black text-[#590907] dark:text-[#FAF6F0]">Recent Activity</h3>
                <a href="#" @click.prevent="navigateTo('contacts')" class="text-[11px] font-bold text-[#590907] dark:text-[#E8D2B5] hover:underline">View All</a>
              </div>

              <div class="divide-y divide-[#E8D2B5]/30 dark:divide-[#29181C] mt-1">
                <!-- Activity 1 -->
                <div class="py-2.5 flex items-start justify-between gap-2.5">
                  <div class="flex items-center gap-2.5 min-w-0">
                    <div class="w-7 h-7 rounded-full bg-[#E8D2B5]/50 text-[#590907] dark:bg-[#590907]/30 dark:text-[#E8D2B5] flex items-center justify-center text-xs font-bold shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                    </div>
                    <div class="min-w-0">
                      <div class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">New contact added</div>
                      <div class="text-[11px] text-slate-500 dark:text-[#A5A79B] truncate">Rahul Sharma</div>
                    </div>
                  </div>
                  <span class="text-[10px] text-slate-400 dark:text-slate-500 font-semibold whitespace-nowrap">10 min ago</span>
                </div>

                <!-- Activity 2 -->
                <div class="py-2.5 flex items-start justify-between gap-2.5">
                  <div class="flex items-center gap-2.5 min-w-0">
                    <div class="w-7 h-7 rounded-full bg-[#A5A79B]/30 text-[#590907] dark:bg-[#A5A79B]/20 dark:text-[#E8D2B5] flex items-center justify-center text-xs font-bold shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
                    </div>
                    <div class="min-w-0">
                      <div class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">Project updated</div>
                      <div class="text-[11px] text-slate-500 dark:text-[#A5A79B] truncate">E-commerce Website</div>
                    </div>
                  </div>
                  <span class="text-[10px] text-slate-400 dark:text-slate-500 font-semibold whitespace-nowrap">1 hour ago</span>
                </div>

                <!-- Activity 3 -->
                <div class="py-2.5 flex items-start justify-between gap-2.5">
                  <div class="flex items-center gap-2.5 min-w-0">
                    <div class="w-7 h-7 rounded-full bg-[#E8D2B5]/50 text-[#590907] dark:bg-[#590907]/30 dark:text-[#E8D2B5] flex items-center justify-center text-xs font-bold shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 14l6-6m-5.5.5h.01m4.99 5h.01M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16l3.5-2 3.5 2 3.5-2 3.5 2z"/></svg>
                    </div>
                    <div class="min-w-0">
                      <div class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">Invoice created</div>
                      <div class="text-[11px] text-slate-500 dark:text-[#A5A79B] truncate">INV-2024-001</div>
                    </div>
                  </div>
                  <span class="text-[10px] text-slate-400 dark:text-slate-500 font-semibold whitespace-nowrap">3 hours ago</span>
                </div>
              </div>
            </div>

            <!-- Upcoming Tasks Widget -->
            <div class="bg-white dark:bg-[#1A0F12] rounded-2xl border border-[#A5A79B]/50 dark:border-[#382428] p-4 shadow-pocket">
              <div class="flex items-center justify-between pb-3 border-b border-[#A5A79B]/30 dark:border-[#29181C]">
                <h3 class="text-xs font-black text-[#590907] dark:text-[#FAF6F0]">Upcoming Tasks</h3>
                <button @click="openAddModal('task')" class="text-[11px] font-bold text-[#590907] dark:text-[#E8D2B5] hover:underline">+ Add</button>
              </div>
              <div class="divide-y divide-[#A5A79B]/20 dark:divide-[#29181C] mt-1">
                <template x-for="t in tasks.slice(0, 3)" :key="t.id">
                  <div class="py-2.5 flex items-center justify-between gap-2">
                    <div class="flex items-center gap-2.5 min-w-0">
                      <input type="checkbox" :checked="t.completed" @change="toggleTaskCompletion(t.id)" class="w-3.5 h-3.5 rounded text-[#590907] focus:ring-[#590907] cursor-pointer"/>
                      <span class="text-xs font-bold text-slate-800 dark:text-slate-200 truncate" :class="t.completed ? 'line-through text-slate-400 dark:text-slate-500' : ''" x-text="t.title"></span>
                    </div>
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold shrink-0" 
                      :class="t.priority === 'High' ? 'bg-[#590907]/10 text-[#590907] dark:bg-[#590907]/30 dark:text-[#E8D2B5]' : 'bg-[#E8D2B5]/50 text-[#590907] dark:bg-[#E8D2B5]/20 dark:text-[#E8D2B5]'" 
                      x-text="t.priority"></span>
                  </div>
                </template>
              </div>
            </div>

            </div> <!-- end grid-cols-2 -->

          </div>


          <!-- ===================================================================
               SCREEN 3: CONTACTS & CLIENTS LIST (Exact Match Screen 3)
               =================================================================== -->
          <div x-show="currentView === 'contacts'" class="space-y-3">
            
            <!-- Search & Filter Bar (Screen 1 Reference) -->
            <div class="flex items-center gap-2">
              <div class="relative flex-1">
                <span class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                </span>
                <input type="text" x-model="contactSearchQuery" placeholder="Search contacts..." 
                  class="w-full pl-8 pr-8 py-2 bg-white border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20 shadow-xs"/>
                <template x-if="contactSearchQuery">
                  <button @click="contactSearchQuery = ''" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400 hover:text-slate-600">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </template>
              </div>

              <!-- + Add Contact Button (Screen 1 Reference) -->
              <button @click="openAddContactModal()" class="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold shadow-xs flex items-center gap-1.5 touch-press shrink-0">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                <span>Add</span>
              </button>
            </div>

            <!-- Filter Pill Chips Row (Screen 1: All, Client, Lead, Prospect) -->
            <div class="flex items-center gap-1.5 overflow-x-auto no-scrollbar pb-1 text-xs font-bold">
              <button @click="contactFilter = 'all'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="contactFilter === 'all' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                All (<span x-text="contacts.length"></span>)
              </button>

              <button @click="contactFilter = 'Client'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="contactFilter.toLowerCase() === 'client' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                Client (<span x-text="contacts.filter(c => (c.category || '').toLowerCase() === 'client').length"></span>)
              </button>

              <button @click="contactFilter = 'Lead'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="contactFilter.toLowerCase() === 'lead' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                Lead (<span x-text="contacts.filter(c => (c.category || '').toLowerCase() === 'lead').length"></span>)
              </button>

              <button @click="contactFilter = 'Prospect'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="contactFilter.toLowerCase() === 'prospect' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                Prospect (<span x-text="contacts.filter(c => (c.category || '').toLowerCase() === 'prospect').length"></span>)
              </button>
            </div>

            <!-- Contacts Cards Feed (Responsive: 1-col mobile, 2-col tablet, 3-col desktop) -->
            <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3 space-y-0">
              <!-- Empty State -->
              <template x-if="filteredContacts.length === 0">
                <div class="p-8 bg-white rounded-2xl border border-slate-200 text-center space-y-3">
                  <div class="w-12 h-12 rounded-full bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                    <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  </div>
                  <div>
                    <h3 class="text-xs font-bold text-slate-800">No contacts found</h3>
                    <p class="text-[11px] text-slate-400 mt-0.5">Try a different search or filter, or create a new contact.</p>
                  </div>
                  <button @click="openAddContactModal()" class="px-4 py-2 bg-blue-600 text-white font-bold text-xs rounded-xl shadow-xs touch-press">
                    + Add New Contact
                  </button>
                </div>
              </template>

              <!-- Contact Cards List -->
              <template x-for="c in filteredContacts" :key="c.id">
                <div @click="viewContactDetail(c)" 
                  class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 transition touch-press">
                  
                  <div class="flex items-center gap-3 min-w-0">
                    <!-- Avatar circle with initials -->
                    <div class="w-10 h-10 rounded-full flex items-center justify-center font-extrabold text-xs shrink-0 uppercase"
                      :class="(c.category || '').toLowerCase() === 'client' ? 'bg-blue-100 text-blue-700' : ((c.category || '').toLowerCase() === 'lead' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700')"
                      x-text="(c.name || 'C').substring(0, 2)"></div>
                    <div class="min-w-0">
                      <div class="text-xs font-extrabold text-slate-900 truncate" x-text="c.name">Rahul Sharma</div>
                      <div class="text-[11px] text-slate-400 truncate mt-0.5" x-text="c.company || c.position || c.phone">ABC Tech Solutions</div>
                    </div>
                  </div>

                  <!-- Status Badge & 3-Dots Menu (Screen 1 & 4) -->
                  <div class="flex items-center gap-2 shrink-0">
                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-extrabold capitalize"
                      :class="(c.category || '').toLowerCase() === 'client' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : ((c.category || '').toLowerCase() === 'lead' ? 'bg-blue-50 text-blue-700 border border-blue-200/60' : 'bg-amber-50 text-amber-700 border border-amber-200/60')"
                      x-text="c.category || 'Client'">Client</span>

                    <button @click.stop="openContactOptionsMenu(c)" class="p-1 text-slate-400 hover:text-slate-700 touch-press rounded-lg" title="Contact Actions">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                    </button>
                  </div>

                </div>
              </template>
            </div>

          </div>

          <!-- ===================================================================
               SCREEN 4: CONTACT DETAIL VIEW (Exact Match Screen 4)
               =================================================================== -->
          <div x-show="currentView === 'contact_detail'" class="max-w-4xl mx-auto w-full space-y-4">
            
            <!-- Large Profile Banner Card (Screen 3 Reference) -->
            <div class="bg-white rounded-3xl border border-slate-200/80 p-5 shadow-pocket text-center">
              
              <!-- Large Avatar Circle -->
              <div class="w-20 h-20 rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 text-white flex items-center justify-center text-2xl font-bold uppercase mx-auto mb-3 shadow-lg shadow-blue-500/20"
                x-text="activeContact ? (activeContact.name || 'C').substring(0, 2) : 'RS'">
                RS
              </div>

              <!-- Name & Status Badge -->
              <div class="flex items-center justify-center gap-2">
                <h2 class="text-lg font-black text-slate-900" x-text="activeContact ? activeContact.name : 'Rahul Sharma'">Rahul Sharma</h2>
                <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold capitalize"
                  :class="activeContact && (activeContact.category || '').toLowerCase() === 'client' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : 'bg-blue-50 text-blue-700 border border-blue-200/60'"
                  x-text="activeContact ? (activeContact.category || 'Client') : 'Client'">Client</span>
              </div>
              <div class="text-xs font-semibold text-slate-500 mt-0.5" x-text="activeContact ? (activeContact.company || activeContact.position || 'Software Client') : 'ABC Tech Solutions'">ABC Tech Solutions</div>

              <!-- 4 Action Buttons Row: Call, WhatsApp, Email, More (Screen 3 & 4) -->
              <div class="grid grid-cols-4 gap-2 mt-5 pt-4 border-t border-slate-100">
                <!-- 1. Call -->
                <button @click="triggerCallAction(activeContact)" class="flex flex-col items-center gap-1.5 touch-press group">
                  <div class="w-11 h-11 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Call</span>
                </button>

                <!-- 2. WhatsApp -->
                <button @click="triggerWhatsAppAction(activeContact)" class="flex flex-col items-center gap-1.5 touch-press group">
                  <div class="w-11 h-11 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">WhatsApp</span>
                </button>

                <!-- 3. Email -->
                <button @click="triggerEmailAction(activeContact)" class="flex flex-col items-center gap-1.5 touch-press group">
                  <div class="w-11 h-11 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Email</span>
                </button>

                <!-- 4. More -->
                <button @click="openMoreActionsModal(activeContact)" class="flex flex-col items-center gap-1.5 touch-press group">
                  <div class="w-11 h-11 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 12h.01M12 12h.01M19 12h.01M6 12a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">More</span>
                </button>
              </div>

              <!-- 5 Tabs Row: Overview, History, Files, Projects, Invoices (Screen 3 Reference) -->
              <div class="flex items-center justify-between border-t border-slate-100 mt-5 pt-3 text-xs font-bold overflow-x-auto no-scrollbar">
                <button @click="contactDetailTab = 'overview'" class="pb-1.5 whitespace-nowrap" :class="contactDetailTab === 'overview' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">Overview</button>
                <button @click="contactDetailTab = 'history'" class="pb-1.5 whitespace-nowrap" :class="contactDetailTab === 'history' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">History</button>
                <button @click="contactDetailTab = 'media'; mediaViewLevel = 'projects';" class="pb-1.5 whitespace-nowrap" :class="contactDetailTab === 'media' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">Files</button>
                <button @click="contactDetailTab = 'projects'" class="pb-1.5 whitespace-nowrap" :class="contactDetailTab === 'projects' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">Projects</button>
                <button @click="contactDetailTab = 'invoices'" class="pb-1.5 whitespace-nowrap" :class="contactDetailTab === 'invoices' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">Invoices</button>
              </div>

            </div>

            <!-- TAB 1: OVERVIEW (Screen 3 Reference: About & Recent Activity) -->
            <div x-show="contactDetailTab === 'overview'" class="space-y-3.5">
              
              <!-- About Card (Screen 3 Reference) -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-2.5 text-xs">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                  <h3 class="font-extrabold text-slate-900">About</h3>
                  <button @click="openEditContact(activeContact)" class="text-blue-600 font-bold hover:underline flex items-center gap-1 touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                    <span>Edit</span>
                  </button>
                </div>

                <p class="text-slate-600 leading-relaxed text-xs" 
                  x-text="activeContact && activeContact.notes ? activeContact.notes : 'Key client for web development and digital marketing projects. Interested in long-term partnership.'"></p>

                <!-- Key-Value Table (Company, Position, Phone, Email, Location, Source, Tags) -->
                <div class="pt-2 border-t border-slate-100 space-y-2 text-[11px]">
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Company</span>
                    <span class="font-bold text-blue-600 hover:underline cursor-pointer touch-press" 
                      @click="if (activeContact && (activeContact.company || activeContact.company_id)) { const targetId = activeContact.company_id || (companies.find(k => k.name.toLowerCase() === (activeContact.company || '').toLowerCase()) || {}).id; if (targetId) { contactReturnView = 'contact_detail'; viewCompanyDetail(targetId); } else { showToast(activeContact.company || 'No company linked'); } }" 
                      x-text="activeContact ? (activeContact.company || '—') : '—'"></span>
                  </div>
                  <div class="flex justify-between items-center"><span class="text-slate-400 font-semibold">Position</span><span class="font-bold text-slate-900" x-text="activeContact ? (activeContact.position || activeContact.occupation || '—') : '—'"></span></div>
                  <div class="flex justify-between items-center"><span class="text-slate-400 font-semibold">Phone</span><span class="font-bold text-blue-600 font-mono cursor-pointer" @click="triggerCallAction(activeContact)" x-text="activeContact ? (activeContact.phone || '—') : '—'"></span></div>
                  <div class="flex justify-between items-center"><span class="text-slate-400 font-semibold">Email</span><span class="font-bold text-blue-600 cursor-pointer" @click="triggerEmailAction(activeContact)" x-text="activeContact ? (activeContact.email || '—') : '—'"></span></div>
                  <div class="flex justify-between items-center"><span class="text-slate-400 font-semibold">Location</span><span class="font-bold text-slate-900" x-text="activeContact ? (activeContact.location || activeContact.address || '—') : '—'"></span></div>
                  <div class="flex justify-between items-center"><span class="text-slate-400 font-semibold">Source</span><span class="font-bold text-slate-900" x-text="activeContact ? (activeContact.source || activeContact.lead_from || '—') : '—'"></span></div>
                  <div class="flex justify-between items-center pt-1">
                    <span class="text-slate-400 font-semibold">Tags</span>
                    <div class="flex items-center gap-1.5 flex-wrap justify-end">
                      <template x-for="t in getContactTags(activeContact)" :key="t">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-50 text-blue-600 border border-blue-200/60" x-text="t"></span>
                      </template>
                      <template x-if="!getContactTags(activeContact).length">
                        <span class="text-slate-400 text-[10px]">None</span>
                      </template>
                    </div>
                  </div>
                </div>
              </div>

              <!-- Recent Activity Card (Screen 3 Reference) -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-2">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                  <h3 class="font-extrabold text-slate-900 text-xs">Recent Activity</h3>
                  <button @click="contactDetailTab = 'history'" class="text-[11px] font-bold text-blue-600 hover:underline">View All</button>
                </div>
                <template x-if="activeContact && activeContact.history && activeContact.history.length > 0">
                  <div class="py-2 flex items-start justify-between gap-2.5">
                    <div class="flex items-center gap-2.5 min-w-0">
                      <div class="w-7 h-7 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center text-xs font-bold shrink-0">
                        &bull;
                      </div>
                      <div class="min-w-0">
                        <div class="text-xs font-bold text-slate-900 truncate" x-text="activeContact.history[0].staff || 'Staff interaction'"></div>
                        <div class="text-[11px] text-slate-400 truncate" x-text="activeContact.history[0].text || activeContact.history[0].note_text"></div>
                      </div>
                    </div>
                    <span class="text-[10px] text-slate-400 shrink-0" x-text="activeContact.history[0].time || 'Recent'"></span>
                  </div>
                </template>
                <template x-if="!activeContact || !activeContact.history || activeContact.history.length === 0">
                  <div class="text-[11px] text-slate-400 py-2">No recent activity recorded.</div>
                </template>
              </div>

            </div>

            <!-- TAB 2: HISTORY TIMELINE (Screen 7 Reference) -->
            <div x-show="contactDetailTab === 'history'" class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <span class="text-xs font-bold text-slate-900">Timeline & Interaction Log</span>
                <button @click="openLogNoteModal()" class="text-[11px] font-bold text-blue-600 hover:underline flex items-center gap-1 touch-press">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                  <span>Log Note</span>
                </button>
              </div>
              <div class="space-y-2">
                <template x-if="!activeContact || !activeContact.history || activeContact.history.length === 0">
                  <div class="p-6 text-center text-slate-400 text-xs">
                    No timeline notes recorded yet. Tap "+ Log Note" to add an interaction.
                  </div>
                </template>
                <template x-for="h in (activeContact ? activeContact.history : [])" :key="h.id">
                  <div class="p-3 rounded-xl bg-slate-50 border border-slate-100 text-xs space-y-1">
                    <div class="flex justify-between font-bold text-slate-800 text-[11px]">
                      <span x-text="h.staff || 'Staff'"></span>
                      <span class="text-slate-400 font-mono text-[10px]" x-text="h.time || h.date_str || 'Recent'"></span>
                    </div>
                    <p class="text-slate-600 leading-relaxed text-xs" x-text="h.text || h.note_text"></p>
                  </div>
                </template>
              </div>
            </div>

            <!-- TAB 3: 4-LEVEL FILES & ASSET FOLDERS (Screen 13 Reference) -->
            <div x-show="contactDetailTab === 'media'" class="space-y-3">
              
              <!-- LEVEL 1: PROJECT FOLDERS VIEW -->
              <div x-show="mediaViewLevel === 'projects'" class="space-y-2.5">
                <div class="flex items-center justify-between px-1">
                  <span class="text-xs font-extrabold text-slate-900">Project Media Folders</span>
                  <span class="text-[11px] text-blue-600 font-bold" x-text="getContactProjects(activeContact).length + ' Folders'"></span>
                </div>

                <div class="space-y-2">
                  <template x-for="(proj, pIdx) in getContactProjects(activeContact)" :key="proj.id || pIdx">
                    <div @click="openProjectFolder(proj)" 
                      class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 transition touch-press">
                      <div class="flex items-center gap-3">
                        <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-bold text-lg shrink-0">
                          📁
                        </div>
                        <div>
                          <div class="text-xs font-bold text-slate-900" x-text="proj.name">Project Folder</div>
                          <div class="text-[10px] text-slate-400 mt-0.5" x-text="(proj.versions ? proj.versions.length : 0) + ' Sub-folders / Versions'"></div>
                        </div>
                      </div>
                      <span class="text-slate-400 font-bold text-xs">&rarr;</span>
                    </div>
                  </template>
                </div>
              </div>

              <!-- LEVEL 2: VERSIONS / SUB-CATEGORY FOLDERS VIEW -->
              <div x-show="mediaViewLevel === 'versions' && selectedProject" class="space-y-2.5">
                <div class="p-2.5 bg-white rounded-xl border border-slate-200/80 shadow-xs flex items-center justify-between text-xs">
                  <button @click="goBackMedia()" class="font-bold text-blue-600 flex items-center gap-1 touch-press">
                    <span>&larr; Projects</span>
                  </button>
                  <span class="font-bold text-slate-800 truncate max-w-[180px]" x-text="selectedProject ? selectedProject.name : ''"></span>
                  <span class="text-[10px] text-slate-400">Step 2/4</span>
                </div>

                <div class="space-y-2">
                  <template x-if="selectedProject && selectedProject.versions">
                    <template x-for="(ver, vIdx) in selectedProject.versions" :key="ver.id || vIdx">
                      <div @click="openVersionFolder(ver)"
                        class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 transition touch-press">
                        <div class="flex items-center gap-3">
                          <div class="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-lg shrink-0">
                            📂
                          </div>
                          <div>
                            <div class="text-xs font-bold text-slate-900" x-text="ver.name">Version 2.0</div>
                            <div class="text-[10px] text-emerald-600 font-bold mt-0.5" x-text="ver.status || 'Active'">Active</div>
                          </div>
                        </div>
                        <span class="text-slate-400 font-bold text-xs">&rarr;</span>
                      </div>
                    </template>
                  </template>
                </div>
              </div>

              <!-- LEVEL 3: COMMON ASSET FOLDERS (Images, Videos, Notes, Design) -->
              <div x-show="mediaViewLevel === 'categories' && selectedVersion" class="space-y-2.5">
                <div class="p-2.5 bg-white rounded-xl border border-slate-200/80 shadow-xs flex items-center justify-between text-xs">
                  <button @click="goBackMedia()" class="font-bold text-blue-600 flex items-center gap-1 touch-press">
                    <span>&larr; Versions</span>
                  </button>
                  <span class="font-bold text-slate-800 truncate max-w-[180px]" x-text="selectedVersion ? selectedVersion.name : ''"></span>
                  <span class="text-[10px] text-slate-400">Step 3/4</span>
                </div>

                <div class="grid grid-cols-2 gap-2">
                  <div @click="openCategoryFolder('images')" class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket cursor-pointer hover:border-purple-400 transition touch-press text-center">
                    <div class="w-10 h-10 rounded-xl bg-purple-100 text-purple-600 flex items-center justify-center font-bold mx-auto mb-2 text-lg">🖼️</div>
                    <div class="text-xs font-bold text-slate-900">Images</div>
                    <div class="text-[10px] text-slate-400 mt-0.5" x-text="getCategoryFileCount('images') + ' Files'"></div>
                  </div>

                  <div @click="openCategoryFolder('videos')" class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket cursor-pointer hover:border-rose-400 transition touch-press text-center">
                    <div class="w-10 h-10 rounded-xl bg-rose-100 text-rose-600 flex items-center justify-center font-bold mx-auto mb-2 text-lg">🎥</div>
                    <div class="text-xs font-bold text-slate-900">Videos & Demos</div>
                    <div class="text-[10px] text-slate-400 mt-0.5" x-text="getCategoryFileCount('videos') + ' Files'"></div>
                  </div>

                  <div @click="openCategoryFolder('notes')" class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket cursor-pointer hover:border-blue-400 transition touch-press text-center">
                    <div class="w-10 h-10 rounded-xl bg-blue-100 text-blue-600 flex items-center justify-center font-bold mx-auto mb-2 text-lg">📝</div>
                    <div class="text-xs font-bold text-slate-900">Notes & Docs</div>
                    <div class="text-[10px] text-slate-400 mt-0.5" x-text="getCategoryFileCount('notes') + ' Files'"></div>
                  </div>

                  <div @click="openCategoryFolder('design')" class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket cursor-pointer hover:border-amber-400 transition touch-press text-center">
                    <div class="w-10 h-10 rounded-xl bg-amber-100 text-amber-600 flex items-center justify-center font-bold mx-auto mb-2 text-lg">🎨</div>
                    <div class="text-xs font-bold text-slate-900">Design Assets</div>
                    <div class="text-[10px] text-slate-400 mt-0.5" x-text="getCategoryFileCount('design') + ' Files'"></div>
                  </div>
                </div>
              </div>

              <!-- LEVEL 4: FILES LIST & VIEWER -->
              <div x-show="mediaViewLevel === 'files' && selectedCategory" class="space-y-2.5">
                <div class="p-2.5 bg-white rounded-xl border border-slate-200/80 shadow-xs flex items-center justify-between text-xs">
                  <button @click="goBackMedia()" class="font-bold text-blue-600 flex items-center gap-1 touch-press">
                    <span>&larr; Categories</span>
                  </button>
                  <span class="font-bold text-slate-800 capitalize truncate" x-text="selectedCategory"></span>
                  <label class="px-2.5 py-1 bg-blue-600 text-white rounded-lg text-[10px] font-bold cursor-pointer touch-press">
                    <span>+ Add</span>
                    <input type="file" @change="uploadMediaFileToCurrentCategory($event)" class="hidden" />
                  </label>
                </div>

                <div class="space-y-2">
                  <template x-if="getCategoryFiles().length === 0">
                    <div class="p-6 bg-white rounded-2xl border border-slate-200/80 text-center text-slate-400 text-xs">
                      No files in this folder yet. Tap + Add to upload!
                    </div>
                  </template>

                  <template x-for="(file, fIdx) in getCategoryFiles()" :key="fIdx">
                    <div class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between touch-press">
                      <div class="flex items-center gap-3 min-w-0" @click="openFileViewer(file)">
                        <div class="w-9 h-9 rounded-xl bg-slate-100 flex items-center justify-center font-bold text-sm shrink-0">
                          📄
                        </div>
                        <div class="min-w-0">
                          <div class="text-xs font-bold text-slate-900 truncate" x-text="file.name">File.png</div>
                          <div class="text-[10px] text-slate-400" x-text="(file.size || '1.8 MB') + ' • ' + (file.date || 'Recent')"></div>
                        </div>
                      </div>
                      <button @click="openFileViewer(file)" class="text-xs font-bold text-blue-600 hover:underline shrink-0 ml-2">
                        View
                      </button>
                    </div>
                  </template>
                </div>
              </div>

            </div>

            <!-- TAB 4: ASSOCIATED PROJECTS (Screens 11 & 12 Reference) -->
            <div x-show="contactDetailTab === 'projects'" class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <h4 class="text-xs font-bold text-slate-900">Associated Client Projects</h4>
                <span class="text-[10px] text-slate-400 font-bold" x-text="getAssociatedProjects(activeContact).length + ' Projects'"></span>
              </div>
              <div class="space-y-2">
                <template x-if="getAssociatedProjects(activeContact).length === 0">
                  <div class="p-6 text-center text-slate-400 text-xs space-y-1">
                    <p class="font-bold text-slate-600">No linked projects yet</p>
                    <p class="text-[11px]">Projects assigned to this contact will appear here.</p>
                  </div>
                </template>
                <template x-for="p in getAssociatedProjects(activeContact)" :key="p.id">
                  <div @click="viewProjectDetail(p)" class="p-3 rounded-xl bg-slate-50 border border-slate-100 flex items-center justify-between cursor-pointer hover:border-blue-400 transition touch-press">
                    <div class="min-w-0 pr-2">
                      <div class="text-xs font-bold text-slate-900 truncate" x-text="p.title"></div>
                      <div class="text-[10px] text-slate-400 mt-0.5" x-text="'Progress: ' + (p.progress || 0) + '% • ' + (p.status || 'Active')"></div>
                      <div class="w-32 bg-slate-200 h-1.5 rounded-full mt-1.5 overflow-hidden">
                        <div class="bg-blue-600 h-full rounded-full" :style="'width: ' + (p.progress || 0) + '%'"></div>
                      </div>
                    </div>
                    <div class="flex items-center gap-2 shrink-0">
                      <span class="px-2 py-0.5 rounded-full text-[10px] font-bold"
                        :class="(p.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'"
                        x-text="p.status || 'In Progress'"></span>
                      <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                    </div>
                  </div>
                </template>
              </div>
            </div>

            <!-- TAB 5: INVOICES & BILLING (Screens 8, 9, 10 Reference) -->
            <div x-show="contactDetailTab === 'invoices'" class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <h4 class="text-xs font-bold text-slate-900">Billing & Invoices</h4>
                <span class="text-[10px] text-slate-400 font-bold" x-text="getAssociatedInvoices(activeContact).length + ' Invoices'"></span>
              </div>
              <div class="space-y-2">
                <template x-if="getAssociatedInvoices(activeContact).length === 0">
                  <div class="p-6 text-center text-slate-400 text-xs space-y-1">
                    <p class="font-bold text-slate-600">No invoices on file</p>
                    <p class="text-[11px]">Invoices issued to this client will appear here.</p>
                  </div>
                </template>
                <template x-for="inv in getAssociatedInvoices(activeContact)" :key="inv.id">
                  <div @click="openInvoiceDetails(inv)" class="p-3 rounded-xl bg-slate-50 border border-slate-100 flex items-center justify-between cursor-pointer hover:border-blue-400 transition touch-press">
                    <div class="min-w-0 pr-2">
                      <div class="text-xs font-bold text-slate-900 truncate" x-text="inv.invoice_no || inv.id"></div>
                      <div class="text-[10px] text-slate-400 mt-0.5" x-text="'Due: ' + (inv.due_date || '10 Aug 2024')"></div>
                    </div>
                    <div class="text-right shrink-0">
                      <div class="text-xs font-bold text-slate-900" x-text="'$' + Number(inv.amount).toLocaleString()"></div>
                      <span class="px-2 py-0.5 rounded-full text-[9px] font-bold" 
                        :class="inv.status === 'Paid' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200/60' : 'bg-amber-50 text-amber-600 border border-amber-200/60'" 
                        x-text="inv.status"></span>
                    </div>
                  </div>
                </template>
              </div>
            </div>

          </div>

          <!-- ===================================================================
               SCREEN 5: PROJECTS MANAGEMENT (Exact Match Screen 5)
               =================================================================== -->
          <div x-show="currentView === 'projects'" class="space-y-3">
            
            <!-- Filter Pill Chips (Screen 5 Reference) -->
            <div class="flex items-center gap-1.5 overflow-x-auto no-scrollbar pb-1 text-xs font-bold">
              <button @click="projectFilter = 'all'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="projectFilter === 'all' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                All (<span x-text="projects.length"></span>)
              </button>

              <button @click="projectFilter = 'In Progress'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="(projectFilter === 'In Progress' || projectFilter === 'active') ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                Active (<span x-text="projects.filter(p => (p.status || '').toLowerCase() === 'in progress' || (p.status || '').toLowerCase() === 'active').length"></span>)
              </button>

              <button @click="projectFilter = 'Completed'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="projectFilter === 'Completed' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200'">
                Completed (<span x-text="projects.filter(p => (p.status || '').toLowerCase() === 'completed').length"></span>)
              </button>
            </div>

            <!-- Project Cards List (Responsive: 1-col mobile, 2-col tablet, 3-col desktop) -->
            <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3.5 space-y-0">
              <template x-for="p in filteredProjects" :key="p.id">
                <div @click="viewProjectDetail(p)" class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2.5 cursor-pointer hover:border-blue-300 hover:shadow-md transition-all active:scale-[0.99] touch-press">
                  <div class="flex items-start justify-between gap-3">
                    <div class="flex items-center gap-3 min-w-0">
                      <!-- Project Colored Square Icon (Screen 5) -->
                      <div class="w-10 h-10 rounded-xl flex items-center justify-center font-bold text-base shrink-0"
                        :class="p.color === 'purple' ? 'bg-purple-100 text-purple-600' : (p.color === 'indigo' ? 'bg-indigo-100 text-indigo-600' : (p.color === 'emerald' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'))">
                        <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <h4 class="text-xs font-black text-slate-900 truncate" x-text="p.title">E-commerce Website</h4>
                        <p class="text-[11px] text-slate-400 font-medium truncate mt-0.5" x-text="p.client_name">ABC Tech Solutions</p>
                      </div>
                    </div>
                    <button @click.stop="openProjectActionMenu(p)" class="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg hover:bg-slate-50 transition-colors" title="Project Options">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                    </button>
                  </div>

                  <!-- Progress Bar & Team Avatars (Screen 5) -->
                  <div>
                    <div class="flex justify-between items-center text-[10px] font-bold text-slate-500 mb-1">
                      <span>Progress</span>
                      <span x-text="(p.progress || 0) + '%'">70%</span>
                    </div>
                    <div class="w-full h-1.5 rounded-full bg-slate-100 overflow-hidden">
                      <div class="h-full bg-blue-600 rounded-full transition-all duration-300" :style="'width: ' + (p.progress || 0) + '%'"></div>
                    </div>
                  </div>

                  <!-- Team stack footer -->
                  <div class="flex items-center justify-between pt-1">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold"
                      :class="(p.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'"
                      x-text="p.status"></span>

                    <div class="flex items-center -space-x-1.5">
                      <template x-for="(tm, idx) in getProjectTeamMembers(p).slice(0, 3)" :key="idx">
