                    <div class="flex items-center gap-3.5 min-w-0">
                      <!-- Project Blue Square Icon with Initial (Exact Screen 1 Reference) -->
                      <div class="w-13 h-13 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-xl shrink-0 shadow-md shadow-blue-500/20">
                        <span x-text="activeProject.title ? activeProject.title.trim()[0].toUpperCase() : 'P'">E</span>
                      </div>
                      <div class="min-w-0">
                        <h2 class="text-base font-black text-slate-900 truncate leading-snug" x-text="activeProject.title">E-commerce Website</h2>
                        <div class="flex items-center gap-1.5 mt-0.5 text-xs text-slate-500 font-semibold truncate">
                          <span x-text="activeProject.company_name ? ('Company: ' + activeProject.company_name) : (activeProject.client_name ? ('Client: ' + activeProject.client_name) : 'No Company Linked')">Website development for Test Client</span>
                          <template x-if="activeProject.company_id || activeProject.company_name">
                            <button type="button" @click="viewCompanyFromProject(activeProject)" class="text-[11px] font-bold text-blue-600 hover:text-blue-800 hover:underline inline-flex items-center gap-0.5">
                              <span>(View Company &rarr;)</span>
                            </button>
                          </template>
                        </div>
                      </div>
                    </div>

                    <!-- Status Pill (Screen 1 Reference: In Progress in green pill) -->
                    <span class="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold shrink-0"
                      :class="(activeProject.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : 'bg-emerald-50 text-emerald-700 border border-emerald-200/60'">
                      <span x-text="activeProject.status || 'In Progress'">In Progress</span>
                    </span>
                  </div>

                  <!-- 4-Stat Metric Grid (Exact Screen 1 Reference) -->
                  <div class="grid grid-cols-2 gap-2.5 pt-1">
                    <!-- Start Date -->
                    <div class="p-3 bg-slate-50/80 rounded-xl border border-slate-100 flex items-center gap-2.5">
                      <div class="w-8 h-8 rounded-lg bg-blue-100/70 text-blue-600 flex items-center justify-center shrink-0">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[10px] font-bold text-slate-400">Start Date</div>
                        <div class="text-xs font-extrabold text-slate-900 truncate" x-text="formatDisplayDate(activeProject.start_date || '2024-07-15')">15 Jul 2024</div>
                      </div>
                    </div>

                    <!-- Due Date -->
                    <div class="p-3 bg-slate-50/80 rounded-xl border border-slate-100 flex items-center gap-2.5">
                      <div class="w-8 h-8 rounded-lg bg-rose-100/70 text-rose-600 flex items-center justify-center shrink-0">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[10px] font-bold text-slate-400">Due Date</div>
                        <div class="text-xs font-extrabold text-slate-900 truncate" x-text="formatDisplayDate(activeProject.deadline || '2024-09-25')">25 Sep 2024</div>
                      </div>
                    </div>

                    <!-- Budget -->
                    <div class="p-3 bg-slate-50/80 rounded-xl border border-slate-100 flex items-center gap-2.5">
                      <div class="w-8 h-8 rounded-lg bg-emerald-100/70 text-emerald-600 flex items-center justify-center shrink-0">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[10px] font-bold text-slate-400">Budget</div>
                        <div class="text-xs font-extrabold text-slate-900 truncate" x-text="activeProject.budget || '$22,000'">$22,000</div>
                      </div>
                    </div>

                    <!-- Project Manager -->
                    <div class="p-3 bg-slate-50/80 rounded-xl border border-slate-100 flex items-center gap-2.5">
                      <div class="w-8 h-8 rounded-lg bg-purple-100/70 text-purple-600 flex items-center justify-center shrink-0">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[10px] font-bold text-slate-400">Project Manager</div>
                        <div class="text-xs font-extrabold text-slate-900 truncate" x-text="activeProject.project_manager || 'Priya Verma'">Priya Verma</div>
                      </div>
                    </div>
                  </div>
                </div>

                <!-- 2. Project Details Tabs Navigation (Screen 1 Reference) -->
                <div class="flex items-center bg-white border border-slate-200/80 rounded-2xl px-2 py-1 shadow-pocket overflow-x-auto no-scrollbar">
                  <button @click="projectDetailTab = 'overview'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="projectDetailTab === 'overview' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Overview
                  </button>
                  <button @click="projectDetailTab = 'tasks'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="projectDetailTab === 'tasks' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Tasks
                  </button>
                  <button @click="projectDetailTab = 'team'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="projectDetailTab === 'team' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Team
                  </button>
                  <button @click="projectDetailTab = 'files'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="projectDetailTab === 'files' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Files
                  </button>
                  <button @click="projectDetailTab = 'activity'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="projectDetailTab === 'activity' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Activity
                  </button>
                </div>

                <!-- ===================================================================
                     TAB 1: OVERVIEW (Screen 1 Reference)
                     =================================================================== -->
                <div x-show="projectDetailTab === 'overview'" class="space-y-3">
                  <!-- About Project Card -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <h4 class="text-xs font-black text-slate-900">About Project</h4>
                      <button type="button" @click="openEditProjectModal(activeProject)" class="text-xs font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1 touch-press">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                        <span>Edit</span>
                      </button>
                    </div>
                    
                    <p class="text-xs text-slate-600 leading-relaxed font-medium" x-text="activeProject.description || 'Development of a full-feature e-commerce website for Test Client including product catalog, payment integration and admin panel.'"></p>

                    <!-- Category Tag Pills (Screen 1 Reference) -->
                    <div class="flex items-center gap-2 flex-wrap pt-1">
                      <span class="px-2.5 py-1 rounded-lg bg-blue-50 text-blue-700 text-[10px] font-bold">E-commerce</span>
                      <span class="px-2.5 py-1 rounded-lg bg-blue-50 text-blue-700 text-[10px] font-bold">Website</span>
                      <span class="px-2.5 py-1 rounded-lg bg-blue-50 text-blue-700 text-[10px] font-bold">Development</span>
                      <template x-if="activeProject.category && !['e-commerce', 'website', 'development'].includes(activeProject.category.toLowerCase())">
                        <span class="px-2.5 py-1 rounded-lg bg-slate-100 text-slate-700 text-[10px] font-bold" x-text="activeProject.category"></span>
                      </template>
                    </div>

                    <!-- Progress Bar -->
                    <div class="pt-2">
                      <div class="flex justify-between items-center text-xs font-bold mb-1.5">
                        <span class="text-slate-800">Progress</span>
                        <span class="text-slate-900 font-extrabold" x-text="(activeProject.progress !== undefined ? activeProject.progress : 70) + '%'">70%</span>
                      </div>
                      <div class="w-full h-2 rounded-full bg-slate-100 overflow-hidden">
                        <div class="h-full bg-blue-600 rounded-full transition-all duration-300" :style="'width: ' + (activeProject.progress !== undefined ? activeProject.progress : 70) + '%'"></div>
                      </div>
                    </div>

                    <!-- Key Dates Section -->
                    <div class="pt-2 border-t border-slate-100">
                      <div class="text-[11px] font-black text-slate-800 mb-2">Key Dates</div>
                      <div class="grid grid-cols-2 gap-2 text-xs">
                        <div>
                          <span class="text-[10px] text-slate-400 block font-semibold">Start Date</span>
                          <span class="font-extrabold text-slate-800" x-text="formatDisplayDate(activeProject.start_date || '2024-07-15')">15 Jul 2024</span>
                        </div>
                        <div>
                          <span class="text-[10px] text-slate-400 block font-semibold">Due Date</span>
                          <span class="font-extrabold text-slate-800" x-text="formatDisplayDate(activeProject.deadline || '2024-09-25')">25 Sep 2024</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- Associated Company Card -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <div class="flex items-center gap-2">
                        <div class="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
                          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                        </div>
                        <div>
                          <h4 class="text-xs font-black text-slate-900">Associated Company</h4>
                          <span class="text-[10px] text-slate-400 font-semibold" x-text="(activeProject.company_id || activeProject.company_name) ? 'Database Relationship Active' : 'No Company Associated'"></span>
                        </div>
                      </div>
                      <template x-if="activeProject.company_id || activeProject.company_name">
                        <button type="button" @click="viewCompanyFromProject(activeProject)" class="text-xs font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1 touch-press group">
                          <span>Open Company</span>
                          <svg class="w-3.5 h-3.5 group-hover:translate-x-0.5 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                        </button>
                      </template>
                      <template x-if="!activeProject.company_id && !activeProject.company_name">
                        <button type="button" @click="openEditProjectModal(activeProject)" class="text-xs font-bold text-blue-600 hover:underline">
                          + Associate Company
                        </button>
                      </template>
                    </div>

                    <template x-if="activeProject.company_id || activeProject.company_name">
                      <div @click="viewCompanyFromProject(activeProject)" class="p-3 rounded-xl bg-slate-50 hover:bg-blue-50/50 border border-slate-100 hover:border-blue-200 flex items-center justify-between cursor-pointer transition touch-press group">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black text-xs uppercase shrink-0 shadow-xs"
                            x-text="(activeProject.company_name || activeProject.client_name || 'C').substring(0, 2)">
                          </div>
                          <div class="min-w-0">
                            <div class="text-xs font-black text-slate-900 group-hover:text-blue-600 truncate transition" x-text="activeProject.company_name || activeProject.client_name"></div>
                            <div class="text-[10px] text-slate-400 flex items-center gap-2 mt-0.5">
                              <span x-text="activeProject.company_industry || 'Enterprise Partner'"></span>
                              <span class="text-emerald-600 font-semibold flex items-center gap-1">
                                <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                                Matched & Linked
                              </span>
                            </div>
                          </div>
                        </div>
                        <div class="flex items-center gap-2 shrink-0">
                          <span class="text-[11px] font-bold text-blue-600 hidden sm:inline">View Details</span>
                          <svg class="w-4 h-4 text-slate-400 group-hover:text-blue-600 group-hover:translate-x-0.5 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                        </div>
                      </div>
                    </template>

                    <template x-if="!activeProject.company_id && !activeProject.company_name">
                      <div class="p-3.5 rounded-xl bg-slate-50 border border-dashed border-slate-200 text-center space-y-1">
                        <p class="text-xs text-slate-600 font-semibold">No company is associated with this project</p>
                        <p class="text-[10px] text-slate-400">Projects are automatically matched when their title matches a company name, or you can select one manually.</p>
                      </div>
                    </template>
                  </div>
                </div>

                <!-- ===================================================================
                     TAB 2: TASKS (Screen 3 Reference)
                     =================================================================== -->
                <div x-show="projectDetailTab === 'tasks'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <div>
                        <h4 class="text-xs font-black text-slate-900">Project Tasks</h4>
                        <p class="text-[10px] text-slate-400 font-medium" x-text="getProjectTasks(activeProject).length + ' total tasks linked to this project'"></p>
                      </div>
                      <button type="button" @click="openAddTaskForProject(activeProject)" class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs touch-press transition-colors">
                        <span>+ Add Task</span>
                      </button>
                    </div>

                    <div class="space-y-2">
                      <template x-if="getProjectTasks(activeProject).length === 0">
                        <div class="p-6 text-center border border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
                          <p class="text-xs font-bold text-slate-700">No tasks created yet</p>
                          <p class="text-[11px] text-slate-400 mt-0.5">Click + Add Task to create the first task for this project.</p>
                        </div>
                      </template>

                      <template x-for="t in getProjectTasks(activeProject)" :key="t.id">
                        <div @click="viewTaskDetailFromProject(t)" class="p-3 bg-slate-50 hover:bg-slate-100/80 rounded-xl border border-slate-100 flex items-center justify-between gap-3 cursor-pointer transition-colors group">
                          <div class="flex items-center gap-3 min-w-0">
                            <!-- Checkbox -->
                            <input type="checkbox" :checked="t.completed || t.status === 'Completed'" @click.stop @change="toggleTaskCompletion(t.id)" class="w-4 h-4 rounded text-blue-600 border-slate-300 focus:ring-blue-500 cursor-pointer"/>
                            <div class="min-w-0">
                              <div class="text-xs font-bold text-slate-900 truncate" :class="(t.completed || t.status === 'Completed') ? 'line-through text-slate-400' : ''" x-text="t.title"></div>
                              <div class="flex items-center gap-2 text-[10px] text-slate-400 mt-0.5">
                                <span x-text="formatTaskDueSubline(t)"></span>
                              </div>
                            </div>
                          </div>
                          <div class="flex items-center gap-2 shrink-0">
                            <span class="px-2.5 py-0.5 rounded-full text-[9px] font-bold uppercase shrink-0"
                              :class="(t.completed || t.status === 'Completed') ? 'bg-emerald-50 text-emerald-600' : (t.priority === 'High' ? 'bg-rose-50 text-rose-600' : (t.priority === 'Medium' ? 'bg-amber-50 text-amber-600' : 'bg-slate-100 text-slate-600'))"
                              x-text="(t.completed || t.status === 'Completed') ? 'COMPLETED' : (t.priority ? t.priority.toUpperCase() : 'NORMAL')"></span>
                            <button type="button" @click.stop="openTaskActionMenu(t)" class="p-1 text-slate-400 hover:text-slate-600 touch-press" title="Task options">
                              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                            </button>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- ===================================================================
                     TAB 3: TEAM (Screen 7 Reference)
                     =================================================================== -->
                <div x-show="projectDetailTab === 'team'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <div>
                        <h4 class="text-xs font-black text-slate-900">Project Team</h4>
                        <p class="text-[10px] text-slate-400 font-medium" x-text="getProjectTeamMembers(activeProject).length + ' team members'"></p>
                      </div>
                      <button type="button" @click="openAddTeamMemberModal()" class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs touch-press transition-colors">
                        <span>+ Add Member</span>
                      </button>
                    </div>

                    <div class="space-y-2.5">
                      <template x-for="tm in getProjectTeamMembers(activeProject)" :key="tm.id || tm.name">
                        <div @click="viewTeamMemberDetailFromProject(tm)" class="p-3 bg-slate-50 hover:bg-slate-100/80 rounded-xl border border-slate-100 flex items-center justify-between cursor-pointer transition-colors group">
                          <div class="flex items-center gap-3 min-w-0">
                            <!-- Avatar / Initials -->
                            <template x-if="tm.avatar_url || tm.avatarUrl">
                              <img :src="tm.avatar_url || tm.avatarUrl" :alt="tm.name" class="w-10 h-10 rounded-full object-cover ring-2 ring-white shrink-0"/>
                            </template>
                            <template x-if="!tm.avatar_url && !tm.avatarUrl">
                              <div class="w-10 h-10 rounded-full flex items-center justify-center text-xs font-black text-white shrink-0"
                                :class="tm.color_class || tm.colorClass || 'bg-blue-600'"
                                x-text="tm.initials || computeInitials(tm.name)">
                              </div>
                            </template>
                            <div class="min-w-0">
                              <div class="text-xs font-extrabold text-slate-900 truncate" x-text="tm.name"></div>
                              <div class="text-[10px] text-slate-500 font-medium truncate" x-text="tm.role || 'Member'"></div>
                              <div class="text-[10px] text-slate-400 truncate" x-text="tm.email || 'team@softwarecrm.com'"></div>
                            </div>
                          </div>
                          <div class="text-slate-400 group-hover:text-blue-600 group-hover:translate-x-0.5 transition-all">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- ===================================================================
                     TAB 4: FILES (Screen 9 Reference)
                     =================================================================== -->
                <div x-show="projectDetailTab === 'files'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <div>
                        <h4 class="text-xs font-black text-slate-900">Project Files</h4>
                        <p class="text-[10px] text-slate-400 font-medium" x-text="getProjectFiles(activeProject).length + ' files uploaded'"></p>
                      </div>
                      <label class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs cursor-pointer touch-press transition-colors"
                        :class="isUploadingProjectFile ? 'opacity-50 pointer-events-none' : ''">
                        <svg x-show="!isUploadingProjectFile" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                        <svg x-show="isUploadingProjectFile" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        <span x-text="isUploadingProjectFile ? 'Uploading...' : '+ Upload File'"></span>
                        <input type="file" class="hidden" @change="uploadProjectFile($event)"/>
                      </label>
                    </div>

                    <!-- Files List -->
                    <div class="space-y-2">
                      <template x-if="getProjectFiles(activeProject).length === 0 && !isUploadingProjectFile">
                        <div class="p-6 text-center border border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
                          <p class="text-xs font-bold text-slate-700">No project files yet</p>
                          <p class="text-[11px] text-slate-400 mt-0.5">Upload PDFs, designs, specs, or documents.</p>
                        </div>
                      </template>

                      <template x-for="(file, fIdx) in getProjectFiles(activeProject)" :key="file.id || fIdx">
                        <div @click="openProjectFileViewer(file)" class="p-3 bg-slate-50 hover:bg-slate-100/80 rounded-xl border border-slate-100 flex items-center justify-between cursor-pointer transition-colors group">
                          <div class="flex items-center gap-3 min-w-0">
                            <!-- File Icon Badge -->
                            <div class="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 uppercase text-[10px] font-black"
                              :class="{
                                'bg-rose-100 text-rose-600': file.type === 'pdf' || (file.name && file.name.endsWith('.pdf')),
                                'bg-blue-100 text-blue-600': file.type === 'doc' || (file.name && (file.name.endsWith('.doc') || file.name.endsWith('.docx'))),
                                'bg-emerald-100 text-emerald-600': file.name && (file.name.endsWith('.xls') || file.name.endsWith('.xlsx')),
                                'bg-purple-100 text-purple-600': file.type === 'image' || (file.name && file.name.match(/\.(png|jpg|jpeg|gif|webp)$/i)),
                                'bg-amber-100 text-amber-600': file.name && file.name.endsWith('.zip')
                              }">
                              <span x-text="file.name ? file.name.split('.').pop().toUpperCase() : 'FILE'">PDF</span>
                            </div>

                            <div class="min-w-0">
                              <div class="text-xs font-bold text-slate-900 truncate" x-text="file.name"></div>
                              <div class="text-[10px] text-slate-400 flex items-center gap-1.5 mt-0.5">
                                <span x-text="file.size"></span>
                                <span>&bull;</span>
                                <span x-text="file.date"></span>
                              </div>
                            </div>
                          </div>

                          <div class="flex items-center gap-2 shrink-0">
                            <span class="text-xs font-bold text-blue-600 hover:text-blue-700">View</span>
                            <template x-if="file.download_url">
                              <a :href="file.download_url" @click.stop class="p-1 text-slate-400 hover:text-slate-600" title="Download">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                              </a>
                            </template>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- ===================================================================
                     TAB 5: ACTIVITY (Screen 12 Reference)
                     =================================================================== -->
                <div x-show="projectDetailTab === 'activity'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <h4 class="text-xs font-black text-slate-900">Project Activity</h4>
                      <button type="button" @click="openAddProjectNoteModal()" class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1 shadow-xs touch-press transition-colors">
                        <span>+ Add Note</span>
                      </button>
                    </div>

                    <div class="space-y-3.5 pl-2 pt-1">
                      <template x-for="(act, idx) in getProjectActivity(activeProject)" :key="act.id || idx">
                        <div class="relative pl-6 pb-2 border-l-2 border-slate-100 last:border-l-0 last:pb-0">
                          <div class="absolute -left-[5px] top-1 w-2.5 h-2.5 rounded-full bg-blue-600 ring-4 ring-blue-50"></div>
                          <div class="flex items-start justify-between gap-2">
                            <div>
                              <div class="text-xs font-black text-slate-900" x-text="act.title"></div>
                              <div class="text-[11px] text-slate-600 font-medium mt-0.5" x-text="act.description"></div>
                              <div class="text-[10px] text-slate-400 font-medium mt-0.5" x-text="'by ' + act.user + ' • ' + act.time"></div>
                            </div>
                            <template x-if="act.id && act.id.startsWith('act_')">
                              <button type="button" @click="deleteProjectActivity(act)" class="p-1 text-slate-300 hover:text-rose-500 touch-press" title="Delete Note">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              </button>
                            </template>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- 5. Bottom Action: Blue "Edit Project" Button -->
                <button type="button" @click="openEditProjectModal(activeProject)" class="w-full py-3 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white font-extrabold text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-500/25 transition-all touch-press mt-2">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                  <span>Edit Project</span>
                </button>

              </div>
            </template>
          </div>

          <!-- ===================================================================
               SCREEN 1, 5, 6, 7, 10: TASKS DASHBOARD & LIST
               =================================================================== -->
          <div x-show="currentView === 'tasks'" class="space-y-3 pb-8" x-cloak>
            
            <!-- Search Bar (Screen 1 & 5 Reference) -->
            <div class="relative">
              <svg class="w-4 h-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
              <input type="text" x-model="taskSearchQuery" placeholder="Search tasks..." class="w-full pl-10 pr-9 py-2.5 bg-white border border-slate-200/90 rounded-2xl text-xs font-medium placeholder-slate-400 shadow-pocket focus:border-blue-500 focus:outline-none transition-all"/>
              <button x-show="taskSearchQuery.length > 0" @click="taskSearchQuery = ''" class="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 text-sm font-bold">&times;</button>
            </div>

            <!-- Task Tabs (Screen 1, 5, 6 Reference) -->
            <div class="flex items-center gap-1.5 overflow-x-auto no-scrollbar pb-1 text-xs font-bold">
              <button @click="taskFilter = 'my'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="taskFilter === 'my' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200/90'">
                My Tasks (<span x-text="myTasksCount"></span>)
              </button>

              <button @click="taskFilter = 'all'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="taskFilter === 'all' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200/90'">
                All Tasks (<span x-text="allTasksCount"></span>)
              </button>

              <button @click="taskFilter = 'overdue'" 
                class="px-3.5 py-1.5 rounded-full transition-all whitespace-nowrap cursor-pointer touch-press"
                :class="taskFilter === 'overdue' ? 'bg-blue-600 text-white shadow-sm' : 'bg-white text-slate-600 border border-slate-200/90'">
                Overdue (<span x-text="overdueTasksCount"></span>)
              </button>
            </div>

            <!-- Filter Dropdowns Row (Screen 5 Reference) -->
            <div class="grid grid-cols-3 gap-2">
              <select x-model="taskProjectFilter" class="w-full px-2.5 py-1.5 bg-white border border-slate-200/90 rounded-xl text-[11px] font-bold text-slate-700 shadow-pocket focus:outline-none truncate">
                <option value="all">All Projects</option>
                <template x-for="p in uniqueTaskProjects" :key="p">
                  <option :value="p" x-text="p"></option>
                </template>
              </select>

              <select x-model="taskPriorityFilter" class="w-full px-2.5 py-1.5 bg-white border border-slate-200/90 rounded-xl text-[11px] font-bold text-slate-700 shadow-pocket focus:outline-none">
                <option value="all">All Priority</option>
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
              </select>

              <select x-model="taskStatusFilter" class="w-full px-2.5 py-1.5 bg-white border border-slate-200/90 rounded-xl text-[11px] font-bold text-slate-700 shadow-pocket focus:outline-none">
                <option value="all">All Status</option>
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
              </select>
            </div>

            <!-- Progress Summary Card (Screen 1 Reference) -->
            <div class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center gap-3.5">
              <!-- Circular Progress Gauge -->
              <div class="relative w-14 h-14 shrink-0 flex items-center justify-center">
                <svg class="w-14 h-14 -rotate-90" viewBox="0 0 36 36">
                  <path class="text-slate-100" stroke-width="3.5" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                  <path class="text-blue-600 transition-all duration-500 ease-out" stroke-dasharray="100, 100" :stroke-dashoffset="100 - taskCompletionPercentage" stroke-linecap="round" stroke-width="3.5" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                </svg>
                <span class="absolute text-xs font-black text-slate-900" x-text="taskCompletionPercentage + '%'">62%</span>
              </div>

              <div class="flex-1 min-w-0">
                <div class="flex items-center justify-between">
                  <div class="text-xs font-black text-slate-900" x-text="completedTasksCount + ' of ' + totalTasksCount + ' completed'">5 of 8 completed</div>
                  <button @click="enterBulkMode()" x-show="!bulkMode" class="text-[10px] font-bold text-blue-600 hover:text-blue-800 touch-press">Select</button>
                </div>
                <p class="text-[11px] text-slate-400 font-medium mt-0.5">Great progress! Keep it up.</p>
                <!-- Mini Progress Bar -->
                <div class="w-full h-1.5 rounded-full bg-slate-100 mt-2 overflow-hidden">
                  <div class="h-full bg-blue-600 rounded-full transition-all duration-300" :style="'width: ' + taskCompletionPercentage + '%'"></div>
                </div>
              </div>
            </div>

            <!-- Task Cards List (Responsive: 1-col mobile, 2-col desktop) -->
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-3 space-y-0">
              <template x-for="t in filteredTasks" :key="t.id">
                <div @click="bulkMode ? toggleTaskSelection(t.id) : viewTaskDetail(t)" 
                  class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between gap-2.5 transition-all cursor-pointer hover:border-blue-300 active:scale-[0.99] touch-press"
                  :class="bulkMode && selectedTaskIds.includes(t.id) ? 'ring-2 ring-blue-500 bg-blue-50/20' : ''">
                  
                  <div class="flex items-center gap-3 min-w-0 flex-1">
                    <!-- Bulk Checkbox OR Task Complete Checkbox -->
                    <template x-if="bulkMode">
                      <div class="w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 transition-colors"
                        :class="selectedTaskIds.includes(t.id) ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-300 bg-white'">
                        <svg x-show="selectedTaskIds.includes(t.id)" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </div>
                    </template>

                    <template x-if="!bulkMode">
                      <button @click.stop="toggleTask(t)" class="w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 transition-all touch-press"
                        :class="Number(t.completed) === 1 ? 'bg-blue-600 border-blue-600 text-white shadow-xs' : 'border-slate-300 bg-white hover:border-blue-400'"
                        :title="Number(t.completed) === 1 ? 'Mark as Incomplete' : 'Mark as Completed'">
                        <svg x-show="Number(t.completed) === 1" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </button>
                    </template>

                    <!-- Title & Project/Subtitle -->
                    <div class="min-w-0 flex-1">
                      <h4 class="text-xs font-black truncate transition-colors"
                        :class="Number(t.completed) === 1 ? 'line-through text-slate-400' : 'text-slate-900'"
                        x-text="t.title"></h4>
                      <p class="text-[11px] text-slate-400 font-medium truncate mt-0.5" 
                        x-text="t.project_name || t.client_name || 'General Task'"></p>
                    </div>
                  </div>

                  <!-- Right: Priority, Due Date & Context Menu -->
                  <div class="flex items-center gap-2 shrink-0">
                    <!-- Priority Pill -->
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold"
                      :class="t.priority === 'High' ? 'bg-rose-50 text-rose-600 border border-rose-200/60' : (t.priority === 'Medium' ? 'bg-amber-50 text-amber-600 border border-amber-200/60' : 'bg-emerald-50 text-emerald-600 border border-emerald-200/60')"
                      x-text="t.priority || 'Medium'"></span>

                    <!-- Due Date -->
                    <span class="text-[10px] font-bold min-w-12 text-right"
                      :class="(!Number(t.completed) && isTaskOverdue(t)) ? 'text-rose-600 font-extrabold' : 'text-slate-400'"
                      x-text="t.due_time || formatDisplayDate(t.due_date) || 'Today'"></span>

                    <!-- 3-Dots Button -->
                    <button @click.stop="openTaskActionMenu(t)" class="p-1 text-slate-400 hover:text-slate-700 rounded-lg hover:bg-slate-50 transition-colors" title="Task Options">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                    </button>
                  </div>

                </div>
              </template>

              <!-- Empty State (Screen 10 Reference) -->
              <div x-show="filteredTasks.length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket">
                <!-- Illustrated Clipboard with Check Icon -->
                <div class="w-16 h-16 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mx-auto mb-3 shadow-xs">
                  <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
                </div>
                <h3 class="text-sm font-black text-slate-900">No Tasks Found</h3>
                <p class="text-xs text-slate-400 max-w-xs mx-auto mt-1 leading-relaxed">You don't have any tasks matching this filter yet. Create your first task to get started.</p>
                <button @click="openAddTaskScreen()" class="mt-4 px-6 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-md shadow-blue-500/25 transition-all touch-press">
                  Create Task
                </button>
              </div>
            </div>

            <!-- Bulk Actions Fixed Bottom Toolbar (Screen 7 Reference) -->
            <div x-show="bulkMode" class="fixed bottom-16 inset-x-0 bg-white border-t border-slate-200 p-3 shadow-2xl flex items-center justify-around z-40 max-w-md mx-auto" x-cloak>
              <button @click="executeBulkComplete()" class="flex flex-col items-center gap-1 text-[10px] font-bold text-slate-700 hover:text-blue-600 touch-press" :disabled="selectedTaskIds.length === 0">
                <svg class="w-5 h-5 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                <span>Complete</span>
              </button>

              <button @click="openBulkAssignModal()" class="flex flex-col items-center gap-1 text-[10px] font-bold text-slate-700 hover:text-blue-600 touch-press" :disabled="selectedTaskIds.length === 0">
                <svg class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                <span>Assign</span>
              </button>

              <button @click="openBulkMoveModal()" class="flex flex-col items-center gap-1 text-[10px] font-bold text-slate-700 hover:text-blue-600 touch-press" :disabled="selectedTaskIds.length === 0">
                <svg class="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"/></svg>
                <span>Move</span>
              </button>

              <button @click="executeBulkDelete()" class="flex flex-col items-center gap-1 text-[10px] font-bold text-rose-600 touch-press" :disabled="selectedTaskIds.length === 0">
                <svg class="w-5 h-5 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                <span>Delete</span>
              </button>
            </div>

          </div>


          <!-- ===================================================================
               SCREEN 2: ADD TASK SCREEN (Exact Match Screen 2)
               =================================================================== -->
          <div x-show="currentView === 'task_add'" class="space-y-4 pb-8" x-cloak>
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5">
              
              <!-- Task Title -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Task Title <span class="text-rose-500">*</span></label>
                <input type="text" x-model="taskForm.title" placeholder="Enter task title..." required class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:bg-white focus:border-blue-500 focus:outline-none"/>
              </div>

              <!-- Description -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Description</label>
                <textarea x-model="taskForm.description" rows="3" placeholder="Enter description..." class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:bg-white focus:border-blue-500 focus:outline-none"></textarea>
              </div>

              <!-- Select Project -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Select Project</label>
                <select x-model="taskForm.project_id" @change="onProjectSelectChange($event)" class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:bg-white focus:border-blue-500 focus:outline-none">
                  <option value="">Select Project</option>
                  <template x-for="p in projects" :key="p.id">
                    <option :value="p.id" x-text="p.title"></option>
                  </template>
                </select>
              </div>

              <!-- Assign To Section -->
              <div>
                <div class="flex items-center justify-between mb-1.5">
                  <label class="block text-xs font-bold text-slate-800 dark:text-slate-200">Assign To</label>
                  <button type="button" @click="openTaskAssigneesModal()" 
                    class="text-[11px] font-bold text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 hover:underline flex items-center gap-1 touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                    <span>+ Add Members</span>
                  </button>
                </div>

                <!-- Field Container: Shows either placeholder + Add button or Member chips + Add button -->
                <div class="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl min-h-[46px] flex flex-wrap items-center gap-2 transition-all">
                  
                  <!-- Empty State: "[ Select team members... ] [ + Add Members ]" -->
                  <div x-show="!taskForm.selected_members || taskForm.selected_members.length === 0" class="w-full flex items-center justify-between gap-2">
                    <button type="button" @click="openTaskAssigneesModal()" 
                      class="flex-1 text-left text-xs font-medium text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 flex items-center gap-2 cursor-pointer">
                      <svg class="w-4 h-4 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                      <span>Select team members...</span>
                    </button>
                    <button type="button" @click="openTaskAssigneesModal()" 
                      class="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold flex items-center gap-1 shadow-xs touch-press transition-colors shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                      <span>+ Add Members</span>
                    </button>
                  </div>

                  <!-- Member Chips List when members are selected -->
                  <template x-for="m in taskForm.selected_members" :key="m.id">
                    <div class="inline-flex items-center gap-1.5 pl-1.5 pr-2 py-1 bg-white dark:bg-slate-800 border border-slate-200/90 dark:border-slate-700 rounded-lg shadow-2xs text-xs font-bold text-slate-800 dark:text-slate-100 group transition-all">
                      <!-- Profile Picture / Initials Avatar -->
                      <template x-if="m.avatar_url">
                        <img :src="m.avatar_url" class="w-5 h-5 rounded-full object-cover shrink-0" :alt="m.name"/>
                      </template>
                      <template x-if="!m.avatar_url">
                        <div class="w-5 h-5 rounded-full text-white text-[9px] font-extrabold flex items-center justify-center shrink-0"
                          :class="m.color_class || 'bg-blue-600'">
                          <span x-text="m.initials || m.name.substring(0, 2).toUpperCase()"></span>
                        </div>
                      </template>
                      
                      <!-- Name chip text -->
                      <span class="truncate max-w-[140px]" x-text="(m.initials ? m.initials + ' — ' : '') + m.name"></span>
                      
                      <!-- Remove (x) Button -->
                      <button type="button" @click.stop="removeMemberFromTask(m.id)" 
                        class="text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 rounded-full p-0.5 ml-0.5 touch-press transition-colors" 
                        title="Remove member">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                      </button>
                    </div>
                  </template>

                  <!-- [+ Add Members] Button beside chips -->
                  <button type="button" x-show="taskForm.selected_members && taskForm.selected_members.length > 0" 
                    @click="openTaskAssigneesModal()" 
                    class="inline-flex items-center gap-1 px-2.5 py-1 bg-blue-50 dark:bg-blue-900/40 hover:bg-blue-100 dark:hover:bg-blue-900/60 text-blue-600 dark:text-blue-300 border border-blue-200/80 dark:border-blue-800 rounded-lg text-xs font-bold touch-press transition-colors">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                    <span>+ Add Members</span>
                  </button>

                </div>
              </div>

              <!-- Priority -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Priority</label>
                <div class="grid grid-cols-3 gap-2">
                  <button type="button" @click="taskForm.priority = 'Low'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'Low' ? 'bg-emerald-50 text-emerald-700 border-emerald-300 ring-2 ring-emerald-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    Low
                  </button>
                  <button type="button" @click="taskForm.priority = 'Medium'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'Medium' ? 'bg-amber-50 text-amber-700 border-amber-300 ring-2 ring-amber-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    Medium
                  </button>
                  <button type="button" @click="taskForm.priority = 'High'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'High' ? 'bg-rose-50 text-rose-700 border-rose-300 ring-2 ring-rose-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    High
                  </button>
                </div>
              </div>

              <!-- Due Date -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Due Date</label>
                <input type="date" x-model="taskForm.due_date" class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:bg-white focus:border-blue-500 focus:outline-none"/>
              </div>

              <!-- Create Task Button -->
              <button @click="submitTaskForm()" class="w-full py-3 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white font-extrabold text-sm shadow-lg shadow-blue-500/25 transition-all touch-press mt-2">
                Create Task
              </button>

            </div>
          </div>


          <!-- ===================================================================
               SCREEN 3: TASK DETAILS VIEW (Exact Match Screen 3)
               =================================================================== -->
          <div x-show="currentView === 'task_detail'" class="max-w-4xl mx-auto w-full space-y-3 pb-8" x-cloak>
            <template x-if="activeTask">
              <div class="space-y-3">
                
                <!-- 1. Header Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                  <div class="flex items-start justify-between gap-3">
                    <div class="flex items-start gap-3 min-w-0">
                      <!-- Big Checkbox -->
                      <button @click="toggleTask(activeTask)" class="w-7 h-7 rounded-lg border-2 flex items-center justify-center shrink-0 transition-all touch-press mt-0.5"
                        :class="Number(activeTask.completed) === 1 ? 'bg-blue-600 border-blue-600 text-white shadow-xs' : 'border-slate-300 bg-white hover:border-blue-400'">
                        <svg x-show="Number(activeTask.completed) === 1" class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </button>

                      <div class="min-w-0">
                        <h2 class="text-sm font-black text-slate-900 leading-snug"
                          :class="Number(activeTask.completed) === 1 ? 'line-through text-slate-400' : ''"
                          x-text="activeTask.title">Design Homepage</h2>
                        <p class="text-xs text-slate-500 font-semibold mt-0.5" x-text="activeTask.project_name || activeTask.client_name || 'E-commerce Website'"></p>
                        <p class="text-[11px] text-slate-400 font-medium" x-text="activeTask.category || 'Web Development'"></p>
                      </div>
                    </div>

                    <!-- Priority Badge -->
                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold shrink-0"
                      :class="activeTask.priority === 'High' ? 'bg-rose-50 text-rose-600 border border-rose-200/60' : (activeTask.priority === 'Medium' ? 'bg-amber-50 text-amber-600 border border-amber-200/60' : 'bg-emerald-50 text-emerald-600 border border-emerald-200/60')"
                      x-text="activeTask.priority || 'High'"></span>
                  </div>
                </div>

                <!-- 2. Navigation Tabs (Overview, Files, Activity, Comments) -->
                <div class="flex items-center border-b border-slate-200 bg-white rounded-2xl px-2 py-1 shadow-pocket overflow-x-auto no-scrollbar">
                  <button @click="taskDetailTab = 'overview'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="taskDetailTab === 'overview' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Overview
                  </button>
                  <button @click="taskDetailTab = 'files'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="taskDetailTab === 'files' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Files
                  </button>
                  <button @click="taskDetailTab = 'activity'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="taskDetailTab === 'activity' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Activity
                  </button>
                  <button @click="taskDetailTab = 'comments'" class="flex-1 py-2 text-xs font-bold text-center border-b-2 transition-all whitespace-nowrap px-3 touch-press"
                    :class="taskDetailTab === 'comments' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'">
                    Comments
                  </button>
                </div>

                <!-- TAB 1: OVERVIEW -->
                <div x-show="taskDetailTab === 'overview'" class="space-y-3">
                  <!-- Description Section -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                    <div class="flex items-center gap-2">
                      <div class="w-6 h-6 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                      </div>
                      <h4 class="text-xs font-extrabold text-slate-900">Description</h4>
                    </div>
                    <p class="text-xs text-slate-600 leading-relaxed pl-8" x-text="activeTask.description || 'Create a modern and responsive homepage design for the e-commerce website including banner, product sections and footer.'"></p>
                  </div>

                  <!-- Task Info List (Status, Priority, Due Date, Project, Assign To) -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3 text-xs">
                    <!-- Status -->
                    <div class="flex items-center justify-between py-1 border-b border-slate-100">
                      <div class="flex items-center gap-2 text-slate-500 font-semibold">
                        <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                        <span>Status</span>
                      </div>
                      <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold"
                        :class="Number(activeTask.completed) === 1 ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-blue-50 text-blue-700 border border-blue-200'"
                        x-text="Number(activeTask.completed) === 1 ? 'Completed' : (activeTask.status || 'In Progress')"></span>
                    </div>

                    <!-- Priority -->
                    <div class="flex items-center justify-between py-1 border-b border-slate-100">
                      <div class="flex items-center gap-2 text-slate-500 font-semibold">
                        <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9"/></svg>
                        <span>Priority</span>
                      </div>
                      <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold"
                        :class="activeTask.priority === 'High' ? 'bg-rose-50 text-rose-600' : (activeTask.priority === 'Medium' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600')"
                        x-text="activeTask.priority || 'Medium'"></span>
                    </div>

                    <!-- Due Date -->
                    <div class="flex items-center justify-between py-1 border-b border-slate-100">
                      <div class="flex items-center gap-2 text-slate-500 font-semibold">
                        <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                        <span>Due Date</span>
                      </div>
                      <span class="font-bold text-slate-900" x-text="activeTask.due_time ? (activeTask.due_time + ', ' + formatDisplayDate(activeTask.due_date || '2024-08-28')) : formatDisplayDate(activeTask.due_date || '2024-08-28')">Today, 28 Aug 2024</span>
                    </div>

                    <!-- Project -->
                    <div class="flex items-center justify-between py-1 border-b border-slate-100">
                      <div class="flex items-center gap-2 text-slate-500 font-semibold">
                        <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                        <span>Project</span>
                      </div>
                      <span class="font-bold text-blue-600" x-text="activeTask.project_name || activeTask.client_name || 'E-commerce Website'">E-commerce Website</span>
                    </div>

                    <!-- Assign To -->
                    <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between py-1 gap-2">
                      <div class="flex items-center gap-2 text-slate-500 font-semibold shrink-0">
                        <svg class="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                        <span>Assign To</span>
                      </div>
                      <div class="flex flex-wrap items-center gap-1.5 font-bold text-slate-900 justify-start sm:justify-end">
                        <template x-if="activeTask.assigned_members && activeTask.assigned_members.length > 0">
                          <div class="flex flex-wrap items-center gap-1.5">
                            <template x-for="m in activeTask.assigned_members" :key="m.id">
                              <span class="inline-flex items-center gap-1.5 px-2 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 text-xs border border-slate-200/80 dark:border-slate-700 shadow-2xs">
                                <div class="w-4 h-4 rounded-full flex items-center justify-center text-[8px] font-black text-white shrink-0"
                                     :class="m.color_class || 'bg-blue-600'"
                                     x-text="m.initials || (m.name ? m.name.substring(0, 2).toUpperCase() : 'TM')"></div>
                                <span class="font-bold text-xs" x-text="m.name"></span>
                              </span>
                            </template>
                          </div>
                        </template>
                        <template x-if="!activeTask.assigned_members || activeTask.assigned_members.length === 0">
                          <div class="flex items-center gap-1.5">
                            <div class="w-5 h-5 rounded-full bg-blue-600 text-white flex items-center justify-center text-[9px] font-bold"
                                 x-text="(activeTask.assigned_staff || 'Unassigned').substring(0,2).toUpperCase()"></div>
                            <span x-text="activeTask.assigned_staff || 'Unassigned'"></span>
                          </div>
                        </template>
                      </div>
                    </div>
                  </div>
                </div>

                <!-- TAB 2: FILES -->
                <div x-show="taskDetailTab === 'files'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <div>
                        <h4 class="text-xs font-extrabold text-slate-900">Task Attachments</h4>
                        <p class="text-[10px] text-slate-400">View images, PDFs, text, and documents</p>
                      </div>
                      <label class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1.5 shadow-xs cursor-pointer touch-press transition-colors"
                        :class="isUploadingTaskFile ? 'opacity-50 pointer-events-none' : ''">
                        <svg x-show="!isUploadingTaskFile" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                        <svg x-show="isUploadingTaskFile" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        <span x-text="isUploadingTaskFile ? 'Uploading...' : '+ Upload File'"></span>
                        <input type="file" class="hidden" @change="uploadTaskFile($event, activeTask)"/>
                      </label>
                    </div>

                    <!-- Attachments List -->
                    <div class="space-y-2">
                      <template x-if="getTaskFiles(activeTask).length === 0 && !isUploadingTaskFile">
                        <div class="p-6 text-center border border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
                          <div class="w-10 h-10 mx-auto rounded-full bg-slate-100 flex items-center justify-center text-slate-400 mb-2">
                            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                          </div>
                          <p class="text-xs font-bold text-slate-700">No attachments yet</p>
                          <p class="text-[11px] text-slate-400 mt-0.5">Upload images, PDFs, notes, or documents</p>
                        </div>
                      </template>

                      <template x-for="(f, idx) in getTaskFiles(activeTask)" :key="f.id || idx">
                        <div @click="openTaskFileViewer(f)" class="p-3 bg-slate-50 hover:bg-slate-100/80 rounded-xl border border-slate-100 flex items-center justify-between cursor-pointer transition-colors group">
                          <div class="flex items-center gap-2.5 min-w-0">
                            <!-- File Icon -->
                            <div class="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
                              :class="{
                                'bg-purple-50 text-purple-600': f.type === 'image',
                                'bg-rose-50 text-rose-600': f.type === 'pdf',
                                'bg-emerald-50 text-emerald-600': f.type === 'text',
                                'bg-blue-50 text-blue-600': f.type !== 'image' && f.type !== 'pdf' && f.type !== 'text'
                              }">
                              <!-- Image icon -->
                              <template x-if="f.type === 'image'">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                              </template>
                              <!-- PDF icon -->
                              <template x-if="f.type === 'pdf'">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                              </template>
                              <!-- Text icon -->
                              <template x-if="f.type === 'text'">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                              </template>
                              <!-- Document icon -->
                              <template x-if="f.type !== 'image' && f.type !== 'pdf' && f.type !== 'text'">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                              </template>
                            </div>
                            <div class="min-w-0">
                              <div class="text-xs font-bold text-slate-900 truncate" x-text="f.name"></div>
                              <div class="text-[10px] text-slate-400 flex items-center gap-1.5">
                                <span x-text="f.size"></span>
                                <span>&bull;</span>
                                <span x-text="f.date"></span>
                                <template x-if="f.type">
                                  <span class="uppercase tracking-wider px-1.5 py-0.2 rounded bg-slate-200/60 text-slate-600 text-[9px] font-semibold" x-text="f.type"></span>
                                </template>
                              </div>
                            </div>
                          </div>
                          
                          <div class="flex items-center gap-2 shrink-0">
                            <!-- View Button -->
                            <button type="button" @click.stop="openTaskFileViewer(f)" class="px-2.5 py-1 rounded-lg bg-blue-50 hover:bg-blue-100 text-blue-600 text-xs font-bold transition-colors">
                              View
                            </button>
                            <!-- Download Link -->
                            <template x-if="f.download_url">
                              <a :href="f.download_url" @click.stop class="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-200/50 transition-colors" title="Download">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                              </a>
                            </template>
                            <!-- Delete File Button -->
                            <button type="button" @click.stop="promptDeleteTaskFile(f, activeTask)" class="px-2 py-1 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-600 text-xs font-bold transition-colors flex items-center gap-1 touch-press" title="Delete File" aria-label="Delete File">
                              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              <span>Delete File</span>
                            </button>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- TAB 3: ACTIVITY -->
                <div x-show="taskDetailTab === 'activity'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <h4 class="text-xs font-extrabold text-slate-900">Task History</h4>
                    <div class="space-y-3.5 pl-2">
                      <template x-for="(act, idx) in getTaskActivity(activeTask)" :key="idx">
                        <div class="relative pl-6 pb-2 border-l-2 border-slate-100 last:border-l-0 last:pb-0">
                          <div class="absolute -left-[5px] top-1 w-2.5 h-2.5 rounded-full bg-blue-600 ring-4 ring-blue-50"></div>
                          <div>
                            <div class="text-xs font-extrabold text-slate-900" x-text="act.title"></div>
                            <div class="text-[11px] text-slate-600 font-medium mt-0.5" x-text="act.description"></div>
                            <div class="text-[10px] text-slate-400 font-medium mt-0.5" x-text="'by ' + act.user + ' • ' + act.time"></div>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- TAB 4: COMMENTS -->
                <div x-show="taskDetailTab === 'comments'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <h4 class="text-xs font-extrabold text-slate-900">Discussion</h4>
                    
                    <!-- Comment Input -->
                    <div class="flex gap-2">
                      <input type="text" x-model="newCommentText" placeholder="Write a comment..." class="flex-1 px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:bg-white focus:outline-none"/>
                      <button @click="addCommentToTask(activeTask)" class="px-3.5 py-2 rounded-xl bg-blue-600 text-white font-bold text-xs touch-press">Post</button>
                    </div>

                    <!-- Comments List -->
                    <div class="space-y-2.5 pt-2">
                      <template x-for="(c, cIdx) in getTaskComments(activeTask)" :key="cIdx">
                        <div class="p-3 bg-slate-50 rounded-xl border border-slate-100 space-y-1">
                          <div class="flex items-center justify-between text-[11px]">
                            <span class="font-extrabold text-slate-900" x-text="c.user"></span>
                            <span class="text-slate-400 font-medium" x-text="c.time"></span>
                          </div>
                          <p class="text-xs text-slate-700 leading-relaxed" x-text="c.text"></p>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

                <!-- 3. Bottom Action Buttons (Matching Reference Screen 3) -->
                <div class="space-y-2 pt-1">
                  <!-- Mark as Completed / Reopen -->
                  <button @click="toggleTask(activeTask)" class="w-full py-3 rounded-2xl text-white font-extrabold text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-500/25 transition-all touch-press"
                    :class="Number(activeTask.completed) === 1 ? 'bg-slate-700 hover:bg-slate-800' : 'bg-blue-600 hover:bg-blue-700'">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                    <span x-text="Number(activeTask.completed) === 1 ? 'Reopen Task' : 'Mark as Completed'">Mark as Completed</span>
                  </button>

                  <!-- Edit Task -->
                  <button @click="openEditTaskScreen(activeTask)" class="w-full py-3 rounded-2xl bg-white border border-slate-200/90 hover:bg-slate-50 text-slate-800 font-extrabold text-sm flex items-center justify-center gap-2 shadow-pocket transition-all touch-press">
                    <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                    <span>Edit Task</span>
                  </button>
                </div>

              </div>
            </template>
          </div>


          <!-- ===================================================================
               SCREEN 4: EDIT TASK SCREEN (Exact Match Screen 4)
               =================================================================== -->
          <div x-show="currentView === 'task_edit'" class="space-y-4 pb-8" x-cloak>
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5">
              
              <!-- Task Title -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Task Title <span class="text-rose-500">*</span></label>
                <input type="text" x-model="taskForm.title" placeholder="Enter task title..." required class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:bg-white focus:border-blue-500 focus:outline-none"/>
              </div>

              <!-- Description -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Description</label>
                <textarea x-model="taskForm.description" rows="3" placeholder="Enter description..." class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:bg-white focus:border-blue-500 focus:outline-none"></textarea>
              </div>

              <!-- Project -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Project</label>
                <select x-model="taskForm.project_id" @change="onProjectSelectChange($event)" class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:bg-white focus:border-blue-500 focus:outline-none">
                  <option value="">Select Project</option>
                  <template x-for="p in projects" :key="p.id">
                    <option :value="p.id" x-text="p.title"></option>
                  </template>
                </select>
              </div>

              <!-- Assign To Section -->
              <div>
                <div class="flex items-center justify-between mb-1.5">
                  <label class="block text-xs font-bold text-slate-800 dark:text-slate-200">Assign To</label>
                  <button type="button" @click="openTaskAssigneesModal()" 
                    class="text-[11px] font-bold text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 hover:underline flex items-center gap-1 touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                    <span>+ Add Members</span>
                  </button>
                </div>

                <!-- Field Container: Shows either placeholder + Add button or Member chips + Add button -->
                <div class="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl min-h-[46px] flex flex-wrap items-center gap-2 transition-all">
                  
                  <!-- Empty State: "[ Select team members... ] [ + Add Members ]" -->
                  <div x-show="!taskForm.selected_members || taskForm.selected_members.length === 0" class="w-full flex items-center justify-between gap-2">
                    <button type="button" @click="openTaskAssigneesModal()" 
                      class="flex-1 text-left text-xs font-medium text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 flex items-center gap-2 cursor-pointer">
                      <svg class="w-4 h-4 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                      <span>Select team members...</span>
                    </button>
                    <button type="button" @click="openTaskAssigneesModal()" 
                      class="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold flex items-center gap-1 shadow-xs touch-press transition-colors shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                      <span>+ Add Members</span>
                    </button>
                  </div>

                  <!-- Member Chips List when members are selected -->
                  <template x-for="m in taskForm.selected_members" :key="m.id">
                    <div class="inline-flex items-center gap-1.5 pl-1.5 pr-2 py-1 bg-white dark:bg-slate-800 border border-slate-200/90 dark:border-slate-700 rounded-lg shadow-2xs text-xs font-bold text-slate-800 dark:text-slate-100 group transition-all">
                      <!-- Profile Picture / Initials Avatar -->
                      <template x-if="m.avatar_url">
                        <img :src="m.avatar_url" class="w-5 h-5 rounded-full object-cover shrink-0" :alt="m.name"/>
                      </template>
                      <template x-if="!m.avatar_url">
                        <div class="w-5 h-5 rounded-full text-white text-[9px] font-extrabold flex items-center justify-center shrink-0"
                          :class="m.color_class || 'bg-blue-600'">
                          <span x-text="m.initials || m.name.substring(0, 2).toUpperCase()"></span>
                        </div>
                      </template>
                      
                      <!-- Name chip text -->
                      <span class="truncate max-w-[140px]" x-text="(m.initials ? m.initials + ' — ' : '') + m.name"></span>
                      
                      <!-- Remove (x) Button -->
                      <button type="button" @click.stop="removeMemberFromTask(m.id)" 
                        class="text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 rounded-full p-0.5 ml-0.5 touch-press transition-colors" 
                        title="Remove member">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                      </button>
                    </div>
                  </template>

                  <!-- [+ Add Members] Button beside chips -->
                  <button type="button" x-show="taskForm.selected_members && taskForm.selected_members.length > 0" 
                    @click="openTaskAssigneesModal()" 
                    class="inline-flex items-center gap-1 px-2.5 py-1 bg-blue-50 dark:bg-blue-900/40 hover:bg-blue-100 dark:hover:bg-blue-900/60 text-blue-600 dark:text-blue-300 border border-blue-200/80 dark:border-blue-800 rounded-lg text-xs font-bold touch-press transition-colors">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                    <span>+ Add Members</span>
                  </button>

                </div>
              </div>

              <!-- Priority -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Priority</label>
                <div class="grid grid-cols-3 gap-2">
                  <button type="button" @click="taskForm.priority = 'Low'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'Low' ? 'bg-emerald-50 text-emerald-700 border-emerald-300 ring-2 ring-emerald-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    Low
                  </button>
                  <button type="button" @click="taskForm.priority = 'Medium'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'Medium' ? 'bg-amber-50 text-amber-700 border-amber-300 ring-2 ring-amber-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    Medium
                  </button>
                  <button type="button" @click="taskForm.priority = 'High'" 
                    class="py-2 text-xs font-bold rounded-xl border transition-all text-center touch-press"
                    :class="taskForm.priority === 'High' ? 'bg-rose-50 text-rose-700 border-rose-300 ring-2 ring-rose-400/30 font-extrabold' : 'bg-slate-50 text-slate-600 border-slate-200'">
                    High
                  </button>
                </div>
              </div>

              <!-- Due Date -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Due Date</label>
                <input type="date" x-model="taskForm.due_date" class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:bg-white focus:border-blue-500 focus:outline-none"/>
              </div>

              <!-- Status -->
              <div>
                <label class="block text-xs font-bold text-slate-800 mb-1.5">Status</label>
                <select x-model="taskForm.status" class="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:bg-white focus:border-blue-500 focus:outline-none">
                  <option value="In Progress">In Progress</option>
                  <option value="Completed">Completed</option>
                  <option value="Pending">Pending</option>
                </select>
              </div>

              <!-- Update Task Button -->
              <button @click="submitTaskForm()" class="w-full py-3 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white font-extrabold text-sm shadow-lg shadow-blue-500/25 transition-all touch-press mt-2">
                Update Task
              </button>

            </div>
          </div>


          <!-- ===================================================================
               CALENDAR VIEW (Exact Reference Implementation)
               =================================================================== -->
          <div x-show="currentView === 'calendar'" class="space-y-4 pb-20">
            
            <!-- 1. Calendar Card (Exact Match Reference) -->
            <div class="bg-white rounded-3xl border border-slate-200/80 p-4 shadow-pocket">
              
              <!-- Month Navigation Bar -->
              <div class="flex items-center justify-between mb-4">
                <button @click="prevCalendarMonth()" 
                  type="button"
                  class="w-8 h-8 rounded-full border border-slate-200 flex items-center justify-center text-slate-500 hover:text-blue-600 hover:border-blue-300 transition-all touch-press"
                  title="Previous Month">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
                </button>

                <div class="text-center">
                  <h3 class="text-base font-extrabold text-slate-900" x-text="calendarMonthTitle">October 2026</h3>
                  <p class="text-[11px] font-medium text-slate-400 mt-0.5" x-text="calendarMonthSubTitle">Friday, October 23, 2026</p>
                </div>

                <div class="flex items-center gap-1.5">
                  <button @click="jumpToToday()" 
                    type="button"
                    class="px-2.5 py-1 rounded-full bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold text-xs transition-colors touch-press">
                    Today
                  </button>
                  <button @click="nextCalendarMonth()" 
                    type="button"
                    class="w-8 h-8 rounded-full border border-slate-200 flex items-center justify-center text-slate-500 hover:text-blue-600 hover:border-blue-300 transition-all touch-press"
                    title="Next Month">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                  </button>
                </div>
              </div>

              <!-- Weekday Headers -->
              <div class="grid grid-cols-7 gap-1 text-center font-bold text-xs text-slate-400 mb-2">
                <div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div>
              </div>

              <!-- Calendar 7xN Monthly Grid -->
              <div class="grid grid-cols-7 gap-1 text-center">
                <template x-for="day in calendarGridDays" :key="day.dateStr">
                  <button @click="selectCalendarDate(day.dateStr)"
                    type="button"
                    class="h-10 w-full rounded-2xl flex flex-col items-center justify-center relative transition-all touch-press"
                    :class="{
                      'bg-blue-600 text-white font-extrabold shadow-md shadow-blue-500/30 scale-105 z-10': day.isSelected,
                      'bg-blue-50 text-blue-700 font-bold border border-blue-200/90': day.isToday && !day.isSelected,
                      'bg-emerald-50 text-emerald-800 font-bold': day.hasEvents && !day.isSelected && !day.isToday && !day.hasHoliday,
                      'bg-rose-50 text-rose-700 font-bold': day.hasHoliday && !day.isSelected && !day.isToday,
                      'text-slate-300 font-normal': !day.isCurrentMonth && !day.isSelected,
                      'text-slate-800 font-bold hover:bg-slate-50': day.isCurrentMonth && !day.isSelected && !day.isToday && !day.hasEvents && !day.hasHoliday
                    }">
                    <span class="text-xs leading-none" x-text="day.dayNum"></span>

                    <!-- Indicator Dots Container -->
                    <div class="flex items-center justify-center gap-0.5 mt-1 h-1.5" x-show="!day.isSelected">
                      <template x-if="day.isToday">
                        <span class="w-1.5 h-1.5 rounded-full bg-blue-600"></span>
                      </template>
                      <template x-if="day.hasEvents">
                        <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                      </template>
                      <template x-if="day.hasHoliday">
                        <span class="w-1.5 h-1.5 rounded-full bg-rose-500"></span>
                      </template>
                      <template x-if="day.hasTasks">
                        <span class="w-1.5 h-1.5 rounded-full bg-amber-500"></span>
                      </template>
                    </div>

                    <!-- White Dot when Selected -->
                    <div class="flex items-center justify-center mt-1 h-1.5" x-show="day.isSelected">
                      <span class="w-1.5 h-1.5 rounded-full bg-white/90"></span>
                    </div>
                  </button>
                </template>
              </div>

              <!-- Legend (Exact Reference Implementation) -->
              <div class="flex items-center justify-between text-[10px] font-bold text-slate-500 pt-3 mt-3 border-t border-slate-100 overflow-x-auto no-scrollbar gap-2">
                <div class="flex items-center gap-1.5 shrink-0">
                  <span class="w-2.5 h-2.5 rounded-full bg-blue-600"></span>
                  <span>Selected Date</span>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                  <span class="w-2.5 h-2.5 rounded-full bg-blue-300"></span>
                  <span>Today</span>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                  <span class="w-2.5 h-2.5 rounded-full bg-emerald-500"></span>
                  <span>Event</span>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                  <span class="w-2.5 h-2.5 rounded-full bg-rose-500"></span>
                  <span>Holiday</span>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                  <span class="w-2.5 h-2.5 rounded-full bg-amber-500"></span>
                  <span>Task Due</span>
                </div>
              </div>

            </div>

            <!-- 2. Selected Date Agenda Card (Exact Reference Implementation) -->
            <div class="bg-white rounded-3xl border border-slate-200/80 p-4 shadow-pocket">
              
              <!-- Agenda Header -->
              <div class="flex items-center justify-between mb-4 pb-3 border-b border-slate-100">
                <div class="flex items-center gap-3 min-w-0">
                  <div class="w-10 h-10 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                  </div>
                  <div class="min-w-0">
                    <h4 class="text-sm font-extrabold text-slate-900 truncate" x-text="selectedDateFormattedTitle">Friday, October 23, 2026</h4>
                    <p class="text-xs font-semibold text-slate-400 mt-0.5" x-text="selectedDateCountsText">3 Events • 1 Task • 1 Holiday</p>
                  </div>
                </div>

                <button @click="openAddEventModal()" 
                  type="button"
                  class="px-3.5 py-1.5 rounded-full bg-blue-50 hover:bg-blue-600 text-blue-600 hover:text-white font-extrabold text-xs flex items-center gap-1 transition-all touch-press shrink-0">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                  <span>Add Event</span>
                </button>
              </div>

              <!-- Agenda Items List -->
              <div class="space-y-2.5">
                <template x-for="item in selectedDateAgendaItems" :key="item.id">
                  <div class="p-3 bg-white rounded-2xl border border-slate-100 hover:border-slate-200 shadow-xs flex items-center justify-between gap-3 transition">
                    
                    <!-- Time Column -->
                    <div class="w-16 shrink-0 text-left">
                      <template x-if="item.time === 'All Day'">
                        <span class="text-xs font-black text-slate-800">All Day</span>
                      </template>
                      <template x-if="item.time !== 'All Day'">
                        <div>
                          <div class="text-xs font-extrabold text-slate-800" x-text="item.time">09:00 AM</div>
                          <div class="text-[10px] font-semibold text-slate-400" x-text="item.endTime || ''">10:00 AM</div>
                        </div>
                      </template>
                    </div>

                    <!-- Vertical Accent Line -->
                    <div class="w-1 self-stretch rounded-full shrink-0" :style="'background-color: ' + item.color"></div>

                    <!-- Content Column -->
                    <div class="flex-1 min-w-0">
                      <div class="flex items-center gap-1.5">
                        <template x-if="item.type === 'holiday'">
                          <svg class="w-3.5 h-3.5 text-rose-500 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                        </template>
                        <h5 class="text-xs font-extrabold text-slate-900 truncate" x-text="item.title">Team Meeting</h5>
                      </div>
                      <p class="text-[11px] font-medium text-slate-400 truncate mt-0.5" x-text="item.location">Internal • Conference Room</p>
                    </div>

                    <!-- Right Category Badge & Options -->
                    <div class="flex items-center gap-2 shrink-0">
                      <span class="px-2.5 py-1 rounded-full text-[10px] font-extrabold"
                        :class="item.badgeClass"
                        x-text="item.badgeText">Meeting</span>
                      
                      <!-- 3-dots action menu for events and tasks -->
                      <button @click="openEventActionMenu(item)" 
                        type="button"
                        class="p-1 text-slate-300 hover:text-slate-700 rounded-lg hover:bg-slate-50 transition touch-press"
                        title="Options">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
                      </button>
                    </div>

                  </div>
                </template>

                <!-- Empty State -->
                <div x-show="selectedDateAgendaItems.length === 0" class="py-10 text-center">
                  <div class="w-12 h-12 mx-auto rounded-2xl bg-slate-50 text-slate-300 flex items-center justify-center mb-2">
                    <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                  </div>
                  <p class="text-xs font-bold text-slate-600">No events scheduled for this date.</p>
                  <button @click="openAddEventModal()" type="button" class="mt-3 px-4 py-1.5 rounded-full bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-sm transition touch-press">
                    + Add Event
                  </button>
                </div>
              </div>

            </div>

          </div>


          <!-- ===================================================================
               SCREEN 1: INVOICES DASHBOARD (Exact Match Reference Image Screen 1)
               =================================================================== -->
          <div x-show="currentView === 'invoices'" class="space-y-3.5 pb-8" x-cloak>

            <!-- 1. Four Summary Cards (Responsive: 1-col mobile, 2-col tablet, 4-col laptop/desktop) -->
            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
              <!-- Total Invoiced -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-3 shadow-pocket flex items-center gap-2.5">
                <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-medium text-slate-500 truncate">Total Invoiced</div>
                  <div class="text-sm font-black text-slate-900 tracking-tight" x-text="formatMoney(summaryTotalInvoiced)"></div>
                </div>
              </div>

              <!-- Paid -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-3 shadow-pocket flex items-center gap-2.5">
                <div class="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center shrink-0">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-medium text-slate-500 truncate">Paid</div>
                  <div class="text-sm font-black text-slate-900 tracking-tight" x-text="formatMoney(summaryTotalPaid)"></div>
                </div>
              </div>

              <!-- Pending -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-3 shadow-pocket flex items-center gap-2.5">
                <div class="w-10 h-10 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center shrink-0">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-medium text-slate-500 truncate">Pending</div>
                  <div class="text-sm font-black text-slate-900 tracking-tight" x-text="formatMoney(summaryTotalPending)"></div>
                </div>
              </div>

              <!-- Overdue -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-3 shadow-pocket flex items-center gap-2.5">
                <div class="w-10 h-10 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center shrink-0">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-medium text-slate-500 truncate">Overdue</div>
                  <div class="text-sm font-black text-slate-900 tracking-tight" x-text="formatMoney(summaryTotalOverdue)"></div>
                </div>
              </div>
            </div>

            <!-- 2. Search Bar -->
            <div class="relative">
              <input type="text" x-model="invoiceSearchQuery" placeholder="Search invoices, clients..." 
                class="w-full bg-white border border-slate-200/90 rounded-2xl pl-10 pr-9 py-2.5 text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 shadow-xs transition-all">
              <div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
              </div>
              <button x-show="invoiceSearchQuery" @click="invoiceSearchQuery = ''" class="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <!-- 3. Dynamic Filter Pills: All (12), Paid (8), Pending (2), Overdue (2) -->
            <div class="flex items-center gap-2 overflow-x-auto no-scrollbar py-0.5 text-xs font-bold">
              <button @click="invoiceFilter = 'all'" 
                class="px-3.5 py-1.5 rounded-full transition-all shrink-0 touch-press"
                :class="invoiceFilter === 'all' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>All</span>
                <span class="ml-1 opacity-90" x-text="'(' + countAllInvoices + ')'"></span>
              </button>
              <button @click="invoiceFilter = 'Paid'" 
                class="px-3.5 py-1.5 rounded-full transition-all shrink-0 touch-press"
                :class="invoiceFilter === 'Paid' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>Paid</span>
                <span class="ml-1 opacity-90" x-text="'(' + countPaidInvoices + ')'"></span>
              </button>
              <button @click="invoiceFilter = 'Pending'" 
                class="px-3.5 py-1.5 rounded-full transition-all shrink-0 touch-press"
                :class="invoiceFilter === 'Pending' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>Pending</span>
                <span class="ml-1 opacity-90" x-text="'(' + countPendingInvoices + ')'"></span>
              </button>
              <button @click="invoiceFilter = 'Overdue'" 
                class="px-3.5 py-1.5 rounded-full transition-all shrink-0 touch-press"
                :class="invoiceFilter === 'Overdue' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>Overdue</span>
                <span class="ml-1 opacity-90" x-text="'(' + countOverdueInvoices + ')'"></span>
              </button>
            </div>

            <!-- 4. Invoice List Cards (Responsive: 1-col mobile, 2-col tablet, 3-col desktop) -->
            <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3.5 space-y-0">
              <template x-for="inv in filteredInvoices" :key="inv.id">
                <div @click="openInvoiceDetail(inv)" 
                  class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between gap-3 cursor-pointer hover:border-blue-300 hover:shadow-md transition-all active:scale-[0.99] touch-press">
                  
                  <!-- Left: INV Badge + Number + Customer + Dates -->
                  <div class="flex items-center gap-3 min-w-0">
                    <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xs shrink-0 tracking-wider">
                      INV
                    </div>
                    <div class="min-w-0">
                      <div class="text-xs font-black text-slate-900 truncate" x-text="inv.invoice_no || inv.id"></div>
                      <div class="text-[11px] text-slate-500 font-semibold truncate mt-0.5" x-text="inv.customer_name || 'Valued Client'"></div>
                      <div class="flex items-center gap-1.5 text-[10px] text-slate-400 mt-0.5">
                        <svg class="w-3 h-3 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                        <span x-text="(inv.issue_date || 'Today') + (inv.due_date ? ' • Due: ' + inv.due_date : '')"></span>
                      </div>
                    </div>
                  </div>

                  <!-- Right: Status Pill + Amount + Chevron -->
                  <div class="flex items-center gap-2.5 shrink-0">
                    <div class="text-right">
                      <span class="px-2.5 py-0.5 rounded-full text-[9px] font-extrabold inline-block"
                        :class="getInvoiceStatusClass(inv)"
                        x-text="getInvoiceEffectiveStatus(inv)"></span>
                      <div class="text-xs font-black text-slate-900 mt-1" x-text="formatMoney(inv.amount)"></div>
                    </div>
                    <svg class="w-4 h-4 text-slate-300 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M9 5l7 7-7 7"/></svg>
                  </div>

                </div>
              </template>

              <!-- Empty State -->
              <div x-show="filteredInvoices.length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket">
                <div class="w-12 h-12 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mx-auto mb-2.5 shadow-xs">
                  <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 14l6-6m-5.5.5h.01m4.99 5h.01M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16l3.5-2 3.5 2 3.5-2 3.5 2z"/></svg>
                </div>
                <div class="text-xs font-bold text-slate-800">No invoices found</div>
                <p class="text-[11px] text-slate-400 mt-0.5">Try adjusting your search query or filter</p>
              </div>
            </div>

          </div>


          <!-- ===================================================================
               SCREEN 2: INVOICE DETAILS / ITEMIZED BILL (Exact Match Screen 2)
               =================================================================== -->
          <div x-show="currentView === 'invoice_detail'" class="max-w-4xl mx-auto w-full space-y-3 pb-8" x-cloak>
            <template x-if="activeInvoice">
              <div class="space-y-3">

                <!-- 1. Top Header Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3.5">
                  <div class="flex items-center justify-between">
                    <div class="flex items-center gap-3 min-w-0">
                      <div class="w-11 h-11 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xs shrink-0 tracking-wider shadow-xs">
                        INV
                      </div>
                      <div class="min-w-0">
                        <div class="text-sm font-black text-slate-900 truncate" x-text="activeInvoice.invoice_no || activeInvoice.id"></div>
                        <div class="text-xs text-slate-500 font-semibold truncate mt-0.5" x-text="activeInvoice.customer_name || 'Valued Client'"></div>
                      </div>
                    </div>
                    <span class="px-3 py-1 rounded-full text-[10px] font-extrabold shrink-0"
                      :class="getInvoiceStatusClass(activeInvoice)"
                      x-text="getInvoiceEffectiveStatus(activeInvoice)"></span>
                  </div>

                  <!-- Two Date Grid: Issue Date & Due Date -->
                  <div class="grid grid-cols-2 gap-2 pt-2 border-t border-slate-100">
                    <div class="flex items-center gap-2 p-2 bg-slate-50/80 rounded-xl border border-slate-100">
                      <div class="w-7 h-7 rounded-lg bg-blue-100/60 text-blue-600 flex items-center justify-center shrink-0">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Issue Date</div>
                        <div class="text-xs font-black text-slate-900 truncate" x-text="activeInvoice.issue_date || 'Today'"></div>
                      </div>
                    </div>
                    <div class="flex items-center gap-2 p-2 bg-slate-50/80 rounded-xl border border-slate-100">
                      <div class="w-7 h-7 rounded-lg bg-amber-100/60 text-amber-600 flex items-center justify-center shrink-0">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                      </div>
                      <div class="min-w-0">
                        <div class="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Due Date</div>
                        <div class="text-xs font-black text-slate-900 truncate" x-text="activeInvoice.due_date || 'Due on receipt'"></div>
                      </div>
                    </div>
                  </div>
                </div>

                <!-- 2. Itemized Bill Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                  <h3 class="text-xs font-black text-slate-900 tracking-tight">Itemized Bill</h3>

                  <!-- Table -->
                  <div class="border border-slate-200/90 rounded-xl overflow-hidden">
                    <table class="w-full text-left text-xs">
                      <thead class="bg-slate-50 border-b border-slate-200/80 text-[10px] font-bold text-slate-500 uppercase tracking-wider">
                        <tr>
                          <th class="py-2.5 px-3">Description</th>
                          <th class="py-2.5 px-2 text-center">Qty</th>
                          <th class="py-2.5 px-2 text-right whitespace-nowrap">Rate (₹)</th>
                          <th class="py-2.5 px-3 text-right whitespace-nowrap">Amount (₹)</th>
                        </tr>
                      </thead>
                      <tbody class="divide-y divide-slate-100 text-[11px]">
                        <template x-for="item in (activeInvoice.items || [])" :key="item.id || item.description">
                          <tr>
                            <td class="py-2.5 px-3 font-semibold text-slate-800" x-text="item.description"></td>
                            <td class="py-2.5 px-2 text-center text-slate-600" x-text="item.quantity || 1"></td>
                            <td class="py-2.5 px-2 text-right text-slate-600 font-mono" x-text="Number(item.rate || 0).toLocaleString('en-IN')"></td>
                            <td class="py-2.5 px-3 text-right font-bold text-slate-900 font-mono" x-text="Number(item.amount || 0).toLocaleString('en-IN')"></td>
                          </tr>
                        </template>
                      </tbody>
                    </table>
                  </div>

                  <!-- Financial Summary Block -->
                  <div class="pt-2 space-y-1.5 text-xs text-slate-600">
                    <div class="flex justify-between items-center">
                      <span class="font-medium">Subtotal</span>
                      <span class="font-bold text-slate-900 font-mono" x-text="formatMoney(activeInvoice.subtotal || activeInvoice.amount)"></span>
                    </div>

                    <template x-if="Number(activeInvoice.discount_percent) > 0 || Number(activeInvoice.discount_amount) > 0">
                      <div class="flex justify-between items-center text-rose-600">
                        <span class="font-medium" x-text="'Discount (' + (activeInvoice.discount_percent || 0) + '%)'"></span>
                        <span class="font-bold font-mono" x-text="'- ' + formatMoney(activeInvoice.discount_amount || 0)"></span>
                      </div>
                    </template>

                    <template x-if="Number(activeInvoice.tax_percent) > 0 || Number(activeInvoice.tax_amount) > 0">
                      <div class="flex justify-between items-center text-slate-700">
                        <span class="font-medium" x-text="'GST (' + (activeInvoice.tax_percent || 0) + '%)'"></span>
                        <span class="font-bold font-mono" x-text="formatMoney(activeInvoice.tax_amount || 0)"></span>
                      </div>
                    </template>

                    <div class="flex justify-between items-center pt-2 border-t border-slate-100 text-sm font-black text-slate-900">
                      <span>Total Amount</span>
                      <span class="text-base text-slate-900 font-black font-mono" x-text="formatMoney(activeInvoice.amount)"></span>
                    </div>

                    <template x-if="Number(activeInvoice.paid_amount) > 0">
                      <div class="flex justify-between items-center text-xs text-emerald-600 pt-1">
                        <span class="font-bold">Total Paid to Date</span>
                        <span class="font-bold font-mono" x-text="formatMoney(activeInvoice.paid_amount)"></span>
                      </div>
                    </template>

                    <template x-if="Number(activeInvoice.balance_amount) > 0 && activeInvoice.status !== 'Paid'">
                      <div class="flex justify-between items-center text-xs text-amber-600 pt-0.5">
                        <span class="font-bold">Remaining Balance</span>
                        <span class="font-black font-mono" x-text="formatMoney(activeInvoice.balance_amount)"></span>
                      </div>
                    </template>
                  </div>
                </div>

                <!-- 3. Notes / Deliverables Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                  <div class="flex items-center gap-2">
                    <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                    <h3 class="text-xs font-black text-slate-900 tracking-tight">Notes / Deliverables</h3>
                  </div>
                  <div class="text-[11px] text-slate-600 whitespace-pre-line leading-relaxed pl-6" x-text="activeInvoice.notes || '• Complete website development as per scope\n• Source code and documentation will be provided\n• 3 months of post-launch support'"></div>
                </div>

                <!-- 4. Payment Terms Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                  <div class="flex items-center gap-2">
                    <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    <h3 class="text-xs font-black text-slate-900 tracking-tight">Payment Terms</h3>
                  </div>
                  <div class="text-[11px] text-slate-600 leading-relaxed pl-6" x-text="activeInvoice.terms || '50% advance, 50% on project completion.'"></div>
                </div>

                <!-- 5. Action Buttons -->
                <div class="space-y-2.5 pt-1">
                  <!-- Row 1: Download PDF & Share Invoice -->
                  <div class="flex gap-2">
                    <button @click="downloadInvoicePdf(activeInvoice)" 
                      class="flex-1 py-2.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-2 touch-press">
                      <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                      <span>Download PDF</span>
                    </button>
                    <button @click="shareInvoice(activeInvoice)" 
                      class="flex-1 py-2.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-2 touch-press">
                      <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                      <span>Share Invoice</span>
                    </button>
                  </div>

                  <!-- Row 2: Record Payment (Primary Blue Button) -->
                  <template x-if="activeInvoice.status !== 'Paid' || Number(activeInvoice.balance_amount) > 0">
                    <button @click="openRecordPaymentModal(activeInvoice)" 
                      class="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-md shadow-blue-500/25 flex items-center justify-center gap-2 touch-press">
                      <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"/></svg>
                      <span>Record Payment</span>
                    </button>
                  </template>
                </div>

              </div>
            </template>
          </div>


          <!-- ===================================================================
               SCREEN 3: PAYMENT RECEIPT (Exact Match Reference Image Screen 3)
               =================================================================== -->
          <div x-show="currentView === 'payment_receipt'" class="space-y-3.5 pb-8" x-cloak>
            <template x-if="activePaymentReceipt">
              <div class="space-y-3.5">

                <!-- 1. Success Icon & Header -->
                <div class="text-center pt-2 pb-1">
                  <div class="w-16 h-16 rounded-full bg-emerald-500 text-white flex items-center justify-center mx-auto mb-3 shadow-lg shadow-emerald-500/30 ring-8 ring-emerald-50">
                    <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                  </div>
                  <h2 class="text-lg font-black text-slate-900 tracking-tight">Payment Successful!</h2>
                  <p class="text-xs text-slate-400 mt-1">The payment has been recorded successfully.</p>
                </div>

                <!-- 2. Receipt Card -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3.5">
                  <!-- Receipt Top Row: Icon + No + Date -->
                  <div class="flex items-center justify-between pb-3 border-b border-slate-100">
                    <div class="flex items-center gap-2.5">
                      <div class="w-9 h-9 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center shrink-0">
                        <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                      </div>
                      <div>
                        <div class="text-[10px] text-slate-400 font-semibold">Receipt No.</div>
                        <div class="text-xs font-black text-slate-900 font-mono" x-text="activePaymentReceipt.receipt_no || activePaymentReceipt.id"></div>
                      </div>
                    </div>
                    <div class="text-right">
                      <div class="text-xs font-bold text-slate-700" x-text="activePaymentReceipt.payment_date || 'Today'"></div>
                      <div class="text-[10px] text-slate-400">Recorded</div>
                    </div>
                  </div>

                  <!-- Two Column Grid Info -->
                  <div class="space-y-2 text-xs">
                    <div class="flex justify-between items-center">
                      <span class="text-slate-500 font-medium">Invoice No.</span>
                      <button @click="openInvoiceByNo(activePaymentReceipt.invoice_no)" class="font-bold text-blue-600 hover:underline font-mono" x-text="activePaymentReceipt.invoice_no"></button>
                    </div>

                    <div class="flex justify-between items-center">
                      <span class="text-slate-500 font-medium">Client / Company</span>
                      <span class="font-bold text-slate-900" x-text="activePaymentReceipt.customer_name"></span>
                    </div>

                    <div class="flex justify-between items-center">
                      <span class="text-slate-500 font-medium">Payment Status</span>
                      <span class="px-2.5 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-50 text-emerald-700 border border-emerald-200/60"
                        x-text="activePaymentReceipt.status || 'Paid'"></span>
                    </div>
                  </div>

                  <!-- Amount Paid Highlight Box -->
                  <div class="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                    <span class="text-xs font-bold text-slate-600">Amount Paid</span>
                    <span class="text-lg font-black text-slate-900 font-mono tracking-tight" x-text="formatMoney(activePaymentReceipt.amount)"></span>
                  </div>

                  <!-- Payment Details -->
                  <div class="space-y-2 text-xs pt-1 border-t border-slate-100 text-slate-600">
                    <div class="flex justify-between items-center">
                      <span class="font-medium">Payment Date</span>
                      <span class="font-semibold text-slate-900" x-text="activePaymentReceipt.payment_date"></span>
                    </div>

                    <div class="flex justify-between items-center">
                      <span class="font-medium">Payment Method</span>
                      <span class="font-semibold text-slate-900" x-text="activePaymentReceipt.payment_method || 'Online Transfer'"></span>
                    </div>

                    <template x-if="activePaymentReceipt.transaction_id">
                      <div class="flex justify-between items-center">
                        <span class="font-medium">Transaction ID</span>
                        <span class="font-mono text-slate-800 text-[11px]" x-text="activePaymentReceipt.transaction_id"></span>
                      </div>
                    </template>

                    <template x-if="activePaymentReceipt.reference">
                      <div class="flex justify-between items-center">
                        <span class="font-medium">Reference</span>
                        <span class="text-slate-800 text-[11px] font-medium" x-text="activePaymentReceipt.reference"></span>
                      </div>
                    </template>
                  </div>

                  <!-- Balance Summary Box -->
                  <div class="p-3 bg-slate-50/80 rounded-xl border border-slate-100 space-y-1.5 text-xs">
                    <div class="flex justify-between text-slate-500">
                      <span>Invoice Total</span>
                      <span class="font-semibold text-slate-800 font-mono" x-text="formatMoney(activePaymentReceipt.invoice_total || (activeInvoice ? activeInvoice.amount : activePaymentReceipt.amount))"></span>
                    </div>
                    <div class="flex justify-between text-slate-500">
                      <span>Amount Paid</span>
                      <span class="font-semibold text-slate-800 font-mono" x-text="formatMoney(activePaymentReceipt.amount)"></span>
                    </div>
                    <div class="flex justify-between items-center pt-1.5 border-t border-slate-200/60 font-bold">
                      <span class="text-slate-800">Remaining Balance</span>
                      <span class="font-black font-mono text-sm" 
                        :class="Number(activePaymentReceipt.balance_amount) <= 0 ? 'text-emerald-600' : 'text-amber-600'"
                        x-text="formatMoney(activePaymentReceipt.balance_amount || 0)"></span>
                    </div>
                  </div>

                </div>

                <!-- 3. Bottom Action Buttons -->
                <div class="space-y-2 pt-1">
                  <button @click="downloadReceiptPdf(activePaymentReceipt)" 
                    class="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-md shadow-blue-500/25 flex items-center justify-center gap-2 touch-press">
                    <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                    <span>Download Receipt PDF</span>
                  </button>

                  <button @click="shareReceipt(activePaymentReceipt)" 
                    class="w-full py-2.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-2 touch-press">
                    <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                    <span>Share Receipt</span>
                  </button>

                  <button @click="navigateTo('invoices')" 
                    class="w-full py-2.5 text-center text-xs font-bold text-slate-500 hover:text-slate-800 touch-press">
                    Back to Invoices
                  </button>
                </div>

              </div>
            </template>
          </div>


          <!-- ===================================================================
               ADDITIONAL SCREENS: COMPANIES, TEAM, REPORTS, SETTINGS
               =================================================================== -->
          <!-- ===================================================================
               SCREEN: COMPANIES LIST (Interactive, Responsive & Connected to API)
               =================================================================== -->
          <div x-show="currentView === 'companies'" class="space-y-3 pb-8" x-cloak>
            
            <!-- Top Controls: Search Bar & Add Button -->
            <div class="flex items-center gap-2">
              <div class="relative flex-1">
                <input type="text" x-model="companySearchQuery" placeholder="Search companies, industry, phone..." 
                  class="w-full bg-white border border-slate-200/90 rounded-2xl pl-10 pr-9 py-2.5 text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 shadow-xs transition-all">
                <div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                </div>
                <button x-show="companySearchQuery" @click="companySearchQuery = ''" class="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <button @click="openAddCompanyModal()" class="px-3.5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold text-xs shadow-xs flex items-center gap-1.5 shrink-0 touch-press transition">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                <span class="hidden sm:inline">Add Company</span>
                <span class="sm:hidden">Add</span>
              </button>
            </div>

            <!-- Header Title & Counter Badge -->
            <div class="flex items-center justify-between px-1">
              <div class="flex items-center gap-2">
                <h2 class="text-base font-extrabold text-slate-900">Companies</h2>
                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-600" x-text="uniqueCompanies.length + ' Total'"></span>
              </div>
              <button @click="loadCompanies()" class="text-[11px] font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1 touch-press" title="Refresh Companies">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                <span>Refresh</span>
              </button>
            </div>

            <!-- Loading Skeleton -->
            <div x-show="companiesLoading" class="space-y-2">
              <div class="p-3.5 bg-white rounded-2xl border border-slate-200/80 animate-pulse flex items-center gap-3">
                <div class="w-10 h-10 rounded-xl bg-slate-200"></div>
                <div class="space-y-2 flex-1">
                  <div class="h-3.5 bg-slate-200 rounded w-1/3"></div>
                  <div class="h-2.5 bg-slate-100 rounded w-1/4"></div>
                </div>
              </div>
              <div class="p-3.5 bg-white rounded-2xl border border-slate-200/80 animate-pulse flex items-center gap-3">
                <div class="w-10 h-10 rounded-xl bg-slate-200"></div>
                <div class="space-y-2 flex-1">
                  <div class="h-3.5 bg-slate-200 rounded w-1/2"></div>
                  <div class="h-2.5 bg-slate-100 rounded w-1/3"></div>
                </div>
              </div>
            </div>

            <!-- Companies List (Responsive: 1-col mobile, 2-col tablet, 3-col desktop) -->
            <div x-show="!companiesLoading" class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3 space-y-0">
              <template x-for="comp in uniqueCompanies" :key="comp.id || comp.name">
                <div @click="viewCompanyDetail(comp)" 
                  class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 hover:shadow-md transition-all active:scale-[0.99] touch-press group">
                  <div class="flex items-center gap-3 min-w-0">
                    <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-bold text-xs uppercase shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-colors duration-150" 
                      x-text="(comp.name || 'C').substring(0, 2)">C</div>
                    <div class="min-w-0">
                      <div class="flex items-center gap-1.5 flex-wrap">
                        <span class="text-xs font-bold text-slate-900 group-hover:text-blue-600 transition-colors truncate" x-text="comp.name"></span>
                        <template x-if="comp.industry">
                          <span class="px-1.5 py-0.2 rounded text-[9px] font-semibold bg-slate-100 text-slate-600 shrink-0" x-text="comp.industry"></span>
                        </template>
                      </div>
                      <div class="text-[10px] text-slate-400 flex items-center gap-2 mt-0.5">
                        <span x-text="(comp.contacts_count || 0) + ' ' + (comp.contacts_count === 1 ? 'Contact' : 'Contacts')"></span>
                        <template x-if="Number(comp.projects_count) > 0">
                          <span>• <span x-text="comp.projects_count + ' ' + (comp.projects_count === 1 ? 'Project' : 'Projects')"></span></span>
                        </template>
                        <template x-if="comp.phone">
                          <span class="hidden sm:inline">• <span x-text="comp.phone"></span></span>
                        </template>
                      </div>
                    </div>
                  </div>
                  
                  <div class="flex items-center gap-1 shrink-0">
                    <button @click.stop="openEditCompanyModal(comp)" class="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg touch-press transition" title="Edit Company">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                    </button>
                    <svg class="w-4 h-4 text-slate-300 group-hover:text-blue-500 group-hover:translate-x-0.5 transition-transform duration-150" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                  </div>
                </div>
              </template>

              <!-- Empty State -->
              <div x-show="uniqueCompanies.length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                <div class="w-12 h-12 rounded-2xl bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                  <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                </div>
                <div class="text-xs font-bold text-slate-800" x-text="companySearchQuery ? 'No companies match your search' : 'No companies found'"></div>
                <p class="text-[11px] text-slate-400 max-w-xs mx-auto" x-text="companySearchQuery ? 'Try searching by a different name, industry, or clear the search filter.' : 'Get started by creating your first company record.'"></p>
                <button @click="openAddCompanyModal()" class="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-xs inline-flex items-center gap-1.5 touch-press">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                  <span>Add Company</span>
                </button>
              </div>
            </div>

          </div>

          <!-- ===================================================================
               SCREEN: COMPANY DETAILS (Hero, Tabs, Associated Contacts/Projects/Invoices)
               =================================================================== -->
          <div x-show="currentView === 'company_detail'" class="max-w-4xl mx-auto w-full space-y-4 pb-8" x-cloak>
            
            <!-- Hero Card -->
            <div class="bg-white rounded-3xl border border-slate-200/80 p-5 shadow-pocket text-center relative overflow-hidden">
              
              <!-- Company Avatar -->
              <div class="w-20 h-20 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white flex items-center justify-center text-2xl font-bold uppercase mx-auto mb-3 shadow-lg shadow-blue-500/20"
                x-text="activeCompany ? (activeCompany.name || 'C').substring(0, 2) : 'CO'">
                CO
              </div>

              <!-- Company Name & Badges -->
              <div class="flex items-center justify-center gap-2 flex-wrap">
                <h2 class="text-lg font-black text-slate-900" x-text="activeCompany ? activeCompany.name : 'Company Name'"></h2>
                <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-50 text-blue-700 border border-blue-200/60"
                  x-text="activeCompany && activeCompany.industry ? activeCompany.industry : 'Corporate'"></span>
              </div>

              <!-- Company ID Pill -->
              <div class="mt-1 flex items-center justify-center gap-2 text-[10px] text-slate-400 font-mono">
                <span>ID:</span>
                <span class="font-bold text-slate-600 bg-slate-100 px-2 py-0.5 rounded-full" x-text="activeCompany ? activeCompany.id : '—'"></span>
              </div>

              <!-- 4 Quick Action Buttons: Phone, Email, Website, Edit -->
              <div class="grid grid-cols-4 gap-2 mt-5 pt-4 border-t border-slate-100">
                <!-- 1. Phone -->
                <a :href="activeCompany && activeCompany.phone ? 'tel:' + activeCompany.phone : '#'"
                  @click="if (!activeCompany || !activeCompany.phone) { $event.preventDefault(); showToast('No phone number provided', 'error'); }"
                  class="flex flex-col items-center gap-1.5 touch-press group"
                  :class="activeCompany && activeCompany.phone ? '' : 'opacity-50'">
                  <div class="w-11 h-11 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Call</span>
                </a>

                <!-- 2. Email -->
                <a :href="activeCompany && activeCompany.email ? 'mailto:' + activeCompany.email : '#'"
                  @click="if (!activeCompany || !activeCompany.email) { $event.preventDefault(); showToast('No email address provided', 'error'); }"
                  class="flex flex-col items-center gap-1.5 touch-press group"
                  :class="activeCompany && activeCompany.email ? '' : 'opacity-50'">
                  <div class="w-11 h-11 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Email</span>
                </a>

                <!-- 3. Website -->
                <a :href="activeCompany && activeCompany.website ? (activeCompany.website.startsWith('http') ? activeCompany.website : 'https://' + activeCompany.website) : '#'"
                  target="_blank" rel="noopener noreferrer"
                  @click="if (!activeCompany || !activeCompany.website) { $event.preventDefault(); showToast('No website provided', 'error'); }"
                  class="flex flex-col items-center gap-1.5 touch-press group"
                  :class="activeCompany && activeCompany.website ? '' : 'opacity-50'">
                  <div class="w-11 h-11 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Website</span>
                </a>

                <!-- 4. Edit -->
                <button @click="openEditCompanyModal(activeCompany)" class="flex flex-col items-center gap-1.5 touch-press group">
                  <div class="w-11 h-11 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center group-hover:scale-105 transition shadow-xs">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                  </div>
                  <span class="text-[11px] font-bold text-slate-700">Edit</span>
                </button>
              </div>

              <!-- 4 Tabs Row: Overview, Contacts, Projects, Invoices -->
              <div class="flex items-center justify-between border-t border-slate-100 mt-5 pt-3 text-xs font-bold overflow-x-auto no-scrollbar">
                <button @click="companyDetailTab = 'overview'" class="pb-1.5 whitespace-nowrap flex items-center gap-1 touch-press" :class="companyDetailTab === 'overview' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">
                  <span>Overview</span>
                </button>
                <button @click="companyDetailTab = 'contacts'" class="pb-1.5 whitespace-nowrap flex items-center gap-1 touch-press" :class="companyDetailTab === 'contacts' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">
                  <span>Contacts</span>
                  <span class="text-[10px] px-1.5 py-0.2 rounded-full" :class="companyDetailTab === 'contacts' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-500'" x-text="(activeCompany && activeCompany.contacts ? activeCompany.contacts.length : 0)"></span>
                </button>
                <button @click="companyDetailTab = 'projects'" class="pb-1.5 whitespace-nowrap flex items-center gap-1 touch-press" :class="companyDetailTab === 'projects' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">
                  <span>Projects</span>
                  <span class="text-[10px] px-1.5 py-0.2 rounded-full" :class="companyDetailTab === 'projects' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-500'" x-text="(activeCompany && activeCompany.projects ? activeCompany.projects.length : 0)"></span>
                </button>
                <button @click="companyDetailTab = 'invoices'" class="pb-1.5 whitespace-nowrap flex items-center gap-1 touch-press" :class="companyDetailTab === 'invoices' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'">
                  <span>Invoices</span>
                  <span class="text-[10px] px-1.5 py-0.2 rounded-full" :class="companyDetailTab === 'invoices' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-500'" x-text="(activeCompany && activeCompany.invoices ? activeCompany.invoices.length : 0)"></span>
                </button>
              </div>

            </div>

            <!-- TAB 1: OVERVIEW -->
            <div x-show="companyDetailTab === 'overview'" class="space-y-3.5">
              
              <!-- Company Info Card -->
              <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3 text-xs">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                  <h3 class="font-extrabold text-slate-900">Company Information</h3>
                  <div class="flex items-center gap-2">
                    <button @click="openEditCompanyModal(activeCompany)" class="text-blue-600 font-bold hover:underline flex items-center gap-1 touch-press text-xs">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                      <span>Edit</span>
                    </button>
                  </div>
                </div>

                <!-- Description / Notes -->
                <div class="space-y-1">
                  <span class="text-slate-400 font-semibold text-[11px]">About / Description</span>
                  <p class="text-slate-700 leading-relaxed text-xs" 
                    x-text="activeCompany && activeCompany.description ? activeCompany.description : 'No description provided.'"></p>
                </div>

                <!-- Key-Value Table -->
                <div class="pt-2 border-t border-slate-100 space-y-2.5 text-[11px]">
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Industry</span>
                    <span class="font-bold text-slate-900" x-text="activeCompany && activeCompany.industry ? activeCompany.industry : 'Not provided'"></span>
                  </div>
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Website</span>
                    <template x-if="activeCompany && activeCompany.website">
                      <a :href="activeCompany.website.startsWith('http') ? activeCompany.website : 'https://' + activeCompany.website" target="_blank" rel="noopener noreferrer" class="font-bold text-blue-600 hover:underline truncate max-w-[200px]" x-text="activeCompany.website"></a>
                    </template>
                    <template x-if="!activeCompany || !activeCompany.website">
                      <span class="font-semibold text-slate-400">Not provided</span>
                    </template>
                  </div>
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Business Email</span>
                    <template x-if="activeCompany && activeCompany.email">
                      <a :href="'mailto:' + activeCompany.email" class="font-bold text-blue-600 hover:underline truncate max-w-[200px]" x-text="activeCompany.email"></a>
                    </template>
                    <template x-if="!activeCompany || !activeCompany.email">
                      <span class="font-semibold text-slate-400">Not provided</span>
                    </template>
                  </div>
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Phone</span>
                    <template x-if="activeCompany && activeCompany.phone">
                      <a :href="'tel:' + activeCompany.phone" class="font-bold text-blue-600 font-mono" x-text="activeCompany.phone"></a>
                    </template>
                    <template x-if="!activeCompany || !activeCompany.phone">
                      <span class="font-semibold text-slate-400">Not provided</span>
                    </template>
                  </div>
                  <div class="flex justify-between items-start gap-4">
                    <span class="text-slate-400 font-semibold shrink-0">Address</span>
                    <span class="font-bold text-slate-900 text-right" x-text="activeCompany && activeCompany.address ? activeCompany.address : 'Not provided'"></span>
                  </div>
                  <div class="flex justify-between items-center">
                    <span class="text-slate-400 font-semibold">Created Date</span>
                    <span class="font-bold text-slate-700" x-text="activeCompany && activeCompany.created_at ? (new Date(activeCompany.created_at)).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }) : '—'"></span>
                  </div>
                </div>
              </div>

              <!-- Danger Zone Card -->
              <div class="bg-rose-50/50 rounded-2xl border border-rose-200/60 p-4 shadow-pocket space-y-2 text-xs">
                <div class="flex items-center justify-between">
                  <div>
                    <h4 class="font-bold text-rose-900">Delete Company</h4>
                    <p class="text-[11px] text-rose-600 mt-0.5">Contacts will be kept safely and unlinked.</p>
                  </div>
                  <button @click="promptDeleteCompany(activeCompany)" class="px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs rounded-xl shadow-xs touch-press transition">
                    Delete
                  </button>
                </div>
              </div>

            </div>

            <!-- TAB 2: ASSOCIATED CONTACTS -->
            <div x-show="companyDetailTab === 'contacts'" class="space-y-3">
              <div class="flex items-center justify-between px-1">
                <h3 class="font-extrabold text-slate-900 text-xs">Associated Contacts</h3>
                <span class="text-[11px] font-bold text-slate-500" x-text="(activeCompany && activeCompany.contacts ? activeCompany.contacts.length : 0) + ' Total'"></span>
              </div>

              <template x-if="activeCompany && activeCompany.contacts && activeCompany.contacts.length > 0">
                <div class="space-y-2">
                  <template x-for="c in activeCompany.contacts" :key="c.id">
                    <div @click="contactReturnView = 'company_detail'; viewContactDetail(c)" 
                      class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 hover:shadow-md transition-all active:scale-[0.99] touch-press group">
                      <div class="flex items-center gap-3 min-w-0">
                        <div class="w-10 h-10 rounded-full flex items-center justify-center font-extrabold text-xs shrink-0 uppercase"
                          :class="(c.category || '').toLowerCase() === 'client' ? 'bg-blue-100 text-blue-700' : ((c.category || '').toLowerCase() === 'lead' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700')"
                          x-text="(c.name || 'C').substring(0, 2)"></div>
                        <div class="min-w-0">
                          <div class="text-xs font-extrabold text-slate-900 group-hover:text-blue-600 transition truncate" x-text="c.name"></div>
                          <div class="text-[11px] text-slate-400 truncate mt-0.5" x-text="c.position || c.phone || c.email || 'Contact'"></div>
                        </div>
                      </div>
                      <div class="flex items-center gap-2 shrink-0">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold capitalize"
                          :class="(c.category || '').toLowerCase() === 'client' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : 'bg-blue-50 text-blue-700 border border-blue-200/60'"
                          x-text="c.category || 'Client'">Client</span>
                        <svg class="w-4 h-4 text-slate-300 group-hover:text-blue-500 group-hover:translate-x-0.5 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                      </div>
                    </div>
                  </template>
                </div>
              </template>

              <!-- Empty Contacts -->
              <template x-if="!activeCompany || !activeCompany.contacts || activeCompany.contacts.length === 0">
                <div class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                  <div class="w-10 h-10 rounded-xl bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  </div>
                  <div class="text-xs font-bold text-slate-700">No Associated Contacts</div>
                  <p class="text-[11px] text-slate-400">No contacts are linked to this company yet.</p>
                </div>
              </template>
            </div>

            <!-- TAB 3: ASSOCIATED PROJECTS -->
            <div x-show="companyDetailTab === 'projects'" class="space-y-3">
              <div class="flex items-center justify-between px-1">
                <h3 class="font-extrabold text-slate-900 text-xs">Associated Projects</h3>
                <span class="text-[11px] font-bold text-slate-500" x-text="(activeCompany && activeCompany.projects ? activeCompany.projects.length : 0) + ' Total'"></span>
              </div>

              <template x-if="activeCompany && activeCompany.projects && activeCompany.projects.length > 0">
                <div class="space-y-2">
                  <template x-for="p in activeCompany.projects" :key="p.id">
                    <div @click="viewProjectDetail(p)" 
                      class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 hover:shadow-md transition-all active:scale-[0.99] touch-press group">
                      <div class="min-w-0">
                        <div class="text-xs font-extrabold text-slate-900 group-hover:text-blue-600 transition truncate" x-text="p.title || p.name"></div>
                        <div class="text-[11px] text-slate-400 flex items-center gap-2 mt-0.5">
                          <span x-text="p.category || 'Software'"></span>
                          <template x-if="p.budget || p.cost">
                            <span>• <span class="font-mono font-bold text-slate-700" x-text="formatMoney(p.budget || p.cost)"></span></span>
                          </template>
                        </div>
                      </div>
                      <div class="flex items-center gap-2 shrink-0">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase"
                          :class="(p.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : 'bg-blue-50 text-blue-700 border border-blue-200/60'"
                          x-text="p.status || 'Active'"></span>
                        <svg class="w-4 h-4 text-slate-300 group-hover:text-blue-500 group-hover:translate-x-0.5 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                      </div>
                    </div>
                  </template>
                </div>
              </template>

              <!-- Empty Projects -->
              <template x-if="!activeCompany || !activeCompany.projects || activeCompany.projects.length === 0">
                <div class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                  <div class="w-10 h-10 rounded-xl bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
                  </div>
                  <div class="text-xs font-bold text-slate-700">No Associated Projects</div>
                  <p class="text-[11px] text-slate-400">No projects are linked to this company yet.</p>
                </div>
              </template>
            </div>

            <!-- TAB 4: ASSOCIATED INVOICES -->
            <div x-show="companyDetailTab === 'invoices'" class="space-y-3">
              <div class="flex items-center justify-between px-1">
                <h3 class="font-extrabold text-slate-900 text-xs">Associated Invoices</h3>
                <span class="text-[11px] font-bold text-slate-500" x-text="(activeCompany && activeCompany.invoices ? activeCompany.invoices.length : 0) + ' Total'"></span>
              </div>

              <template x-if="activeCompany && activeCompany.invoices && activeCompany.invoices.length > 0">
                <div class="space-y-2">
                  <template x-for="inv in activeCompany.invoices" :key="inv.id">
                    <div @click="openInvoiceDetail(inv)" 
                      class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between cursor-pointer hover:border-blue-400 hover:shadow-md transition-all active:scale-[0.99] touch-press group">
                      <div class="min-w-0">
                        <div class="text-xs font-extrabold text-slate-900 group-hover:text-blue-600 transition truncate" x-text="inv.invoice_number || ('INV-' + inv.id)"></div>
                        <div class="text-[11px] text-slate-400 mt-0.5" x-text="inv.issue_date || inv.created_at || '—'"></div>
                      </div>
                      <div class="flex items-center gap-2 shrink-0">
                        <span class="font-mono font-black text-xs text-slate-900" x-text="formatMoney(inv.total_amount || inv.amount)"></span>
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase"
                          :class="(inv.status || '').toLowerCase() === 'paid' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200/60' : 'bg-amber-50 text-amber-700 border border-amber-200/60'"
                          x-text="inv.status || 'Unpaid'"></span>
                        <svg class="w-4 h-4 text-slate-300 group-hover:text-blue-500 group-hover:translate-x-0.5 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                      </div>
                    </div>
                  </template>
                </div>
              </template>

              <!-- Empty Invoices -->
              <template x-if="!activeCompany || !activeCompany.invoices || activeCompany.invoices.length === 0">
                <div class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                  <div class="w-10 h-10 rounded-xl bg-slate-100 text-slate-400 flex items-center justify-center mx-auto">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 14l6-6m0 0l-6-6m6 6H3"/></svg>
                  </div>
                  <div class="text-xs font-bold text-slate-700">No Associated Invoices</div>
                  <p class="text-[11px] text-slate-400">No invoices have been billed to this company yet.</p>
                </div>
              </template>
            </div>

            <!-- Back to Companies Button -->
            <div class="pt-2">
              <button @click="navigateTo('companies')" 
                class="w-full py-2.5 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-2 touch-press">
                <svg class="w-4 h-4 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/></svg>
                <span>Back to Companies</span>
              </button>
            </div>

          </div>

          <!-- ===================================================================
               SCREEN 1: TEAM MEMBERS LIST (Exact Match Reference Image Screen 1)
               =================================================================== -->
          <div x-show="currentView === 'team'" class="space-y-3 pb-8" x-cloak>
            
            <!-- 1. Search Bar (Exact Reference Image Screen 1) -->
            <div class="relative">
              <input type="text" x-model="teamSearchQuery" placeholder="Search team members..." 
                class="w-full bg-white border border-slate-200/90 rounded-2xl pl-10 pr-9 py-2.5 text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 shadow-xs transition-all">
              <div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
              </div>
              <button x-show="teamSearchQuery" @click="teamSearchQuery = ''" class="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <!-- 2. Three Filter Pills: All (12), Active (10), Inactive (2) -->
            <div class="flex items-center gap-2 overflow-x-auto no-scrollbar py-0.5">
              <button @click="teamFilter = 'all'" 
                class="px-3.5 py-1.5 rounded-full text-xs font-bold transition-all shrink-0 touch-press"
                :class="teamFilter === 'all' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>All</span>
                <span class="ml-1 opacity-90" x-text="'(' + allTeamMembersCount + ')'"></span>
              </button>
              <button @click="teamFilter = 'active'" 
                class="px-3.5 py-1.5 rounded-full text-xs font-bold transition-all shrink-0 touch-press"
                :class="teamFilter === 'active' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>Active</span>
                <span class="ml-1 opacity-90" x-text="'(' + activeTeamMembersCount + ')'"></span>
              </button>
              <button @click="teamFilter = 'inactive'" 
                class="px-3.5 py-1.5 rounded-full text-xs font-bold transition-all shrink-0 touch-press"
                :class="teamFilter === 'inactive' ? 'bg-blue-600 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'">
                <span>Inactive</span>
                <span class="ml-1 opacity-90" x-text="'(' + inactiveTeamMembersCount + ')'"></span>
              </button>
            </div>

            <!-- 3. Dynamic Team Member Cards List (Responsive: 1-col mobile, 2-col tablet, 3-col desktop) -->
            <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3.5 space-y-0">
              <template x-for="m in filteredTeamMembers" :key="m.id">
                <div @click="viewTeamMemberDetail(m)" 
                  class="p-3.5 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between gap-3 cursor-pointer hover:border-blue-300 hover:shadow-md transition-all active:scale-[0.99] touch-press">
                  
                  <!-- Left: Avatar + Name + Role -->
                  <div class="flex items-center gap-3 min-w-0">
                    <div class="w-10 h-10 rounded-full text-white flex items-center justify-center font-bold text-xs shrink-0 shadow-xs"
                      :class="m.color_class || 'bg-blue-600'">
                      <span x-text="m.initials || m.name.substring(0, 2).toUpperCase()"></span>
                    </div>
                    
                    <div class="min-w-0">
                      <div class="text-xs font-bold text-slate-900 truncate" x-text="m.name"></div>
                      <div class="text-[11px] text-slate-400 font-medium truncate mt-0.5" x-text="m.role"></div>
                    </div>
                  </div>

                  <!-- Right: Status Pill + Chevron -->
                  <div class="flex items-center gap-2.5 shrink-0">
                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold"
                      :class="(m.status || '').toLowerCase() === 'active' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200/60' : 'bg-slate-100 text-slate-500 border border-slate-200'">
                      <span x-text="m.status || 'Active'"></span>
                    </span>
                    <svg class="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M9 5l7 7-7 7"/></svg>
                  </div>

                </div>
              </template>

              <!-- Empty State -->
              <div x-show="filteredTeamMembers.length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket">
                <div class="w-14 h-14 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mx-auto mb-3 shadow-xs">
                  <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                </div>
                <h3 class="text-sm font-black text-slate-900">No Team Members Found</h3>
                <p class="text-xs text-slate-400 max-w-xs mx-auto mt-1 leading-relaxed">No members match your current search or filter criteria.</p>
                <button @click="openAddTeamMemberModal()" class="mt-4 px-4 py-2 bg-blue-600 text-white rounded-xl text-xs font-bold shadow-sm touch-press">
                  Add Team Member
                </button>
              </div>
            </div>

          </div>

          <!-- ===================================================================
               SCREENS 2 & 3: TEAM MEMBER DETAILS (Exact Match Reference Image)
               =================================================================== -->
          <div x-show="currentView === 'team_detail'" class="max-w-4xl mx-auto w-full space-y-3 pb-8" x-cloak>
            <template x-if="activeTeamMember">
              <div class="space-y-3">
                
                <!-- 1. Top Member Profile Card (Screen 2 Reference) -->
                <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3.5">
                  <div class="flex items-start justify-between">
                    <div class="flex items-center gap-3.5">
                      <!-- Big Colored Avatar with Initials -->
                      <div class="w-14 h-14 rounded-full text-white flex items-center justify-center font-extrabold text-lg shadow-sm shrink-0"
                        :class="activeTeamMember.color_class || 'bg-blue-600'">
                        <span x-text="activeTeamMember.initials || activeTeamMember.name.substring(0, 2).toUpperCase()"></span>
                      </div>
                      <div class="min-w-0">
                        <div class="flex items-center gap-2 flex-wrap">
                          <h2 class="text-base font-extrabold text-slate-900 truncate" x-text="activeTeamMember.name"></h2>
                          <!-- Status Pill -->
                          <span class="px-2 py-0.5 rounded-full text-[9px] font-bold shrink-0"
                            :class="(activeTeamMember.status || '').toLowerCase() === 'active' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200/60' : 'bg-slate-100 text-slate-500 border border-slate-200'"
                            x-text="activeTeamMember.status || 'Active'"></span>
                        </div>
                        <p class="text-xs font-semibold text-slate-500 mt-0.5 truncate" x-text="activeTeamMember.role"></p>
                        <div class="flex items-center gap-1.5 text-[11px] text-slate-400 mt-1 font-medium truncate">
                          <span x-text="activeTeamMember.company || 'Software CRM Inc'"></span>
                          <span>&bull;</span>
                          <span x-text="activeTeamMember.location || 'Bangalore, India'"></span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- 4 Quick Action Buttons (Screen 2 Reference) -->
                  <div class="grid grid-cols-4 gap-2 pt-2 border-t border-slate-100">
                    <button @click="triggerMemberMessage(activeTeamMember)" class="flex flex-col items-center gap-1.5 p-2 rounded-xl bg-slate-50 hover:bg-blue-50 hover:text-blue-600 text-slate-600 transition-colors touch-press">
                      <div class="w-8 h-8 rounded-full bg-white shadow-xs border border-slate-200/80 flex items-center justify-center text-blue-600">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                      </div>
                      <span class="text-[10px] font-bold">Message</span>
                    </button>

                    <button @click="triggerMemberCall(activeTeamMember)" class="flex flex-col items-center gap-1.5 p-2 rounded-xl bg-slate-50 hover:bg-emerald-50 hover:text-emerald-600 text-slate-600 transition-colors touch-press">
                      <div class="w-8 h-8 rounded-full bg-white shadow-xs border border-slate-200/80 flex items-center justify-center text-emerald-600">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                      </div>
                      <span class="text-[10px] font-bold">Call</span>
                    </button>

                    <button @click="triggerMemberEmail(activeTeamMember)" class="flex flex-col items-center gap-1.5 p-2 rounded-xl bg-slate-50 hover:bg-purple-50 hover:text-purple-600 text-slate-600 transition-colors touch-press">
                      <div class="w-8 h-8 rounded-full bg-white shadow-xs border border-slate-200/80 flex items-center justify-center text-purple-600">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                      </div>
                      <span class="text-[10px] font-bold">Email</span>
                    </button>

                    <button @click="openMemberActionMenu(activeTeamMember)" class="flex flex-col items-center gap-1.5 p-2 rounded-xl bg-slate-50 hover:bg-slate-100 text-slate-600 transition-colors touch-press">
                      <div class="w-8 h-8 rounded-full bg-white shadow-xs border border-slate-200/80 flex items-center justify-center text-slate-700">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 12h.01M12 12h.01M19 12h.01M6 12a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0z"/></svg>
                      </div>
                      <span class="text-[10px] font-bold">More</span>
                    </button>
                  </div>
                </div>

                <!-- 2. Segmented Navigation Tabs: Overview, Projects, Tasks, Activity -->
                <div class="flex items-center border-b border-slate-200 bg-white rounded-2xl px-2 py-1 shadow-xs">
                  <button @click="teamDetailTab = 'overview'" 
                    class="flex-1 py-2 text-center text-xs font-bold transition-all relative touch-press"
                    :class="teamDetailTab === 'overview' ? 'text-blue-600' : 'text-slate-400 hover:text-slate-700'">
                    <span>Overview</span>
                    <div x-show="teamDetailTab === 'overview'" class="absolute bottom-0 left-2 right-2 h-0.5 bg-blue-600 rounded-full"></div>
                  </button>
                  <button @click="teamDetailTab = 'projects'" 
                    class="flex-1 py-2 text-center text-xs font-bold transition-all relative touch-press"
                    :class="teamDetailTab === 'projects' ? 'text-blue-600' : 'text-slate-400 hover:text-slate-700'">
                    <span>Projects</span>
                    <div x-show="teamDetailTab === 'projects'" class="absolute bottom-0 left-2 right-2 h-0.5 bg-blue-600 rounded-full"></div>
                  </button>
                  <button @click="teamDetailTab = 'tasks'" 
                    class="flex-1 py-2 text-center text-xs font-bold transition-all relative touch-press"
                    :class="teamDetailTab === 'tasks' ? 'text-blue-600' : 'text-slate-400 hover:text-slate-700'">
                    <span>Tasks</span>
                    <div x-show="teamDetailTab === 'tasks'" class="absolute bottom-0 left-2 right-2 h-0.5 bg-blue-600 rounded-full"></div>
                  </button>
                  <button @click="teamDetailTab = 'activity'" 
                    class="flex-1 py-2 text-center text-xs font-bold transition-all relative touch-press"
                    :class="teamDetailTab === 'activity' ? 'text-blue-600' : 'text-slate-400 hover:text-slate-700'">
                    <span>Activity</span>
                    <div x-show="teamDetailTab === 'activity'" class="absolute bottom-0 left-2 right-2 h-0.5 bg-blue-600 rounded-full"></div>
                  </button>
                </div>

                <!-- =============================================================
                     TAB 1: OVERVIEW (Screen 2 Reference)
                     ============================================================= -->
                <div x-show="teamDetailTab === 'overview'" class="space-y-3">
                  
                  <!-- Contact Information Card -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between pb-1 border-b border-slate-100">
                      <h3 class="text-xs font-extrabold text-slate-900">Contact Information</h3>
                      <button @click="openEditMemberModal(activeTeamMember)" class="text-xs font-bold text-blue-600 hover:text-blue-700 touch-press">Edit</button>
                    </div>

                    <div class="space-y-2.5 text-xs">
                      <!-- Email Row -->
                      <div @click="triggerMemberEmail(activeTeamMember)" class="flex items-center justify-between p-2 rounded-xl hover:bg-slate-50 cursor-pointer transition-colors group">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                          </div>
                          <div class="min-w-0">
                            <div class="text-[10px] font-bold text-slate-400">Email</div>
                            <div class="font-bold text-slate-800 truncate group-hover:text-blue-600" x-text="activeTeamMember.email"></div>
                          </div>
                        </div>
                        <svg class="w-4 h-4 text-slate-300 group-hover:text-blue-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                      </div>

                      <!-- Phone Row -->
                      <div @click="triggerMemberCall(activeTeamMember)" class="flex items-center justify-between p-2 rounded-xl hover:bg-slate-50 cursor-pointer transition-colors group">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-8 h-8 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center shrink-0">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                          </div>
                          <div class="min-w-0">
                            <div class="text-[10px] font-bold text-slate-400">Phone</div>
                            <div class="font-bold text-slate-800 truncate group-hover:text-emerald-600" x-text="activeTeamMember.phone"></div>
                          </div>
                        </div>
                        <svg class="w-4 h-4 text-slate-300 group-hover:text-emerald-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                      </div>

                      <!-- Department Row -->
                      <div class="flex items-center justify-between p-2 rounded-xl">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-8 h-8 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center shrink-0">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                          </div>
                          <div class="min-w-0">
                            <div class="text-[10px] font-bold text-slate-400">Department</div>
                            <div class="font-bold text-slate-800 truncate" x-text="activeTeamMember.department || 'Engineering'"></div>
                          </div>
                        </div>
                      </div>

                      <!-- Joined Date Row -->
                      <div class="flex items-center justify-between p-2 rounded-xl">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-8 h-8 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center shrink-0">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                          </div>
                          <div class="min-w-0">
                            <div class="text-[10px] font-bold text-slate-400">Joined Date</div>
                            <div class="font-bold text-slate-800 truncate" x-text="activeTeamMember.joined_date || 'Jan 2024'"></div>
                          </div>
                        </div>
                      </div>

                      <!-- Website Row -->
                      <div class="flex items-center justify-between p-2 rounded-xl">
                        <div class="flex items-center gap-3 min-w-0">
                          <div class="w-8 h-8 rounded-xl bg-slate-100 text-slate-600 flex items-center justify-center shrink-0">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9"/></svg>
                          </div>
                          <div class="min-w-0">
                            <div class="text-[10px] font-bold text-slate-400">Website</div>
                            <div class="font-bold text-blue-600 truncate" x-text="activeTeamMember.website || 'https://softwarecrm.com'"></div>
                          </div>
                        </div>
                      </div>

                    </div>
                  </div>

                  <!-- About / Bio Card -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2">
                    <h3 class="text-xs font-extrabold text-slate-900">About</h3>
                    <p class="text-xs text-slate-600 leading-relaxed" x-text="activeTeamMember.bio || 'Experienced software professional leading critical initiatives across the enterprise platform.'"></p>
                  </div>

                  <!-- Skills & Expertise Card -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-2.5">
                    <h3 class="text-xs font-extrabold text-slate-900">Skills & Expertise</h3>
                    <div class="flex flex-wrap gap-2">
                      <template x-for="skill in (activeTeamMember.skills || 'Software Engineering, Full Stack').split(',').map(s => s.trim()).filter(Boolean)" :key="skill">
                        <span class="px-3 py-1 rounded-xl bg-blue-50 text-blue-700 border border-blue-200/60 text-[11px] font-bold" x-text="skill"></span>
                      </template>
                    </div>
                  </div>

                </div>

                <!-- =============================================================
                     TAB 2: PROJECTS (Screen 3 Reference)
                     ============================================================= -->
                <div x-show="teamDetailTab === 'projects'" class="space-y-3">
                  
                  <!-- Project Summary Card (Exact Match Screen 3) -->
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3">
                    <div class="flex items-center justify-between">
                      <h3 class="text-xs font-extrabold text-slate-900">Project Summary</h3>
                      <span class="text-xs font-bold text-blue-600" x-text="getTeamMemberProjectStats(activeTeamMember).total + ' Total Projects'"></span>
                    </div>

                    <!-- 3-Pill Metrics Grid: Active, Completed, On Hold -->
                    <div class="grid grid-cols-3 gap-2 text-center">
                      <div class="p-2.5 rounded-xl bg-blue-50 border border-blue-100">
                        <div class="text-base font-black text-blue-600" x-text="getTeamMemberProjectStats(activeTeamMember).active"></div>
                        <div class="text-[10px] font-bold text-slate-500 mt-0.5">Active</div>
                      </div>
                      <div class="p-2.5 rounded-xl bg-emerald-50 border border-emerald-100">
                        <div class="text-base font-black text-emerald-600" x-text="getTeamMemberProjectStats(activeTeamMember).completed"></div>
                        <div class="text-[10px] font-bold text-slate-500 mt-0.5">Completed</div>
                      </div>
                      <div class="p-2.5 rounded-xl bg-amber-50 border border-amber-100">
                        <div class="text-base font-black text-amber-600" x-text="getTeamMemberProjectStats(activeTeamMember).onHold"></div>
                        <div class="text-[10px] font-bold text-slate-500 mt-0.5">On Hold</div>
                      </div>
                    </div>
                  </div>

                  <!-- Projects List (Screen 3 Reference) -->
                  <div class="space-y-2.5">
                    <template x-for="p in getTeamMemberProjects(activeTeamMember)" :key="p.id">
                      <div @click="viewProjectDetail(p)" 
                        class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-3 cursor-pointer hover:border-blue-300 hover:shadow-md transition-all active:scale-[0.99] touch-press">
                        
                        <div class="flex items-start justify-between gap-2">
                          <div class="flex items-center gap-3 min-w-0">
                            <!-- Colored Project Icon -->
                            <div class="w-10 h-10 rounded-xl flex items-center justify-center font-bold text-xs shrink-0"
                              :class="p.color === 'purple' ? 'bg-purple-100 text-purple-600' : (p.color === 'indigo' ? 'bg-indigo-100 text-indigo-600' : (p.color === 'emerald' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'))">
                              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
                            </div>
                            <div class="min-w-0">
                              <h4 class="text-xs font-black text-slate-900 truncate" x-text="p.title"></h4>
                              <p class="text-[11px] text-slate-400 font-medium truncate mt-0.5" x-text="p.client_name"></p>
                            </div>
                          </div>

                          <!-- Status Pill -->
                          <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold shrink-0"
                            :class="(p.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-600'">
                            <span class="w-1.5 h-1.5 rounded-full" :class="(p.status || '').toLowerCase() === 'completed' ? 'bg-emerald-500' : 'bg-blue-600'"></span>
                            <span x-text="p.status || 'Active'"></span>
                          </span>
                        </div>

                        <!-- Progress Bar -->
                        <div>
                          <div class="flex justify-between items-center text-[11px] font-bold mb-1">
                            <span class="text-slate-600">Progress</span>
                            <span class="text-slate-900" x-text="(p.progress || 0) + '%'"></span>
                          </div>
                          <div class="w-full h-1.5 rounded-full bg-slate-100 overflow-hidden">
                            <div class="h-full bg-blue-600 rounded-full transition-all duration-300" :style="'width: ' + (p.progress || 0) + '%'"></div>
                          </div>
                        </div>

                        <!-- Card Footer: Due Date & Budget -->
                        <div class="flex items-center justify-between text-[11px] pt-1 border-t border-slate-100 text-slate-400 font-medium">
                          <span>Due: <strong class="text-slate-700" x-text="formatDisplayDate(p.deadline || '2024-11-30')"></strong></span>
                          <span>Budget: <strong class="text-slate-700" x-text="p.budget || '$12,000'"></strong></span>
                        </div>

                      </div>
                    </template>

                    <!-- Empty Projects State -->
                    <div x-show="getTeamMemberProjects(activeTeamMember).length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket">
                      <p class="text-xs text-slate-400">No projects currently linked to this member.</p>
                    </div>
                  </div>

                </div>

                <!-- =============================================================
                     TAB 3: TASKS
                     ============================================================= -->
                <div x-show="teamDetailTab === 'tasks'" class="space-y-3">
                  
                  <!-- Task Summary Bar -->
                  <div class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between text-xs font-bold">
                    <span class="text-slate-800">Assigned Tasks</span>
                    <div class="flex items-center gap-2">
                      <span class="px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-600 text-[10px]" x-text="getTeamMemberTaskStats(activeTeamMember).completed + ' Done'"></span>
                      <span class="px-2 py-0.5 rounded-full bg-blue-50 text-blue-600 text-[10px]" x-text="getTeamMemberTaskStats(activeTeamMember).pending + ' Pending'"></span>
                    </div>
                  </div>

                  <!-- Tasks List -->
                  <div class="space-y-2">
                    <template x-for="t in getTeamMemberTasks(activeTeamMember)" :key="t.id">
                      <div @click="viewTaskDetail(t)" 
                        class="p-3 bg-white rounded-2xl border border-slate-200/80 shadow-pocket flex items-center justify-between gap-3 cursor-pointer hover:border-blue-300 hover:shadow-md transition-all active:scale-[0.99] touch-press">
                        
                        <div class="flex items-center gap-2.5 min-w-0">
                          <!-- Interactive Checkbox -->
                          <button @click.stop="toggleTask(t)" class="w-5 h-5 rounded-lg border flex items-center justify-center shrink-0 transition-all touch-press"
                            :class="Number(t.completed) === 1 ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-300 bg-white hover:border-blue-500'">
                            <svg x-show="Number(t.completed) === 1" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                          </button>
                          
                          <div class="min-w-0">
                            <h4 class="text-xs font-bold text-slate-900 truncate" :class="Number(t.completed) === 1 ? 'line-through text-slate-400' : ''" x-text="t.title"></h4>
                            <p class="text-[10px] text-slate-400 truncate mt-0.5" x-text="t.project_name || 'Software CRM'"></p>
                          </div>
                        </div>

                        <!-- Priority & Chevron -->
                        <div class="flex items-center gap-2 shrink-0">
                          <span class="px-2 py-0.5 rounded-full text-[9px] font-bold"
                            :class="t.priority === 'High' ? 'bg-rose-50 text-rose-600' : (t.priority === 'Medium' ? 'bg-amber-50 text-amber-700' : 'bg-emerald-50 text-emerald-600')"
                            x-text="t.priority || 'Medium'"></span>
                          <svg class="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                        </div>

                      </div>
                    </template>

                    <!-- Empty Tasks State -->
                    <div x-show="getTeamMemberTasks(activeTeamMember).length === 0" class="p-8 text-center bg-white rounded-2xl border border-slate-200/80 shadow-pocket">
                      <p class="text-xs text-slate-400">No tasks currently assigned to this member.</p>
                    </div>
                  </div>

                </div>

                <!-- =============================================================
                     TAB 4: ACTIVITY
                     ============================================================= -->
                <div x-show="teamDetailTab === 'activity'" class="space-y-3">
                  <div class="p-4 bg-white rounded-2xl border border-slate-200/80 shadow-pocket space-y-4">
                    <h3 class="text-xs font-extrabold text-slate-900">Recent Activity</h3>
                    
                    <div class="space-y-3">
                      <template x-for="act in getTeamMemberActivity(activeTeamMember)" :key="act.id">
                        <div class="flex items-start gap-3">
                          <div class="w-8 h-8 rounded-xl flex items-center justify-center shrink-0 mt-0.5" :class="act.icon_color">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                          </div>
                          <div class="min-w-0 flex-1">
                            <div class="text-xs font-bold text-slate-900" x-text="act.title"></div>
                            <div class="text-[11px] text-slate-400 mt-0.5" x-text="act.subtitle"></div>
                            <div class="text-[10px] text-slate-400 font-mono mt-1" x-text="act.time"></div>
                          </div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>

              </div>
            </template>
          </div>

          <!-- ===================================================================
               SCREEN: GROUP CHART & TEAM STRUCTURE (Interactive Dashboard & Visualization)
               =================================================================== -->
          <div x-show="currentView === 'group_chart'" class="space-y-4 pb-16" x-cloak>

            <!-- 1. Page Header & Top Action Controls -->
            <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 sm:p-5 shadow-xs">
              <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                
                <!-- Left: Title & Subtitle -->
                <div>
                  <div class="flex items-center gap-2.5">
                    <div class="w-9 h-9 rounded-xl bg-blue-50 dark:bg-blue-950/60 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0 border border-blue-100 dark:border-blue-900/60">
                      <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
                    </div>
                    <div>
                      <h1 class="text-lg sm:text-xl font-extrabold text-slate-900 dark:text-slate-100 tracking-tight">Group Chart</h1>
                      <p class="text-xs text-slate-500 dark:text-slate-400 font-medium">Manage groups and team members</p>
                    </div>
                  </div>
                </div>

                <!-- Right: Search & Create Group Button -->
                <div class="flex items-center gap-2 sm:gap-3 flex-wrap">
                  <!-- Search Field -->
                  <div class="relative flex-1 sm:w-64">
                    <input type="text" x-model="groupSearchQuery" placeholder="Search groups or leaders..." 
                      class="w-full bg-slate-50 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-8 py-2 text-xs text-slate-800 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all">
                    <div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                    </div>
                    <button x-show="groupSearchQuery" @click="groupSearchQuery = ''" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>

                  <!-- Create Group Button -->
                  <button @click="openCreateGroupModal()" 
                    class="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold flex items-center gap-2 shadow-xs transition-colors shrink-0 touch-press">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                    <span>Create Group</span>
                  </button>
                </div>

              </div>
            </div>

            <!-- 2. Group Dashboard Summary Cards (4 Cards Grid) -->
            <div class="grid grid-cols-2 lg:grid-cols-4 gap-3">
              
              <!-- Card 1: Total Groups -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 shadow-xs flex items-center gap-3.5">
                <div class="w-11 h-11 rounded-xl bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0 border border-blue-100 dark:border-blue-800">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Total Groups</div>
                  <div class="text-xl sm:text-2xl font-black text-slate-900 dark:text-slate-100 tracking-tight" x-text="groupSummary.total_groups || 0">0</div>
                  <div class="text-[10px] text-slate-400 dark:text-slate-400 font-medium truncate">Configured teams</div>
                </div>
              </div>

              <!-- Card 2: Total Active Team Members -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 shadow-xs flex items-center gap-3.5">
                <div class="w-11 h-11 rounded-xl bg-emerald-50 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center shrink-0 border border-emerald-100 dark:border-emerald-800">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Active Staff</div>
                  <div class="text-xl sm:text-2xl font-black text-slate-900 dark:text-slate-100 tracking-tight" x-text="groupSummary.total_active_members || 0">0</div>
                  <div class="text-[10px] text-slate-400 dark:text-slate-400 font-medium truncate">In CRM workforce</div>
                </div>
              </div>

              <!-- Card 3: Members Without a Group -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 shadow-xs flex items-center gap-3.5">
                <div class="w-11 h-11 rounded-xl bg-amber-50 dark:bg-amber-900/40 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0 border border-amber-100 dark:border-amber-800">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
                </div>
                <div class="min-w-0">
                  <div class="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Unassigned</div>
                  <div class="text-xl sm:text-2xl font-black text-slate-900 dark:text-slate-100 tracking-tight" x-text="groupSummary.members_without_group || 0">0</div>
                  <div class="text-[10px] text-slate-400 dark:text-slate-400 font-medium truncate">Awaiting group</div>
                </div>
              </div>

              <!-- Card 4: Largest Group -->
              <div @click="groupSummary.largest_group ? selectGroup(groupSummary.largest_group.id) : null" 
                class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 shadow-xs flex items-center gap-3.5 transition-all touch-press"
                :class="groupSummary.largest_group ? 'cursor-pointer hover:border-blue-400 hover:shadow-md' : ''">
                <div class="w-11 h-11 rounded-xl bg-purple-50 dark:bg-purple-900/40 text-purple-600 dark:text-purple-400 flex items-center justify-center shrink-0 border border-purple-100 dark:border-purple-800">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z"/></svg>
                </div>
                <div class="min-w-0 flex-1">
                  <div class="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Largest Group</div>
                  <div class="text-sm sm:text-base font-extrabold text-slate-900 dark:text-slate-100 tracking-tight truncate" 
                    x-text="groupSummary.largest_group ? groupSummary.largest_group.name : 'None'">None</div>
                  <div class="text-[10px] text-slate-400 dark:text-slate-400 font-medium truncate" 
                    x-text="groupSummary.largest_group ? (groupSummary.largest_group.member_count + ' members • ' + (groupSummary.largest_group.leader_name || 'No leader')) : '0 members'">0 members</div>
                </div>
              </div>

            </div>

            <!-- 3. Groups Selector Grid / Empty State -->
            <div>
              <div class="flex items-center justify-between mb-2">
                <h3 class="text-xs font-bold text-slate-700 dark:text-slate-300 uppercase tracking-wider">
                  Groups (<span x-text="filteredGroups.length"></span>)
                </h3>
                <span class="text-[11px] text-slate-400" x-show="groups.length > 0">Click a group to view hierarchy</span>
              </div>

              <!-- When Groups Exist: Cards Grid -->
              <div x-show="filteredGroups.length > 0" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                <template x-for="g in filteredGroups" :key="g.id">
                  <div @click="selectGroup(g.id)" 
                    class="p-4 rounded-2xl border transition-all cursor-pointer relative overflow-hidden touch-press"
                    :class="activeGroup && activeGroup.id === g.id 
                      ? 'bg-blue-50/60 dark:bg-blue-950/40 border-blue-500 dark:border-blue-400 ring-2 ring-blue-500/20 shadow-md' 
                      : 'bg-white dark:bg-slate-800 border-slate-200/90 dark:border-slate-700/80 hover:border-slate-300 dark:hover:border-slate-600 shadow-xs'">
                    
                    <!-- Top color strip indicator -->
                    <div class="absolute top-0 left-0 right-0 h-1" :style="'background-color: ' + (g.color || '#590907')"></div>

                    <!-- Header: Icon + Name + Member Count -->
                    <div class="flex items-start justify-between gap-2 pt-1 mb-2">
                      <div class="flex items-center gap-2.5 min-w-0">
                        <div class="w-8 h-8 rounded-lg flex items-center justify-center text-white font-bold text-xs shrink-0 shadow-xs"
                          :style="'background-color: ' + (g.color || '#590907')">
                          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                        </div>
                        <div class="min-w-0">
                          <h4 class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate" x-text="g.name"></h4>
                          <span class="text-[10px] text-slate-400 font-medium" x-text="g.member_count + ' members'"></span>
                        </div>
                      </div>

                      <span x-show="activeGroup && activeGroup.id === g.id" 
                        class="px-2 py-0.5 rounded-full text-[9px] font-extrabold bg-blue-600 text-white shadow-xs">
                        Active
                      </span>
                    </div>

                    <!-- Company Badge -->
                    <div class="mb-2" x-show="g.company_name">
                      <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-blue-50 dark:bg-blue-950/60 text-blue-700 dark:text-blue-300 border border-blue-200/60 dark:border-blue-900/60 text-[10px] font-bold max-w-full truncate">
                        <svg class="w-3 h-3 shrink-0 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                        <span class="truncate" x-text="g.company_name"></span>
                      </span>
                    </div>

                    <!-- Description -->
                    <p class="text-[11px] text-slate-500 dark:text-slate-400 line-clamp-2 min-h-[32px] mb-3" 
                      x-text="g.description || 'No description provided.'"></p>

                    <!-- Footer: Leader info + member preview avatars -->
                    <div class="pt-2 border-t border-slate-100 dark:border-slate-700/60 flex items-center justify-between gap-2 text-xs">
                      <div class="flex items-center gap-1.5 min-w-0">
                        <template x-if="g.leader_name">
                          <div class="flex items-center gap-1.5 min-w-0">
                            <span class="text-[10px] text-slate-400">Leader:</span>
                            <span class="text-[11px] font-bold text-slate-800 dark:text-slate-200 truncate" x-text="g.leader_name"></span>
                          </div>
                        </template>
                        <template x-if="!g.leader_name">
                          <span class="text-[10px] text-amber-500 font-medium italic">No leader</span>
                        </template>
                      </div>

                      <!-- Preview Avatars -->
                      <div class="flex -space-x-1.5 overflow-hidden shrink-0" x-show="g.preview_members && g.preview_members.length > 0">
                        <template x-for="pm in (g.preview_members || []).slice(0, 3)" :key="pm.id">
                          <div class="w-5 h-5 rounded-full text-white text-[8px] font-bold flex items-center justify-center ring-1 ring-white dark:ring-slate-800"
                            :class="pm.color_class || 'bg-blue-600'"
                            :title="pm.name">
                            <span x-text="pm.initials || pm.name.substring(0,2).toUpperCase()"></span>
                          </div>
                        </template>
                        <div x-show="(g.member_count || 0) > 3" class="w-5 h-5 rounded-full bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-[8px] font-bold flex items-center justify-center ring-1 ring-white dark:ring-slate-800">
                          <span x-text="'+' + ((g.member_count || 0) - 3)"></span>
                        </div>
                      </div>
                    </div>

                  </div>
                </template>
              </div>

              <!-- When No Groups Match Search or 0 Groups Exist -->
              <div x-show="filteredGroups.length === 0" class="p-8 text-center bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 shadow-xs space-y-3">
                <div class="w-14 h-14 rounded-2xl bg-blue-50 dark:bg-blue-950/60 text-blue-600 dark:text-blue-400 flex items-center justify-center mx-auto shadow-xs border border-blue-100 dark:border-blue-900/60">
                  <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
                </div>
                <div>
                  <h3 class="text-sm font-extrabold text-slate-900 dark:text-slate-100" x-text="groups.length === 0 ? 'No Groups Created Yet' : 'No Groups Match Your Search'">No Groups Found</h3>
                  <p class="text-xs text-slate-400 dark:text-slate-400 max-w-sm mx-auto mt-1 leading-relaxed">
                    <span x-show="groups.length === 0">Organize your CRM employees into dedicated functional teams, assign leaders, and visualize the structure.</span>
                    <span x-show="groups.length > 0">Try refining your search keyword or clear the search filter.</span>
                  </p>
                </div>
                <div>
                  <button x-show="groups.length === 0" @click="openCreateGroupModal()" class="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold shadow-xs transition-colors touch-press">
                    Create First Group
                  </button>
                  <button x-show="groups.length > 0" @click="groupSearchQuery = ''" class="px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl text-xs font-bold hover:bg-slate-200 transition-colors touch-press">
                    Clear Search
                  </button>
                </div>
              </div>

            </div>

            <!-- 4. Selected Group Details & Team Structure Visualization -->
            <div x-show="activeGroup" class="space-y-4">

              <!-- Group Header Details Card -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-5 shadow-xs">
                <div class="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
                  
                  <!-- Left: Group Profile & Meta -->
                  <div class="flex items-start gap-3.5 min-w-0">
                    <div class="w-12 h-12 rounded-2xl flex items-center justify-center text-white font-extrabold text-base shrink-0 shadow-xs"
                      :style="'background-color: ' + (activeGroup ? (activeGroup.color || '#590907') : '#590907')">
                      <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
                    </div>

                    <div class="min-w-0 flex-1">
                      <div class="flex items-center gap-2 flex-wrap">
                        <h2 class="text-base sm:text-lg font-black text-slate-900 dark:text-slate-100 tracking-tight" x-text="activeGroup ? activeGroup.name : ''"></h2>
                        <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-300 border border-blue-200/80 dark:border-blue-800"
                          x-text="(activeGroup ? (activeGroup.member_count || 0) : 0) + ' Total Members'">
                        </span>
                      </div>

                      <p class="text-xs text-slate-500 dark:text-slate-400 mt-1 max-w-2xl leading-relaxed" 
                        x-text="activeGroup ? (activeGroup.description || 'No description provided for this group.') : ''"></p>

                      <!-- Meta row -->
                      <div class="flex items-center gap-4 mt-2.5 text-[11px] text-slate-400 font-medium flex-wrap">
                        <template x-if="activeGroup && (activeGroup.company_name || (activeGroup.company && activeGroup.company.name))">
                          <div class="flex items-center gap-1.5">
                            <span class="font-bold text-slate-600 dark:text-slate-300">Company:</span>
                            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-blue-50 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 font-bold text-[10px] border border-blue-200/60 dark:border-blue-800/60">
                              <svg class="w-3 h-3 shrink-0 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
                              <span x-text="activeGroup.company_name || activeGroup.company.name"></span>
                            </span>
                          </div>
                        </template>
                        <span x-show="activeGroup && (activeGroup.company_name || (activeGroup.company && activeGroup.company.name))" class="hidden sm:inline">•</span>
                        <div class="flex items-center gap-1.5">
                          <span class="font-bold text-slate-600 dark:text-slate-300">Leader:</span>
                          <span x-text="activeGroup && activeGroup.leader ? activeGroup.leader.name : 'Unassigned'" class="text-slate-800 dark:text-slate-200 font-semibold"></span>
                          <span x-show="activeGroup && activeGroup.leader" class="text-[10px] text-slate-400" x-text="'(' + (activeGroup.leader ? activeGroup.leader.role : '') + ')'"></span>
                        </div>
                        <span class="hidden sm:inline">•</span>
                        <div class="flex items-center gap-1">
                          <span>Created:</span>
                          <span class="font-mono text-slate-600 dark:text-slate-300" x-text="formatDisplayDate(activeGroup ? activeGroup.created_at : '')"></span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- Right: Group Action Buttons -->
                  <div class="flex items-center gap-2 flex-wrap shrink-0 pt-2 lg:pt-0 border-t lg:border-t-0 border-slate-100 dark:border-slate-700/60">
                    <!-- Team Chat Button -->
                    <button @click="openGroupChat(activeGroup)" 
                      class="px-3.5 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white rounded-xl text-xs font-bold flex items-center gap-1.5 shadow-xs transition-colors touch-press"
                      title="Open Team Chat & Calls">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                      <span>Team Chat</span>
                    </button>

                    <!-- Add Member -->
                    <button @click="openAddMembersToGroupModal()" 
                      class="px-3.5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold flex items-center gap-1.5 shadow-xs transition-colors touch-press">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
                      <span>Add Member</span>
                    </button>

                    <!-- Edit Group -->
                    <button @click="openEditGroupModal(activeGroup)" 
                      class="px-3 py-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-600 rounded-xl text-xs font-bold flex items-center gap-1.5 transition-colors touch-press">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                      <span>Edit</span>
                    </button>

                    <!-- Delete Group -->
                    <button @click="promptDeleteGroup(activeGroup)" 
                      class="px-3 py-2 bg-white dark:bg-slate-700 border border-rose-200 dark:border-rose-900/60 text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/40 rounded-xl text-xs font-bold flex items-center gap-1.5 transition-colors touch-press"
                      title="Delete Group">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      <span>Delete</span>
                    </button>
                  </div>

                </div>
              </div>

              <!-- Visual Organizational Chart Panel -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 shadow-xs overflow-hidden">
                
                <!-- Panel Header with Expand/Collapse -->
                <div class="px-5 py-3.5 border-b border-slate-100 dark:border-slate-700/60 flex items-center justify-between gap-3 bg-slate-50/50 dark:bg-slate-800/50">
                  <div class="flex items-center gap-2">
                    <div class="w-6 h-6 rounded-lg bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z"/></svg>
                    </div>
                    <div>
                      <h3 class="text-xs font-bold text-slate-900 dark:text-slate-100">Team Structure Chart</h3>
                      <p class="text-[10px] text-slate-400">Hierarchical reporting lines and group structure</p>
                    </div>
                  </div>

                  <button @click="groupChartExpanded = !groupChartExpanded" 
                    class="px-2.5 py-1 text-[11px] font-bold text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg flex items-center gap-1 transition-colors touch-press">
                    <span x-text="groupChartExpanded ? 'Collapse Chart' : 'Expand Chart'"></span>
                    <svg class="w-3.5 h-3.5 transition-transform" :class="groupChartExpanded ? 'rotate-180' : ''" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
                  </button>
                </div>

                <!-- Chart Canvas Container -->
                <div x-show="groupChartExpanded" class="p-6 overflow-x-auto min-w-full no-scrollbar transition-all bg-gradient-to-b from-slate-50/30 to-transparent dark:from-slate-900/20">
                  <div class="min-w-[320px] flex flex-col items-center py-4">

                    <!-- Level 1: GROUP LEADER NODE -->
                    <div class="flex flex-col items-center">
                      
                      <!-- Leader Card (When Assigned) -->
                      <template x-if="activeGroup && activeGroup.leader">
                        <div class="relative bg-white dark:bg-slate-900 rounded-2xl border-2 border-blue-500 dark:border-blue-400 p-4 shadow-md w-64 max-w-xs text-center transition-transform hover:scale-[1.02]">
                          
                          <!-- Crown / Leader Badge -->
                          <div class="absolute -top-3 inset-x-0 flex justify-center">
                            <span class="px-2.5 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-blue-600 text-white shadow-xs flex items-center gap-1">
                              <svg class="w-3 h-3 text-amber-300" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z"/></svg>
                              <span>Group Leader</span>
                            </span>
                          </div>

                          <!-- Avatar -->
                          <div class="w-12 h-12 rounded-full text-white flex items-center justify-center font-bold text-sm mx-auto mt-1 mb-2 ring-2 ring-blue-500/30 shadow-xs"
                            :class="activeGroup.leader.color_class || 'bg-blue-600'">
                            <span x-text="activeGroup.leader.initials || activeGroup.leader.name.substring(0, 2).toUpperCase()"></span>
                          </div>

                          <!-- Name & Title -->
                          <h4 class="text-xs font-black text-slate-900 dark:text-slate-100 truncate" x-text="activeGroup.leader.name"></h4>
                          <div class="text-[11px] text-blue-600 dark:text-blue-400 font-bold truncate mt-0.5" x-text="activeGroup.leader.role"></div>
                          <div class="text-[10px] text-slate-400 truncate mt-0.5" x-text="activeGroup.leader.email || activeGroup.leader.department || 'CRM Staff'"></div>

                          <!-- Quick Change Leader & Workload Chart Action -->
                          <div class="mt-2.5 pt-2 border-t border-slate-100 dark:border-slate-800 flex items-center justify-center gap-3">
                            <button @click="openMemberChartModal(activeGroup.leader)" class="text-[10px] font-bold text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 flex items-center gap-1 touch-press" title="View Leader Workload Chart">
                              <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
                              <span>Workload</span>
                            </button>
                            <span class="text-slate-300 dark:text-slate-700">•</span>
                            <button @click="openEditGroupModal(activeGroup)" class="text-[10px] font-bold text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 touch-press">
                              Change Leader
                            </button>
                          </div>
                        </div>
                      </template>

                      <!-- Placeholder When No Leader Assigned -->
                      <template x-if="activeGroup && !activeGroup.leader">
                        <div class="bg-amber-50/50 dark:bg-amber-950/20 rounded-2xl border-2 border-dashed border-amber-300 dark:border-amber-700/80 p-4 w-60 text-center space-y-2">
                          <div class="w-9 h-9 rounded-full bg-amber-100 dark:bg-amber-900/60 text-amber-600 dark:text-amber-400 flex items-center justify-center mx-auto">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                          </div>
                          <div>
                            <div class="text-xs font-bold text-amber-800 dark:text-amber-300">No Leader Assigned</div>
                            <div class="text-[10px] text-amber-600/80 dark:text-amber-400/80">Group currently has no leader</div>
                          </div>
                          <button @click="openEditGroupModal(activeGroup)" class="px-3 py-1 bg-amber-600 text-white rounded-lg text-[10px] font-bold hover:bg-amber-700 touch-press">
                            Assign Leader
                          </button>
                        </div>
                      </template>

                      <!-- Vertical Connector Stem -->
                      <div class="w-0.5 h-8 bg-blue-400 dark:bg-blue-500 my-0"></div>

                    </div>

                    <!-- Level 2: TEAM MEMBERS UNDERNEATH -->
                    <div class="w-full">
                      
                      <!-- If Group Has Members (excluding leader if rendered above) -->
                      <template x-if="activeGroup && activeGroup.tree && activeGroup.tree.members && activeGroup.tree.members.length > 0">
                        <div class="relative pt-0">
                          
                          <!-- Horizontal Connecting Crossbar (only if more than 1 member) -->
                          <div x-show="activeGroup.tree.members.length > 1" class="relative mx-auto max-w-[95%]">
                            <div class="h-0.5 bg-slate-300 dark:bg-slate-600 w-full mx-auto"></div>
                          </div>

                          <!-- Member Cards Grid / Flex Row -->
                          <div class="flex flex-wrap items-start justify-center gap-4 sm:gap-6 pt-0 mt-0">
                            <template x-for="m in activeGroup.tree.members" :key="m.id">
                              <div class="flex flex-col items-center">
                                
                                <!-- Vertical Drop Stem onto Member Card -->
                                <div class="w-0.5 h-5 bg-slate-300 dark:bg-slate-600"></div>

                                <!-- Member Node Card -->
                                <div class="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-3.5 shadow-xs hover:shadow-md hover:border-blue-300 dark:hover:border-blue-600 transition-all w-52 text-center relative group">
                                  
                                  <!-- Quick Remove Action Icon Button -->
                                  <button @click="promptRemoveGroupMember(m)" 
                                    class="absolute top-2 right-2 w-6 h-6 rounded-lg bg-slate-50 dark:bg-slate-800 hover:bg-rose-50 dark:hover:bg-rose-950/40 text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 flex items-center justify-center transition-colors touch-press"
                                    title="Remove from Group">
                                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                                  </button>

                                  <!-- Avatar -->
                                  <div class="w-10 h-10 rounded-full text-white flex items-center justify-center font-bold text-xs mx-auto mb-2 shadow-xs ring-1 ring-slate-100 dark:ring-slate-800"
                                    :class="m.color_class || 'bg-blue-600'">
                                    <span x-text="m.initials || m.name.substring(0, 2).toUpperCase()"></span>
                                  </div>

                                  <!-- Name & Job Title -->
                                  <h5 class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate px-1" x-text="m.name"></h5>
                                  <div class="text-[11px] text-slate-500 dark:text-slate-400 font-medium truncate mt-0.5" x-text="m.role"></div>
                                  <div class="text-[10px] text-slate-400 truncate mt-0.5" x-text="m.email || 'Team Member'"></div>

                                  <!-- Status Pill & Quick Action -->
                                  <div class="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between text-[10px]">
                                    <button @click="openMemberChartModal(m)" class="text-indigo-600 dark:text-indigo-400 font-bold hover:underline touch-press flex items-center gap-1" title="View Workload Chart">
                                      <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
                                      <span>Workload</span>
                                    </button>
                                    <button @click="quickChangeGroupLeader(m.id)" class="text-blue-600 dark:text-blue-400 font-bold hover:underline touch-press">
                                      Make Leader
                                    </button>
                                  </div>

                                </div>

                              </div>
                            </template>
                          </div>

                        </div>
                      </template>

                      <!-- If Group Has No Additional Members -->
                      <template x-if="activeGroup && (!activeGroup.tree || !activeGroup.tree.members || activeGroup.tree.members.length === 0)">
                        <div class="text-center p-6 bg-slate-50 dark:bg-slate-900/40 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700/80 max-w-md mx-auto space-y-2">
                          <p class="text-xs text-slate-500 dark:text-slate-400">No additional team members in this group yet.</p>
                          <button @click="openAddMembersToGroupModal()" class="px-3.5 py-1.5 bg-blue-600 text-white rounded-xl text-xs font-bold hover:bg-blue-700 shadow-xs touch-press">
                            + Add Members to Group
                          </button>
                        </div>
                      </template>

                    </div>

                  </div>
                </div>

              </div>

              <!-- Group Members Management Table -->
              <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200/90 dark:border-slate-700/80 p-4 sm:p-5 shadow-xs space-y-3">
                <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2.5">
                  <div>
                    <h3 class="text-xs font-bold text-slate-900 dark:text-slate-100 uppercase tracking-wider">
                      Group Member Roster (<span x-text="activeGroup && activeGroup.members ? activeGroup.members.length : 0"></span>)
                    </h3>
                    <p class="text-[11px] text-slate-400">Complete list of members assigned to <span class="font-bold text-slate-600 dark:text-slate-300" x-text="activeGroup ? activeGroup.name : ''"></span></p>
                  </div>

                  <button @click="openAddMembersToGroupModal()" 
                    class="px-3 py-1.5 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-300 border border-blue-200 dark:border-blue-800 rounded-xl text-xs font-bold hover:bg-blue-100 transition-colors flex items-center gap-1.5 self-start sm:self-auto touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                    <span>Add Member</span>
                  </button>
                </div>

                <!-- Members Table -->
                <div class="overflow-x-auto no-scrollbar">
                  <table class="w-full text-left text-xs">
                    <thead>
                      <tr class="border-b border-slate-100 dark:border-slate-700/80 text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                        <th class="py-2.5 px-3">Team Member</th>
                        <th class="py-2.5 px-3">Job Title / Role</th>
                        <th class="py-2.5 px-3 hidden md:table-cell">Department</th>
                        <th class="py-2.5 px-3 hidden sm:table-cell">Contact</th>
                        <th class="py-2.5 px-3">Group Role</th>
                        <th class="py-2.5 px-3 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100 dark:divide-slate-700/50">
                      <template x-for="m in (activeGroup ? activeGroup.members : [])" :key="m.id">
                        <tr class="hover:bg-slate-50/60 dark:hover:bg-slate-700/30 transition-colors">
                          
                          <!-- Member Name & Avatar -->
                          <td class="py-3 px-3">
                            <div class="flex items-center gap-2.5 min-w-0">
                              <div class="w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-xs shrink-0 shadow-xs"
                                :class="m.color_class || 'bg-blue-600'">
                                <span x-text="m.initials || m.name.substring(0, 2).toUpperCase()"></span>
                              </div>
                              <div class="min-w-0">
                                <div class="font-bold text-slate-900 dark:text-slate-100 truncate" x-text="m.name"></div>
                                <div class="text-[10px] text-slate-400 md:hidden truncate" x-text="m.role"></div>
                              </div>
                            </div>
                          </td>

                          <!-- Job Title -->
                          <td class="py-3 px-3 font-medium text-slate-700 dark:text-slate-300" x-text="m.role"></td>

                          <!-- Department -->
                          <td class="py-3 px-3 hidden md:table-cell text-slate-500 dark:text-slate-400" x-text="m.department || 'Engineering'"></td>

                          <!-- Contact -->
                          <td class="py-3 px-3 hidden sm:table-cell text-slate-500 dark:text-slate-400 truncate max-w-[140px]" x-text="m.email || m.phone || '—'"></td>

                          <!-- Group Role Badge -->
                          <td class="py-3 px-3">
                            <template x-if="m.is_leader">
                              <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-blue-100 dark:bg-blue-900/60 text-blue-700 dark:text-blue-300 border border-blue-200 dark:border-blue-800">
                                Leader
                              </span>
                            </template>
                            <template x-if="!m.is_leader">
                              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                                Member
                              </span>
                            </template>
                          </td>

                          <!-- Actions -->
                          <td class="py-3 px-3 text-right">
                            <div class="flex items-center justify-end gap-2">
                              <button @click="openMemberChartModal(m)" 
                                class="px-2 py-1 text-[10px] font-bold text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-950/40 rounded-lg transition-colors touch-press flex items-center gap-1"
                                title="View Member Workload Chart">
                                <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
                                <span>Chart</span>
                              </button>
                              <button x-show="!m.is_leader" @click="quickChangeGroupLeader(m.id)" 
                                class="px-2 py-1 text-[10px] font-bold text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-lg transition-colors touch-press">
                                Set Leader
                              </button>
                              <button @click="promptRemoveGroupMember(m)" 
                                class="px-2 py-1 text-[10px] font-bold text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/40 rounded-lg transition-colors touch-press"
                                title="Remove from Group">
                                Remove
                              </button>
                            </div>
                          </td>

                        </tr>
                      </template>
                    </tbody>
                  </table>
                </div>

              </div>

            </div>

          </div>

          <!-- ===================================================================
               SCREEN: REPORTS & FINANCIAL DASHBOARD (Desktop, Laptop, iPad & Mobile)
               =================================================================== -->
          <div x-show="currentView === 'reports'" class="space-y-4 pb-16" x-cloak>

            <!-- 1. Top Controls Bar: Month / Period Navigation, View Toggle & Export -->
            <div class="bg-white rounded-2xl border border-slate-200/90 p-3 shadow-xs space-y-3">
              <div class="flex flex-wrap items-center justify-between gap-2.5">
                
                <!-- Period Navigator (Prev, Month Picker, Next, Today) -->
                <div class="flex items-center gap-1.5 flex-wrap">
                  <div class="flex items-center bg-slate-100 rounded-xl p-1 border border-slate-200/80">
                    <button type="button" @click="changeReportMonth(-1)" class="w-7 h-7 rounded-lg hover:bg-white text-slate-600 flex items-center justify-center transition touch-press" title="Previous Month">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
                    </button>
                    
                    <input type="month" x-model="reportsState.selectedMonth" @change="reportsState.periodType = 'month'; loadReports()" 
                      class="bg-transparent border-0 text-xs font-bold text-slate-800 px-2 py-1 focus:ring-0 cursor-pointer">

                    <button type="button" @click="changeReportMonth(1)" class="w-7 h-7 rounded-lg hover:bg-white text-slate-600 flex items-center justify-center transition touch-press" title="Next Month">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                    </button>
                  </div>

                  <!-- Quick Current Month Reset -->
                  <button type="button" @click="resetReportMonth()" class="px-2.5 py-1.5 rounded-xl text-[11px] font-bold bg-slate-100 hover:bg-slate-200 text-slate-600 transition touch-press" title="Current Month">
                    Current
                  </button>

                  <!-- Custom Date Range Toggle -->
                  <div class="relative">
                    <button type="button" @click="reportsState.customRangePopoverOpen = !reportsState.customRangePopoverOpen" 
                      class="px-2.5 py-1.5 rounded-xl text-[11px] font-bold flex items-center gap-1.5 transition touch-press"
                      :class="reportsState.periodType === 'custom' ? 'bg-blue-600 text-white' : 'bg-slate-100 hover:bg-slate-200 text-slate-600'">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                      <span>Custom Dates</span>
                    </button>

                    <!-- Custom Range Dropdown Popover -->
                    <div x-show="reportsState.customRangePopoverOpen" @click.away="reportsState.customRangePopoverOpen = false" 
                      class="absolute top-full left-0 mt-2 w-72 bg-white rounded-2xl border border-slate-200 shadow-xl p-4 z-50 space-y-3" x-cloak>
                      <div class="text-xs font-bold text-slate-800">Select Custom Reporting Period</div>
                      <div class="space-y-2">
                        <div>
                          <label class="text-[10px] font-bold text-slate-400 uppercase">Start Date</label>
                          <input type="date" x-model="reportsState.customStartDate" class="w-full mt-1 border border-slate-200 rounded-xl px-2.5 py-1.5 text-xs text-slate-800">
                        </div>
                        <div>
                          <label class="text-[10px] font-bold text-slate-400 uppercase">End Date</label>
                          <input type="date" x-model="reportsState.customEndDate" class="w-full mt-1 border border-slate-200 rounded-xl px-2.5 py-1.5 text-xs text-slate-800">
                        </div>
                      </div>
                      <div class="flex items-center gap-2 pt-1">
                        <button type="button" @click="applyCustomReportRange()" class="flex-1 py-1.5 bg-blue-600 text-white rounded-xl text-xs font-bold shadow-xs hover:bg-blue-700">Apply</button>
                        <button type="button" @click="reportsState.customRangePopoverOpen = false" class="py-1.5 px-3 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold hover:bg-slate-200">Cancel</button>
                      </div>
                    </div>
                  </div>
                </div>

                <!-- Right Actions: Desktop/Mobile View Switcher & Download Reports Dropdown -->
                <div class="flex items-center gap-2 shrink-0">
                  
                  <!-- Desktop / Mobile View Frame Toggle (Desktop only helper) -->
                  <button type="button" @click="toggleReportsWideMode()" 
                    class="hidden md:flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl text-[11px] font-bold border transition touch-press"
                    :class="reportsState.wideMode ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-slate-50 border-slate-200 text-slate-600'"
                    :title="reportsState.wideMode ? 'Switch to Compact Mobile View' : 'Expand to Wide Multi-Column Dashboard'">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4"/></svg>
                    <span x-text="reportsState.wideMode ? 'Wide View' : 'Mobile Frame'"></span>
                  </button>

                  <!-- Download Reports Button & Dropdown -->
                  <div class="relative">
                    <button type="button" @click="reportsState.exportMenuOpen = !reportsState.exportMenuOpen" 
                      class="px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-bold text-xs shadow-xs flex items-center gap-1.5 touch-press transition">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                      <span>Download</span>
                      <svg class="w-3 h-3 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 9l-7 7-7-7"/></svg>
                    </button>

                    <!-- Export Dropdown Menu -->
                    <div x-show="reportsState.exportMenuOpen" @click.away="reportsState.exportMenuOpen = false" 
                      class="absolute right-0 top-full mt-2 w-64 bg-white rounded-2xl border border-slate-200 shadow-2xl p-1.5 z-50 text-xs space-y-1" x-cloak>
                      <div class="px-3 py-1.5 text-[10px] font-extrabold uppercase tracking-wider text-slate-400 border-b border-slate-100">
                        Export Financial Reports
                      </div>
                      
