                  <div class="relative flex-1">
                    <input type="text" x-model="reportsState.paymentsSearch" @input.debounce.300ms="loadReports()" 
                      placeholder="Search payments by receipt, invoice, client, or txn ID..."
                      class="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-8 py-2 text-xs text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
                    <div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                    </div>
                    <button x-show="reportsState.paymentsSearch" @click="reportsState.paymentsSearch = ''; loadReports()" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400 hover:text-slate-600">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>

                  <!-- Payment Method Filter -->
                  <select x-model="reportsState.paymentsMethodFilter" @change="loadReports()" 
                    class="bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-xs text-slate-700 font-medium focus:outline-none">
                    <option value="all">All Payment Methods</option>
                    <option value="Online Transfer">Online Transfer</option>
                    <option value="UPI">UPI</option>
                    <option value="Credit Card">Credit Card</option>
                    <option value="Bank Transfer">Bank Transfer</option>
                    <option value="Cash">Cash</option>
                  </select>

                  <!-- Payment Status Filter -->
                  <select x-model="reportsState.paymentsStatusFilter" @change="loadReports()" 
                    class="bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-xs text-slate-700 font-medium focus:outline-none">
                    <option value="all">All Statuses</option>
                    <option value="Paid">Paid</option>
                    <option value="Pending">Pending</option>
                  </select>

                  <!-- Download Payments CSV shortcut -->
                  <button type="button" @click="downloadReport('payments_csv')" 
                    class="px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-bold shrink-0 flex items-center gap-1.5 transition touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                    <span>Export CSV</span>
                  </button>
                </div>
              </div>

              <!-- Payments Data Table -->
              <div class="bg-white rounded-2xl border border-slate-200/90 shadow-xs overflow-hidden">
                <div class="overflow-x-auto no-scrollbar">
                  <table class="w-full text-left text-xs border-collapse">
                    <thead>
                      <tr class="bg-slate-50 border-b border-slate-200/80 text-[10px] font-extrabold uppercase text-slate-400 tracking-wider">
                        <th class="py-3 px-3.5">Receipt #</th>
                        <th class="py-3 px-3">Invoice #</th>
                        <th class="py-3 px-3">Client Name</th>
                        <th class="py-3 px-3">Payment Date</th>
                        <th class="py-3 px-3">Method</th>
                        <th class="py-3 px-3 text-right">Amount (₹)</th>
                        <th class="py-3 px-3">Status</th>
                        <th class="py-3 px-3">Reference / Txn</th>
                        <th class="py-3 px-3 text-center">Receipt</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      <template x-if="reportsState.payments.length === 0">
                        <tr>
                          <td colspan="9" class="py-10 text-center text-slate-400">
                            <div class="flex flex-col items-center justify-center gap-1">
                              <svg class="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                              <span class="text-xs font-bold text-slate-600">No payment records found for this period</span>
                              <span class="text-[11px] text-slate-400">Try adjusting your date range or search filter.</span>
                            </div>
                          </td>
                        </tr>
                      </template>

                      <template x-for="p in reportsState.payments" :key="p.id">
                        <tr class="hover:bg-slate-50/80 transition cursor-pointer" @click="viewPaymentDetail(p)">
                          <td class="py-3 px-3.5 font-bold font-mono text-blue-600 truncate max-w-[120px]" x-text="p.receipt_no || p.id"></td>
                          <td class="py-3 px-3 font-mono text-slate-600 truncate max-w-[120px]" x-text="p.invoice_no || '-'"></td>
                          <td class="py-3 px-3 font-bold text-slate-900 truncate max-w-[150px]" x-text="p.customer_name || '-'"></td>
                          <td class="py-3 px-3 text-slate-500 whitespace-nowrap" x-text="p.payment_date || p.normalized_date"></td>
                          <td class="py-3 px-3 whitespace-nowrap">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700" x-text="p.payment_method || 'Online'"></span>
                          </td>
                          <td class="py-3 px-3 text-right font-black text-emerald-600 whitespace-nowrap" x-text="formatMoney(p.amount)"></td>
                          <td class="py-3 px-3 whitespace-nowrap">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-700" x-text="p.status || 'Paid'"></span>
                          </td>
                          <td class="py-3 px-3 font-mono text-slate-400 text-[11px] truncate max-w-[130px]" x-text="p.transaction_id || (p.reference || '-')"></td>
                          <td class="py-3 px-3 text-center" @click.stop>
                            <a :href="'api/ledger.php?action=print_receipt&receipt_no=' + encodeURIComponent(p.receipt_no || p.id)" target="_blank" 
                              class="p-1 text-blue-600 hover:text-blue-800 touch-press inline-block" title="View Printable Receipt">
                              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                            </a>
                          </td>
                        </tr>
                      </template>
                    </tbody>
                  </table>
                </div>

                <!-- Bottom Summary Strip -->
                <div class="p-3 bg-slate-50 border-t border-slate-200/80 flex items-center justify-between text-xs font-bold text-slate-700">
                  <span x-text="reportsState.payments.length + ' Payment Records'"></span>
                  <div class="flex items-center gap-2">
                    <span class="text-slate-400">Total Collected:</span>
                    <span class="text-emerald-600 font-black text-sm" x-text="formatMoney(reportsState.paymentsTotal)"></span>
                  </div>
                </div>
              </div>

            </div>

            <!-- =================================================================
                 TAB 3: BUSINESS EXPENSES MANAGEMENT
                 ================================================================= -->
            <div x-show="reportsState.activeTab === 'expenses'" class="space-y-3">
              
              <!-- Search, Filter & Add Button Strip -->
              <div class="bg-white rounded-2xl border border-slate-200/90 p-3 shadow-xs space-y-2.5">
                <div class="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
                  <div class="relative flex-1">
                    <input type="text" x-model="reportsState.expensesSearch" @input.debounce.300ms="loadReports()" 
                      placeholder="Search expenses by description, reference, or notes..."
                      class="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-8 py-2 text-xs text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
                    <div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                    </div>
                    <button x-show="reportsState.expensesSearch" @click="reportsState.expensesSearch = ''; loadReports()" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400 hover:text-slate-600">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>

                  <!-- Category Filter -->
                  <select x-model="reportsState.expensesCategoryFilter" @change="loadReports()" 
                    class="bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-xs text-slate-700 font-medium focus:outline-none">
                    <option value="all">All Categories</option>
                    <option value="Cloud & Infrastructure">Cloud & Infrastructure</option>
                    <option value="Software & Tools">Software & Tools</option>
                    <option value="Office & Utilities">Office & Utilities</option>
                    <option value="Salaries & Contractors">Salaries & Contractors</option>
                    <option value="Marketing & Sales">Marketing & Sales</option>
                    <option value="Travel & Entertainment">Travel & Entertainment</option>
                    <option value="Other">Other</option>
                  </select>

                  <!-- Add Expense Action Button -->
                  <button type="button" @click="openAddExpenseModal()" 
                    class="px-3.5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold shrink-0 flex items-center gap-1.5 shadow-xs transition touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                    <span>Record Expense</span>
                  </button>
                </div>

                <!-- Category Breakdown Summary Chips -->
                <div class="flex items-center gap-1.5 overflow-x-auto no-scrollbar pt-1">
                  <template x-for="(amt, cat) in reportsState.categoryTotals" :key="cat">
                    <div class="px-2.5 py-1 rounded-xl bg-slate-100 border border-slate-200/80 text-[10px] flex items-center gap-1.5 shrink-0">
                      <span class="font-bold text-slate-700" x-text="cat"></span>
                      <span class="font-black text-amber-600 font-mono" x-text="formatMoney(amt)"></span>
                    </div>
                  </template>
                </div>
              </div>

              <!-- Expenses Data Table -->
              <div class="bg-white rounded-2xl border border-slate-200/90 shadow-xs overflow-hidden">
                <div class="overflow-x-auto no-scrollbar">
                  <table class="w-full text-left text-xs border-collapse">
                    <thead>
                      <tr class="bg-slate-50 border-b border-slate-200/80 text-[10px] font-extrabold uppercase text-slate-400 tracking-wider">
                        <th class="py-3 px-3.5">Expense ID</th>
                        <th class="py-3 px-3">Date</th>
                        <th class="py-3 px-3">Category</th>
                        <th class="py-3 px-3">Description</th>
                        <th class="py-3 px-3 text-right">Amount (₹)</th>
                        <th class="py-3 px-3">Payment Method</th>
                        <th class="py-3 px-3">Reference</th>
                        <th class="py-3 px-3 text-center">Actions</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      <template x-if="reportsState.expenses.length === 0">
                        <tr>
                          <td colspan="8" class="py-10 text-center text-slate-400">
                            <div class="flex flex-col items-center justify-center gap-1">
                              <svg class="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                              <span class="text-xs font-bold text-slate-600">No expenses recorded for this period</span>
                              <span class="text-[11px] text-slate-400">Click &ldquo;Record Expense&rdquo; above to log an operating cost.</span>
                            </div>
                          </td>
                        </tr>
                      </template>

                      <template x-for="e in reportsState.expenses" :key="e.id">
                        <tr class="hover:bg-slate-50/80 transition">
                          <td class="py-3 px-3.5 font-bold font-mono text-slate-600 truncate max-w-[110px]" x-text="e.id"></td>
                          <td class="py-3 px-3 text-slate-500 whitespace-nowrap" x-text="e.expense_date"></td>
                          <td class="py-3 px-3 whitespace-nowrap">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-50 text-blue-700" x-text="e.category"></span>
                          </td>
                          <td class="py-3 px-3 font-medium text-slate-900 max-w-[220px]">
                            <div class="truncate" x-text="e.description"></div>
                            <div x-show="e.notes" class="text-[10px] text-slate-400 truncate mt-0.5" x-text="e.notes"></div>
                          </td>
                          <td class="py-3 px-3 text-right font-black text-amber-600 whitespace-nowrap" x-text="formatMoney(e.amount)"></td>
                          <td class="py-3 px-3 text-slate-600 whitespace-nowrap" x-text="e.payment_method || '-'"></td>
                          <td class="py-3 px-3 font-mono text-slate-400 text-[11px] truncate max-w-[120px]" x-text="e.reference || '-'"></td>
                          <td class="py-3 px-3 text-center whitespace-nowrap">
                            <div class="flex items-center justify-center gap-1">
                              <button type="button" @click="openEditExpenseModal(e)" class="p-1 text-slate-500 hover:text-blue-600 transition" title="Edit Expense">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                              </button>
                              <button type="button" @click="confirmDeleteExpense(e)" class="p-1 text-slate-400 hover:text-rose-600 transition" title="Delete Expense">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              </button>
                            </div>
                          </td>
                        </tr>
                      </template>
                    </tbody>
                  </table>
                </div>

                <!-- Bottom Summary Strip -->
                <div class="p-3 bg-slate-50 border-t border-slate-200/80 flex items-center justify-between text-xs font-bold text-slate-700">
                  <span x-text="reportsState.expenses.length + ' Recorded Expenses'"></span>
                  <div class="flex items-center gap-2">
                    <span class="text-slate-400">Total Expenses:</span>
                    <span class="text-amber-600 font-black text-sm" x-text="formatMoney(reportsState.expensesTotal)"></span>
                  </div>
                </div>
              </div>

            </div>

            <!-- =================================================================
                 TAB 4: PROFIT & LOSS STATEMENT
                 ================================================================= -->
            <div x-show="reportsState.activeTab === 'pnl'" class="space-y-4">
              
              <div class="bg-white rounded-2xl border border-slate-200/90 p-5 shadow-xs space-y-4">
                <div class="flex items-center justify-between pb-3 border-b border-slate-200">
                  <div>
                    <h3 class="text-sm font-black text-slate-900">Profit & Loss Statement</h3>
                    <p class="text-xs text-slate-400 mt-0.5">Reporting Period: <strong class="text-slate-700" x-text="reportsState.periodLabel"></strong></p>
                  </div>
                  <button type="button" @click="downloadReport('pnl_csv')" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-bold flex items-center gap-1.5">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                    <span>Export P&L</span>
                  </button>
                </div>

                <!-- Financial Statement Line Items -->
                <div class="space-y-4 text-xs">
                  
                  <!-- Section A: Revenue -->
                  <div class="space-y-2">
                    <div class="text-[11px] font-black uppercase tracking-wider text-slate-400">1. Operating Revenue</div>
                    <div class="flex justify-between py-1.5 px-3 bg-slate-50 rounded-xl text-slate-700">
                      <span>Total Invoiced Sales (Accrual Basis)</span>
                      <span class="font-bold text-slate-900" x-text="formatMoney(reportsState.summary?.summary_cards?.total_revenue)"></span>
                    </div>
                    <div class="flex justify-between py-1.5 px-3 bg-emerald-50/60 rounded-xl text-emerald-800 font-bold">
                      <span>Actual Cash Collections (Cash Basis Receipts)</span>
                      <span class="font-black text-emerald-700" x-text="formatMoney(reportsState.summary?.summary_cards?.payments_received)"></span>
                    </div>
                  </div>

                  <!-- Section B: Cost of Goods Sold -->
                  <div class="space-y-2">
                    <div class="text-[11px] font-black uppercase tracking-wider text-slate-400">2. Cost of Sales (COGS)</div>
                    <div class="flex justify-between py-1.5 px-3 bg-slate-50 rounded-xl text-slate-700">
                      <span>Direct Software / Subcontractor Line Items</span>
                      <span class="font-bold text-slate-900">₹0.00</span>
                    </div>
                    <div class="flex justify-between py-1.5 px-3 bg-blue-50/70 rounded-xl text-blue-900 font-bold">
                      <span>Gross Profit (Revenue &minus; COGS)</span>
                      <span class="font-black text-blue-700" x-text="formatMoney(reportsState.summary?.summary_cards?.gross_profit)"></span>
                    </div>
                  </div>

                  <!-- Section C: Operating Expenses -->
                  <div class="space-y-2">
                    <div class="text-[11px] font-black uppercase tracking-wider text-slate-400">3. Operating Expenses by Category</div>
                    <div class="space-y-1">
                      <template x-for="eb in (reportsState.summary?.charts?.expense_breakdown || [])" :key="eb.category">
                        <div class="flex justify-between py-1 px-3 text-slate-600 hover:bg-slate-50 rounded-lg">
                          <span x-text="eb.category"></span>
                          <span class="font-medium font-mono" x-text="formatMoney(eb.amount)"></span>
                        </div>
                      </template>
                    </div>
                    <div class="flex justify-between py-1.5 px-3 bg-amber-50/70 rounded-xl text-amber-900 font-bold">
                      <span>Total Operating Overhead</span>
                      <span class="font-black text-amber-700" x-text="formatMoney(reportsState.summary?.summary_cards?.total_expenses)"></span>
                    </div>
                  </div>

                  <!-- Section D: Net Profit Summary -->
                  <div class="pt-2 border-t border-slate-200 space-y-2">
                    <div class="text-[11px] font-black uppercase tracking-wider text-slate-400">4. Net Profit Summary</div>
                    
                    <div class="flex justify-between py-2 px-3 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-950 font-black text-sm">
                      <div>
                        <div>Net Profit (Cash Basis)</div>
                        <div class="text-[10px] font-normal text-emerald-700">Actual Collections &minus; Recorded Operating Expenses</div>
                      </div>
                      <span class="text-base" x-text="formatMoney(reportsState.summary?.summary_cards?.net_profit)"></span>
                    </div>

                    <div class="flex justify-between py-2 px-3 rounded-xl border border-indigo-200 bg-indigo-50 text-indigo-950 font-black text-sm">
                      <div>
                        <div>Net Profit (Accrual Basis)</div>
                        <div class="text-[10px] font-normal text-indigo-700">Total Invoiced &minus; Recorded Operating Expenses</div>
                      </div>
                      <span class="text-base" x-text="formatMoney(reportsState.summary?.summary_cards?.net_profit_accrual)"></span>
                    </div>
                  </div>

                  <!-- Section E: Methodology Note -->
                  <div class="p-3 bg-slate-50 rounded-xl border border-slate-200 text-[11px] text-slate-500 space-y-1">
                    <div class="font-bold text-slate-700">Financial Calculation Methodology:</div>
                    <p>• <strong>Cash Receipts</strong> reflect verified transactions recorded in <code class="bg-slate-200 px-1 rounded">crm_payments</code> with payment date in period.</p>
                    <p>• <strong>Outstanding Receivables</strong> reflect unpaid invoice balances as of the reporting date.</p>
                    <p>• <strong>Gross Profit</strong> reflects 100% services gross margin as direct developer labor is accounted under operational payroll overhead.</p>
                  </div>

                </div>

              </div>

            </div>

          </div>


          <!-- ===================================================================
               SCREEN: SETTINGS & BIOMETRIC MOBILE SECURITY (FULLY FUNCTIONAL)
               =================================================================== -->
          <div x-show="currentView === 'settings'" class="space-y-4 pb-12" x-cloak>
            
            <!-- Header with Sync Button & Double-Click Guard -->
            <div class="flex items-center justify-between px-1">
              <div>
                <h2 class="text-base font-extrabold text-slate-900">Settings & Security</h2>
                <p class="text-[10px] text-slate-400 mt-0.5" x-show="settingsData.last_synced_at">
                  Last synced: <span class="font-medium text-slate-600" x-text="settingsData.last_synced_at"></span>
                </p>
              </div>
              <button type="button" @click="syncData()" :disabled="isSyncing" 
                class="text-[11px] font-bold text-blue-600 hover:text-blue-700 disabled:opacity-50 flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg hover:bg-blue-50/80 touch-press transition">
                <svg :class="isSyncing ? 'animate-spin' : ''" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                <span x-text="isSyncing ? 'Syncing...' : 'Sync'">Sync</span>
              </button>
            </div>

            <!-- Sync Feedback Banner (Success / Informative Failure) -->
            <template x-if="syncFeedback">
              <div :class="syncFeedback.type === 'success' ? 'bg-emerald-50 border-emerald-200/80 text-emerald-900' : 'bg-amber-50 border-amber-200/80 text-amber-900'"
                class="p-3.5 rounded-2xl border text-xs shadow-xs space-y-2">
                <div class="flex items-start gap-2.5">
                  <template x-if="syncFeedback.type === 'success'">
                    <svg class="w-4 h-4 text-emerald-600 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>
                  </template>
                  <template x-if="syncFeedback.type === 'error'">
                    <svg class="w-4 h-4 text-amber-600 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                  </template>
                  <div class="min-w-0 flex-1">
                    <p class="font-bold text-xs" x-text="syncFeedback.message"></p>
                    <template x-if="syncFeedback.instructions && syncFeedback.instructions.length > 0">
                      <ul class="mt-2 space-y-1 text-[11px] list-disc list-inside text-amber-800">
                        <template x-for="(inst, idx) in syncFeedback.instructions" :key="idx">
                          <li x-text="inst"></li>
                        </template>
                      </ul>
                    </template>
                  </div>
                  <button type="button" @click="syncFeedback = null" class="text-slate-400 hover:text-slate-600 p-1 touch-press">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </div>
              </div>
            </template>

            <!-- Responsive 2-Column Grid on Desktop / Laptop (lg+) -->
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-4 lg:gap-6 items-start">
              
              <!-- Column 1: Account Settings & Security Access Control -->
              <div class="space-y-4">

            <!-- ===================================================================
                 CATEGORY 1: ACCOUNT SETTINGS
                 =================================================================== -->
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-4 text-xs">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <div class="flex items-center gap-2">
                  <div class="w-7 h-7 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                  </div>
                  <div>
                    <h3 class="font-extrabold text-slate-900 text-xs">Account Settings</h3>
                    <p class="text-[10px] text-slate-400">Employee Profile & Preferences</p>
                  </div>
                </div>
                <span class="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase bg-emerald-50 text-emerald-700 border border-emerald-200/60 flex items-center gap-1">
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                  <span x-text="settingsData.user?.status || 'Active'">Active</span>
                </span>
              </div>

              <!-- Profile Details -->
              <div class="flex items-start gap-3.5">
                <div class="w-13 h-13 rounded-2xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white font-extrabold text-lg flex items-center justify-center uppercase shadow-sm shrink-0">
                  <span x-text="computeInitials(settingsData.user?.name || currentUser.name)"></span>
                </div>
                <div class="min-w-0 flex-1 space-y-1">
                  <div class="flex items-center gap-2 flex-wrap">
                    <h4 class="font-extrabold text-slate-900 text-sm truncate" x-text="settingsData.user?.name || currentUser.name"></h4>
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase bg-blue-50 text-blue-700 border border-blue-200/60" x-text="settingsData.user?.role || currentUser.role || 'Member'"></span>
                  </div>
                  <p class="text-[11px] text-slate-500 truncate" x-text="settingsData.user?.email || currentUser.email"></p>
                  <p class="text-[10px] text-slate-400 font-mono" x-text="'Employee ID: #' + (settingsData.user?.employee_id || 'EMP-001')"></p>
                </div>
              </div>

              <!-- Contact & Organization Meta -->
              <div class="grid grid-cols-2 gap-2.5 pt-2 border-t border-slate-100 text-[11px]">
                <div class="p-2.5 rounded-xl bg-slate-50/70 border border-slate-100 space-y-0.5">
                  <span class="text-[10px] font-semibold text-slate-400">Phone Number</span>
                  <p class="font-bold text-slate-800 truncate" x-text="settingsData.profile?.phone || 'Not provided'"></p>
                </div>
                <div class="p-2.5 rounded-xl bg-slate-50/70 border border-slate-100 space-y-0.5">
                  <span class="text-[10px] font-semibold text-slate-400">Department</span>
                  <p class="font-bold text-slate-800 truncate" x-text="settingsData.profile?.department || 'Engineering'"></p>
                </div>
                <div class="p-2.5 rounded-xl bg-slate-50/70 border border-slate-100 space-y-0.5">
                  <span class="text-[10px] font-semibold text-slate-400">Company</span>
                  <p class="font-bold text-slate-800 truncate" x-text="settingsData.profile?.company || 'ABC Tech Solutions'"></p>
                </div>
                <div class="p-2.5 rounded-xl bg-slate-50/70 border border-slate-100 space-y-0.5">
                  <span class="text-[10px] font-semibold text-slate-400">Location</span>
                  <p class="font-bold text-slate-800 truncate" x-text="settingsData.profile?.location || 'Bangalore, India'"></p>
                </div>
              </div>

              <!-- Action Buttons for Account Profile -->
              <div class="grid grid-cols-2 gap-2 pt-1">
                <button type="button" @click="openEditProfileModal()" 
                  class="w-full py-2 px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-[11px] flex items-center justify-center gap-1.5 touch-press transition">
                  <svg class="w-3.5 h-3.5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                  <span>Edit Profile</span>
                </button>
                <button type="button" @click="openChangePasswordModal()" 
                  class="w-full py-2 px-3 rounded-xl bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold text-[11px] flex items-center justify-center gap-1.5 touch-press transition">
                  <svg class="w-3.5 h-3.5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
                  <span>Change Password</span>
                </button>
              </div>
            </div>

            <!-- ===================================================================
                 CATEGORY 2: SECURITY & WEBAUTHN BIOMETRICS
                 =================================================================== -->
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5 text-xs">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <div class="flex items-center gap-2">
                  <div class="w-7 h-7 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
                  </div>
                  <div>
                    <h3 class="font-extrabold text-slate-900 text-xs">Security & Access Control</h3>
                    <p class="text-[10px] text-slate-400">Passkeys, Sessions & Verification</p>
                  </div>
                </div>
                <template x-if="biometricDevices.length > 0">
                  <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-50 text-emerald-700 border border-emerald-200/60 flex items-center gap-1">
                    <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    <span>Biometrics Active</span>
                  </span>
                </template>
              </div>

              <!-- Biometric Enrollment Action -->
              <div>
                <button type="button" @click="enrollBiometricDevice()" :disabled="isEnrollingDevice"
                  class="w-full py-2.5 px-3 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold text-xs shadow-md shadow-blue-500/20 flex items-center justify-center gap-2 touch-press transition">
                  <svg x-show="!isEnrollingDevice" class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                  <svg x-show="isEnrollingDevice" class="w-4 h-4 text-white animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                  <span x-text="isEnrollingDevice ? 'Waiting for phone biometric prompt...' : '+ Register This Device (Passkey)'"></span>
                </button>
              </div>

              <!-- Registered Devices List -->
              <div class="space-y-2 pt-1">
                <div class="flex items-center justify-between">
                  <span class="text-[11px] font-bold text-slate-700">Enrolled Devices</span>
                  <span class="text-[10px] font-bold text-slate-400" x-text="biometricDevices.length + ' Registered'"></span>
                </div>

                <div class="space-y-2">
                  <template x-for="dev in biometricDevices" :key="dev.id">
                    <div class="p-2.5 rounded-xl border border-slate-200/80 bg-slate-50/60 flex items-center justify-between gap-2">
                      <div class="flex items-center gap-2.5 min-w-0">
                        <div class="w-8 h-8 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-blue-600 shrink-0">
                          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                        </div>
                        <div class="min-w-0">
                          <div class="font-bold text-slate-900 text-xs truncate" x-text="dev.device_name"></div>
                          <div class="text-[10px] text-slate-400 flex items-center gap-1.5 mt-0.5">
                            <span x-text="'Added: ' + (dev.created_at ? dev.created_at.split(' ')[0] : 'Today')"></span>
                            <span>•</span>
                            <span class="font-mono" x-text="dev.cred_preview"></span>
                          </div>
                        </div>
                      </div>
                      <button type="button" @click="promptRemoveDevice(dev)" class="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg touch-press transition" title="Remove Device">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      </button>
                    </div>
                  </template>

                  <div x-show="biometricDevices.length === 0" class="p-3 text-center bg-slate-50 rounded-xl border border-slate-200/60 text-slate-400 text-[11px]">
                    No biometric devices enrolled yet. Tap "+ Register This Device" to use fingerprint or Face ID.
                  </div>
                </div>

                <div x-show="biometricDevices.length > 0" class="pt-1 text-right">
                  <button type="button" @click="promptDisableAllBiometrics()" class="text-[10px] font-bold text-rose-600 hover:text-rose-700 hover:underline touch-press">
                    Disable Biometric Login for All Devices
                  </button>
                </div>
              </div>

              <!-- Session Management Sub-Card -->
              <div class="pt-2 border-t border-slate-100 space-y-2">
                <div class="flex items-center justify-between">
                  <span class="text-[11px] font-bold text-slate-700">Active Sessions</span>
                  <span class="text-[10px] font-bold text-emerald-600">Online</span>
                </div>
                <div class="p-2.5 rounded-xl border border-slate-200/80 bg-slate-50/70 flex items-center justify-between gap-2">
                  <div class="min-w-0">
                    <div class="flex items-center gap-1.5">
                      <span class="w-2 h-2 rounded-full bg-emerald-500"></span>
                      <span class="font-bold text-slate-800 text-[11px]">This Smartphone / Browser</span>
                    </div>
                    <p class="text-[10px] text-slate-400 mt-0.5">
                      IP: <span class="font-mono text-slate-600" x-text="settingsData.session?.ip_address || '127.0.0.1'"></span> • Login: <span x-text="settingsData.session?.login_time || 'Active'"></span>
                    </p>
                  </div>
                  <button type="button" @click="revokeSessions()" :disabled="isRevokingSessions" 
                    class="py-1 px-2.5 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold text-[10px] touch-press transition">
                    <span x-text="isRevokingSessions ? 'Revoking...' : 'Revoke Others'">Revoke Others</span>
                  </button>
                </div>
              </div>

              <!-- Multi-Factor Security Status -->
              <div class="p-2.5 rounded-xl bg-blue-50/60 border border-blue-100 text-[11px] space-y-1">
                <div class="flex items-center justify-between">
                  <span class="font-bold text-blue-900">Mandatory 4-Digit Email OTP</span>
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-blue-100 text-blue-800">Enforced</span>
                </div>
                <p class="text-[10px] text-blue-700 leading-relaxed">
                  Every sign-in attempt requires two factors: your credentials or biometric passkey, plus a one-time cryptographic code sent to your registered email.
                </p>
              </div>

              <!-- Security Information Callout -->
              <div class="p-2.5 rounded-xl bg-slate-50 border border-slate-200 text-[10px] text-slate-500 leading-relaxed flex items-start gap-2">
                <svg class="w-4 h-4 text-blue-600 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
                <span><strong>Hardware-Protected:</strong> Biometric scans (fingerprint / Face ID) are securely processed inside your phone's hardware enclave and are never uploaded or stored on the server.</span>
              </div>
            </div>

            </div> <!-- /Column 1 -->

            <!-- Column 2: Integrations, Notifications & Appearance -->
            <div class="space-y-4">

            <!-- ===================================================================
                 CATEGORY 3: LIVE INTEGRATIONS & SYSTEM HEALTH
                 =================================================================== -->
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5 text-xs">
              <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                <div class="flex items-center gap-2">
                  <div class="w-7 h-7 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center shrink-0">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                  <div>
                    <h3 class="font-extrabold text-slate-900 text-xs">Integrations & Health</h3>
                    <p class="text-[10px] text-slate-400">Live Status & External Services</p>
                  </div>
                </div>
                <button type="button" @click="loadDiagnostics()" class="text-[10px] font-bold text-indigo-600 hover:text-indigo-700 flex items-center gap-1 touch-press">
                  <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                  <span>Refresh</span>
                </button>
              </div>

              <!-- Integration 1: Google Sheets Employee Registry -->
              <div class="p-3 rounded-xl border border-slate-200/80 bg-slate-50/60 space-y-2">
                <div class="flex items-center justify-between">
                  <div class="flex items-center gap-2">
                    <div class="w-6 h-6 rounded-lg bg-emerald-100 text-emerald-700 flex items-center justify-center shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                    </div>
                    <span class="font-bold text-slate-900 text-xs">Google Sheets API</span>
                  </div>
                  <!-- Granular Connection Status Badges -->
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'CONNECTED'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-100 text-emerald-800" x-text="settingsDiagnostics?.google_sheets?.permission_level === 'Editor' ? 'Connected (Editor)' : 'Connected (Viewer)'">Connected</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'AUTHENTICATION_FAILED'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-rose-100 text-rose-800" title="Google rejected service account JWT assertion">Auth Failed</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'PERMISSION_DENIED'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-amber-100 text-amber-800" title="Spreadsheet not shared with Service Account">Permission Denied</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'SPREADSHEET_NOT_FOUND'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-rose-100 text-rose-800" title="Spreadsheet ID does not exist">Sheet Not Found</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'WORKSHEET_NOT_FOUND'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-amber-100 text-amber-800" title="Sheet2 tab not found in spreadsheet">Sheet2 Not Found</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'API_NOT_ENABLED'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-purple-100 text-purple-800" title="Sheets API disabled in Google Cloud">API Disabled</span>
                  </template>
                  <template x-if="settingsDiagnostics?.google_sheets?.connection_status === 'CONFIGURATION_ERROR'">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-slate-200 text-slate-700" title="Missing credentials or spreadsheet ID">Config Error</span>
                  </template>
                  <template x-if="!['CONNECTED','AUTHENTICATION_FAILED','PERMISSION_DENIED','SPREADSHEET_NOT_FOUND','WORKSHEET_NOT_FOUND','API_NOT_ENABLED','CONFIGURATION_ERROR'].includes(settingsDiagnostics?.google_sheets?.connection_status)">
                    <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-amber-100 text-amber-800" x-text="settingsDiagnostics?.google_sheets?.connection_status || 'Checking...'">Checking...</span>
                  </template>
                </div>
                <div class="space-y-1 text-[10px] text-slate-500 font-mono">
                  <p>Spreadsheet: <span class="text-slate-800 font-bold" x-text="settingsDiagnostics?.google_sheets?.spreadsheet_id ? (settingsDiagnostics.google_sheets.spreadsheet_id.substring(0, 16) + '...') : '1eC09oWaqhe2T...'"></span> (Sheet2)</p>
                  <p>Target Range: <span class="text-slate-800 font-semibold" x-text="settingsDiagnostics?.google_sheets?.target_range || 'Sheet2!A1:Z1000'"></span></p>
                  <p>Service Account: <span class="text-slate-700 font-semibold truncate block max-w-full" x-text="settingsDiagnostics?.google_sheets?.service_account_email || 'Configured via JSON Key'"></span></p>
                </div>
                <template x-if="settingsDiagnostics?.google_sheets?.error">
                  <div class="mt-1 p-2 rounded bg-rose-50 border border-rose-100 text-[10px] text-rose-700">
                    <p class="font-bold flex items-center gap-1">
                      <svg class="w-3 h-3 text-rose-500 shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clip-rule="evenodd"/></svg>
                      <span x-text="settingsDiagnostics.google_sheets.connection_status"></span>
                    </p>
                    <p class="mt-0.5 text-[9px] text-rose-600 line-clamp-2" x-text="settingsDiagnostics.google_sheets.error"></p>
                  </div>
                </template>
              </div>

              <!-- Integration 2: Employee Registry Status -->
              <div class="p-3 rounded-xl border border-slate-200/80 bg-slate-50/60 space-y-1.5">
                <div class="flex items-center justify-between">
                  <div class="flex items-center gap-2">
                    <div class="w-6 h-6 rounded-lg bg-blue-100 text-blue-700 flex items-center justify-center shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                    </div>
                    <span class="font-bold text-slate-900 text-xs">Employee Registry</span>
                  </div>
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-blue-100 text-blue-800">Operational</span>
                </div>
                <div class="flex items-center justify-between text-[11px] text-slate-600 pt-0.5">
                  <span>Registered Staff: <strong class="text-slate-900" x-text="settingsDiagnostics?.employee_registry?.total_employees || '12'"></strong></span>
                  <span>Active: <strong class="text-emerald-700" x-text="settingsDiagnostics?.employee_registry?.active_employees || '12'"></strong></span>
                </div>
              </div>

              <!-- Integration 3: Transactional Email Delivery -->
              <div class="p-3 rounded-xl border border-slate-200/80 bg-slate-50/60 space-y-1.5">
                <div class="flex items-center justify-between">
                  <div class="flex items-center gap-2">
                    <div class="w-6 h-6 rounded-lg bg-amber-100 text-amber-700 flex items-center justify-center shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                    </div>
                    <span class="font-bold text-slate-900 text-xs">Email Delivery Dispatcher</span>
                  </div>
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-100 text-emerald-800">Operational</span>
                </div>
                <div class="flex items-center justify-between text-[10px] text-slate-500">
                  <span>Provider: <strong class="text-slate-800 uppercase" x-text="settingsDiagnostics?.email_delivery?.provider || 'Auto'"></strong></span>
                  <span class="truncate max-w-[180px]" x-text="settingsDiagnostics?.email_delivery?.sender_email || 'security@softwarecrm.com'"></span>
                </div>
              </div>

              <!-- Integration 4: Database Health -->
              <div class="p-3 rounded-xl border border-slate-200/80 bg-slate-50/60 space-y-1.5">
                <div class="flex items-center justify-between">
                  <div class="flex items-center gap-2">
                    <div class="w-6 h-6 rounded-lg bg-purple-100 text-purple-700 flex items-center justify-center shrink-0">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 7v10c0 2.21 3.582 4 8 4s8-1.79 8-4V7M4 7c0 2.21 3.582 4 8 4s8-1.79 8-4M4 7c0-2.21 3.582-4 8-4s8 1.79 8 4m0 5c0 2.21-3.582 4-8 4s-8-1.79-8-4"/></svg>
                    </div>
                    <span class="font-bold text-slate-900 text-xs">MySQL / MariaDB</span>
                  </div>
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-100 text-emerald-800">Port 3306</span>
                </div>
                <div class="flex items-center justify-between text-[10px] text-slate-500 font-mono">
                  <span>Engine: <strong class="text-slate-800" x-text="settingsDiagnostics?.database?.engine || 'MYSQL'"></strong></span>
                  <span>Tables: <strong class="text-slate-800" x-text="settingsDiagnostics?.database?.tables_count || '23'"></strong></span>
                </div>
              </div>
            </div>

            <!-- ===================================================================
                 CATEGORY 4: NOTIFICATIONS
                 =================================================================== -->
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5 text-xs">
              <div class="flex items-center gap-2 pb-2 border-b border-slate-100">
                <div class="w-7 h-7 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center shrink-0">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
                </div>
                <div>
                  <h3 class="font-extrabold text-slate-900 text-xs">Notification Preferences</h3>
                  <p class="text-[10px] text-slate-400">In-App Alerts & Transactional Emails</p>
                </div>
              </div>

              <div class="space-y-3 pt-1">
                <!-- Toggle 1: Task Assignment Alerts -->
                <div class="flex items-center justify-between">
                  <div>
                    <p class="font-bold text-slate-800 text-[11px]">Task Assignment Emails</p>
                    <p class="text-[10px] text-slate-400">Receive an email when new CRM tasks are assigned</p>
                  </div>
                  <button type="button" @click="togglePreference('email_notifications')"
                    :class="settingsData.preferences?.email_notifications ? 'bg-blue-600' : 'bg-slate-200'"
                    class="relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full transition-colors duration-200 ease-in-out touch-press">
                    <span :class="settingsData.preferences?.email_notifications ? 'translate-x-4' : 'translate-x-0.5'"
                      class="pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out mt-0.5"></span>
                  </button>
                </div>

                <!-- Toggle 2: Task Reminders -->
                <div class="flex items-center justify-between pt-2 border-t border-slate-100">
                  <div>
                    <p class="font-bold text-slate-800 text-[11px]">Task Due Date Reminders</p>
                    <p class="text-[10px] text-slate-400">In-app notifications when project deadlines approach</p>
                  </div>
                  <button type="button" @click="togglePreference('task_reminder_alerts')"
                    :class="settingsData.preferences?.task_reminder_alerts ? 'bg-blue-600' : 'bg-slate-200'"
                    class="relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full transition-colors duration-200 ease-in-out touch-press">
                    <span :class="settingsData.preferences?.task_reminder_alerts ? 'translate-x-4' : 'translate-x-0.5'"
                      class="pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out mt-0.5"></span>
                  </button>
                </div>

                <!-- Toggle 3: Invoice Payment Alerts -->
                <div class="flex items-center justify-between pt-2 border-t border-slate-100">
                  <div>
                    <p class="font-bold text-slate-800 text-[11px]">Invoice Payment Alerts</p>
                    <p class="text-[10px] text-slate-400">Instant notification when a client payment is recorded</p>
                  </div>
                  <button type="button" @click="togglePreference('invoice_payment_alerts')"
                    :class="settingsData.preferences?.invoice_payment_alerts ? 'bg-blue-600' : 'bg-slate-200'"
                    class="relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full transition-colors duration-200 ease-in-out touch-press">
                    <span :class="settingsData.preferences?.invoice_payment_alerts ? 'translate-x-4' : 'translate-x-0.5'"
                      class="pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out mt-0.5"></span>
                  </button>
                </div>

                <!-- Toggle 4: Weekly Financial Digest -->
                <div class="flex items-center justify-between pt-2 border-t border-slate-100">
                  <div>
                    <p class="font-bold text-slate-800 text-[11px]">Weekly Financial Digest</p>
                    <p class="text-[10px] text-slate-400">Summary of revenue, expenses, and cash collections</p>
                  </div>
                  <button type="button" @click="togglePreference('weekly_financial_digest')"
                    :class="settingsData.preferences?.weekly_financial_digest ? 'bg-blue-600' : 'bg-slate-200'"
                    class="relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full transition-colors duration-200 ease-in-out touch-press">
                    <span :class="settingsData.preferences?.weekly_financial_digest ? 'translate-x-4' : 'translate-x-0.5'"
                      class="pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out mt-0.5"></span>
                  </button>
                </div>
              </div>
            </div>

            <!-- ===================================================================
                 CATEGORY 5: APPEARANCE & DISPLAY
                 =================================================================== -->
            <div class="bg-white rounded-2xl border border-slate-200/80 p-4 shadow-pocket space-y-3.5 text-xs">
              <div class="flex items-center gap-2 pb-2 border-b border-slate-100">
                <div class="w-7 h-7 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center shrink-0">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01"/></svg>
                </div>
                <div>
                  <h3 class="font-extrabold text-slate-900 text-xs">Appearance & Display</h3>
                  <p class="text-[10px] text-slate-400">Interface Themes & Formatting</p>
                </div>
              </div>

              <!-- Theme Selector -->
              <div class="space-y-1.5">
                <span class="text-[11px] font-bold text-slate-700">Interface Theme</span>
                <div class="grid grid-cols-3 gap-2">
                  <button type="button" @click="setAppTheme('light')"
                    :class="(settingsData.preferences?.theme || 'light') === 'light' ? 'bg-blue-600 text-white font-bold border-blue-600 shadow-xs' : 'bg-slate-50 text-slate-700 border-slate-200 hover:bg-slate-100'"
                    class="py-2 rounded-xl border text-[11px] flex items-center justify-center gap-1.5 touch-press transition">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 3v1m0 16v1m9-9h-1M4 9h-1m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                    <span>Light</span>
                  </button>
                  <button type="button" @click="setAppTheme('dark')"
                    :class="(settingsData.preferences?.theme) === 'dark' ? 'bg-blue-600 text-white font-bold border-blue-600 shadow-xs' : 'bg-slate-50 text-slate-700 border-slate-200 hover:bg-slate-100'"
                    class="py-2 rounded-xl border text-[11px] flex items-center justify-center gap-1.5 touch-press transition">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                    <span>Dark</span>
                  </button>
                  <button type="button" @click="setAppTheme('system')"
                    :class="(settingsData.preferences?.theme) === 'system' ? 'bg-blue-600 text-white font-bold border-blue-600 shadow-xs' : 'bg-slate-50 text-slate-700 border-slate-200 hover:bg-slate-100'"
                    class="py-2 rounded-xl border text-[11px] flex items-center justify-center gap-1.5 touch-press transition">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                    <span>System</span>
                  </button>
                </div>
              </div>

              <!-- Currency Display -->
              <div class="flex items-center justify-between pt-2 border-t border-slate-100 text-[11px]">
                <span class="text-slate-600">Default Currency</span>
                <span class="font-bold text-slate-800 bg-slate-100 px-2.5 py-0.5 rounded-lg border border-slate-200">₹ INR (Indian Rupee)</span>
              </div>

              <!-- Welcome Screen Introduction Replay Option -->
              <div class="pt-3 border-t border-slate-100 flex items-center justify-between">
                <div>
                  <p class="font-bold text-slate-800 text-[11px]">Welcome Introduction Animation</p>
                  <p class="text-[10px] text-slate-400">Replay the animated company & platform introduction screen</p>
                </div>
                <button type="button" @click="replayWelcomeIntro()"
                  class="px-3 py-1.5 rounded-xl border border-burgundy-700/30 bg-burgundy-50 hover:bg-burgundy-100 text-burgundy-700 font-bold text-[11px] flex items-center gap-1.5 touch-press transition shadow-xs">
                  <svg class="w-3.5 h-3.5 text-burgundy-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                  <span>Replay Intro</span>
                </button>
              </div>
            </div>

            </div> <!-- /Column 2 -->

            </div> <!-- /Responsive 2-Column Grid -->

            <!-- Sign Out Button -->
            <div class="pt-2">
              <button type="button" @click="logout()" class="w-full py-2.5 bg-rose-50 border border-rose-200/60 hover:bg-rose-100/70 text-rose-700 rounded-xl font-bold text-xs flex items-center justify-center gap-1.5 touch-press transition">
                <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
                <span>Sign Out</span>
              </button>
            </div>

          </div>
        </div>

        </main>


        <!-- =====================================================================
             FIXED MOBILE BOTTOM NAVIGATION (Hidden on Desktop / Laptop lg+)
             ===================================================================== -->
        <nav class="lg:hidden h-16 bg-white border-t border-slate-200/80 px-3 flex items-center justify-around shrink-0 z-30 shadow-nav">
          
          <!-- 1. Home -->
          <button @click="navigateTo('dashboard')" 
            class="flex flex-col items-center gap-1 text-[10px] font-bold touch-press" 
            :class="currentView === 'dashboard' ? 'text-blue-600' : 'text-slate-400'">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/></svg>
            <span>Home</span>
          </button>

          <!-- 2. Contacts -->
          <button @click="navigateTo('contacts')" 
            class="flex flex-col items-center gap-1 text-[10px] font-bold touch-press" 
            :class="currentView === 'contacts' || currentView === 'contact_detail' ? 'text-blue-600' : 'text-slate-400'">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
            <span>Contacts</span>
          </button>

          <!-- 3. Projects -->
          <button @click="navigateTo('projects')" 
            class="flex flex-col items-center gap-1 text-[10px] font-bold touch-press" 
            :class="currentView === 'projects' || currentView === 'project_detail' ? 'text-blue-600' : 'text-slate-400'">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
            <span>Projects</span>
          </button>

          <!-- 4. Team (Screen 1 & 2 Reference) -->
          <button @click="navigateTo('team')" 
            class="flex flex-col items-center gap-1 text-[10px] font-bold touch-press" 
            :class="currentView === 'team' || currentView === 'team_detail' ? 'text-blue-600' : 'text-slate-400'">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
            <span>Team</span>
          </button>

          <!-- 5. More -->
          <button @click="sideDrawerOpen = true" 
            class="flex flex-col items-center gap-1 text-[10px] font-bold text-slate-400 touch-press">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 12h.01M12 12h.01M19 12h.01M6 12a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0z"/></svg>
            <span>More</span>
          </button>

        </nav>
    


    <!-- =======================================================================
         IN-APP MODAL: INVOICE RECEIPT (NO BROWSER NATIVE ALERT)
         ======================================================================= -->
    <div x-show="modalInvoiceReceiptOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalInvoiceReceiptOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm shadow-sheet space-y-4">
        
        <div class="flex items-center justify-between pb-3 border-b border-slate-100">
          <div class="flex items-center gap-2.5">
            <div class="w-9 h-9 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-extrabold text-xs">INV</div>
            <div>
              <h3 class="text-xs font-black text-slate-900">Invoice Details</h3>
              <p class="text-[10px] text-slate-400 font-mono" x-text="activeInvoice ? (activeInvoice.invoice_no || activeInvoice.id) : ''"></p>
            </div>
          </div>
          <button @click="modalInvoiceReceiptOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold">&times;</button>
        </div>

        <div class="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-3 text-xs">
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Client / Company</span>
            <span class="font-bold text-slate-900" x-text="activeInvoice ? activeInvoice.customer_name : ''"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Invoice Amount</span>
            <span class="font-black text-slate-900 text-sm" x-text="activeInvoice ? ('$' + Number(activeInvoice.amount).toLocaleString()) : ''"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Payment Status</span>
            <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold"
              :class="activeInvoice && activeInvoice.status === 'Paid' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-amber-50 text-amber-700 border border-amber-200'"
              x-text="activeInvoice ? activeInvoice.status : ''"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Due Date</span>
            <span class="font-mono text-slate-700" x-text="activeInvoice ? (activeInvoice.due_date || '10 Aug 2024') : ''"></span>
          </div>
        </div>

        <button @click="modalInvoiceReceiptOpen = false" class="w-full py-2.5 rounded-xl bg-blue-600 text-white font-bold text-xs shadow-sm touch-press">
          Close
        </button>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CALL / PHONE DIALER
         ======================================================================= -->
    <div x-show="modalCallOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalCallOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3.5">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-bold text-slate-900">Call Client</h3>
          <button @click="modalCallOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <div class="text-center py-2">
          <div class="text-base font-extrabold text-slate-900" x-text="activeContact ? activeContact.name : ''"></div>
          <div class="text-sm font-mono text-blue-600 mt-1 font-bold" x-text="activeContact ? activeContact.phone : ''"></div>
        </div>
        <div class="flex gap-2">
          <a :href="'tel:' + (activeContact ? activeContact.phone : '')" class="flex-1 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-2 touch-press">
            <span>Call Phone</span>
          </a>
          <button @click="navigator.clipboard.writeText(activeContact ? activeContact.phone : ''); showToast('Phone number copied'); modalCallOpen = false;" class="px-4 py-2.5 bg-slate-100 text-slate-700 font-bold text-xs rounded-xl touch-press">
            Copy
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: WHATSAPP QUICK CHAT
         ======================================================================= -->
    <div x-show="modalWhatsAppOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalWhatsAppOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-bold text-slate-900">WhatsApp Message</h3>
          <button @click="modalWhatsAppOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <textarea x-model="whatsAppMessageText" rows="3" placeholder="Hello! Discussing your project deliverables..." class="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs"></textarea>
        <a :href="'https://wa.me/' + (activeContact ? activeContact.phone.replace(/[^0-9]/g, '') : '') + '?text=' + encodeURIComponent(whatsAppMessageText)" target="_blank"
          @click="modalWhatsAppOpen = false"
          class="w-full py-2.5 bg-emerald-600 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-2 touch-press">
          <span>Open in WhatsApp</span>
        </a>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: FILE & NOTE VIEWER
         ======================================================================= -->
    <div x-show="viewNoteDocModalOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="viewNoteDocModalOpen = false" class="bg-white rounded-3xl border border-slate-200 p-5 w-full max-w-lg shadow-2xl space-y-4 max-h-[90vh] flex flex-col">
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 shrink-0">
          <div class="flex items-center gap-2 min-w-0 pr-2">
            <div class="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
            </div>
            <div class="min-w-0">
              <h3 class="text-xs font-black text-slate-900 truncate" x-text="activeFileDoc ? activeFileDoc.name : 'File Viewer'"></h3>
              <p class="text-[10px] text-slate-400" x-text="activeFileDoc ? (activeFileDoc.size + (activeFileDoc.mime_type ? ' &bull; ' + activeFileDoc.mime_type : '')) : ''"></p>
            </div>
          </div>
          <button @click="viewNoteDocModalOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold w-7 h-7 flex items-center justify-center rounded-lg hover:bg-slate-100 transition-colors">&times;</button>
        </div>

        <!-- Body -->
        <div class="flex-1 overflow-y-auto space-y-3 min-h-[140px]">
          <!-- IMAGE PREVIEW -->
          <template x-if="activeFileDoc && (activeFileDoc.type === 'image' || (activeFileDoc.mime_type && activeFileDoc.mime_type.startsWith('image/')))">
            <div class="rounded-2xl overflow-hidden bg-slate-100 border border-slate-200/80 flex items-center justify-center p-2 min-h-[200px]">
              <img :src="activeFileDoc.url" class="max-h-80 w-auto max-w-full rounded-xl object-contain shadow-xs" :alt="activeFileDoc.name"/>
            </div>
          </template>

          <!-- PDF PREVIEW -->
          <template x-if="activeFileDoc && (activeFileDoc.type === 'pdf' || (activeFileDoc.mime_type && activeFileDoc.mime_type === 'application/pdf'))">
            <div class="space-y-2">
              <div class="rounded-2xl overflow-hidden border border-slate-200 bg-slate-50">
                <iframe :src="activeFileDoc.url" class="w-full h-80 border-0" title="PDF Preview"></iframe>
              </div>
              <p class="text-[10px] text-center text-slate-400">PDF preview. You can also open in full tab or download below.</p>
            </div>
          </template>

          <!-- TEXT / CODE / LOG PREVIEW -->
          <template x-if="activeFileDoc && (activeFileDoc.type === 'text' || (activeFileDoc.mime_type && activeFileDoc.mime_type.startsWith('text/')))">
            <div class="p-3 bg-slate-900 text-slate-100 rounded-2xl border border-slate-800 text-xs font-mono whitespace-pre-wrap max-h-80 overflow-y-auto select-text shadow-inner"
              x-text="activeFileDoc && activeFileDoc.text ? activeFileDoc.text : 'Loading file content...'">
            </div>
          </template>

          <!-- UNSUPPORTED / OTHER FILE TYPE (DOCX, ZIP, ETC.) -->
          <template x-if="activeFileDoc && activeFileDoc.type !== 'image' && activeFileDoc.type !== 'pdf' && activeFileDoc.type !== 'text' && (!activeFileDoc.mime_type || (!activeFileDoc.mime_type.startsWith('image/') && activeFileDoc.mime_type !== 'application/pdf' && !activeFileDoc.mime_type.startsWith('text/')))">
            <div class="p-6 bg-slate-50 rounded-2xl border border-slate-200/80 text-center space-y-3">
              <div class="w-12 h-12 mx-auto rounded-2xl bg-blue-100 text-blue-600 flex items-center justify-center">
                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
              </div>
              <div>
                <h4 class="text-xs font-black text-slate-900 truncate" x-text="activeFileDoc.name"></h4>
                <p class="text-[11px] text-slate-500 mt-0.5">This file cannot be previewed directly in the browser. Click Download below.</p>
              </div>
            </div>
          </template>
        </div>

        <!-- Footer / Action Buttons -->
        <div class="flex items-center gap-2 pt-2 border-t border-slate-100 shrink-0">
          <!-- Download Button -->
          <template x-if="activeFileDoc && (activeFileDoc.download_url || activeFileDoc.url)">
            <a :href="activeFileDoc.download_url || activeFileDoc.url" download class="flex-1 py-2 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center justify-center gap-1.5 shadow-xs touch-press transition-colors">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
              <span>Download</span>
            </a>
          </template>

          <!-- Open in Tab Button (images, PDFs, text) -->
          <template x-if="activeFileDoc && activeFileDoc.url">
            <a :href="activeFileDoc.url" target="_blank" rel="noopener noreferrer" class="py-2 px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs flex items-center justify-center gap-1 touch-press transition-colors">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
              <span>New Tab</span>
            </a>
          </template>

          <!-- Delete File Button in File Viewer -->
          <template x-if="activeFileDoc && activeFileDoc.id">
            <button type="button" @click="promptDeleteTaskFile(activeFileDoc.rawFile || activeFileDoc, activeTask); viewNoteDocModalOpen = false;" class="py-2 px-3 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 font-bold text-xs flex items-center justify-center gap-1 touch-press transition-colors" title="Delete File" aria-label="Delete File">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              <span>Delete</span>
            </button>
          </template>

          <!-- Close Button -->
          <button type="button" @click="viewNoteDocModalOpen = false" class="py-2 px-4 rounded-xl bg-slate-800 hover:bg-slate-900 text-white font-bold text-xs touch-press transition-colors">
            Close
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 2 & 5: ADD / EDIT CONTACT MODAL (Comprehensive Form)
         ======================================================================= -->
    <div x-show="modalContactOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="closeContactModal()" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-md shadow-sheet space-y-4 max-h-[90vh] flex flex-col">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 shrink-0">
          <div>
            <h3 class="text-sm font-black text-slate-900" x-text="contactForm.id ? 'Edit Contact' : 'New Contact'"></h3>
            <p class="text-[10px] text-slate-400" x-text="contactForm.id ? 'Update client details and preferences' : 'Fill in the information to register a contact'"></p>
          </div>
          <button @click="closeContactModal()" class="text-slate-400 hover:text-slate-700 text-xl font-bold touch-press">&times;</button>
        </div>

        <!-- Error Banner -->
        <template x-if="contactFormError">
          <div class="p-2.5 bg-rose-50 border border-rose-200 rounded-xl text-rose-700 text-xs font-semibold flex items-center gap-2">
            <svg class="w-4 h-4 text-rose-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <span x-text="contactFormError"></span>
          </div>
        </template>

        <!-- Form Body -->
        <form @submit.prevent="submitContactForm()" class="space-y-3 text-xs overflow-y-auto pr-1 flex-1">
          
          <!-- Full Name (Required) -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Full Name <span class="text-rose-500">*</span></label>
            <input type="text" x-model="contactForm.name" required placeholder="e.g. Rahul Sharma" 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
          </div>

          <!-- Company & Position -->
          <div class="grid grid-cols-2 gap-2.5">
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Company</label>
              <input type="text" x-model="contactForm.company" placeholder="e.g. ABC Tech Solutions" 
                class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
            </div>
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Position / Role</label>
              <input type="text" x-model="contactForm.position" placeholder="e.g. Founder & CEO" 
                class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
            </div>
          </div>

          <!-- Phone Number with Country Code (Required) -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Phone Number <span class="text-rose-500">*</span></label>
            <div class="flex gap-2">
              <select x-model="contactForm.country_code" class="w-24 px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800">
                <option value="+91">🇮🇳 +91</option>
                <option value="+1">🇺🇸 +1</option>
                <option value="+44">🇬🇧 +44</option>
                <option value="+61">🇦🇺 +61</option>
                <option value="+971">🇦🇪 +971</option>
                <option value="+65">🇸🇬 +65</option>
                <option value="+49">🇩🇪 +49</option>
                <option value="+33">🇫🇷 +33</option>
                <option value="+81">🇯🇵 +81</option>
              </select>
              <input type="tel" x-model="contactForm.phone_number" required placeholder="9876543210" 
                class="flex-1 px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-mono"/>
            </div>
          </div>

          <!-- Email Address -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Email Address</label>
            <input type="email" x-model="contactForm.email" placeholder="client@example.com" 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
          </div>

          <!-- Location -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Location</label>
            <input type="text" x-model="contactForm.location" placeholder="e.g. Mumbai, India" 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
          </div>

          <!-- Contact Type & Source -->
          <div class="grid grid-cols-2 gap-2.5">
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Type <span class="text-rose-500">*</span></label>
              <select x-model="contactForm.category" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800">
                <option value="Client">Client</option>
                <option value="Lead">Lead</option>
                <option value="Prospect">Prospect</option>
                <option value="Partner">Partner</option>
              </select>
            </div>
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Source</label>
              <select x-model="contactForm.source" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800 font-medium">
                <option value="Website">Website</option>
                <option value="Referral">Referral</option>
                <option value="LinkedIn">LinkedIn</option>
                <option value="Cold Call">Cold Call</option>
                <option value="Event">Event</option>
                <option value="Other">Other</option>
              </select>
            </div>
          </div>

          <!-- Tags with Chips -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Tags</label>
            <div class="flex flex-wrap gap-1.5 mb-2">
              <template x-for="(tag, idx) in contactForm.tags" :key="idx">
                <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-50 text-blue-700 border border-blue-200/60">
                  <span x-text="tag"></span>
                  <button type="button" @click="removeTag(idx)" class="text-blue-500 hover:text-blue-800 font-bold ml-0.5">&times;</button>
                </span>
              </template>
            </div>
            <div class="flex gap-1.5">
              <input type="text" x-model="tagInput" @keydown.enter.prevent="addTag()" placeholder="Add a tag..." 
                class="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none"/>
              <button type="button" @click="addTag()" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs touch-press">
                + Add
              </button>
            </div>
            <!-- Quick Suggestions -->
            <div class="flex gap-1 flex-wrap mt-1.5">
              <button type="button" @click="addTag('Important')" class="text-[9px] px-2 py-0.5 bg-slate-100 hover:bg-blue-50 text-slate-600 rounded-md font-semibold">+ Important</button>
              <button type="button" @click="addTag('VIP')" class="text-[9px] px-2 py-0.5 bg-slate-100 hover:bg-blue-50 text-slate-600 rounded-md font-semibold">+ VIP</button>
              <button type="button" @click="addTag('Long Term')" class="text-[9px] px-2 py-0.5 bg-slate-100 hover:bg-blue-50 text-slate-600 rounded-md font-semibold">+ Long Term</button>
              <button type="button" @click="addTag('Enterprise')" class="text-[9px] px-2 py-0.5 bg-slate-100 hover:bg-blue-50 text-slate-600 rounded-md font-semibold">+ Enterprise</button>
            </div>
          </div>

          <!-- Notes -->
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Notes & Details</label>
            <textarea x-model="contactForm.notes" rows="3" placeholder="Key client for web development projects..." 
              class="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"></textarea>
          </div>

          <!-- Action Buttons -->
          <div class="pt-2 flex gap-2 shrink-0">
            <button type="button" @click="closeContactModal()" class="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Cancel
            </button>
            <button type="submit" :disabled="isSubmittingContact" class="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-xs touch-press flex items-center justify-center gap-1.5">
              <template x-if="isSubmittingContact">
                <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              </template>
              <span x-text="contactForm.id ? 'Update Contact' : 'Save Contact'"></span>
            </button>
          </div>

        </form>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CONFIRM DISCARD CONTACT CHANGES
         ======================================================================= -->
    <div x-show="modalConfirmDiscardContactOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDiscardContactOpen = false" class="bg-white rounded-3xl border border-slate-200 p-5 w-full max-w-xs shadow-2xl text-center space-y-3">
        <div class="w-12 h-12 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center mx-auto font-bold text-lg">⚠️</div>
        <div>
          <h3 class="text-sm font-black text-slate-900">Discard changes?</h3>
          <p class="text-xs text-slate-500 mt-1">You have unsaved changes in this form. Are you sure you want to close?</p>
        </div>
        <div class="flex gap-2 pt-1">
          <button @click="modalConfirmDiscardContactOpen = false" class="flex-1 py-2 rounded-xl bg-slate-100 text-slate-700 font-bold text-xs">Keep Editing</button>
          <button @click="forceCloseContactModal()" class="flex-1 py-2 rounded-xl bg-rose-600 text-white font-bold text-xs">Discard</button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 4: CONTACT OPTIONS MENU (ACTION SHEET - 3 DOTS)
         ======================================================================= -->
    <div x-show="modalContactMenuOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalContactMenuOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        
        <div class="flex items-center justify-between pb-3 border-b border-slate-100">
          <div class="flex items-center gap-3 min-w-0 pr-3">
            <div class="w-10 h-10 rounded-full bg-blue-100 text-blue-700 font-black flex items-center justify-center text-xs shrink-0 uppercase"
              x-text="actionContact ? (actionContact.name || 'C').substring(0, 2) : 'RS'"></div>
            <div class="min-w-0">
              <h3 class="text-xs font-black text-slate-900 truncate" x-text="actionContact ? actionContact.name : 'Contact Options'"></h3>
              <p class="text-[10px] text-slate-400 truncate" x-text="actionContact ? (actionContact.company || actionContact.category) : ''"></p>
            </div>
          </div>
          <button @click="modalContactMenuOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold shrink-0">&times;</button>
        </div>

        <div class="space-y-1 text-xs font-bold text-slate-700">
          <!-- Add Member -->
          <button @click="openAddContactModal(); modalContactMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-blue-50 text-blue-600 flex items-center gap-3 text-left touch-press font-bold">
            <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
            <span>Add Member</span>
          </button>

          <!-- View Details -->
          <template x-if="currentView !== 'contact_detail'">
            <button @click="viewContactDetail(actionContact); modalContactMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
              <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
              <span>View Details</span>
            </button>
          </template>

          <!-- Edit Contact -->
          <button @click="openEditContact(actionContact)" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
            <span>Edit Contact</span>
          </button>

          <!-- Duplicate Contact -->
          <button @click="duplicateContact(actionContact)" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2"/></svg>
            <span>Duplicate Contact</span>
          </button>

          <!-- Share Contact -->
          <button @click="shareContact(actionContact)" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
            <span>Share Contact</span>
          </button>

          <!-- Delete Contact -->
          <button @click="openDeleteContactModal(actionContact)" class="w-full py-2.5 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
            <span>Delete Contact</span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 6: DELETE CONTACT CONFIRMATION MODAL
         ======================================================================= -->
    <div x-show="modalDeleteContactOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalDeleteContactOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-xs shadow-2xl text-center space-y-3.5">
        
        <div class="w-14 h-14 rounded-full bg-rose-100 text-rose-600 flex items-center justify-center mx-auto shadow-sm">
          <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>

        <div>
          <h3 class="text-base font-black text-slate-900">Delete Contact?</h3>
          <p class="text-xs text-slate-500 font-medium mt-1 leading-relaxed">
            Are you sure you want to delete <span class="font-black text-slate-800" x-text="contactToDelete ? contactToDelete.name : 'this contact'"></span>? This action cannot be undone and will remove associated interaction history.
          </p>
        </div>

        <div class="space-y-2 pt-1">
          <button @click="executeDeleteContact()" :disabled="isDeletingContact" class="w-full py-2.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs shadow-md shadow-rose-500/20 touch-press flex items-center justify-center gap-1.5">
            <template x-if="isDeletingContact">
              <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
            </template>
            <span>Delete Contact</span>
          </button>
          <button @click="modalDeleteContactOpen = false" class="w-full py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs touch-press">
            Cancel
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 14: MORE ACTIONS BOTTOM SHEET
         ======================================================================= -->
    <div x-show="modalContactMoreActionsOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalContactMoreActionsOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-black text-slate-900">Quick Actions</h3>
          <button @click="modalContactMoreActionsOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>
        <div class="space-y-1 text-xs font-bold text-slate-700">
          <button @click="openAddContactModal(); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-blue-50 text-blue-600 flex items-center gap-3 text-left font-bold">
            <span class="w-7 h-7 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center font-bold">➕</span>
            <span>Add Member</span>
          </button>
          <button @click="triggerCallAction(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center">📞</span>
            <span>Make Phone Call</span>
          </button>
          <button @click="triggerWhatsAppAction(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center">💬</span>
            <span>Chat on WhatsApp</span>
          </button>
          <button @click="triggerEmailAction(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center">✉️</span>
            <span>Send Email</span>
          </button>
          <button @click="shareContact(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center">↗️</span>
            <span>Share Contact</span>
          </button>
          <button @click="openEditContact(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center">✏️</span>
            <span>Edit Profile</span>
          </button>
          <button @click="openDeleteContactModal(activeContact); modalContactMoreActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left">
            <span class="w-7 h-7 rounded-full bg-rose-50 text-rose-600 flex items-center justify-center">🗑️</span>
            <span>Delete Contact</span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 15: CALL ACTION MODAL & MISSING PHONE ALERT
         ======================================================================= -->
    <div x-show="modalNoPhoneOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalNoPhoneOpen = false" class="bg-white rounded-3xl border border-slate-200 p-5 w-full max-w-xs shadow-2xl text-center space-y-3">
        <div class="w-12 h-12 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center mx-auto text-xl">📞</div>
        <div>
          <h3 class="text-sm font-black text-slate-900">No Phone Number</h3>
          <p class="text-xs text-slate-500 mt-1">This contact does not have a recorded phone number. Would you like to add one now?</p>
        </div>
        <div class="flex gap-2 pt-1">
          <button @click="modalNoPhoneOpen = false" class="flex-1 py-2 rounded-xl bg-slate-100 text-slate-700 font-bold text-xs">Cancel</button>
          <button @click="modalNoPhoneOpen = false; openEditContact(callContact || activeContact);" class="flex-1 py-2 rounded-xl bg-blue-600 text-white font-bold text-xs">Edit Contact</button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 17: EMAIL ACTION MODAL & MISSING EMAIL ALERT
         ======================================================================= -->
    <div x-show="modalEmailOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalEmailOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 class="text-xs font-black text-slate-900">Compose Email</h3>
            <p class="text-[10px] text-slate-400 font-mono" x-text="emailContact ? emailContact.email : ''"></p>
          </div>
          <button @click="modalEmailOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <div class="space-y-2 text-xs">
          <div>
            <label class="block text-[10px] font-bold text-slate-500 mb-1">Subject</label>
            <input type="text" x-model="emailSubject" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-semibold text-slate-900"/>
          </div>
          <div>
            <label class="block text-[10px] font-bold text-slate-500 mb-1">Message</label>
            <textarea x-model="emailBody" rows="4" class="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900"></textarea>
          </div>
        </div>
        <div class="flex gap-2 pt-1">
          <a :href="'mailto:' + (emailContact ? emailContact.email : '') + '?subject=' + encodeURIComponent(emailSubject) + '&body=' + encodeURIComponent(emailBody)"
            @click="modalEmailOpen = false"
            class="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5 touch-press">
            <span>Send Email</span>
          </a>
          <button @click="navigator.clipboard.writeText(emailContact ? emailContact.email : ''); showToast('Email copied'); modalEmailOpen = false;" 
            class="px-4 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
            Copy
          </button>
        </div>
      </div>
    </div>

    <div x-show="modalNoEmailOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalNoEmailOpen = false" class="bg-white rounded-3xl border border-slate-200 p-5 w-full max-w-xs shadow-2xl text-center space-y-3">
        <div class="w-12 h-12 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center mx-auto text-xl">✉️</div>
        <div>
          <h3 class="text-sm font-black text-slate-900">No Email Address</h3>
          <p class="text-xs text-slate-500 mt-1">This contact does not have an email address on file. Would you like to add one now?</p>
        </div>
        <div class="flex gap-2 pt-1">
          <button @click="modalNoEmailOpen = false" class="flex-1 py-2 rounded-xl bg-slate-100 text-slate-700 font-bold text-xs">Cancel</button>
          <button @click="modalNoEmailOpen = false; openEditContact(emailContact || activeContact);" class="flex-1 py-2 rounded-xl bg-blue-600 text-white font-bold text-xs">Edit Contact</button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 7: LOG NOTE IN-APP MODAL
         ======================================================================= -->
    <div x-show="modalNoteOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalNoteOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 class="text-xs font-black text-slate-900">Log Interaction Note</h3>
            <p class="text-[10px] text-slate-400" x-text="'For ' + (activeContact ? activeContact.name : 'Client')"></p>
          </div>
          <button @click="modalNoteOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <form @submit.prevent="submitNoteForm()" class="space-y-3 text-xs">
          <textarea x-model="noteInputText" rows="4" required placeholder="Discussed project milestones, budget approval, and next delivery date..." 
            class="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"></textarea>
          <div class="flex gap-2">
            <button type="button" @click="modalNoteOpen = false" class="flex-1 py-2.5 bg-slate-100 text-slate-700 font-bold text-xs rounded-xl">Cancel</button>
            <button type="submit" :disabled="isSubmittingNote" class="flex-1 py-2.5 bg-blue-600 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5">
              <template x-if="isSubmittingNote">
                <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              </template>
              <span>Save Note</span>
            </button>
          </div>
        </form>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 9: DETAILED INVOICE MODAL (ITEMIZED BREAKDOWN & CHARGES)
         ======================================================================= -->
    <div x-show="modalInvoiceDetailOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalInvoiceDetailOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-md shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100">
          <div class="flex items-center gap-2.5">
            <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xs">INV</div>
            <div>
              <h3 class="text-sm font-black text-slate-900" x-text="activeInvoice ? (activeInvoice.invoice_no || activeInvoice.id) : 'Invoice'"></h3>
              <p class="text-[10px] text-slate-400" x-text="'Issued: ' + (activeInvoice ? (activeInvoice.transaction_date || 'Recent') : '')"></p>
            </div>
          </div>
          <span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold"
            :class="activeInvoice && activeInvoice.status === 'Paid' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-amber-50 text-amber-700 border border-amber-200'"
            x-text="activeInvoice ? activeInvoice.status : 'Pending'"></span>
        </div>

        <!-- Billed To Box -->
        <div class="p-3 bg-slate-50 rounded-2xl border border-slate-100 text-xs space-y-1">
          <div class="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Billed To</div>
          <div class="font-extrabold text-slate-900" x-text="activeInvoice ? activeInvoice.customer_name : ''"></div>
          <div class="text-slate-500 text-[11px]" x-text="activeContact ? (activeContact.company || activeContact.email || activeContact.phone) : ''"></div>
        </div>

        <!-- Itemized Charges Table -->
        <div class="space-y-1.5">
          <div class="text-xs font-bold text-slate-800">Itemized Charges</div>
          <div class="border border-slate-200 rounded-xl overflow-hidden text-xs">
            <table class="w-full text-left">
              <thead class="bg-slate-50 text-[10px] font-bold text-slate-500 border-b border-slate-200">
                <tr>
                  <th class="p-2.5">Description</th>
                  <th class="p-2.5 text-center">Qty</th>
                  <th class="p-2.5 text-right">Amount</th>
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-100 text-[11px]">
                <tr>
                  <td class="p-2.5 font-medium text-slate-800" x-text="activeInvoice && activeInvoice.title ? activeInvoice.title : 'Software Engineering & Consulting Services'"></td>
                  <td class="p-2.5 text-center text-slate-600">1</td>
                  <td class="p-2.5 text-right font-bold text-slate-900" x-text="activeInvoice ? ('$' + Number(activeInvoice.amount).toLocaleString()) : '$0'"></td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <!-- Financial Summary -->
        <div class="p-3.5 bg-slate-50 rounded-2xl border border-slate-100 space-y-2 text-xs">
          <div class="flex justify-between text-slate-600">
            <span>Total Amount</span>
            <span class="font-bold text-slate-900" x-text="activeInvoice ? ('$' + Number(activeInvoice.amount).toLocaleString()) : '$0'"></span>
          </div>
          <div class="flex justify-between text-slate-600">
            <span>Paid to Date</span>
            <span class="font-bold text-emerald-600" x-text="activeInvoice ? ('$' + Number(activeInvoice.paid_amount || (activeInvoice.status === 'Paid' ? activeInvoice.amount : 0)).toLocaleString()) : '$0'"></span>
          </div>
          <div class="flex justify-between pt-2 border-t border-slate-200 text-sm font-black text-slate-900">
            <span>Balance Due</span>
            <span :class="activeInvoice && Number(activeInvoice.balance_amount) > 0 ? 'text-rose-600' : 'text-emerald-600'" 
              x-text="activeInvoice ? ('$' + Number(activeInvoice.balance_amount !== undefined ? activeInvoice.balance_amount : (activeInvoice.status === 'Paid' ? 0 : activeInvoice.amount)).toLocaleString()) : '$0'"></span>
          </div>
        </div>

        <!-- Actions -->
        <div class="space-y-2 pt-1">
          <template x-if="activeInvoice && (activeInvoice.status !== 'Paid' || Number(activeInvoice.balance_amount) > 0)">
            <button @click="openRecordPaymentModal(activeInvoice)" class="w-full py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-xs touch-press flex items-center justify-center gap-1.5">
              <span>Record Payment</span>
            </button>
          </template>
          <div class="flex gap-2">
            <button @click="window.print()" class="flex-1 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Print / Save PDF
            </button>
            <button @click="modalInvoiceDetailOpen = false" class="flex-1 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Close
            </button>
          </div>
        </div>

      </div>
    </div>


    <!-- =======================================================================
         SCREEN 10: RECORD PAYMENT MODAL
         ======================================================================= -->
    <div x-show="modalRecordPaymentOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalRecordPaymentOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm shadow-sheet space-y-3.5">
        
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 class="text-xs font-black text-slate-900">Record Payment</h3>
            <p class="text-[10px] text-slate-400 font-mono" x-text="recordPaymentForm.invoice_no"></p>
          </div>
          <button @click="modalRecordPaymentOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>

        <!-- Balance Due Banner -->
        <div class="p-2.5 bg-blue-50 border border-blue-200 rounded-xl flex items-center justify-between text-xs">
          <span class="text-blue-700 font-semibold">Remaining Balance:</span>
          <span class="font-black text-blue-900" x-text="'$' + Number(recordPaymentForm.balance_amount).toLocaleString()"></span>
        </div>

        <form @submit.prevent="submitRecordPayment()" class="space-y-2.5 text-xs">
          <div>
            <label class="block text-[10px] font-bold text-slate-600 mb-1">Payment Amount ($) <span class="text-rose-500">*</span></label>
            <input type="number" step="0.01" min="1" x-model="recordPaymentForm.amount" required 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20"/>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[10px] font-bold text-slate-600 mb-1">Date</label>
              <input type="date" x-model="recordPaymentForm.payment_date" required 
                class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none"/>
            </div>
            <div>
              <label class="block text-[10px] font-bold text-slate-600 mb-1">Method</label>
              <select x-model="recordPaymentForm.payment_method" class="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-800">
                <option value="Bank Transfer">Bank Transfer</option>
                <option value="UPI / Online">UPI / Online</option>
                <option value="Cash">Cash</option>
                <option value="Credit Card">Credit Card</option>
                <option value="Cheque">Cheque</option>
              </select>
            </div>
          </div>

          <div>
            <label class="block text-[10px] font-bold text-slate-600 mb-1">Transaction Ref / ID</label>
            <input type="text" x-model="recordPaymentForm.transaction_id" placeholder="e.g. TXN-89472" 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none font-mono"/>
          </div>

          <div>
            <label class="block text-[10px] font-bold text-slate-600 mb-1">Notes</label>
            <input type="text" x-model="recordPaymentForm.notes" placeholder="Optional payment note..." 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:outline-none"/>
          </div>

          <div class="pt-2 flex gap-2">
            <button type="button" @click="modalRecordPaymentOpen = false" class="flex-1 py-2.5 bg-slate-100 text-slate-700 font-bold text-xs rounded-xl">Cancel</button>
            <button type="submit" :disabled="isSubmittingPayment" class="flex-1 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
              <template x-if="isSubmittingPayment">
                <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              </template>
              <span>Confirm Payment</span>
            </button>
          </div>
        </form>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 8: TASK COMPLETION IN-APP MODAL (Exact Match Screen 8)
         ======================================================================= -->
    <div x-show="modalTaskCompletedOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalTaskCompletedOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-xs shadow-2xl text-center space-y-3.5 relative">
        <button @click="modalTaskCompletedOpen = false" class="absolute top-4 right-4 text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>

        <!-- Green Circular Check Icon -->
        <div class="w-14 h-14 rounded-full bg-emerald-500 text-white flex items-center justify-center mx-auto shadow-md shadow-emerald-500/20">
          <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
        </div>

        <div>
          <h3 class="text-base font-black text-slate-900">Task Completed!</h3>
          <p class="text-xs text-slate-500 font-medium mt-1 leading-relaxed">
            "<span class="font-bold text-slate-700" x-text="completedModalTask ? completedModalTask.title : ''"></span>" has been marked as completed.
          </p>
        </div>

        <div class="space-y-2 pt-1">
          <button @click="viewTaskDetail(completedModalTask); modalTaskCompletedOpen = false;" class="w-full py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-md shadow-blue-500/20 touch-press">
            View Task
          </button>
          <button @click="modalTaskCompletedOpen = false" class="w-full py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs touch-press">
            Close
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         SCREEN 9: TASK OPTIONS MENU (ACTION SHEET - Exact Match Screen 9)
         ======================================================================= -->
    <div x-show="modalTaskMenuOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalTaskMenuOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="min-w-0 pr-3">
            <h3 class="text-xs font-black text-slate-900 truncate" x-text="actionTask ? actionTask.title : 'Task Options'"></h3>
            <p class="text-[10px] text-slate-400 truncate" x-text="actionTask ? (actionTask.project_name || actionTask.client_name) : ''"></p>
          </div>
          <button @click="modalTaskMenuOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold shrink-0">&times;</button>
        </div>

        <div class="space-y-1 text-xs font-bold text-slate-700">
          <!-- View Details -->
          <button @click="viewTaskDetail(actionTask); modalTaskMenuOpen = false;" class="w-full py-2 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
            <span>View Details</span>
          </button>

          <!-- Edit Task -->
          <button @click="openEditTaskScreen(actionTask); modalTaskMenuOpen = false;" class="w-full py-2 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
            <span>Edit Task</span>
          </button>

          <!-- Mark as Completed / Reopen -->
          <button @click="toggleTask(actionTask); modalTaskMenuOpen = false;" class="w-full py-2 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
            <span x-text="actionTask && Number(actionTask.completed) === 1 ? 'Reopen Task' : 'Mark as Completed'"></span>
          </button>

          <!-- Change Priority submenu -->
          <div class="py-1 px-3">
            <div class="text-[10px] text-slate-400 font-bold mb-1">Change Priority</div>
            <div class="flex gap-2">
              <button @click="changeTaskPriority(actionTask, 'Low')" class="px-2.5 py-1 rounded-lg text-[10px] font-bold bg-emerald-50 text-emerald-700 hover:bg-emerald-100 touch-press">Low</button>
              <button @click="changeTaskPriority(actionTask, 'Medium')" class="px-2.5 py-1 rounded-lg text-[10px] font-bold bg-amber-50 text-amber-700 hover:bg-amber-100 touch-press">Medium</button>
              <button @click="changeTaskPriority(actionTask, 'High')" class="px-2.5 py-1 rounded-lg text-[10px] font-bold bg-rose-50 text-rose-700 hover:bg-rose-100 touch-press">High</button>
            </div>
          </div>

          <!-- Duplicate -->
          <button @click="duplicateTask(actionTask)" class="w-full py-2 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2"/></svg>
            <span>Duplicate Task</span>
          </button>

          <!-- Delete -->
          <button @click="deleteTask(actionTask)" class="w-full py-2 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
            <span>Delete Task</span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODALS: BULK ASSIGN & BULK MOVE
         ======================================================================= -->
    <div x-show="modalBulkAssignOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalBulkAssignOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-black text-slate-900">Assign Selected Tasks</h3>
          <button @click="modalBulkAssignOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <select x-model="bulkAssignStaff" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700">
          <template x-for="tm in teamMembers" :key="tm.name">
            <option :value="tm.name" x-text="tm.name + ' (' + tm.role + ')'"></option>
          </template>
        </select>
        <button @click="executeBulkAssign(bulkAssignStaff)" class="w-full py-2.5 rounded-xl bg-blue-600 text-white font-bold text-xs touch-press">
          Confirm Assignment
        </button>
      </div>
    </div>

    <div x-show="modalBulkMoveOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalBulkMoveOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-black text-slate-900">Move Selected Tasks</h3>
          <button @click="modalBulkMoveOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>
        <select x-model="bulkMoveProjectId" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700">
          <option value="">Select Target Project</option>
          <template x-for="p in projects" :key="p.id">
            <option :value="p.id" x-text="p.title"></option>
          </template>
        </select>
        <button @click="executeBulkMove(bulkMoveProjectId)" class="w-full py-2.5 rounded-xl bg-blue-600 text-white font-bold text-xs touch-press">
          Confirm Move
        </button>
      </div>
    </div>


    <!-- =======================================================================
         ADD TASK MODAL (Exact Match Screen 2 & Screen 3)
         ======================================================================= -->
    <div x-show="modalTaskOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="closeAddTaskModal()" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm sm:max-w-md shadow-2xl space-y-4 max-h-[92vh] overflow-y-auto no-scrollbar relative animate-in fade-in slide-in-from-bottom duration-200">
        
        <!-- Mobile Drag Handle (Reference Image Top) -->
        <div class="w-12 h-1 bg-slate-200 rounded-full mx-auto sm:hidden -mt-1 mb-1"></div>

        <!-- Header -->
        <div class="flex items-center justify-between">
          <h3 class="text-base sm:text-lg font-black text-slate-900">Add New Task</h3>
          <button type="button" @click="closeAddTaskModal()" class="text-slate-400 hover:text-slate-700 p-1 rounded-full touch-press" title="Close">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <!-- Auto-selected Project Card (Screens 2 & 3) -->
        <div class="p-3 bg-blue-50/60 border border-blue-100 rounded-2xl flex items-center justify-between gap-3">
          <div class="flex items-center gap-3 min-w-0">
            <div class="w-10 h-10 rounded-xl bg-blue-100 text-blue-600 flex items-center justify-center shrink-0">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z"/></svg>
            </div>
            <div class="min-w-0">
              <div class="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Project</div>
              <div class="text-xs font-black text-slate-900 truncate" x-text="taskForm.client_name || taskForm.project_name || (activeProject ? (activeProject.client_name || activeProject.title) : 'ABC Tech Solutions')">ABC Tech Solutions</div>
              <div class="text-[10px] text-slate-400 font-medium">(Auto-selected)</div>
            </div>
          </div>
          <div class="text-slate-400 p-1 shrink-0" title="Locked to current project">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
          </div>
        </div>

        <!-- Task Form Fields -->
        <div class="space-y-3.5">
          <!-- Task Title -->
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1.5">Task Title <span class="text-rose-500">*</span></label>
            <input type="text" x-model="taskForm.title" placeholder="Enter task title" required class="w-full px-3.5 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-medium text-slate-900 placeholder:text-slate-400 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none transition-all"/>
            <div x-show="taskFormError" class="text-[11px] text-rose-500 font-semibold mt-1" x-text="taskFormError"></div>
          </div>

          <!-- Description -->
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1.5">Description</label>
            <textarea x-model="taskForm.description" maxlength="500" rows="3" placeholder="Enter task description (optional)" class="w-full px-3.5 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-medium text-slate-900 placeholder:text-slate-400 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none resize-none transition-all"></textarea>
            <div class="text-right text-[10px] text-slate-400 mt-0.5" x-text="(taskForm.description ? taskForm.description.length : 0) + '/500'">0/500</div>
          </div>

          <!-- Due Date -->
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1.5">Due Date</label>
            <div class="relative flex items-center">
              <div class="absolute left-3.5 text-slate-400 pointer-events-none">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
              </div>
              <input type="date" x-model="taskForm.due_date" class="w-full pl-10 pr-9 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-medium text-slate-900 focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none cursor-pointer"/>
              <button type="button" x-show="taskForm.due_date" @click="taskForm.due_date = ''; taskForm.due_time = ''" class="absolute right-3 text-slate-400 hover:text-slate-600 p-1 touch-press" title="Clear Date">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>
          </div>

          <!-- Priority & Status (2 Columns) -->
          <div class="grid grid-cols-2 gap-3">
            <!-- Priority -->
            <div>
              <label class="block text-xs font-bold text-slate-800 mb-1.5">Priority</label>
              <div class="relative flex items-center">
                <div class="absolute left-3 pointer-events-none">
                  <svg class="w-3.5 h-3.5" :class="taskForm.priority === 'High' ? 'text-rose-500' : (taskForm.priority === 'Medium' ? 'text-amber-500' : 'text-emerald-500')" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9"/></svg>
                </div>
                <select x-model="taskForm.priority" class="w-full pl-8 pr-7 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none appearance-none cursor-pointer">
                  <option value="Low">Low</option>
                  <option value="Medium">Medium</option>
                  <option value="High">High</option>
                </select>
                <div class="absolute right-2.5 pointer-events-none text-slate-400">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
                </div>
              </div>
            </div>

            <!-- Status -->
            <div>
              <label class="block text-xs font-bold text-slate-800 mb-1.5">Status</label>
              <div class="relative flex items-center">
                <div class="absolute left-3 pointer-events-none">
                  <span class="w-2.5 h-2.5 rounded-full border-2 block" :class="taskForm.status === 'Completed' ? 'border-emerald-500 bg-emerald-500' : (taskForm.status === 'In Progress' ? 'border-blue-500 bg-blue-500' : 'border-blue-500 bg-transparent')"></span>
                </div>
                <select x-model="taskForm.status" class="w-full pl-8 pr-7 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-800 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 focus:outline-none appearance-none cursor-pointer">
                  <option value="To Do">To Do</option>
                  <option value="In Progress">In Progress</option>
                  <option value="Completed">Completed</option>
                </select>
                <div class="absolute right-2.5 pointer-events-none text-slate-400">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
                </div>
              </div>
            </div>
          </div>

          <!-- Assign To -->
          <div>
            <div class="flex items-center justify-between mb-1.5">
              <label class="block text-xs font-bold text-slate-800">Assign To</label>
              <button type="button" @click="openTaskAssigneesModal()" 
                class="text-[11px] font-bold text-blue-600 hover:text-blue-700 hover:underline flex items-center gap-1 touch-press">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                <span>+ Add Members</span>
              </button>
            </div>

            <div class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl min-h-[46px] flex flex-wrap items-center gap-2 transition-all">
              <!-- Empty State: "[ Select team members... ] [ + Add Members ]" -->
              <div x-show="!taskForm.selected_members || taskForm.selected_members.length === 0" class="w-full flex items-center justify-between gap-2">
                <button type="button" @click="openTaskAssigneesModal()" 
                  class="flex-1 text-left text-xs font-medium text-slate-400 hover:text-slate-600 flex items-center gap-2 cursor-pointer">
                  <svg class="w-4 h-4 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  <span>Select team members...</span>
                </button>
                <button type="button" @click="openTaskAssigneesModal()" 
                  class="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold flex items-center gap-1 shadow-xs touch-press transition-colors shrink-0">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                  <span>+ Add Members</span>
                </button>
              </div>

              <!-- Member Chips List when members are selected -->
              <template x-for="m in taskForm.selected_members" :key="m.id">
                <div class="inline-flex items-center gap-1.5 pl-1.5 pr-2 py-1 bg-white border border-slate-200/90 rounded-lg shadow-2xs text-xs font-bold text-slate-800 group transition-all">
                  <template x-if="m.avatar_url">
                    <img :src="m.avatar_url" class="w-5 h-5 rounded-full object-cover shrink-0" :alt="m.name"/>
                  </template>
                  <template x-if="!m.avatar_url">
                    <div class="w-5 h-5 rounded-full text-white text-[9px] font-extrabold flex items-center justify-center shrink-0"
                      :class="m.color_class || 'bg-blue-600'">
                      <span x-text="m.initials || (m.name ? m.name.substring(0, 2).toUpperCase() : 'TM')"></span>
                    </div>
                  </template>
                  <span class="truncate max-w-[140px]" x-text="(m.initials ? m.initials + ' — ' : '') + m.name"></span>
                  <button type="button" @click.stop="removeMemberFromTask(m.id)" 
                    class="text-slate-400 hover:text-rose-600 rounded-full p-0.5 ml-0.5 touch-press transition-colors" 
                    title="Remove member">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </div>
              </template>

              <!-- [+ Add Members] Button beside chips -->
              <button type="button" x-show="taskForm.selected_members && taskForm.selected_members.length > 0" 
                @click="openTaskAssigneesModal()" 
                class="inline-flex items-center gap-1 px-2.5 py-1 bg-blue-50 hover:bg-blue-100 text-blue-600 border border-blue-200/80 rounded-lg text-xs font-bold touch-press transition-colors">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
                <span>+ Add Members</span>
              </button>
            </div>
          </div>
        </div>

        <!-- Footer Actions -->
        <div class="flex items-center gap-3 pt-2">
          <button type="button" @click="closeAddTaskModal()" class="w-1/3 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-bold text-xs touch-press text-center transition-colors">
            Cancel
          </button>
          <button type="button" @click="submitTaskForm()" :disabled="isSubmittingTask" class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:opacity-60 text-white font-bold text-xs shadow-md shadow-blue-500/20 touch-press text-center transition-all flex items-center justify-center gap-2">
            <span x-show="!isSubmittingTask">Create Task</span>
            <span x-show="isSubmittingTask" class="flex items-center gap-1.5"><svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg> Creating...</span>
          </button>
        </div>

      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: PROJECT ACTIONS MENU (NO BROWSER NATIVE ALERT)
         ======================================================================= -->
    <div x-show="modalProjectActionsOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalProjectActionsOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3 animate-in fade-in slide-in-from-bottom duration-200">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 class="text-xs font-black text-slate-900" x-text="actionProject ? actionProject.title : 'Project Options'"></h3>
            <p class="text-[10px] text-slate-400 font-medium" x-text="actionProject ? (actionProject.client_name ? ('Website development for ' + actionProject.client_name) : 'Project Actions') : ''"></p>
          </div>
          <button @click="modalProjectActionsOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>

        <div class="space-y-1 text-xs font-bold text-slate-700">
          <!-- 1. Edit Project -->
          <button type="button" @click="openEditProjectModal(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
            <span>Edit Project</span>
          </button>

          <!-- 2. Duplicate Project -->
          <button type="button" @click="duplicateProject(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
            <span>Duplicate Project</span>
          </button>

          <!-- 3. Archive Project -->
          <button type="button" @click="archiveProject(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4"/></svg>
            <span x-text="actionProject && actionProject.archived ? 'Restore Project' : 'Archive Project'">Archive Project</span>
          </button>

          <!-- 4. Share Project -->
          <button type="button" @click="shareProject(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
            <span>Share Project</span>
          </button>

          <!-- 5. Export Project -->
          <button type="button" @click="exportProject(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg>
            <span>Export Project</span>
          </button>

          <!-- 6. Delete Project (Red) -->
          <button type="button" @click="promptDeleteProject(actionProject); modalProjectActionsOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left touch-press transition-colors">
            <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
            <span>Delete Project</span>
          </button>
        </div>
      </div>
    </div>

    <!-- Confirmation Modal: Delete Project -->
    <div x-show="modalConfirmDeleteProjectOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteProjectOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-2xl space-y-4 text-center animate-in fade-in zoom-in-95 duration-150">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div>
          <h3 class="text-sm font-black text-slate-900">Delete Project?</h3>
          <p class="text-xs text-slate-500 mt-1">Are you sure you want to delete <span class="font-bold text-slate-800" x-text="projectToDelete ? projectToDelete.title : 'this project'"></span>? Linked tasks will be preserved as unassigned. This action cannot be undone.</p>
        </div>
        <div class="flex items-center gap-3 pt-2">
          <button type="button" @click="modalConfirmDeleteProjectOpen = false" class="flex-1 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-bold text-xs touch-press transition-colors">
            Cancel
          </button>
          <button type="button" @click="confirmDeleteProject()" class="flex-1 py-2.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs shadow-md shadow-rose-500/20 touch-press transition-colors">
            Delete Project
          </button>
        </div>
      </div>
    </div>

    <!-- Confirmation Modal: Delete Task Attachment File -->
    <div x-show="modalConfirmDeleteTaskFileOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteTaskFileOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-2xl space-y-4 text-center animate-in fade-in zoom-in-95 duration-150">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div>
          <h3 class="text-sm font-black text-slate-900">Delete Attachment?</h3>
          <p class="text-xs text-slate-500 mt-1">Are you sure you want to delete <span class="font-bold text-slate-800" x-text="taskFileToDelete ? (taskFileToDelete.name || taskFileToDelete.original_name) : 'this file'"></span>? This will only remove this attachment. Your task and other files will remain unchanged.</p>
        </div>
        <div class="flex items-center gap-3 pt-2">
          <button type="button" @click="modalConfirmDeleteTaskFileOpen = false; taskFileToDelete = null; taskForFileDeletion = null;" class="flex-1 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-bold text-xs touch-press transition-colors">
            Cancel
          </button>
          <button type="button" @click="confirmDeleteTaskFileAction()" :disabled="isDeletingTaskFile" class="flex-1 py-2.5 rounded-xl bg-rose-600 hover:bg-rose-700 disabled:opacity-50 text-white font-bold text-xs shadow-md shadow-rose-500/20 touch-press transition-colors flex items-center justify-center gap-1.5">
            <template x-if="isDeletingTaskFile">
              <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
            </template>
            <span x-text="isDeletingTaskFile ? 'Deleting...' : 'Delete File'"></span>
          </button>
        </div>
      </div>
    </div>

    <!-- Modal: Add Project Note (Screen 12 Reference) -->
    <div x-show="modalAddProjectNoteOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalAddProjectNoteOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm sm:max-w-md shadow-2xl space-y-4 animate-in fade-in slide-in-from-bottom duration-200">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-sm font-black text-slate-900">Add Project Note</h3>
          <button type="button" @click="modalAddProjectNoteOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>
        <form @submit.prevent="submitProjectNote()" class="space-y-3.5 text-xs">
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1.5">Note Title <span class="text-rose-500">*</span></label>
            <input type="text" x-model="projectNoteForm.title" required placeholder="e.g. Milestone reached, Client feedback" class="w-full px-3.5 py-2.5 bg-white border border-slate-200 rounded-xl font-medium focus:border-blue-500 focus:outline-none"/>
          </div>
          <div>
            <label class="block text-xs font-bold text-slate-800 mb-1.5">Description <span class="text-rose-500">*</span></label>
            <textarea x-model="projectNoteForm.description" required rows="3" placeholder="Enter note details..." class="w-full px-3.5 py-2.5 bg-white border border-slate-200 rounded-xl font-medium focus:border-blue-500 focus:outline-none resize-none"></textarea>
          </div>
          <div class="flex items-center gap-3 pt-2">
            <button type="button" @click="modalAddProjectNoteOpen = false" class="w-1/3 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-bold text-xs touch-press transition-colors">
              Cancel
            </button>
            <button type="submit" class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-md shadow-blue-500/20 touch-press transition-colors">
              Save Note
            </button>
          </div>
        </form>
      </div>
    </div>

    <!-- Modal: Project File Preview (Screen 10 & 11 Reference) -->
    <div x-show="modalProjectFileViewerOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalProjectFileViewerOpen = false" class="bg-white rounded-3xl border border-slate-200 p-5 w-full max-w-lg shadow-2xl space-y-4 max-h-[90vh] flex flex-col">
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 shrink-0">
          <div class="flex items-center gap-2.5 min-w-0 pr-2">
            <div class="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 text-xs font-black uppercase"
              :class="{
                'bg-rose-100 text-rose-600': activeProjectFileDoc && (activeProjectFileDoc.type === 'pdf' || (activeProjectFileDoc.name && activeProjectFileDoc.name.endsWith('.pdf'))),
                'bg-blue-100 text-blue-600': activeProjectFileDoc && (activeProjectFileDoc.type === 'doc' || (activeProjectFileDoc.name && activeProjectFileDoc.name.endsWith('.doc'))),
                'bg-purple-100 text-purple-600': activeProjectFileDoc && (activeProjectFileDoc.type === 'image' || (activeProjectFileDoc.name && activeProjectFileDoc.name.match(/\.(png|jpg|jpeg|gif|webp)$/i)))
              }">
              <span x-text="activeProjectFileDoc && activeProjectFileDoc.name ? activeProjectFileDoc.name.split('.').pop().toUpperCase() : 'FILE'">PDF</span>
            </div>
            <div class="min-w-0">
              <h3 class="text-xs font-black text-slate-900 truncate" x-text="activeProjectFileDoc ? activeProjectFileDoc.name : 'File Preview'"></h3>
              <p class="text-[10px] text-slate-400" x-text="activeProjectFileDoc ? (activeProjectFileDoc.size + ' • ' + (activeProjectFileDoc.date || '')) : ''"></p>
            </div>
          </div>
          <button @click="modalProjectFileViewerOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold w-7 h-7 flex items-center justify-center rounded-lg hover:bg-slate-100 transition-colors">&times;</button>
        </div>

        <!-- Body -->
        <div class="flex-1 overflow-y-auto space-y-3 min-h-[160px]">
          <!-- IMAGE PREVIEW (Screen 10 Reference) -->
          <template x-if="activeProjectFileDoc && (activeProjectFileDoc.type === 'image' || (activeProjectFileDoc.mime_type && activeProjectFileDoc.mime_type.startsWith('image/')) || (activeProjectFileDoc.name && activeProjectFileDoc.name.match(/\.(png|jpg|jpeg|gif|webp)$/i)))">
            <div class="rounded-2xl overflow-hidden bg-slate-100 border border-slate-200/80 flex items-center justify-center p-2 min-h-[220px]">
              <img :src="activeProjectFileDoc.url" class="max-h-80 w-auto max-w-full rounded-xl object-contain shadow-xs" :alt="activeProjectFileDoc.name"/>
            </div>
          </template>

          <!-- PDF PREVIEW (Screen 11 Reference) -->
          <template x-if="activeProjectFileDoc && (activeProjectFileDoc.type === 'pdf' || (activeProjectFileDoc.mime_type && activeProjectFileDoc.mime_type === 'application/pdf') || (activeProjectFileDoc.name && activeProjectFileDoc.name.endsWith('.pdf')))">
            <div class="space-y-2">
              <div class="rounded-2xl overflow-hidden border border-slate-200 bg-slate-50">
                <iframe :src="activeProjectFileDoc.url" class="w-full h-80 border-0" title="PDF Preview"></iframe>
              </div>
            </div>
          </template>

          <!-- TEXT PREVIEW -->
          <template x-if="activeProjectFileDoc && (activeProjectFileDoc.type === 'text' || (activeProjectFileDoc.mime_type && activeProjectFileDoc.mime_type.startsWith('text/')) || (activeProjectFileDoc.name && activeProjectFileDoc.name.match(/\.(txt|md|csv|json)$/i)))">
            <div class="p-3 bg-slate-900 text-slate-100 rounded-2xl border border-slate-800 text-xs font-mono whitespace-pre-wrap max-h-80 overflow-y-auto select-text shadow-inner"
              x-text="activeProjectFileDoc && activeProjectFileDoc.text ? activeProjectFileDoc.text : 'Loading file content...'">
            </div>
          </template>

          <!-- OTHER DOCUMENT TYPE -->
          <template x-if="activeProjectFileDoc && !activeProjectFileDoc.name.match(/\.(png|jpg|jpeg|gif|webp|pdf|txt|md|csv|json)$/i)">
            <div class="p-6 bg-slate-50 rounded-2xl border border-slate-200/80 text-center space-y-3">
              <div class="w-12 h-12 mx-auto rounded-2xl bg-blue-100 text-blue-600 flex items-center justify-center">
                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
              </div>
              <div>
                <h4 class="text-xs font-black text-slate-900 truncate" x-text="activeProjectFileDoc.name"></h4>
                <p class="text-[11px] text-slate-500 mt-0.5">This document cannot be previewed in the browser directly. Click Download below.</p>
              </div>
            </div>
          </template>
        </div>

        <!-- Footer Actions (Screen 10 & 11 Reference: Download & Open in New Tab) -->
        <div class="flex items-center gap-3 pt-2 border-t border-slate-100 shrink-0">
          <template x-if="activeProjectFileDoc && (activeProjectFileDoc.download_url || activeProjectFileDoc.url)">
            <a :href="activeProjectFileDoc.download_url || activeProjectFileDoc.url" download class="flex-1 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-bold text-xs flex items-center justify-center gap-1.5 touch-press transition-colors">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
              <span>Download</span>
            </a>
          </template>
          <template x-if="activeProjectFileDoc && activeProjectFileDoc.url">
            <a :href="activeProjectFileDoc.url" target="_blank" rel="noopener noreferrer" class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center justify-center gap-1.5 shadow-sm touch-press transition-colors">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
              <span>Open in New Tab</span>
            </a>
          </template>
        </div>
      </div>
    </div>

    <!-- =======================================================================
         IN-APP MODAL: TEAM MEMBER ACTIONS MENU (Screen 2 Reference)
         ======================================================================= -->
    <div x-show="modalMemberMenuOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalMemberMenuOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2.5 min-w-0">
            <div class="w-8 h-8 rounded-full text-white flex items-center justify-center font-bold text-xs shrink-0"
              :class="activeTeamMember ? (activeTeamMember.color_class || 'bg-blue-600') : 'bg-blue-600'">
              <span x-text="activeTeamMember ? (activeTeamMember.initials || activeTeamMember.name.substring(0, 2).toUpperCase()) : ''"></span>
            </div>
            <div class="min-w-0">
              <h3 class="text-xs font-black text-slate-900 truncate" x-text="activeTeamMember ? activeTeamMember.name : 'Member Options'"></h3>
              <p class="text-[10px] text-slate-400 truncate" x-text="activeTeamMember ? activeTeamMember.role : ''"></p>
            </div>
          </div>
          <button @click="modalMemberMenuOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold shrink-0">&times;</button>
        </div>

        <div class="space-y-1 text-xs font-bold text-slate-700">
          <!-- Add Member -->
          <button @click="openAddTeamMemberModal(); modalMemberMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-blue-50 text-blue-600 flex items-center gap-3 text-left touch-press font-bold">
            <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
            <span>Add Member</span>
          </button>

          <!-- Edit Profile -->
          <button @click="openEditMemberModal(activeTeamMember); modalMemberMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
            <span>Edit Member Profile</span>
          </button>

          <!-- Toggle Status -->
          <button @click="toggleMemberStatus(activeTeamMember)" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <span x-text="activeTeamMember && (activeTeamMember.status || '').toLowerCase() === 'active' ? 'Set as Inactive' : 'Set as Active'"></span>
          </button>

          <!-- Send Email -->
          <button @click="triggerMemberEmail(activeTeamMember); modalMemberMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
            <span>Send Email</span>
          </button>

          <!-- Call Member -->
          <button @click="triggerMemberCall(activeTeamMember); modalMemberMenuOpen = false;" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
            <span>Call Member</span>
          </button>

          <!-- Delete Member -->
          <button @click="deleteTeamMember(activeTeamMember)" class="w-full py-2.5 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left touch-press">
            <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
            <span>Delete Member</span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: ADD / EDIT TEAM MEMBER PROFILE
         ======================================================================= -->
    <div x-show="modalEditMemberOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalEditMemberOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto no-scrollbar">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
            </div>
            <h3 class="text-sm font-extrabold text-slate-900" x-text="teamMemberForm.id ? 'Edit Team Member' : 'Add Team Member'"></h3>
          </div>
          <button @click="modalEditMemberOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>

        <form @submit.prevent="submitTeamMemberForm()" class="space-y-3 text-xs">
          <div>
            <label class="block font-bold text-slate-700 mb-1">Full Name *</label>
            <input type="text" x-model="teamMemberForm.name" required placeholder="e.g. Suresh Kumar" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Job Title / Role *</label>
            <input type="text" x-model="teamMemberForm.role" required placeholder="e.g. Lead Architect" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div class="grid grid-cols-2 gap-2.5">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Department</label>
              <select x-model="teamMemberForm.department" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-white font-semibold text-slate-800">
                <option value="Executive">Executive</option>
                <option value="Engineering">Engineering</option>
                <option value="Design">Design</option>
                <option value="Product">Product</option>
                <option value="QA / Testing">QA / Testing</option>
                <option value="Marketing">Marketing</option>
              </select>
            </div>
            <div>
              <label class="block font-bold text-slate-700 mb-1">Status</label>
              <select x-model="teamMemberForm.status" class="w-full px-3 py-2.5 rounded-xl border border-slate-200 bg-white font-semibold text-slate-800">
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
              </select>
            </div>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Email Address *</label>
            <input type="email" x-model="teamMemberForm.email" required placeholder="e.g. suresh@softwarecrm.com" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Phone Number *</label>
            <input type="tel" x-model="teamMemberForm.phone" required placeholder="e.g. +91 98765 43210" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div class="grid grid-cols-2 gap-2.5">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Company</label>
              <input type="text" x-model="teamMemberForm.company" placeholder="Company Name" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 font-semibold text-slate-800"/>
            </div>
            <div>
              <label class="block font-bold text-slate-700 mb-1">Location</label>
              <input type="text" x-model="teamMemberForm.location" placeholder="e.g. Bangalore, IN" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 font-semibold text-slate-800"/>
            </div>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">About / Bio</label>
            <textarea x-model="teamMemberForm.bio" rows="2" placeholder="Brief background of the team member..." 
              class="w-full px-3.5 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-medium text-slate-800"></textarea>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Skills & Expertise (comma separated)</label>
            <input type="text" x-model="teamMemberForm.skills" placeholder="e.g. PHP, React, MySQL, Architecture" 
              class="w-full px-3.5 py-2 rounded-xl border border-slate-200 font-medium text-slate-800"/>
          </div>

          <div class="pt-2 flex gap-2">
            <button type="button" @click="modalEditMemberOpen = false" class="flex-1 py-2.5 rounded-xl border border-slate-200 text-slate-600 font-bold hover:bg-slate-50 touch-press">
              Cancel
            </button>
            <button type="submit" class="flex-1 py-2.5 rounded-xl bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-md shadow-blue-500/20 touch-press">
              <span x-text="teamMemberForm.id ? 'Save Changes' : 'Add Member'"></span>
            </button>
          </div>
        </form>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CONFIRM DELETE TEAM MEMBER (STRICTLY NO BROWSER CONFIRM)
         ======================================================================= -->
    <div x-show="modalConfirmDeleteMemberOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteMemberOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm shadow-sheet space-y-4">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto shadow-xs">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        
        <div class="text-center space-y-1">
          <h3 class="text-sm font-black text-slate-900">Remove Team Member?</h3>
          <p class="text-xs text-slate-500 leading-relaxed">
            Are you sure you want to remove <span class="font-bold text-slate-800" x-text="memberToDelete ? memberToDelete.name : 'this member'"></span> from the team? This action cannot be undone.
          </p>
        </div>

        <div class="grid grid-cols-2 gap-2.5 pt-1">
          <button @click="modalConfirmDeleteMemberOpen = false" class="py-2.5 rounded-xl border border-slate-200 text-slate-600 font-bold text-xs hover:bg-slate-50 touch-press">
            Cancel
          </button>
          <button @click="confirmDeleteTeamMember()" class="py-2.5 rounded-xl bg-rose-600 text-white font-bold text-xs hover:bg-rose-700 shadow-sm touch-press">
            Confirm Delete
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: SELECT TASK ASSIGNEES / ADD MEMBERS
         ======================================================================= -->
    <div x-show="modalTaskAssigneesOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="closeTaskAssigneesModal()" class="bg-white dark:bg-slate-800 rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-md shadow-2xl space-y-4 max-h-[90vh] flex flex-col relative animate-in fade-in slide-in-from-bottom duration-200">
        
        <!-- Mobile Drag Handle -->
        <div class="w-12 h-1 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto sm:hidden -mt-1 mb-1"></div>

        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-700/60 shrink-0">
          <div class="flex items-center gap-2.5">
            <div class="w-9 h-9 rounded-xl bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
            </div>
            <div>
              <h3 class="text-sm sm:text-base font-black text-slate-900 dark:text-slate-100">Assign Team Members</h3>
              <p class="text-[11px] text-slate-400 dark:text-slate-400">Select one or more members for this task</p>
            </div>
          </div>
          <button type="button" @click="closeTaskAssigneesModal()" class="text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 p-1 rounded-full touch-press" title="Close">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <!-- Search input -->
        <div class="relative shrink-0">
          <div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
          </div>
          <input type="text" x-model="taskMemberSearchQuery" placeholder="Search members by name, email, or role..." 
                 class="w-full pl-9 pr-8 py-2.5 bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-700 rounded-xl text-xs text-slate-900 dark:text-slate-100 placeholder:text-slate-400 focus:bg-white dark:focus:bg-slate-900 focus:border-blue-500 focus:outline-none transition-all"/>
          <button type="button" x-show="taskMemberSearchQuery" @click="taskMemberSearchQuery = ''" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400 hover:text-slate-600">
            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <!-- Quick actions: Select All, Clear Selection, Counter -->
        <div class="flex items-center justify-between text-xs py-1 px-1 shrink-0">
          <div class="flex items-center gap-2">
            <button type="button" @click="selectAllTaskMembers()" class="text-blue-600 dark:text-blue-400 hover:underline font-bold text-[11px] touch-press cursor-pointer">
              Select All
            </button>
            <span class="text-slate-300 dark:text-slate-600">•</span>
            <button type="button" @click="clearAllTaskMembers()" class="text-slate-500 dark:text-slate-400 hover:underline font-semibold text-[11px] touch-press cursor-pointer">
              Clear Selection
            </button>
          </div>
          <div class="text-[11px] font-bold text-slate-500 dark:text-slate-400">
            <span class="text-blue-600 dark:text-blue-400" x-text="tempSelectedMemberIds.length">0</span> of <span x-text="(teamMembers || []).length">0</span> selected
          </div>
        </div>

        <!-- Members list -->
        <div class="flex-1 overflow-y-auto space-y-1.5 pr-0.5 max-h-64 sm:max-h-72">
          <template x-for="m in filteredTaskAvailableMembers" :key="m.id">
            <div @click="toggleTaskMemberSelection(m.id)" 
                 class="flex items-center justify-between p-2.5 rounded-xl border cursor-pointer transition-all touch-press select-none"
                 :class="tempSelectedMemberIds.includes(String(m.id)) ? 'bg-blue-50/70 dark:bg-blue-900/30 border-blue-300 dark:border-blue-700 shadow-xs' : 'bg-white dark:bg-slate-800/80 border-slate-200 dark:border-slate-700/70 hover:bg-slate-50 dark:hover:bg-slate-700/50'">
              
              <div class="flex items-center gap-3 min-w-0">
                <!-- Checkbox -->
                <div class="w-4 h-4 rounded-md border flex items-center justify-center shrink-0 transition-colors"
                     :class="tempSelectedMemberIds.includes(String(m.id)) ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700'">
                  <svg x-show="tempSelectedMemberIds.includes(String(m.id))" class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                </div>

                <!-- Avatar or Initials -->
                <div class="relative shrink-0">
                  <template x-if="m.avatar_url">
                    <img :src="m.avatar_url" class="w-8 h-8 rounded-full object-cover border border-slate-200 dark:border-slate-700" :alt="m.name"/>
                  </template>
                  <template x-if="!m.avatar_url">
                    <div class="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white shadow-xs"
                         :class="m.color_class || 'bg-blue-600'"
                         x-text="m.initials || (m.name ? m.name.substring(0, 2).toUpperCase() : 'TM')"></div>
                  </template>
                </div>

                <!-- Member Info -->
                <div class="min-w-0">
                  <div class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate" x-text="m.name"></div>
                  <div class="text-[11px] text-slate-400 dark:text-slate-400 truncate flex items-center gap-1.5">
                    <span x-text="m.email"></span>
                    <template x-if="m.role || m.department">
                      <span>• <span class="font-medium text-slate-500 dark:text-slate-400" x-text="m.role || m.department"></span></span>
                    </template>
                  </div>
                </div>
              </div>

              <!-- Status pill -->
              <div class="shrink-0 text-[10px] font-bold px-2 py-0.5 rounded-full"
                   :class="m.status === 'Active' ? 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-600 dark:text-emerald-400' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'">
                <span x-text="m.status || 'Active'"></span>
              </div>
            </div>
          </template>

          <!-- Empty search state -->
          <div x-show="filteredTaskAvailableMembers.length === 0" class="py-8 text-center text-slate-400 text-xs">
            <svg class="w-8 h-8 mx-auto mb-2 text-slate-300 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
            No team members found matching "<span x-text="taskMemberSearchQuery"></span>"
          </div>
        </div>

        <!-- Footer Actions -->
        <div class="flex items-center gap-2.5 pt-3 border-t border-slate-100 dark:border-slate-700/60 shrink-0">
          <button type="button" @click="closeTaskAssigneesModal()" class="w-1/3 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold text-xs touch-press text-center transition-colors">
            Cancel
          </button>
          <button type="button" @click="confirmSelectedTaskMembers()" class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs shadow-md shadow-blue-500/20 touch-press text-center transition-all flex items-center justify-center gap-1.5">
            <span>Add Selected Members</span>
            <span class="px-1.5 py-0.5 rounded-full bg-white/20 text-[10px]" x-text="tempSelectedMemberIds.length"></span>
          </button>
        </div>

      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CREATE / EDIT GROUP
         ======================================================================= -->
    <div x-show="modalGroupFormOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalGroupFormOpen = false" class="bg-white dark:bg-slate-800 rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-lg shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto no-scrollbar">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-700/60">
          <div class="flex items-center gap-2.5">
            <div class="w-8 h-8 rounded-xl bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
            </div>
            <div>
              <h3 class="text-sm font-black text-slate-900 dark:text-slate-100" x-text="isEditingGroup ? 'Edit Group' : 'Create New Group'"></h3>
              <p class="text-[11px] text-slate-400">Configure team properties, leader, and initial membership</p>
            </div>
          </div>
          <button @click="modalGroupFormOpen = false" class="text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 text-lg font-bold touch-press">&times;</button>
        </div>

        <!-- Form -->
        <form @submit.prevent="submitGroupForm()" class="space-y-3.5 text-xs">
          
          <!-- General error if any -->
          <div x-show="groupFormErrors.general" class="p-2.5 bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-900/60 rounded-xl text-rose-600 dark:text-rose-400 text-xs font-medium" x-text="groupFormErrors.general"></div>

          <!-- Group Name -->
          <div>
            <label class="block font-bold text-slate-700 dark:text-slate-300 mb-1">Group Name <span class="text-rose-500">*</span></label>
            <input type="text" x-model="groupForm.name" placeholder="e.g. Engineering Core, Design Studio..." 
              class="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-900 border rounded-xl font-medium text-slate-800 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
              :class="groupFormErrors.name ? 'border-rose-400 dark:border-rose-500 ring-1 ring-rose-400/20' : 'border-slate-200 dark:border-slate-700'">
            <p x-show="groupFormErrors.name" class="text-[10px] text-rose-500 mt-1 font-bold" x-text="groupFormErrors.name"></p>
          </div>

          <!-- Company Selection (Required) -->
          <div>
            <div class="flex items-center justify-between mb-1">
              <label class="block font-bold text-slate-700 dark:text-slate-300">Company <span class="text-rose-500">*</span></label>
              <button type="button" @click="openCreateCompanyModalFromGroupForm()" 
                class="text-[11px] font-bold text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 hover:underline flex items-center gap-1 touch-press">
                <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/></svg>
                <span>+ New Company</span>
              </button>
            </div>

            <!-- When companies exist -->
            <div x-show="companies && companies.length > 0" class="space-y-1.5">
              <input x-show="companies && companies.length > 6" type="text" x-model="groupCompanySearch" placeholder="Type to filter companies..." 
                class="w-full px-2.5 py-1.5 bg-slate-100/80 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-700 rounded-lg text-[11px] font-medium text-slate-700 dark:text-slate-200 placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-blue-500">
              <select x-model="groupForm.company_id" 
                class="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-900 border rounded-xl font-medium text-slate-800 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all cursor-pointer"
                :class="groupFormErrors.company_id ? 'border-rose-400 dark:border-rose-500 ring-1 ring-rose-400/20' : 'border-slate-200 dark:border-slate-700'">
                <option value="" disabled :selected="!groupForm.company_id">Select a company</option>
                <template x-for="c in sortedCompanies" :key="c.id">
                  <option :value="c.id" x-text="c.name + (c.industry ? ' (' + c.industry + ')' : '')"></option>
                </template>
              </select>
            </div>

            <!-- Empty state when no companies exist -->
            <div x-show="!companies || companies.length === 0" class="p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800/60 rounded-xl text-amber-800 dark:text-amber-300 text-xs flex items-center justify-between gap-2">
              <div class="flex items-center gap-2 min-w-0">
                <svg class="w-4 h-4 text-amber-500 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                <span class="truncate">No companies found. Create a company first to assign this group.</span>
              </div>
              <button type="button" @click="openCreateCompanyModalFromGroupForm()" class="px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-[11px] font-bold shrink-0 touch-press">
                Create
              </button>
            </div>

            <p x-show="groupFormErrors.company_id" class="text-[10px] text-rose-500 mt-1 font-bold" x-text="groupFormErrors.company_id"></p>
          </div>

          <!-- Group Description -->
          <div>
            <label class="block font-bold text-slate-700 dark:text-slate-300 mb-1">Description</label>
            <textarea x-model="groupForm.description" rows="2" placeholder="Brief purpose or responsibility of this team..." 
              class="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-slate-800 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"></textarea>
          </div>

          <!-- Group Leader -->
          <div>
            <label class="block font-bold text-slate-700 dark:text-slate-300 mb-1">Group Leader</label>
            <select x-model="groupForm.leader_id" 
              class="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-slate-800 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all">
              <option value="">-- No Leader (Assign Later) --</option>
              <template x-for="emp in availableGroupEmployees" :key="emp.id">
                <option :value="emp.id" x-text="emp.name + ' (' + emp.role + ' • ' + (emp.department || 'Engineering') + ')'"></option>
              </template>
            </select>
            <p class="text-[10px] text-slate-400 mt-1">Leaders are positioned at the top of the organizational chart.</p>
          </div>

          <!-- Group Color -->
          <div>
            <label class="block font-bold text-slate-700 dark:text-slate-300 mb-1.5">Group Theme Color</label>
            <div class="flex items-center gap-2 flex-wrap">
              <template x-for="c in ['#590907', '#A5A79B', '#E8D2B5', '#75110E', '#8C8E82', '#DCBE97', '#430605']" :key="c">
                <button type="button" @click="groupForm.color = c" 
                  class="w-7 h-7 rounded-xl transition-transform touch-press"
                  :style="'background-color: ' + c"
                  :class="groupForm.color === c ? 'ring-2 ring-offset-2 ring-blue-500 dark:ring-offset-slate-800 scale-110 shadow-xs' : 'opacity-80 hover:opacity-100'">
                </button>
              </template>
            </div>
          </div>

          <!-- Initial Members Selection (Only when creating new group) -->
          <div x-show="!isEditingGroup" class="space-y-1.5">
            <div class="flex items-center justify-between">
              <label class="block font-bold text-slate-700 dark:text-slate-300">Initial Team Members</label>
              <span class="text-[10px] text-slate-400 font-medium" x-text="groupForm.selected_member_ids.length + ' selected'"></span>
            </div>

            <div class="max-h-40 overflow-y-auto no-scrollbar border border-slate-200 dark:border-slate-700 rounded-xl divide-y divide-slate-100 dark:divide-slate-800 bg-slate-50/50 dark:bg-slate-900/40 p-1">
              <template x-for="emp in availableGroupEmployees" :key="emp.id">
                <label class="flex items-center gap-2.5 p-2 rounded-lg hover:bg-white dark:hover:bg-slate-800 cursor-pointer transition-colors">
                  <input type="checkbox" :value="emp.id" x-model="groupForm.selected_member_ids" 
                    class="rounded text-blue-600 focus:ring-blue-500 dark:bg-slate-800 dark:border-slate-600">
                  <div class="w-6 h-6 rounded-full text-white text-[9px] font-bold flex items-center justify-center shrink-0"
                    :class="emp.color_class || 'bg-blue-600'">
                    <span x-text="emp.initials || emp.name.substring(0, 2).toUpperCase()"></span>
                  </div>
                  <div class="min-w-0 flex-1">
                    <div class="text-[11px] font-bold text-slate-800 dark:text-slate-200 truncate" x-text="emp.name"></div>
                    <div class="text-[9px] text-slate-400 truncate" x-text="emp.role + ' • ' + (emp.department || 'CRM')"></div>
                  </div>
                </label>
              </template>
            </div>
          </div>

          <!-- Footer Buttons -->
          <div class="pt-3 flex gap-2.5 border-t border-slate-100 dark:border-slate-700/60">
            <button type="button" @click="modalGroupFormOpen = false" 
              class="flex-1 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold hover:bg-slate-50 dark:hover:bg-slate-700 touch-press transition-colors">
              Cancel
            </button>
            <button type="submit" :disabled="isSubmittingGroupForm"
              class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold shadow-md shadow-blue-500/20 touch-press transition-colors flex items-center justify-center gap-2">
              <span x-show="isSubmittingGroupForm" class="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
              <span x-text="isSubmittingGroupForm ? 'Saving...' : (isEditingGroup ? 'Save Changes' : 'Create Group')"></span>
            </button>
          </div>

        </form>

      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: ADD MEMBERS TO GROUP (SEARCHABLE MULTI-SELECT)
         ======================================================================= -->
    <div x-show="modalAddGroupMembersOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalAddGroupMembersOpen = false" class="bg-white dark:bg-slate-800 rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-md shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto no-scrollbar">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-2 border-b border-slate-100 dark:border-slate-700/60">
          <div class="flex items-center gap-2.5">
            <div class="w-8 h-8 rounded-xl bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
            </div>
            <div class="min-w-0">
              <h3 class="text-sm font-black text-slate-900 dark:text-slate-100 truncate">Add Team Members</h3>
              <p class="text-[11px] text-slate-400 truncate">Add members to <span class="font-bold text-slate-700 dark:text-slate-300" x-text="activeGroup ? activeGroup.name : 'Group'"></span></p>
            </div>
          </div>
          <button @click="modalAddGroupMembersOpen = false" class="text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 text-lg font-bold touch-press">&times;</button>
        </div>

        <!-- Search & Selection Controls -->
        <div class="space-y-2">
          <!-- Search input -->
          <div class="relative">
            <input type="text" x-model="employeeSearchQuery" placeholder="Search employees by name, title, department..." 
              class="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-8 py-2 text-xs text-slate-800 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all">
            <div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            </div>
            <button x-show="employeeSearchQuery" @click="employeeSearchQuery = ''" class="absolute inset-y-0 right-0 pr-2.5 flex items-center text-slate-400">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>

          <!-- Selection Action Quick Buttons -->
          <div class="flex items-center justify-between text-[11px] text-slate-500">
            <span>Selected: <strong class="text-blue-600 dark:text-blue-400" x-text="selectedMemberIdsToAdd.length"></strong> members</span>
            <div class="flex items-center gap-2">
              <button type="button" @click="selectAllAvailableMembers()" class="text-blue-600 dark:text-blue-400 font-bold hover:underline touch-press">Select All</button>
              <span>•</span>
              <button type="button" @click="clearSelectedMembersToAdd()" class="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 touch-press">Clear</button>
            </div>
          </div>
        </div>

        <!-- Available Employees List -->
        <div class="max-h-60 overflow-y-auto no-scrollbar border border-slate-200 dark:border-slate-700 rounded-2xl divide-y divide-slate-100 dark:divide-slate-800 bg-slate-50/40 dark:bg-slate-900/40 p-1">
          
          <template x-for="emp in filteredAvailableEmployees" :key="emp.id">
            <div class="flex items-center justify-between gap-2.5 p-2.5 rounded-xl transition-colors"
              :class="emp.already_in_group 
                ? 'opacity-60 bg-slate-100/60 dark:bg-slate-800/40 cursor-not-allowed' 
                : (selectedMemberIdsToAdd.includes(emp.id) ? 'bg-blue-50/80 dark:bg-blue-950/40 cursor-pointer' : 'hover:bg-white dark:hover:bg-slate-800 cursor-pointer')"
              @click="!emp.already_in_group ? toggleSelectMemberToAdd(emp.id) : null">
              
              <!-- Left: Checkbox + Avatar + Info -->
              <div class="flex items-center gap-2.5 min-w-0">
                <input type="checkbox" :checked="selectedMemberIdsToAdd.includes(emp.id)" :disabled="emp.already_in_group"
                  @click.stop="toggleSelectMemberToAdd(emp.id)"
                  class="rounded text-blue-600 focus:ring-blue-500 dark:bg-slate-800 dark:border-slate-600">

                <div class="w-8 h-8 rounded-full text-white text-xs font-bold flex items-center justify-center shrink-0 shadow-xs"
                  :class="emp.color_class || 'bg-blue-600'">
                  <span x-text="emp.initials || emp.name.substring(0, 2).toUpperCase()"></span>
                </div>

                <div class="min-w-0">
                  <div class="text-xs font-bold text-slate-900 dark:text-slate-100 truncate" x-text="emp.name"></div>
                  <div class="text-[10px] text-slate-500 dark:text-slate-400 truncate" x-text="emp.role + ' • ' + (emp.department || 'Engineering')"></div>
                </div>
              </div>

              <!-- Right: Status Badge -->
              <div class="shrink-0">
                <template x-if="emp.already_in_group">
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                    Already Added
                  </span>
                </template>
                <template x-if="!emp.already_in_group && selectedMemberIdsToAdd.includes(emp.id)">
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-blue-600 text-white">
                    Selected
                  </span>
                </template>
              </div>

            </div>
          </template>

          <!-- Empty list state -->
          <div x-show="filteredAvailableEmployees.length === 0" class="p-6 text-center text-xs text-slate-400">
            No employees match your search.
          </div>

        </div>

        <!-- Footer Buttons -->
        <div class="pt-2 flex gap-2.5 border-t border-slate-100 dark:border-slate-700/60">
          <button type="button" @click="modalAddGroupMembersOpen = false" 
            class="flex-1 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold text-xs hover:bg-slate-50 dark:hover:bg-slate-700 touch-press transition-colors">
            Cancel
          </button>
          <button type="button" @click="submitAddMembersToGroup()" :disabled="isSubmittingAddMembers || selectedMemberIdsToAdd.length === 0"
            class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold text-xs shadow-md shadow-blue-500/20 touch-press transition-colors flex items-center justify-center gap-2">
            <span x-show="isSubmittingAddMembers" class="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
            <span x-text="isSubmittingAddMembers ? 'Adding...' : ('Add ' + selectedMemberIdsToAdd.length + ' Member' + (selectedMemberIdsToAdd.length === 1 ? '' : 's'))"></span>
          </button>
        </div>

      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CONFIRM REMOVE MEMBER FROM GROUP
         ======================================================================= -->
    <div x-show="modalConfirmRemoveMemberOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmRemoveMemberOpen = false" class="bg-white dark:bg-slate-800 rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-sm shadow-sheet space-y-4">
        
        <div class="w-12 h-12 rounded-2xl bg-amber-50 dark:bg-amber-950/40 text-amber-600 dark:text-amber-400 flex items-center justify-center mx-auto shadow-xs border border-amber-100 dark:border-amber-900/60">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 7a4 4 0 11-8 0 4 4 0 018 0zM9 14a6 6 0 00-6 6v1h12v-1a6 6 0 00-6-6zM21 12h-6"/></svg>
        </div>
        
        <div class="text-center space-y-1">
          <h3 class="text-sm font-black text-slate-900 dark:text-slate-100">Remove from Group?</h3>
          <p class="text-xs text-slate-500 dark:text-slate-400 leading-relaxed">
            Remove <span class="font-bold text-slate-800 dark:text-slate-200" x-text="memberToRemove ? memberToRemove.name : 'this member'"></span> from <span class="font-bold text-slate-800 dark:text-slate-200" x-text="activeGroup ? activeGroup.name : 'group'"></span>?
          </p>
        </div>

        <!-- Leader Replacement Notice if removed member is the leader -->
        <div x-show="activeGroup && memberToRemove && activeGroup.leader_id === memberToRemove.id" 
          class="p-3 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 rounded-xl space-y-2 text-xs">
          <div class="font-bold text-amber-800 dark:text-amber-300 flex items-center gap-1.5">
            <svg class="w-4 h-4 text-amber-500" fill="currentColor" viewBox="0 0 20 20"><path d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"/></svg>
            <span>This member is the Group Leader</span>
          </div>
          <p class="text-[11px] text-amber-700 dark:text-amber-400">
            Select a replacement leader from the remaining members, or leave the group temporarily leaderless:
          </p>
          <select x-model="removeMemberNewLeaderId" 
            class="w-full p-2 bg-white dark:bg-slate-900 border border-amber-300 dark:border-amber-700 rounded-lg text-xs font-medium text-slate-800 dark:text-slate-200">
            <option value="">-- Temporarily No Leader --</option>
            <template x-for="rm in (activeGroup ? activeGroup.members : []).filter(m => memberToRemove && m.id !== memberToRemove.id)" :key="rm.id">
              <option :value="rm.id" x-text="rm.name + ' (' + rm.role + ')'"></option>
            </template>
          </select>
        </div>

        <div class="p-2.5 bg-slate-50 dark:bg-slate-900/60 rounded-xl text-[11px] text-slate-500 dark:text-slate-400 border border-slate-100 dark:border-slate-800">
          <strong>Safe Action:</strong> The employee account, history, and CRM data are 100% preserved.
        </div>

        <div class="grid grid-cols-2 gap-2.5 pt-1">
          <button @click="modalConfirmRemoveMemberOpen = false" class="py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold text-xs hover:bg-slate-50 dark:hover:bg-slate-700 touch-press transition-colors">
            Cancel
          </button>
          <button @click="confirmRemoveGroupMember()" :disabled="isSubmittingRemoveMember"
            class="py-2.5 rounded-xl bg-amber-600 hover:bg-amber-700 disabled:opacity-50 text-white font-bold text-xs shadow-sm touch-press transition-colors flex items-center justify-center gap-2">
            <span x-show="isSubmittingRemoveMember" class="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
            <span x-text="isSubmittingRemoveMember ? 'Removing...' : 'Confirm Remove'"></span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: CONFIRM DELETE GROUP
         ======================================================================= -->
    <div x-show="modalConfirmDeleteGroupOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteGroupOpen = false" class="bg-white dark:bg-slate-800 rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-sm shadow-sheet space-y-4">
        
        <div class="w-12 h-12 rounded-2xl bg-rose-50 dark:bg-rose-950/40 text-rose-600 dark:text-rose-400 flex items-center justify-center mx-auto shadow-xs border border-rose-100 dark:border-rose-900/60">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        
        <div class="text-center space-y-1">
          <h3 class="text-sm font-black text-slate-900 dark:text-slate-100">Delete Group?</h3>
          <p class="text-xs text-slate-500 dark:text-slate-400 leading-relaxed">
            Are you sure you want to delete <span class="font-bold text-slate-800 dark:text-slate-200" x-text="groupToDelete ? groupToDelete.name : 'this group'"></span>?
          </p>
        </div>

        <div class="p-2.5 bg-blue-50/70 dark:bg-blue-950/40 rounded-xl text-[11px] text-blue-700 dark:text-blue-300 border border-blue-200/80 dark:border-blue-900/60">
          <strong>Important Guarantee:</strong> Deleting this group will NOT delete any employee records. All team members remain active in the CRM.
        </div>

        <div class="grid grid-cols-2 gap-2.5 pt-1">
          <button @click="modalConfirmDeleteGroupOpen = false" class="py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold text-xs hover:bg-slate-50 dark:hover:bg-slate-700 touch-press transition-colors">
            Cancel
          </button>
          <button @click="confirmDeleteGroup()" :disabled="isSubmittingDeleteGroup"
            class="py-2.5 rounded-xl bg-rose-600 hover:bg-rose-700 disabled:opacity-50 text-white font-bold text-xs shadow-sm touch-press transition-colors flex items-center justify-center gap-2">
            <span x-show="isSubmittingDeleteGroup" class="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
            <span x-text="isSubmittingDeleteGroup ? 'Deleting...' : 'Delete Group'"></span>
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: QUICK MESSAGE TO MEMBER
         ======================================================================= -->
    <div x-show="modalQuickMessageOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalQuickMessageOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3.5">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
            </div>
            <h3 class="text-xs font-black text-slate-900 truncate" x-text="quickMessageRecipient ? ('Message ' + quickMessageRecipient.name) : 'Send Message'"></h3>
          </div>
          <button @click="modalQuickMessageOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>

        <div class="space-y-2 text-xs">
          <label class="block font-bold text-slate-700">Quick Note</label>
          <textarea x-model="quickMessageText" rows="3" placeholder="Type your message..." 
            class="w-full p-3 rounded-xl border border-slate-200 font-medium text-slate-800 focus:ring-2 focus:ring-blue-500"></textarea>
        </div>

        <div class="grid grid-cols-2 gap-2 pt-1">
          <button @click="modalQuickMessageOpen = false" class="py-2.5 rounded-xl border border-slate-200 text-slate-600 font-bold text-xs touch-press">
            Cancel
          </button>
          <button @click="sendQuickMessage()" class="py-2.5 rounded-xl bg-blue-600 text-white font-bold text-xs shadow-sm touch-press">
            Send Note
          </button>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: ADD / EDIT CALENDAR EVENT
         ======================================================================= -->
    <div x-show="modalEventOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalEventOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
            </div>
            <h3 class="text-sm font-extrabold text-slate-900" x-text="eventForm.id ? 'Edit Event' : 'Schedule New Event'"></h3>
          </div>
          <button @click="modalEventOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>

        <div class="space-y-3 text-xs">
          <div>
            <label class="block font-bold text-slate-700 mb-1">Event Title *</label>
            <input type="text" x-model="eventForm.title" placeholder="e.g., Client Architecture Sync" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Date *</label>
              <input type="date" x-model="eventForm.event_date" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800"/>
            </div>
            <div>
              <label class="block font-bold text-slate-700 mb-1">Category</label>
              <select x-model="eventForm.category" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 bg-white">
                <option value="Meeting">Meeting</option>
                <option value="Call">Call</option>
                <option value="Review">Review</option>
                <option value="Deadline">Deadline</option>
                <option value="General">General</option>
              </select>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Start Time</label>
              <input type="text" x-model="eventForm.event_time" placeholder="09:00 AM" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800"/>
            </div>
            <div>
              <label class="block font-bold text-slate-700 mb-1">End Time</label>
              <input type="text" x-model="eventForm.end_time" placeholder="10:00 AM" 
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800"/>
            </div>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Location / Details</label>
            <input type="text" x-model="eventForm.location" placeholder="e.g., Internal • Conference Room" 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-semibold text-slate-800 placeholder-slate-400"/>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Description / Notes</label>
            <textarea x-model="eventForm.description" rows="2" placeholder="Agenda or discussion points..." 
              class="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 font-medium text-slate-800 placeholder-slate-400"></textarea>
          </div>
        </div>

        <div class="pt-2 flex items-center gap-2">
          <button @click="modalEventOpen = false" 
            type="button"
            class="flex-1 py-2.5 rounded-xl border border-slate-200 font-bold text-xs text-slate-600 hover:bg-slate-50 transition touch-press">
            Cancel
          </button>
          <button @click="submitEventForm()" 
            type="button"
            class="flex-1 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-extrabold text-xs shadow-md shadow-blue-500/25 transition touch-press">
            Save Event
          </button>
        </div>
      </div>
    </div>

    <!-- =======================================================================
         IN-APP MODAL: EVENT ACTIONS (DELETE / EDIT / VIEW)
         ======================================================================= -->
    <div x-show="modalEventActionOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalEventActionOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 class="text-xs font-black text-slate-900 truncate" x-text="actionCalendarItem ? actionCalendarItem.title : 'Options'"></h3>
            <p class="text-[10px] text-slate-400" x-text="actionCalendarItem ? actionCalendarItem.time : ''"></p>
          </div>
          <button @click="modalEventActionOpen = false" class="text-slate-400 hover:text-slate-700 text-lg font-bold">&times;</button>
        </div>

        <div class="space-y-1 text-xs font-bold text-slate-700">
          <template x-if="actionCalendarItem && actionCalendarItem.type === 'event'">
            <button @click="deleteCalendarEvent(actionCalendarItem.id)" type="button" class="w-full py-2.5 px-3 rounded-xl hover:bg-rose-50 text-rose-600 flex items-center gap-3 text-left touch-press">
              <svg class="w-4 h-4 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              <span>Delete Event</span>
            </button>
          </template>

          <template x-if="actionCalendarItem && actionCalendarItem.type === 'task'">
            <button @click="viewTaskDetail(actionCalendarItem.taskRaw); modalEventActionOpen = false;" type="button" class="w-full py-2.5 px-3 rounded-xl hover:bg-slate-50 flex items-center gap-3 text-left touch-press">
              <svg class="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
              <span>View Task Details</span>
            </button>
          </template>

          <template x-if="actionCalendarItem && actionCalendarItem.type === 'holiday'">
            <div class="p-3 bg-rose-50 rounded-xl text-rose-700 text-xs font-medium">
              This is a gazetted public holiday.
            </div>
          </template>
        </div>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: ADD / EDIT PROJECT
         ======================================================================= -->
    <div x-show="modalProjectOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalProjectOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3 max-h-[90vh] overflow-y-auto no-scrollbar">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-bold text-slate-900" x-text="projectForm.id ? 'Edit Project' : 'New Project'"></h3>
          <button @click="modalProjectOpen = false" class="text-slate-400 font-bold text-lg">&times;</button>
        </div>
        <form @submit.prevent="submitProjectForm()" class="space-y-2.5 text-xs">
          <div>
            <label class="block text-[10px] font-bold text-slate-500 mb-1">Project Title *</label>
            <input type="text" x-model="projectForm.title" @input="onProjectTitleInput()" required placeholder="e.g. E-commerce Website" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"/>
          </div>

          <div>
            <div class="flex items-center justify-between mb-1">
              <label class="block text-[10px] font-bold text-slate-500">Associated Company</label>
              <template x-if="projectForm.auto_matched_company_name">
                <span class="text-[9px] font-bold text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded flex items-center gap-1">
                  <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                  Auto-Matched
                </span>
              </template>
              <template x-if="projectForm.manual_company_override">
                <span class="text-[9px] font-semibold text-slate-400">Manual Selection</span>
              </template>
            </div>
            <select x-model="projectForm.company_id" @change="onProjectCompanySelect()" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-medium text-slate-800">
              <option value="">-- No Company Associated --</option>
              <template x-for="c in uniqueCompanies" :key="c.id || c.name">
                <option :value="c.id" x-text="c.name"></option>
              </template>
            </select>
            <p x-show="projectForm.auto_matched_company_name" class="text-[10px] text-emerald-600 font-semibold mt-1">
              ✨ Automatically matched with company <span class="font-bold" x-text="projectForm.auto_matched_company_name"></span> based on project name.
            </p>
          </div>

          <div>
            <label class="block text-[10px] font-bold text-slate-500 mb-1">Client / Company Name *</label>
            <input type="text" x-model="projectForm.client_name" required placeholder="e.g. ABC Tech Solutions" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"/>
          </div>

          <div>
            <label class="block text-[10px] font-bold text-slate-500 mb-1">Project Description</label>
            <textarea x-model="projectForm.description" rows="3" placeholder="Describe the scope, deliverables, and architecture..." class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"></textarea>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Progress (%)</label>
              <input type="number" min="0" max="100" x-model="projectForm.progress" placeholder="70" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"/>
            </div>
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Status</label>
              <select x-model="projectForm.status" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold">
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
              </select>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Budget</label>
              <input type="text" x-model="projectForm.budget" placeholder="$12,000" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"/>
            </div>
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Project Manager</label>
              <input type="text" x-model="projectForm.project_manager" placeholder="Rahul Sharma" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl"/>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Start Date</label>
              <input type="date" x-model="projectForm.start_date" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-slate-700"/>
            </div>
            <div>
              <label class="block text-[10px] font-bold text-slate-500 mb-1">Due Date</label>
              <input type="date" x-model="projectForm.deadline" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-slate-700"/>
            </div>
          </div>

          <button type="submit" class="w-full py-2.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold touch-press transition-colors shadow-sm">
            Save Project
          </button>
        </form>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: NEW INVOICE WITH ITEMIZED CHARGES
         ======================================================================= -->
    <div x-show="modalInvoiceOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs overflow-y-auto" x-cloak>
      <div @click.away="modalInvoiceOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-md shadow-sheet space-y-4 max-h-[90vh] overflow-y-auto">
        
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 sticky top-0 bg-white z-10">
          <div class="flex items-center gap-2.5">
            <div class="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xs">INV</div>
            <div>
              <h3 class="text-sm font-black text-slate-900">New Invoice</h3>
              <p class="text-[10px] text-slate-400">Create itemized bill for client</p>
            </div>
          </div>
          <button @click="modalInvoiceOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold">&times;</button>
        </div>

        <form @submit.prevent="submitInvoiceForm()" class="space-y-3.5 text-xs">

          <!-- 1. Client & Project Row -->
          <div class="space-y-2">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Client / Company <span class="text-rose-500">*</span></label>
              <div class="grid grid-cols-1 gap-1.5">
                <select x-model="invoiceForm.client_id" @change="onInvoiceClientChange($event)" class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-semibold text-slate-800 text-xs focus:ring-2 focus:ring-blue-500">
                  <option value="">-- Select Existing Client --</option>
                  <template x-for="c in contacts" :key="c.id">
                    <option :value="c.id" x-text="c.name + (c.company ? ' (' + c.company + ')' : '')"></option>
                  </template>
                </select>
                <input type="text" x-model="invoiceForm.customer_name" required placeholder="Or enter client / company name *" 
                  class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-semibold text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500"/>
              </div>
            </div>

            <div class="grid grid-cols-2 gap-2">
              <div>
                <label class="block font-bold text-slate-700 mb-1">Associated Project</label>
                <select x-model="invoiceForm.project_id" class="w-full px-2.5 py-2 bg-slate-50 border border-slate-200 rounded-xl font-semibold text-slate-800 text-xs focus:ring-2 focus:ring-blue-500">
                  <option value="">-- None --</option>
                  <template x-for="p in projects" :key="p.id">
                    <option :value="p.id" x-text="p.title"></option>
                  </template>
                </select>
              </div>

              <div>
                <label class="block font-bold text-slate-700 mb-1">Status</label>
                <select x-model="invoiceForm.status" class="w-full px-2.5 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 text-xs">
                  <option value="Pending">Pending</option>
                  <option value="Paid">Paid</option>
                  <option value="Draft">Draft</option>
                </select>
              </div>
            </div>
          </div>

          <!-- 2. Invoice Title / Scope -->
          <div>
            <label class="block font-bold text-slate-700 mb-1">Invoice Title / Scope</label>
            <input type="text" x-model="invoiceForm.title" placeholder="e.g. Website & Mobile Platform Development" 
              class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-medium text-slate-900 focus:outline-none focus:ring-2 focus:ring-blue-500"/>
          </div>

          <!-- 3. Dates -->
          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block font-bold text-slate-700 mb-1">Issue Date</label>
              <input type="date" x-model="invoiceForm.issue_date" required class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-medium text-slate-900"/>
            </div>
            <div>
              <label class="block font-bold text-slate-700 mb-1">Due Date</label>
              <input type="date" x-model="invoiceForm.due_date" required class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl font-medium text-slate-900"/>
            </div>
          </div>

          <!-- 4. Itemized Charges Section -->
          <div class="space-y-2 pt-1 border-t border-slate-100">
            <div class="flex items-center justify-between">
              <label class="font-black text-slate-800 text-xs">Line Items</label>
              <button type="button" @click="addInvoiceLineItem()" class="text-xs font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1 touch-press">
                <span>+ Add Item</span>
              </button>
            </div>

            <div class="space-y-2">
              <template x-for="(it, idx) in invoiceForm.items" :key="idx">
                <div class="p-2.5 bg-slate-50 rounded-xl border border-slate-200/80 space-y-2 text-xs">
                  <div class="flex items-center justify-between gap-2">
                    <input type="text" x-model="it.description" required placeholder="Service or milestone description *" 
                      class="flex-1 px-2.5 py-1.5 bg-white border border-slate-200 rounded-lg font-medium text-slate-900"/>
                    <button type="button" @click="removeInvoiceLineItem(idx)" class="text-slate-400 hover:text-rose-600 p-1 text-sm font-bold" title="Remove">&times;</button>
                  </div>
                  <div class="grid grid-cols-3 gap-2 items-center">
                    <div>
                      <span class="text-[10px] text-slate-400 font-bold block">Qty</span>
                      <input type="number" step="0.5" min="0.5" x-model="it.quantity" @input="calculateInvoiceLine(it)" 
                        class="w-full px-2 py-1 bg-white border border-slate-200 rounded-lg text-center font-bold"/>
                    </div>
                    <div>
                      <span class="text-[10px] text-slate-400 font-bold block">Rate (₹)</span>
                      <input type="number" step="1" min="0" x-model="it.rate" @input="calculateInvoiceLine(it)" 
                        class="w-full px-2 py-1 bg-white border border-slate-200 rounded-lg text-right font-mono font-bold"/>
                    </div>
                    <div>
                      <span class="text-[10px] text-slate-400 font-bold block">Amount (₹)</span>
                      <div class="py-1 px-1 text-right font-black text-slate-900 font-mono truncate" x-text="formatMoney(it.amount)"></div>
                    </div>
                  </div>
                </div>
              </template>
            </div>
          </div>

          <!-- 5. Tax & Discount Row -->
          <div class="grid grid-cols-2 gap-2 pt-1">
            <div>
              <label class="block font-bold text-slate-600 mb-1 text-[11px]">Discount (%)</label>
              <input type="number" step="1" min="0" max="100" x-model="invoiceForm.discount_percent" 
                class="w-full px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-900"/>
            </div>
            <div>
              <label class="block font-bold text-slate-600 mb-1 text-[11px]">GST / Tax (%)</label>
              <input type="number" step="1" min="0" max="100" x-model="invoiceForm.tax_percent" 
                class="w-full px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-900"/>
            </div>
          </div>

          <!-- 6. Real-time Summary Box -->
          <div class="p-3 bg-blue-50/70 border border-blue-200/80 rounded-xl space-y-1.5 text-xs">
            <div class="flex justify-between text-slate-600">
              <span>Subtotal:</span>
              <span class="font-bold font-mono" x-text="formatMoney(computedInvoiceSubtotal)"></span>
            </div>
            <template x-if="Number(invoiceForm.discount_percent) > 0">
              <div class="flex justify-between text-rose-600">
                <span x-text="'Discount (' + invoiceForm.discount_percent + '%):'"></span>
                <span class="font-bold font-mono" x-text="'- ' + formatMoney(computedInvoiceDiscount)"></span>
              </div>
            </template>
            <template x-if="Number(invoiceForm.tax_percent) > 0">
              <div class="flex justify-between text-slate-700">
                <span x-text="'GST (' + invoiceForm.tax_percent + '%):'"></span>
                <span class="font-bold font-mono" x-text="formatMoney(computedInvoiceTax)"></span>
              </div>
            </template>
            <div class="flex justify-between pt-1 border-t border-blue-200/80 text-sm font-black text-blue-950">
              <span>Total Invoice Amount:</span>
              <span class="font-mono text-base" x-text="formatMoney(computedInvoiceTotal)"></span>
            </div>
          </div>

          <!-- 7. Notes & Terms -->
          <div>
            <label class="block font-bold text-slate-700 mb-1">Notes / Deliverables</label>
            <textarea x-model="invoiceForm.notes" rows="2" class="w-full px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800 leading-relaxed"></textarea>
          </div>

          <div>
            <label class="block font-bold text-slate-700 mb-1">Payment Terms</label>
            <input type="text" x-model="invoiceForm.terms" class="w-full px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-800"/>
          </div>

          <!-- Buttons -->
          <div class="pt-2 flex gap-2">
            <button type="button" @click="modalInvoiceOpen = false" class="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">Cancel</button>
            <button type="submit" :disabled="isCreatingInvoice" class="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-md shadow-blue-500/20 flex items-center justify-center gap-1.5 touch-press">
              <template x-if="isCreatingInvoice">
                <svg class="animate-spin w-3.5 h-3.5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              </template>
              <span>Save & Issue Invoice</span>
            </button>
          </div>
        </form>

      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: INVOICE ACTION MENU (3-DOTS)
         ======================================================================= -->
    <div x-show="modalInvoiceActionMenuOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalInvoiceActionMenuOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-2">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100 mb-1">
          <div>
            <h3 class="text-xs font-black text-slate-900">Invoice Actions</h3>
            <p class="text-[10px] text-slate-400 font-mono" x-text="activeInvoice ? (activeInvoice.invoice_no || activeInvoice.id) : ''"></p>
          </div>
          <button @click="modalInvoiceActionMenuOpen = false" class="text-slate-400 text-lg font-bold">&times;</button>
        </div>

        <template x-if="activeInvoice && (activeInvoice.status !== 'Paid' || Number(activeInvoice.balance_amount) > 0)">
          <button @click="modalInvoiceActionMenuOpen = false; openRecordPaymentModal(activeInvoice);" class="w-full p-2.5 text-left text-xs font-bold text-slate-800 hover:bg-slate-50 rounded-xl flex items-center gap-2.5 touch-press">
            <span class="text-blue-600">💳</span>
            <span>Record Payment</span>
          </button>
        </template>

        <button @click="modalInvoiceActionMenuOpen = false; downloadInvoicePdf(activeInvoice);" class="w-full p-2.5 text-left text-xs font-bold text-slate-800 hover:bg-slate-50 rounded-xl flex items-center gap-2.5 touch-press">
          <span class="text-blue-600">📄</span>
          <span>Download / Print PDF</span>
        </button>

        <button @click="modalInvoiceActionMenuOpen = false; shareInvoice(activeInvoice);" class="w-full p-2.5 text-left text-xs font-bold text-slate-800 hover:bg-slate-50 rounded-xl flex items-center gap-2.5 touch-press">
          <span class="text-blue-600">🔗</span>
          <span>Share Invoice</span>
        </button>

        <button @click="modalInvoiceActionMenuOpen = false; promptDeleteInvoice(activeInvoice);" class="w-full p-2.5 text-left text-xs font-bold text-rose-600 hover:bg-rose-50 rounded-xl flex items-center gap-2.5 touch-press">
          <span>🗑️</span>
          <span>Delete Invoice</span>
        </button>
      </div>
    </div>


    <!-- =======================================================================
         IN-APP MODAL: ADD INTERACTION NOTE (NO PROMPT OR ALERT)
         ======================================================================= -->
    <div x-show="modalNoteOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalNoteOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 w-full max-w-sm shadow-sheet space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <h3 class="text-xs font-bold text-slate-900">Log Interaction Note</h3>
          <button @click="modalNoteOpen = false" class="text-slate-400 font-bold">&times;</button>
        </div>
        <form @submit.prevent="submitNoteForm()" class="space-y-2.5 text-xs">
          <textarea x-model="noteInputText" required rows="3" placeholder="Enter meeting notes, follow-up, or discussion details..." class="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs"></textarea>
          <button type="submit" class="w-full py-2.5 rounded-xl bg-blue-600 text-white font-bold touch-press">Save Note</button>
        </form>
      </div>
    </div>


    <!-- =======================================================================
         NOTIFICATION SLIDE-OVER DRAWER (Desktop, Tablet & Mobile)
         ======================================================================= -->
    <div x-show="modalNotificationsOpen" 
         class="fixed inset-0 z-50 overflow-hidden" 
         x-cloak 
         role="dialog" 
         aria-modal="true" 
         aria-labelledby="notification-drawer-title">
      <!-- Backdrop with smooth fade -->
      <div x-show="modalNotificationsOpen"
           x-transition:enter="transition-opacity ease-out duration-300"
           x-transition:enter-start="opacity-0"
           x-transition:enter-end="opacity-100"
           x-transition:leave="transition-opacity ease-in duration-200"
           x-transition:leave-start="opacity-100"
           x-transition:leave-end="opacity-0"
           @click="closeNotificationsModal()" 
           class="fixed inset-0 bg-slate-900/60 backdrop-blur-xs transition-opacity"></div>

      <!-- Slide-over panel container -->
      <div class="fixed inset-y-0 right-0 max-w-full flex pl-4 sm:pl-10 pointer-events-none">
        <div x-show="modalNotificationsOpen"
             x-transition:enter="transform transition ease-in-out duration-300"
             x-transition:enter-start="translate-x-full"
             x-transition:enter-end="translate-x-0"
             x-transition:leave="transform transition ease-in-out duration-300"
             x-transition:leave-start="translate-x-0"
             x-transition:leave-end="translate-x-full"
             @click.outside="closeNotificationsModal()"
             class="w-screen max-w-md pointer-events-auto crm-notification-panel shadow-2xl flex flex-col h-full border-l border-slate-200">
          
          <!-- 1. Header -->
          <div class="p-4 sm:p-5 border-b crm-notification-header shrink-0 flex items-center justify-between gap-3">
            <div class="flex items-center gap-2.5 min-w-0">
              <div class="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0 border border-blue-100">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
              </div>
              <div>
                <div class="flex items-center gap-2">
                  <h2 id="notification-drawer-title" class="text-sm sm:text-base font-extrabold crm-notification-title tracking-tight">Notifications</h2>
                  <template x-if="unreadNotificationsCount > 0">
                    <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-rose-50 text-rose-600 border border-rose-200" x-text="unreadNotificationsCount + ' New'"></span>
                  </template>
                </div>
                <p class="text-[11px] crm-notification-time">Real-time alerts, invoices & team activities</p>
              </div>
            </div>

            <div class="flex items-center gap-1.5 shrink-0">
              <!-- Mark all as read button -->
              <button type="button" 
                      x-show="unreadNotificationsCount > 0"
                      @click="markAllNotificationsAsRead()" 
                      :disabled="isMarkingAllNotificationsRead"
                      class="px-2.5 py-1.5 rounded-lg crm-notification-action-btn text-xs font-bold transition-colors flex items-center gap-1 touch-press disabled:opacity-50"
                      title="Mark all as read">
                <template x-if="isMarkingAllNotificationsRead">
                  <svg class="animate-spin w-3 h-3 text-blue-600" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                </template>
                <template x-if="!isMarkingAllNotificationsRead">
                  <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7m-14 6l4 4L19 7"/></svg>
                </template>
                <span class="hidden sm:inline">Mark all read</span>
              </button>

              <!-- Close button -->
              <button type="button" 
                      @click="closeNotificationsModal()" 
                      class="w-8 h-8 rounded-full flex items-center justify-center crm-notification-time hover:text-slate-700 hover:bg-slate-100 touch-press transition-colors"
                      title="Close notifications">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>
          </div>

          <!-- 2. Category Filter Tabs (Horizontally scrollable) -->
          <div class="px-4 py-2 crm-notification-header border-b overflow-x-auto no-scrollbar flex items-center gap-1.5 shrink-0">
            <!-- All Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('all')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'all' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>All</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'all' ? 'bg-blue-700 text-white' : 'crm-notification-action-btn'"
                    x-text="notificationsCounts.all || 0"></span>
            </button>

            <!-- Unread Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('unread')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'unread' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>Unread</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'unread' ? 'bg-blue-700 text-white' : (notificationsCounts.unread > 0 ? 'bg-rose-100 text-rose-700 font-bold' : 'crm-notification-action-btn')"
                    x-text="notificationsCounts.unread || 0"></span>
            </button>

            <!-- Invoices Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('invoices')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'invoices' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>Invoices</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'invoices' ? 'bg-blue-700 text-white' : 'crm-notification-action-btn'"
                    x-text="notificationsCounts.invoices || 0"></span>
            </button>

            <!-- Clients Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('clients')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'clients' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>Clients</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'clients' ? 'bg-blue-700 text-white' : 'crm-notification-action-btn'"
                    x-text="notificationsCounts.clients || 0"></span>
            </button>

            <!-- Tasks Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('tasks')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'tasks' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>Tasks</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'tasks' ? 'bg-blue-700 text-white' : 'crm-notification-action-btn'"
                    x-text="notificationsCounts.tasks || 0"></span>
            </button>

            <!-- System Alerts Tab -->
            <button type="button" 
                    @click="setNotificationsFilter('system')"
                    class="px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-1.5 touch-press"
                    :class="notificationsFilter === 'system' ? 'bg-blue-600 text-white shadow-xs' : 'crm-notification-tab-inactive'">
              <span>System Alerts</span>
              <span class="text-[10px] px-1.5 py-0.2 rounded-full font-mono"
                    :class="notificationsFilter === 'system' ? 'bg-blue-700 text-white' : 'crm-notification-action-btn'"
                    x-text="notificationsCounts.system || 0"></span>
            </button>
          </div>

          <!-- 3. Cards Body -->
          <div class="flex-1 overflow-y-auto p-4 space-y-3 no-scrollbar crm-notification-body">
            
            <!-- Loading State (Skeleton pulse cards) -->
            <template x-if="notificationsLoading">
              <div class="space-y-3">
                <template x-for="i in [1, 2, 3, 4]" :key="i">
                  <div class="crm-notification-card rounded-2xl p-3.5 space-y-3 animate-pulse">
                    <div class="flex items-start gap-3">
                      <div class="w-10 h-10 rounded-xl bg-slate-200 dark:bg-slate-700 shrink-0"></div>
                      <div class="flex-1 space-y-2">
                        <div class="h-3.5 bg-slate-200 dark:bg-slate-700 rounded w-3/4"></div>
                        <div class="h-3 bg-slate-100 dark:bg-slate-800 rounded w-full"></div>
                        <div class="h-2.5 bg-slate-100 dark:bg-slate-800 rounded w-1/3"></div>
                      </div>
                    </div>
                  </div>
                </template>
              </div>
            </template>

            <!-- Error State -->
            <template x-if="!notificationsLoading && notificationsError">
              <div class="p-4 rounded-2xl bg-rose-50 border border-rose-200 text-center space-y-3 my-4">
                <div class="w-10 h-10 rounded-full bg-rose-100 text-rose-600 flex items-center justify-center mx-auto">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                </div>
                <div>
                  <p class="text-xs font-bold text-rose-900" x-text="notificationsError"></p>
                  <p class="text-[11px] text-rose-600 mt-0.5">Please check your connection and try again.</p>
                </div>
                <button type="button" @click="loadNotifications()" class="px-3 py-1.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs touch-press transition-colors">
                  Retry Loading
                </button>
              </div>
            </template>

            <!-- Empty State -->
            <template x-if="!notificationsLoading && !notificationsError && notifications.length === 0">
              <div class="py-12 px-4 text-center space-y-3">
                <div class="w-14 h-14 rounded-2xl bg-blue-50 text-blue-500 flex items-center justify-center mx-auto border border-blue-100">
                  <svg class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
                </div>
                <div>
                  <h4 class="text-xs sm:text-sm font-bold crm-notification-title">No notifications found</h4>
                  <p class="text-xs crm-notification-time mt-1 max-w-xs mx-auto">You are completely caught up! We'll notify you as new invoices, clients, tasks, and system activities occur.</p>
                </div>
              </div>
            </template>

            <!-- Notifications Cards List -->
            <template x-if="!notificationsLoading && !notificationsError && notifications.length > 0">
              <div class="space-y-2.5">
                <template x-for="item in notifications" :key="item.id">
                  <div @click="handleNotificationClick(item)"
                       class="crm-notification-card relative p-3.5 rounded-2xl transition-all cursor-pointer group touch-press"
                       :class="!item.is_read ? 'is-unread' : 'is-read'">
                    
                    <!-- Unread indicator dot -->
                    <template x-if="!item.is_read">
                      <span class="absolute top-3 right-3 w-2.5 h-2.5 rounded-full bg-blue-600 ring-2 ring-blue-100"></span>
                    </template>

                    <div class="flex items-start gap-3">
                      <!-- Category Icon Container -->
                      <div class="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border"
                           :class="'crm-icon-' + (item.category || 'system')">
                        <!-- Invoices Icon -->
                        <template x-if="item.category === 'invoices'">
                          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 14l6-6m-5.5.5h.01m4.99 5h.01M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16l3.5-2 3.5 2 3.5-2 3.5 2zM10 8.5a.5.5 0 11-1 0 .5.5 0 011 0zm5 5a.5.5 0 11-1 0 .5.5 0 011 0z"/></svg>
                        </template>
                        <!-- Clients Icon -->
                        <template x-if="item.category === 'clients'">
                          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                        </template>
                        <!-- Tasks Icon -->
                        <template x-if="item.category === 'tasks'">
                          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
                        </template>
                        <!-- System Icon -->
                        <template x-if="item.category === 'system'">
                          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
                        </template>
                      </div>

                      <!-- Content Column -->
                      <div class="flex-1 min-w-0 pr-4">
                        <div class="flex items-center gap-1.5 flex-wrap">
                          <h4 class="text-xs font-bold crm-notification-title group-hover:text-blue-500 transition-colors" x-text="item.title"></h4>
                          <span class="text-[9px] uppercase tracking-wider font-extrabold px-1.5 py-0.5 rounded"
                                :class="'crm-badge-' + (item.category || 'system')"
                                x-text="item.category"></span>
                        </div>

                        <p class="text-xs crm-notification-desc mt-1 leading-relaxed" x-text="item.message"></p>

                        <div class="flex items-center justify-between gap-2 mt-2.5 pt-1.5 border-t crm-notification-divider">
                          <!-- Timestamp -->
                          <div class="flex items-center gap-1 text-[11px] crm-notification-time">
                            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                            <span x-text="item.time_ago || item.formatted_date"></span>
                          </div>

                          <!-- Card Action Controls -->
                          <div class="flex items-center gap-1.5">
                            <!-- Action Pill Button -->
                            <template x-if="item.action_label">
                              <button type="button" 
                                      @click.stop="handleNotificationClick(item)"
                                      class="crm-notification-action-btn px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all flex items-center gap-1 touch-press">
                                <span x-text="item.action_label"></span>
                                <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                              </button>
                            </template>

                            <!-- Mark as Read Icon Button (only if unread) -->
                            <template x-if="!item.is_read">
                              <button type="button" 
                                      @click.stop="markNotificationAsRead(item.id, $event)"
                                      class="p-1 rounded-lg crm-notification-time hover:text-blue-600 hover:bg-blue-50 transition-colors touch-press"
                                      title="Mark as read">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                              </button>
                            </template>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </template>
              </div>
            </template>
          </div>

          <!-- 4. Footer -->
          <div class="p-3 crm-notification-footer border-t shrink-0 flex items-center justify-between text-[11px] crm-notification-time">
            <div class="flex items-center gap-1.5">
              <span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span>Synced live with CRM database</span>
            </div>
            <button type="button" @click="loadNotifications()" class="text-blue-600 hover:text-blue-700 font-bold hover:underline touch-press">
              Refresh
            </button>
          </div>
        </div>
      </div>
    </div>


    <!-- =========================================================================
         MODAL: ADD / EDIT COMPANY
         ========================================================================= -->
    <div x-show="modalCompanyFormOpen" class="fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalCompanyFormOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-md shadow-sheet space-y-4 max-h-[90vh] flex flex-col">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 shrink-0">
          <div>
            <h3 class="text-base font-extrabold text-slate-900" x-text="companyFormMode === 'create' ? 'Add New Company' : 'Edit Company'"></h3>
            <p class="text-[11px] text-slate-400">Company profile & business information</p>
          </div>
          <button @click="modalCompanyFormOpen = false" class="p-1.5 text-slate-400 hover:text-slate-600 rounded-xl touch-press">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <!-- Form Body -->
        <form @submit.prevent="saveCompanyForm()" class="overflow-y-auto space-y-3.5 pr-1 flex-1">
          <!-- Error Alert -->
          <div x-show="companyFormError" class="p-2.5 bg-rose-50 border border-rose-200 rounded-xl text-rose-700 text-xs font-semibold flex items-center gap-2">
            <svg class="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <span x-text="companyFormError"></span>
          </div>

          <!-- Company Name (Required) -->
          <div class="space-y-1">
            <label class="text-[11px] font-bold text-slate-700">Company Name <span class="text-rose-500">*</span></label>
            <input type="text" x-model="companyForm.name" required placeholder="e.g. Acme Corporation" 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
          </div>

          <!-- Industry -->
          <div class="space-y-1">
            <label class="text-[11px] font-bold text-slate-700">Industry</label>
            <input type="text" x-model="companyForm.industry" placeholder="e.g. Technology, Finance, Healthcare" 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
          </div>

          <!-- Website -->
          <div class="space-y-1">
            <label class="text-[11px] font-bold text-slate-700">Website</label>
            <input type="text" x-model="companyForm.website" placeholder="e.g. https://example.com" 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
          </div>

          <!-- Email & Phone Row -->
          <div class="grid grid-cols-2 gap-2">
            <div class="space-y-1">
              <label class="text-[11px] font-bold text-slate-700">Email</label>
              <input type="email" x-model="companyForm.email" placeholder="contact@company.com" 
                class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
            </div>
            <div class="space-y-1">
              <label class="text-[11px] font-bold text-slate-700">Phone</label>
              <input type="tel" x-model="companyForm.phone" placeholder="+91 98765 43210" 
                class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
            </div>
          </div>

          <!-- Address -->
          <div class="space-y-1">
            <label class="text-[11px] font-bold text-slate-700">Address / Location</label>
            <input type="text" x-model="companyForm.address" placeholder="e.g. Mumbai, Maharashtra, India" 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
          </div>

          <!-- Description / Notes -->
          <div class="space-y-1">
            <label class="text-[11px] font-bold text-slate-700">Description / Notes</label>
            <textarea x-model="companyForm.description" rows="2" placeholder="Brief details about the company..." 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-900 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition resize-none"></textarea>
          </div>

          <!-- Action Buttons -->
          <div class="pt-2 flex items-center justify-end gap-2 shrink-0">
            <button type="button" @click="modalCompanyFormOpen = false" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Cancel
            </button>
            <button type="submit" :disabled="isSavingCompany" class="px-5 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center gap-2 touch-press">
              <svg x-show="isSavingCompany" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
              <span x-text="companyFormMode === 'create' ? 'Create Company' : 'Save Changes'"></span>
            </button>
          </div>
        </form>

      </div>
    </div>

    <!-- =========================================================================
         MODAL: CONFIRM DELETE COMPANY
         ========================================================================= -->
    <!-- =======================================================================
         MODALS: EXPENSE MANAGEMENT & PAYMENT DETAILS
         ======================================================================= -->

    <!-- 1. ADD / EDIT EXPENSE MODAL -->
    <div x-show="modalExpenseOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalExpenseOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm sm:max-w-md shadow-2xl space-y-4 max-h-[92vh] overflow-y-auto no-scrollbar relative animate-in fade-in slide-in-from-bottom duration-200">
        
        <div class="flex items-center justify-between pb-3 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-8 h-8 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center font-bold text-xs">₹</div>
            <h3 class="text-sm font-extrabold text-slate-900" x-text="expenseForm.id ? 'Edit Operating Expense' : 'Record New Expense'"></h3>
          </div>
          <button type="button" @click="modalExpenseOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold">&times;</button>
        </div>

        <form @submit.prevent="submitExpenseForm()" class="space-y-3.5 text-xs">
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Expense Date *</label>
            <input type="date" x-model="expenseForm.expense_date" required 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Expense Category *</label>
            <select x-model="expenseForm.category" required 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
              <option value="Cloud & Infrastructure">Cloud & Infrastructure (AWS, Servers, Hosting)</option>
              <option value="Software & Tools">Software & Tools (GitHub, Figma, SaaS)</option>
              <option value="Office & Utilities">Office & Utilities (Rent, Internet, Electricity)</option>
              <option value="Salaries & Contractors">Salaries & Contractors (Payroll, Freelancers)</option>
              <option value="Marketing & Sales">Marketing & Sales (Ads, Google Workspace, CRM)</option>
              <option value="Travel & Entertainment">Travel & Entertainment</option>
              <option value="Other">Other Operating Expense</option>
            </select>
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Description / Vendor *</label>
            <input type="text" x-model="expenseForm.description" required placeholder="e.g. AWS Cloud Cluster, Office Internet Leased Line..." 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Amount (₹) *</label>
            <input type="number" step="0.01" min="0.01" x-model="expenseForm.amount" required placeholder="0.00" 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs text-slate-800 font-bold font-mono focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500">
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Payment Method</label>
              <select x-model="expenseForm.payment_method" 
                class="w-full bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-xs text-slate-800 focus:outline-none">
                <option value="Bank Transfer">Bank Transfer</option>
                <option value="Company Card">Company Card</option>
                <option value="Credit Card">Credit Card</option>
                <option value="UPI">UPI</option>
                <option value="Cash">Cash</option>
              </select>
            </div>
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Reference / Receipt #</label>
              <input type="text" x-model="expenseForm.reference" placeholder="e.g. INV-9928, TXN..." 
                class="w-full bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-xs text-slate-800 focus:outline-none">
            </div>
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Notes (Optional)</label>
            <textarea x-model="expenseForm.notes" rows="2" placeholder="Deliverables or purpose of expense..." 
              class="w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 text-xs text-slate-800 focus:outline-none"></textarea>
          </div>

          <div class="flex items-center gap-2 pt-2 border-t border-slate-100">
            <button type="submit" :disabled="isSavingExpense" 
              class="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-xs shadow-xs touch-press transition flex items-center justify-center gap-1.5">
              <svg x-show="isSavingExpense" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              <span x-text="expenseForm.id ? 'Save Changes' : 'Record Expense'"></span>
            </button>
            <button type="button" @click="modalExpenseOpen = false" 
              class="py-2.5 px-4 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs transition">
              Cancel
            </button>
          </div>
        </form>

      </div>
    </div>

    <!-- 2. DELETE EXPENSE CONFIRMATION MODAL -->
    <div x-show="modalDeleteExpenseOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalDeleteExpenseOpen = false" class="bg-white rounded-2xl border border-slate-200 p-5 w-full max-w-sm shadow-xl space-y-3">
        <div class="w-10 h-10 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div class="text-center">
          <h4 class="text-sm font-extrabold text-slate-900">Delete Operating Expense?</h4>
          <p class="text-xs text-slate-500 mt-1">
            Are you sure you want to delete <strong class="text-slate-800" x-text="expenseToDelete?.description"></strong> (<span class="font-bold text-rose-600" x-text="formatMoney(expenseToDelete?.amount)"></span>)?
          </p>
        </div>
        <div class="flex items-center gap-2 pt-2">
          <button type="button" @click="executeDeleteExpense()" :disabled="isDeletingExpense" 
            class="flex-1 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold text-xs shadow-xs touch-press transition">
            <span x-text="isDeletingExpense ? 'Deleting...' : 'Delete Expense'"></span>
          </button>
          <button type="button" @click="modalDeleteExpenseOpen = false" 
            class="py-2 px-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs">
            Cancel
          </button>
        </div>
      </div>
    </div>

    <!-- 3. PAYMENT DETAIL MODAL -->
    <div x-show="modalPaymentDetailOpen" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalPaymentDetailOpen = false" class="bg-white rounded-t-3xl sm:rounded-3xl border border-slate-200 p-5 sm:p-6 w-full max-w-sm sm:max-w-md shadow-2xl space-y-4 max-h-[92vh] overflow-y-auto no-scrollbar relative animate-in fade-in slide-in-from-bottom duration-200">
        
        <div class="flex items-center justify-between pb-3 border-b border-slate-100">
          <div class="flex items-center gap-2.5">
            <div class="w-9 h-9 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center font-black text-xs">REC</div>
            <div>
              <h3 class="text-sm font-black text-slate-900" x-text="activePaymentDetail?.receipt_no || 'Payment Details'"></h3>
              <p class="text-[10px] text-slate-400 font-mono" x-text="'Invoice: ' + (activePaymentDetail?.invoice_no || '-')"></p>
            </div>
          </div>
          <button type="button" @click="modalPaymentDetailOpen = false" class="text-slate-400 hover:text-slate-700 text-xl font-bold">&times;</button>
        </div>

        <div class="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2.5 text-xs">
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Client Name</span>
            <span class="font-bold text-slate-900" x-text="activePaymentDetail?.customer_name || '-'"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Payment Date</span>
            <span class="font-bold text-slate-800" x-text="activePaymentDetail?.payment_date || '-'"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Payment Method</span>
            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200/80 text-slate-800" x-text="activePaymentDetail?.payment_method || '-'"></span>
          </div>
          <div class="flex justify-between items-center">
            <span class="text-slate-400 font-semibold">Transaction Reference</span>
            <span class="font-mono text-slate-700" x-text="activePaymentDetail?.transaction_id || (activePaymentDetail?.reference || '-')"></span>
          </div>
          <div class="flex justify-between items-center pt-2 border-t border-slate-200 text-sm">
            <span class="font-extrabold text-slate-700">Amount Received</span>
            <span class="font-black text-emerald-600 font-mono text-base" x-text="formatMoney(activePaymentDetail?.amount)"></span>
          </div>
        </div>

        <template x-if="activePaymentDetail?.notes">
          <div class="p-3 bg-blue-50/50 rounded-xl border border-blue-100 text-xs">
            <span class="font-bold text-blue-900 block mb-0.5">Notes:</span>
            <span class="text-blue-700" x-text="activePaymentDetail.notes"></span>
          </div>
        </template>

        <div class="flex items-center gap-2 pt-1">
          <a :href="'api/ledger.php?action=print_receipt&receipt_no=' + encodeURIComponent(activePaymentDetail?.receipt_no || activePaymentDetail?.id)" target="_blank" 
            class="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-xs shadow-xs text-center flex items-center justify-center gap-1.5 touch-press">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"/></svg>
            <span>Print Receipt</span>
          </a>
          <button type="button" @click="modalPaymentDetailOpen = false" 
            class="py-2.5 px-4 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs">
            Close
          </button>
        </div>

      </div>
    </div>


    <div x-show="modalConfirmDeleteCompanyOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteCompanyOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-sheet space-y-4 text-center">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div>
          <h3 class="text-base font-extrabold text-slate-900">Delete Company?</h3>
          <p class="text-xs text-slate-500 mt-1">
            Are you sure you want to delete <span class="font-bold text-slate-800" x-text="companyToDelete ? companyToDelete.name : 'this company'"></span>?
          </p>
          <div class="p-2.5 mt-2 bg-amber-50 border border-amber-200 rounded-xl text-[11px] text-amber-800 text-left">
            <span class="font-bold">Safety Note:</span> Any associated contacts will remain intact in your CRM and will be unlinked safely.
          </div>
        </div>
        <div class="grid grid-cols-2 gap-2 pt-2">
          <button type="button" @click="modalConfirmDeleteCompanyOpen = false" class="w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
            Cancel
          </button>
          <button type="button" @click="confirmDeleteCompany()" :disabled="isDeletingCompany" class="w-full py-2.5 bg-rose-600 hover:bg-rose-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
            <svg x-show="isDeletingCompany" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            <span>Delete</span>
          </button>
        </div>
      </div>
    </div>

    <!-- =========================================================================
         MODAL: CONFIRM REMOVE BIOMETRIC DEVICE
         ========================================================================= -->
    <div x-show="modalConfirmRemoveDeviceOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmRemoveDeviceOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-sheet space-y-4 text-center">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div>
          <h3 class="text-base font-extrabold text-slate-900">Remove Biometric Device?</h3>
          <p class="text-xs text-slate-500 mt-1">
            Are you sure you want to remove <span class="font-bold text-slate-800" x-text="deviceToRemove ? deviceToRemove.device_name : 'this device'"></span>?
          </p>
          <div class="p-2.5 mt-2 bg-amber-50 border border-amber-200 rounded-xl text-[11px] text-amber-800 text-left">
            <span class="font-bold">Security Note:</span> You will no longer be able to use fingerprint or Face ID on this device to sign in until you register it again.
          </div>
        </div>
        <div class="grid grid-cols-2 gap-2 pt-2">
          <button type="button" @click="modalConfirmRemoveDeviceOpen = false" class="w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
            Cancel
          </button>
          <button type="button" @click="confirmRemoveDevice()" :disabled="isRemovingDevice" class="w-full py-2.5 bg-rose-600 hover:bg-rose-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
            <svg x-show="isRemovingDevice" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            <span>Remove</span>
          </button>
        </div>
      </div>
    </div>

    <!-- =========================================================================
         MODAL: CONFIRM DISABLE ALL BIOMETRICS
         ========================================================================= -->
    <div x-show="modalConfirmDisableAllBiometricsOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDisableAllBiometricsOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-sheet space-y-4 text-center">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
        </div>
        <div>
          <h3 class="text-base font-extrabold text-slate-900">Disable Biometrics?</h3>
          <p class="text-xs text-slate-500 mt-1">
            This will revoke all registered fingerprint and Face ID credentials across all your mobile phones and computers.
          </p>
          <div class="p-2.5 mt-2 bg-rose-50 border border-rose-200 rounded-xl text-[11px] text-rose-800 text-left">
            <span class="font-bold">Important:</span> You will still be able to sign in using your standard email, password, and OTP.
          </div>
        </div>
        <div class="grid grid-cols-2 gap-2 pt-2">
          <button type="button" @click="modalConfirmDisableAllBiometricsOpen = false" class="w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
            Cancel
          </button>
          <button type="button" @click="confirmDisableAllBiometrics()" :disabled="isDisablingAllBiometrics" class="w-full py-2.5 bg-rose-600 hover:bg-rose-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
            <svg x-show="isDisablingAllBiometrics" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            <span>Disable All</span>
          </button>
        </div>
      </div>
    </div>

    <!-- =========================================================================
         MODAL: EDIT EMPLOYEE PROFILE
         ========================================================================= -->
    <div x-show="modalEditProfileOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalEditProfileOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-md shadow-sheet space-y-4 text-left">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
            </div>
            <div>
              <h3 class="text-sm font-extrabold text-slate-900">Edit Profile</h3>
              <p class="text-[10px] text-slate-400">Update employee details</p>
            </div>
          </div>
          <button type="button" @click="modalEditProfileOpen = false" class="text-slate-400 hover:text-slate-600 p-1">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <form @submit.prevent="saveProfile()" class="space-y-3 text-xs">
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Full Name *</label>
            <input type="text" x-model="editProfileForm.name" required
              class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Phone Number</label>
              <input type="text" x-model="editProfileForm.phone" placeholder="+91 98765 43210"
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
            </div>
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Department</label>
              <input type="text" x-model="editProfileForm.department" placeholder="Engineering"
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
            </div>
          </div>

          <div class="grid grid-cols-2 gap-2">
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Company</label>
              <input type="text" x-model="editProfileForm.company" placeholder="ABC Tech Solutions"
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
            </div>
            <div>
              <label class="block text-[11px] font-bold text-slate-700 mb-1">Location</label>
              <input type="text" x-model="editProfileForm.location" placeholder="Bangalore, India"
                class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
            </div>
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Bio / Notes</label>
            <textarea x-model="editProfileForm.bio" rows="2" placeholder="Brief professional summary..."
              class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800 resize-none"></textarea>
          </div>

          <div class="grid grid-cols-2 gap-2 pt-2">
            <button type="button" @click="modalEditProfileOpen = false" class="w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Cancel
            </button>
            <button type="submit" :disabled="isUpdatingProfile" class="w-full py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
              <svg x-show="isUpdatingProfile" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
              <span>Save Changes</span>
            </button>
          </div>
        </form>
      </div>
    </div>

    <!-- =========================================================================
         MODAL: CHANGE PASSWORD
         ========================================================================= -->
    <div x-show="modalChangePasswordOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalChangePasswordOpen = false" class="bg-white rounded-3xl border border-slate-200 p-6 w-full max-w-sm shadow-sheet space-y-4 text-left">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <div class="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
            <div>
              <h3 class="text-sm font-extrabold text-slate-900">Change Password</h3>
              <p class="text-[10px] text-slate-400">Update security credentials</p>
            </div>
          </div>
          <button type="button" @click="modalChangePasswordOpen = false" class="text-slate-400 hover:text-slate-600 p-1">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <form @submit.prevent="savePassword()" class="space-y-3 text-xs">
          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Current Password *</label>
            <input type="password" x-model="changePasswordForm.current_password" required placeholder="••••••••"
              class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">New Password (min 8 chars) *</label>
            <input type="password" x-model="changePasswordForm.new_password" required minlength="8" placeholder="••••••••"
              class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
          </div>

          <div>
            <label class="block text-[11px] font-bold text-slate-700 mb-1">Confirm New Password *</label>
            <input type="password" x-model="changePasswordForm.confirm_password" required minlength="8" placeholder="••••••••"
              class="w-full px-3 py-2 rounded-xl border border-slate-200 focus:border-blue-600 focus:outline-none text-xs text-slate-800" />
          </div>

          <div class="grid grid-cols-2 gap-2 pt-2">
            <button type="button" @click="modalChangePasswordOpen = false" class="w-full py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl touch-press">
              Cancel
            </button>
            <button type="submit" :disabled="isChangingPassword" class="w-full py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold text-xs rounded-xl shadow-xs flex items-center justify-center gap-1.5 touch-press">
              <svg x-show="isChangingPassword" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
              <span>Update Password</span>
            </button>
          </div>
        </form>
      </div>
    </div>


    <!-- =========================================================================
         MODAL / DRAWER: TEAM CHATS & GROUP CONVERSATIONS
         ========================================================================= -->
    <div x-show="modalTeamChatOpen" class="fixed inset-0 z-50 flex items-center justify-center p-2 sm:p-4 md:p-6 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="closeGroupChat()" class="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col md:flex-row overflow-hidden relative animate-in fade-in zoom-in-95 duration-200">
        
        <!-- Channels Sidebar (Desktop & Tablet always visible, scrollable on mobile) -->
        <div class="w-full md:w-80 border-b md:border-b-0 md:border-r border-slate-200 dark:border-slate-800 flex flex-col bg-slate-50/70 dark:bg-slate-900/80 shrink-0 h-48 md:h-full">
          
          <!-- Sidebar Header -->
          <div class="p-4 border-b border-slate-200/80 dark:border-slate-800">
            <div class="flex items-center justify-between mb-3">
              <div class="flex items-center gap-2">
                <div class="w-8 h-8 rounded-xl bg-blue-600 text-white flex items-center justify-center shadow-xs">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                </div>
                <div>
                  <h3 class="text-sm font-black text-slate-900 dark:text-slate-100">Team Chats</h3>
                  <p class="text-[10px] text-slate-400">Real-time team messaging & calls</p>
                </div>
              </div>
            </div>

            <!-- Search Chats Input -->
            <div class="relative">
              <input type="text" x-model="chatSearchQuery" placeholder="Search Chats..." 
                class="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700/80 rounded-xl pl-8 pr-3 py-1.5 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
              <svg class="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            </div>

            <!-- Filters: All, Groups, Projects -->
            <div class="flex items-center gap-1 mt-2.5 bg-slate-200/60 dark:bg-slate-800 p-1 rounded-xl text-[11px] font-bold">
              <button @click="chatChannelFilter = 'All'" 
                :class="chatChannelFilter === 'All' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-xs' : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'" 
                class="flex-1 py-1 rounded-lg text-center transition">All</button>
              <button @click="chatChannelFilter = 'Groups'" 
                :class="chatChannelFilter === 'Groups' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-xs' : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'" 
                class="flex-1 py-1 rounded-lg text-center transition">Groups</button>
              <button @click="chatChannelFilter = 'Projects'" 
                :class="chatChannelFilter === 'Projects' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-xs' : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'" 
                class="flex-1 py-1 rounded-lg text-center transition">Projects</button>
            </div>
          </div>

          <!-- Channels List -->
          <div class="flex-1 overflow-y-auto p-2 space-y-1">
            <template x-for="c in filteredChatChannels" :key="c.id">
              <button @click="selectChatChannel(c)" 
                class="w-full text-left p-2.5 rounded-xl transition flex items-center gap-3 touch-press"
                :class="activeChatGroup && activeChatGroup.id === c.id ? 'bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 font-bold border border-blue-200/60 dark:border-blue-900/40' : 'hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300'">
                <div class="w-9 h-9 rounded-xl flex items-center justify-center font-bold text-xs shrink-0 text-white shadow-xs"
                  :style="'background-color: ' + (c.color || '#590907')">
                  <span x-text="c.name.substring(0, 2).toUpperCase()"></span>
                </div>
                <div class="flex-1 min-w-0">
                  <div class="flex items-center justify-between">
                    <span class="text-xs truncate font-bold" x-text="c.name"></span>
                    <span class="text-[9px] uppercase tracking-wider font-extrabold px-1.5 py-0.5 rounded bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300" x-text="c.channel_type"></span>
                  </div>
                  <p class="text-[10px] text-slate-400 truncate mt-0.5" x-text="c.description || (c.member_count + ' members')"></p>
                </div>
              </button>
            </template>
          </div>

        </div>

        <!-- Main Conversation Area -->
        <div class="flex-1 flex flex-col h-full bg-white dark:bg-slate-900 min-w-0">
          
          <!-- Conversation Header -->
          <div class="px-5 py-3 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between gap-3 bg-slate-50/40 dark:bg-slate-900/40 shrink-0">
            <div class="flex items-center gap-3 min-w-0">
              <div class="w-10 h-10 rounded-2xl flex items-center justify-center font-bold text-white shadow-xs shrink-0"
                :style="'background-color: ' + (activeChatGroup?.color || '#590907')">
                <span x-text="(activeChatGroup?.name || 'GC').substring(0, 2).toUpperCase()"></span>
              </div>
              <div class="min-w-0">
                <div class="flex items-center gap-2">
                  <h3 class="text-xs sm:text-sm font-black text-slate-900 dark:text-slate-100 truncate" x-text="activeChatGroup?.name || 'Select Conversation'"></h3>
                  <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800">
                    Live
                  </span>
                </div>
                <p class="text-[10px] text-slate-400 truncate mt-0.5" x-text="(activeChatGroup?.member_count || 0) + ' members • ' + (activeChatGroup?.description || 'Team Conversation')"></p>
              </div>
            </div>

            <!-- Call & Action Controls -->
            <div class="flex items-center gap-1.5 sm:gap-2 shrink-0">
              <!-- Audio Call Button -->
              <button @click="startGroupCall('audio')" 
                class="px-2.5 sm:px-3 py-1.5 bg-emerald-50 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-800 hover:bg-emerald-100 dark:hover:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300 rounded-xl text-xs font-bold flex items-center gap-1.5 transition touch-press"
                title="Start Group Audio Call">
                <svg class="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                <span class="hidden sm:inline">Audio</span>
              </button>

              <!-- Video Call Button -->
              <button @click="startGroupCall('video')" 
                class="px-2.5 sm:px-3 py-1.5 bg-blue-50 dark:bg-blue-950/40 border border-blue-200 dark:border-blue-800 hover:bg-blue-100 dark:hover:bg-blue-900/50 text-blue-700 dark:text-blue-300 rounded-xl text-xs font-bold flex items-center gap-1.5 transition touch-press"
                title="Start Group Video Call">
                <svg class="w-3.5 h-3.5 text-blue-600 dark:text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
                <span class="hidden sm:inline">Video</span>
              </button>

              <!-- Close Chat Drawer -->
              <button @click="closeGroupChat()" class="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-xl touch-press ml-1">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>
          </div>

          <!-- Messages Stream Container -->
          <div id="chatMessagesContainer" class="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50/30 dark:bg-slate-900/30 relative">
            
            <!-- Empty State -->
            <template x-if="chatMessages.length === 0">
              <div class="py-16 text-center space-y-2">
                <div class="w-12 h-12 rounded-2xl bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center mx-auto">
                  <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/></svg>
                </div>
                <h4 class="text-xs font-bold text-slate-800 dark:text-slate-200">No messages in this channel yet</h4>
                <p class="text-[11px] text-slate-400">Say hello to kick off team communication!</p>
              </div>
            </template>

            <!-- Message Stream -->
            <template x-for="m in chatMessages" :key="m.id">
              <div class="flex flex-col" :class="m.is_own ? 'items-end' : 'items-start'">
                
                <div class="flex items-start gap-2 max-w-[85%] sm:max-w-[75%]" :class="m.is_own ? 'flex-row-reverse' : 'flex-row'">
                  
                  <!-- Avatar -->
                  <div class="w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-bold text-white shrink-0 mt-1 shadow-xs"
                    :class="m.is_own ? 'bg-blue-600' : 'bg-slate-600'">
                    <span x-text="(m.user_name || 'U').substring(0, 2).toUpperCase()"></span>
                  </div>

                  <!-- Bubble Body Container -->
                  <div class="relative group">
                    <div class="rounded-2xl px-3.5 py-2.5 shadow-xs text-xs relative transition-all"
                      :class="m.is_own ? 'bg-blue-600 text-white rounded-tr-xs' : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 border border-slate-200/80 dark:border-slate-700/80 rounded-tl-xs'">
                      
                      <!-- Sender Info Row (For others' messages) -->
                      <div x-show="!m.is_own" class="flex items-center gap-2 mb-1">
                        <span class="font-extrabold text-[11px] text-blue-600 dark:text-blue-400" x-text="m.user_name"></span>
                        <span class="text-[9px] px-1 rounded bg-slate-100 dark:bg-slate-700 text-slate-500" x-text="m.user_role || 'Member'"></span>
                      </div>

                      <!-- Reply Reference Box -->
                      <template x-if="m.reply_to_text">
                        <div class="mb-2 p-1.5 rounded-lg border-l-3 text-[10px] opacity-90 truncate"
                          :class="m.is_own ? 'bg-blue-700/60 border-white text-blue-100' : 'bg-slate-100 dark:bg-slate-700/60 border-blue-500 text-slate-600 dark:text-slate-300'">
                          <span class="font-bold mr-1" x-text="m.reply_to_name ? m.reply_to_name + ':' : 'Replying:'"></span>
                          <span x-text="m.reply_to_text"></span>
                        </div>
                      </template>

                      <!-- Message Text -->
                      <div>
                        <!-- Unsent Message State -->
                        <template x-if="m.deletion_state === 'unsent'">
                          <div class="italic text-[11px] opacity-75 flex items-center gap-1">
                            <svg class="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636"/></svg>
                            <span>This message was unsent.</span>
                          </div>
                        </template>

                        <!-- Deleted for Everyone State -->
                        <template x-if="m.deletion_state === 'deleted_everyone'">
                          <div class="italic text-[11px] opacity-75 flex items-center gap-1">
                            <svg class="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                            <span>This message was deleted.</span>
                          </div>
                        </template>

                        <!-- Normal Message Content -->
                        <template x-if="m.deletion_state === 'none'">
                          <div>
                            <span class="whitespace-pre-wrap leading-relaxed select-text" x-text="m.message"></span>
                            <span x-show="m.edited_at" class="text-[9px] opacity-70 ml-1.5 font-sans">(edited)</span>
                          </div>
                        </template>
                      </div>

                      <!-- Footer: Timestamp & WhatsApp Delivery/Read Ticks -->
                      <div class="flex items-center justify-end gap-1.5 mt-1.5 pt-0.5 text-[9px] opacity-80"
                        :class="m.is_own ? 'text-blue-100' : 'text-slate-400'">
                        <span x-text="formatDisplayTime ? formatDisplayTime(m.created_at) : (m.created_at ? m.created_at.substring(11, 16) : '')"></span>
                        
                        <!-- Delivery / Read Status Indicators for Sender -->
                        <template x-if="m.is_own">
                          <span class="inline-flex items-center ml-0.5">
                            <!-- Sending spinner -->
                            <template x-if="m.receipt_summary === 'sending'">
                              <svg class="w-3 h-3 animate-spin opacity-80" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
                            </template>
                            <!-- Single Grey Tick: Accepted by Server -->
                            <template x-if="m.receipt_summary === 'sent'">
                              <svg class="w-3.5 h-3.5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24" title="Sent to server"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                            </template>
                            <!-- Double Grey Ticks: Delivered -->
                            <template x-if="m.receipt_summary === 'delivered'">
                              <span class="flex -space-x-1.5 text-slate-300" title="Delivered to participants">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                              </span>
                            </template>
                            <!-- Double Blue Ticks: Read -->
                            <template x-if="m.receipt_summary === 'read'">
                              <span class="flex -space-x-1.5 text-cyan-300" title="Read by participants">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                              </span>
                            </template>
                            <!-- Failed Message State -->
                            <template x-if="m.has_failed || m.receipt_summary === 'failed'">
                              <button @click.stop="retryChatMessage(m)" class="text-rose-300 hover:text-white flex items-center gap-0.5 touch-press" title="Failed to send. Click to retry.">
                                <svg class="w-3 h-3 text-rose-300" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clip-rule="evenodd"/></svg>
                                <span class="underline">Retry</span>
                              </button>
                            </template>
                          </span>
                        </template>
                      </div>

                    </div>

                    <!-- Three-Dot Action Trigger Button (hover or click) -->
                    <div class="absolute top-1" :class="m.is_own ? '-left-6' : '-right-6'">
                      <button @click.stop="chatOpenMessageMenuId = (chatOpenMessageMenuId === m.id ? null : m.id)" 
                        class="w-5 h-5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200 flex items-center justify-center opacity-70 group-hover:opacity-100 transition shadow-xs touch-press"
                        title="Message Options">
                        <svg class="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z"/></svg>
                      </button>

                      <!-- Three-Dot Dropdown Menu -->
                      <div x-show="chatOpenMessageMenuId === m.id" @click.away="chatOpenMessageMenuId = null"
                        class="absolute z-40 top-6 bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-xl py-1.5 w-44 text-xs font-semibold text-slate-700 dark:text-slate-200"
                        :class="m.is_own ? 'right-0' : 'left-0'">
                        
                        <!-- Reply -->
                        <button @click="replyToGroupMessage(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2">
                          <svg class="w-3.5 h-3.5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6"/></svg>
                          <span>Reply</span>
                        </button>

                        <!-- Copy Message -->
                        <button @click="copyGroupMessage(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2">
                          <svg class="w-3.5 h-3.5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
                          <span>Copy Message</span>
                        </button>

                        <!-- Edit Message (Own, un-deleted only) -->
                        <template x-if="m.is_own && m.deletion_state === 'none'">
                          <button @click="startEditGroupMessage(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2">
                            <svg class="w-3.5 h-3.5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                            <span>Edit Message</span>
                          </button>
                        </template>

                        <!-- Unsend Message (Own, un-deleted only) -->
                        <template x-if="m.is_own && m.deletion_state === 'none'">
                          <button @click="unsendGroupMessage(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 text-amber-600 dark:text-amber-400">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                            <span>Unsend Message</span>
                          </button>
                        </template>

                        <div class="my-1 border-t border-slate-100 dark:border-slate-700"></div>

                        <!-- Delete for Me -->
                        <button @click="deleteGroupMessageForMe(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 text-rose-500">
                          <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                          <span>Delete for Me</span>
                        </button>

                        <!-- Delete for Everyone (Own or Admin/Leader) -->
                        <template x-if="(m.is_own || currentUser.role === 'admin') && m.deletion_state !== 'deleted_everyone'">
                          <button @click="promptDeleteGroupMessageForEveryone(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 text-rose-600 font-bold">
                            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                            <span>Delete for Everyone</span>
                          </button>
                        </template>

                        <!-- Message Info (Own message) -->
                        <template x-if="m.is_own && m.deletion_state === 'none'">
                          <div class="mt-1 pt-1 border-t border-slate-100 dark:border-slate-700">
                            <button @click="openMessageInfo(m)" class="w-full text-left px-3 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2 text-indigo-600 dark:text-indigo-400">
                              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                              <span>Message Info</span>
                            </button>
                          </div>
                        </template>

                      </div>
                    </div>

                  </div>

                </div>

              </div>
            </template>

          </div>

          <!-- Bottom Composer -->
          <div class="p-3 sm:p-4 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 shrink-0">
            
            <!-- Reply Banner Preview -->
            <template x-if="chatReplyTo">
              <div class="mb-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-950/40 border border-blue-200/80 dark:border-blue-800 rounded-xl flex items-center justify-between text-xs">
                <div class="flex items-center gap-2 min-w-0">
                  <svg class="w-3.5 h-3.5 text-blue-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h10a8 8 0 018-8v2M3 10l6 6m-6-6l6-6"/></svg>
                  <span class="font-bold text-blue-700 dark:text-blue-300" x-text="'Replying to ' + chatReplyTo.user_name + ':'"></span>
                  <span class="text-slate-600 dark:text-slate-300 truncate" x-text="chatReplyTo.message"></span>
                </div>
                <button @click="cancelChatReply()" class="p-1 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">&times;</button>
              </div>
            </template>

            <!-- Edit Banner Preview -->
            <template x-if="chatEditingMessage">
              <div class="mb-2 px-3 py-1.5 bg-amber-50 dark:bg-amber-950/40 border border-amber-200/80 dark:border-amber-800 rounded-xl flex items-center justify-between text-xs">
                <div class="flex items-center gap-2 min-w-0">
                  <svg class="w-3.5 h-3.5 text-amber-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                  <span class="font-bold text-amber-700 dark:text-amber-300">Editing Message</span>
                </div>
                <button @click="cancelEditGroupMessage()" class="p-1 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">&times;</button>
              </div>
            </template>

            <!-- Input Bar Form -->
            <form @submit.prevent="submitChatMessage()" class="flex items-center gap-2">
              <input type="text" id="chatInputMessage" x-model="chatInputText" 
                :placeholder="chatEditingMessage ? 'Edit your message...' : (chatReplyTo ? 'Write a reply...' : 'Type a message in ' + (activeChatGroup?.name || 'group') + '...')"
                class="flex-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700/80 rounded-2xl px-4 py-2.5 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition">
              
              <button type="submit" :disabled="chatIsSending || !chatInputText.trim()"
                class="px-4 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-40 text-white rounded-2xl text-xs font-bold shadow-xs transition flex items-center gap-1.5 touch-press">
                <svg x-show="chatIsSending" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
                <svg x-show="!chatIsSending" class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/></svg>
                <span x-text="chatEditingMessage ? 'Save' : 'Send'"></span>
              </button>
            </form>

          </div>

        </div>

      </div>
    </div>

    <!-- =========================================================================
         MODAL: CONFIRM DELETE MESSAGE FOR EVERYONE
         ========================================================================= -->
    <div x-show="modalConfirmDeleteForEveryoneOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="modalConfirmDeleteForEveryoneOpen = false" class="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-sm shadow-2xl space-y-4">
        <div class="w-12 h-12 rounded-2xl bg-rose-50 dark:bg-rose-950/40 text-rose-600 dark:text-rose-400 flex items-center justify-center mx-auto">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
        </div>
        <div class="text-center">
          <h4 class="text-sm font-extrabold text-slate-900 dark:text-slate-100">Delete for Everyone?</h4>
          <p class="text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed">
            This will permanently remove the message content and attachments for all members of this conversation. It will be replaced with <span class="italic text-slate-600 dark:text-slate-300">"This message was deleted."</span>
          </p>
        </div>
        <div class="flex items-center gap-2 pt-2">
          <button type="button" @click="confirmDeleteGroupMessageForEveryone()" :disabled="isDeletingMessageForEveryone"
            class="flex-1 py-2.5 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold text-xs shadow-xs touch-press transition flex items-center justify-center gap-1.5">
            <svg x-show="isDeletingMessageForEveryone" class="w-3.5 h-3.5 animate-spin" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
            <span x-text="isDeletingMessageForEveryone ? 'Deleting...' : 'Delete for Everyone'"></span>
          </button>
          <button type="button" @click="modalConfirmDeleteForEveryoneOpen = false"
            class="py-2.5 px-4 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 rounded-xl font-bold text-xs transition">
            Cancel
          </button>
        </div>
      </div>
    </div>

    <!-- =========================================================================
         MODAL: MESSAGE INFO (Delivery & Read Receipts)
         ========================================================================= -->
    <div x-show="modalMessageInfoOpen" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs" x-cloak>
      <div @click.away="closeMessageInfo()" class="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 w-full max-w-md shadow-2xl space-y-4 max-h-[85vh] flex flex-col">
        
        <!-- Header -->
        <div class="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-700/80 shrink-0">
          <div class="flex items-center gap-2">
            <div class="w-8 h-8 rounded-xl bg-indigo-50 dark:bg-indigo-950/40 text-indigo-600 dark:text-indigo-400 flex items-center justify-center">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            </div>
            <div>
              <h3 class="text-sm font-black text-slate-900 dark:text-slate-100">Message Info</h3>
              <p class="text-[10px] text-slate-400">Delivery and read receipts per member</p>
            </div>
          </div>
          <button @click="closeMessageInfo()" class="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-xl touch-press">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <!-- Body -->
        <div class="flex-1 overflow-y-auto space-y-4 pr-1">
          <!-- Message Preview Card -->
          <div class="p-3.5 rounded-2xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200/80 dark:border-slate-700/80 space-y-1">
            <div class="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Message Content</div>
            <p class="text-xs text-slate-900 dark:text-slate-100 font-medium" x-text="activeMessageInfo?.message?.message"></p>
            <div class="text-[10px] text-slate-400 pt-1" x-text="'Sent at ' + (activeMessageInfo?.message?.created_at || 'Recently')"></div>
          </div>

          <!-- Loading Spinner -->
          <template x-if="isLoadingMessageInfo">
            <div class="py-8 text-center text-slate-400 text-xs flex items-center justify-center gap-2">
              <svg class="w-4 h-4 animate-spin text-blue-600" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
              <span>Loading receipts...</span>
            </div>
          </template>

          <!-- Read By Section -->
          <template x-if="!isLoadingMessageInfo && activeMessageInfo">
            <div class="space-y-2">
              <div class="flex items-center justify-between text-xs font-bold text-cyan-600 dark:text-cyan-400 border-b border-slate-100 dark:border-slate-700/80 pb-1.5">
                <span class="flex items-center gap-1.5">
                  <span class="flex -space-x-1.5 text-cyan-500">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                  </span>
                  <span>Read By</span>
                </span>
                <span class="text-[11px] px-2 py-0.5 rounded-full bg-cyan-50 dark:bg-cyan-950/40 text-cyan-700 dark:text-cyan-300 font-extrabold" x-text="(activeMessageInfo.read_by || []).length"></span>
              </div>

              <template x-if="(activeMessageInfo.read_by || []).length === 0">
                <p class="text-[11px] text-slate-400 italic py-1">No participants have read this message yet.</p>
              </template>

              <div class="space-y-1.5">
                <template x-for="r in activeMessageInfo.read_by" :key="r.user_id">
                  <div class="flex items-center justify-between p-2 rounded-xl bg-slate-50/60 dark:bg-slate-900/40 text-xs">
                    <div class="flex items-center gap-2">
                      <div class="w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold text-[9px]">
                        <span x-text="(r.user_name || 'U').substring(0, 2).toUpperCase()"></span>
                      </div>
                      <span class="font-bold text-slate-800 dark:text-slate-200" x-text="r.user_name"></span>
                    </div>
                    <span class="text-[10px] text-slate-400 font-mono" x-text="r.read_at"></span>
                  </div>
                </template>
              </div>
            </div>
          </template>

          <!-- Delivered To Section -->
          <template x-if="!isLoadingMessageInfo && activeMessageInfo">
            <div class="space-y-2 pt-2">
              <div class="flex items-center justify-between text-xs font-bold text-slate-600 dark:text-slate-400 border-b border-slate-100 dark:border-slate-700/80 pb-1.5">
                <span class="flex items-center gap-1.5">
                  <span class="flex -space-x-1.5 text-slate-400">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                  </span>
                  <span>Delivered To</span>
                </span>
                <span class="text-[11px] px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 font-extrabold" x-text="(activeMessageInfo.delivered_to || []).length"></span>
              </div>

              <template x-if="(activeMessageInfo.delivered_to || []).length === 0">
                <p class="text-[11px] text-slate-400 italic py-1">Delivery receipts pending.</p>
              </template>

              <div class="space-y-1.5">
                <template x-for="d in activeMessageInfo.delivered_to" :key="d.user_id">
                  <div class="flex items-center justify-between p-2 rounded-xl bg-slate-50/60 dark:bg-slate-900/40 text-xs">
                    <div class="flex items-center gap-2">
                      <div class="w-6 h-6 rounded-full bg-slate-500 text-white flex items-center justify-center font-bold text-[9px]">
                        <span x-text="(d.user_name || 'U').substring(0, 2).toUpperCase()"></span>
                      </div>
                      <span class="font-bold text-slate-800 dark:text-slate-200" x-text="d.user_name"></span>
                    </div>
                    <span class="text-[10px] text-slate-400 font-mono" x-text="d.delivered_at"></span>
                  </div>
                </template>
              </div>
            </div>
          </template>

          <!-- Pending Section -->
          <template x-if="!isLoadingMessageInfo && activeMessageInfo && (activeMessageInfo.pending_members || []).length > 0">
            <div class="space-y-2 pt-2">
              <div class="flex items-center justify-between text-xs font-bold text-amber-600 dark:text-amber-400 border-b border-slate-100 dark:border-slate-700/80 pb-1.5">
                <span class="flex items-center gap-1.5">
                  <svg class="w-3.5 h-3.5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                  <span>Pending / Unread</span>
                </span>
                <span class="text-[11px] px-2 py-0.5 rounded-full bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300 font-extrabold" x-text="activeMessageInfo.pending_members.length"></span>
              </div>

              <div class="space-y-1.5">
                <template x-for="p in activeMessageInfo.pending_members" :key="p.user_id">
                  <div class="flex items-center justify-between p-2 rounded-xl bg-slate-50/60 dark:bg-slate-900/40 text-xs">
                    <div class="flex items-center gap-2">
                      <div class="w-6 h-6 rounded-full bg-amber-500 text-white flex items-center justify-center font-bold text-[9px]">
                        <span x-text="(p.user_name || 'U').substring(0, 2).toUpperCase()"></span>
                      </div>
                      <span class="font-bold text-slate-800 dark:text-slate-200" x-text="p.user_name"></span>
                    </div>
                    <span class="text-[10px] text-amber-600 dark:text-amber-400 font-bold">Unopened</span>
                  </div>
                </template>
              </div>
            </div>
          </template>

        </div>

      </div>
    </div>

    <!-- =========================================================================
         MODAL / OVERLAY: GROUP WEBRTC CALL & SCREEN-SHARING PRESENTATIONS
         ========================================================================= -->
    <div x-show="modalGroupCallOpen" class="fixed inset-0 z-50 flex items-center justify-center p-2 sm:p-4 bg-slate-950/85 backdrop-blur-md" x-cloak>
      <div class="bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl w-full max-w-5xl h-[92vh] flex flex-col overflow-hidden relative text-white">
        
        <!-- Call Header -->
        <div class="px-5 py-3.5 border-b border-slate-800 bg-slate-900/90 flex items-center justify-between gap-3 shrink-0">
          <div class="flex items-center gap-3">
            <div class="w-9 h-9 rounded-xl flex items-center justify-center font-bold"
              :class="callType === 'video' ? 'bg-blue-600 text-white' : 'bg-emerald-600 text-white'">
              <template x-if="callType === 'video'">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
              </template>
              <template x-if="callType === 'audio'">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
              </template>
            </div>

            <div>
              <div class="flex items-center gap-2">
                <h3 class="text-sm font-extrabold text-white" x-text="activeChatGroup?.name || 'Group Call'"></h3>
                <span class="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider"
                  :class="callStatus === 'connected' ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30' : (callStatus === 'calling' || callStatus === 'ringing' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30' : 'bg-slate-700 text-slate-300')"
                  x-text="callStatus">
                </span>
              </div>
              <div class="flex items-center gap-2 text-[11px] text-slate-400 mt-0.5">
                <span class="font-mono text-emerald-400 font-bold" x-text="callDurationFormatted"></span>
                <span>•</span>
                <span x-text="(callParticipants.length || 1) + ' connected'"></span>
              </div>
            </div>
          </div>

          <!-- Presenting Live Indicator (if active) -->
          <template x-if="isCallScreenSharing || (activeCall && activeCall.is_presenting)">
            <div class="px-3 py-1 bg-indigo-600/30 border border-indigo-500 text-indigo-200 rounded-xl text-xs font-bold flex items-center gap-2 animate-pulse">
              <span class="w-2 h-2 rounded-full bg-indigo-400"></span>
              <span>Screen Presentation Live</span>
            </div>
          </template>
        </div>

        <!-- Video / Screen Grid Area -->
        <div class="flex-1 p-4 overflow-y-auto flex flex-col justify-center items-center gap-4 bg-slate-950/60">
          
          <!-- Screen Sharing Presentation Main Stage -->
          <template x-if="isCallScreenSharing || (activeCall && activeCall.is_presenting)">
            <div class="w-full h-full max-h-[62vh] bg-black rounded-2xl overflow-hidden border border-indigo-500/50 shadow-2xl relative flex items-center justify-center">
              <video id="screenShareVideoFeed" autoplay playsinline class="w-full h-full object-contain"></video>
              <div class="absolute top-3 left-3 px-3 py-1 rounded-xl bg-slate-900/80 backdrop-blur-xs text-xs font-bold text-white border border-slate-700 flex items-center gap-2">
                <svg class="w-3.5 h-3.5 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                <span x-text="'Presenter: ' + (activeCall?.presenter_name || currentUser.name)"></span>
              </div>
            </div>
          </template>

          <!-- Participant Video / Avatar Grid -->
          <div class="w-full grid gap-3"
            :class="(isCallScreenSharing || (activeCall && activeCall.is_presenting)) ? 'grid-cols-2 sm:grid-cols-4 max-h-36' : (callParticipants.length <= 1 ? 'grid-cols-1 sm:grid-cols-2 max-w-2xl h-full max-h-[60vh]' : 'grid-cols-2 sm:grid-cols-3 max-w-4xl h-full max-h-[60vh]')">
            
            <!-- Local User Tile -->
            <div class="relative rounded-2xl bg-slate-800/90 border border-slate-700/80 overflow-hidden flex items-center justify-center min-h-[140px] shadow-lg">
              <!-- Video if Camera is ON -->
              <video id="localVideoFeed" autoplay muted playsinline class="w-full h-full object-cover" :class="isCallCameraOff ? 'hidden' : 'block'"></video>
              
              <!-- Avatar placeholder if Camera is OFF -->
              <div x-show="isCallCameraOff" class="flex flex-col items-center justify-center p-4">
                <div class="w-14 h-14 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold text-lg shadow-md ring-2 ring-blue-500/30">
                  <span x-text="(currentUser.name || 'You').substring(0, 2).toUpperCase()"></span>
                </div>
                <span class="text-xs font-bold text-white mt-2">You</span>
              </div>

              <!-- Local User Badges -->
              <div class="absolute bottom-2 left-2 px-2 py-0.5 rounded-lg bg-slate-900/80 backdrop-blur-xs text-[10px] font-bold text-white flex items-center gap-1">
                <span>You</span>
                <span x-show="isCallMuted" class="text-rose-400 font-extrabold">• Muted</span>
              </div>
            </div>

            <!-- Remote Participants Tiles -->
            <template x-for="p in callParticipants" :key="p.user_id">
              <template x-if="Number(p.user_id) !== Number(currentUser.id)">
                <div class="relative rounded-2xl bg-slate-800/90 border border-slate-700/80 overflow-hidden flex items-center justify-center min-h-[140px] shadow-lg">
                  <div class="flex flex-col items-center justify-center p-4">
                    <div class="w-14 h-14 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold text-lg shadow-md ring-2 ring-indigo-500/30">
                      <span x-text="(p.user_name || 'U').substring(0, 2).toUpperCase()"></span>
                    </div>
                    <span class="text-xs font-bold text-white mt-2" x-text="p.user_name"></span>
