  <!-- =========================================================================
       ALPINE.JS CONTROLLERS (Unauthenticated & Authenticated)
       ========================================================================= -->
  <script>
    // -------------------------------------------------------------------------
    // UNAUTHENTICATED AUTH CONTROLLER (Login, Register, 4-Digit Email OTP)
    // -------------------------------------------------------------------------
    function authScreenController() {
      return {
        // Welcome Screen Animation & Onboarding State
        showIntro: true,
        introStage: 1, // 1: Animated CRM Logo, 2: Welcome Screen
        introExiting: false,
        isNavigatingToLogin: false,
        introProgress: 0,
        introStepText: 'Initializing Workspace...',
        introRememberChoice: false,
        introProgressTimer: null,
        logoStageTimer: null,

        authMode: 'login', // 'login' | 'register' | 'otp'
        loginForm: {
          email: '',
          password: '',
          rememberMe: true
        },
        registerForm: {
          name: '',
          email: '',
          password: '',
          confirm_password: '',
          terms_accepted: false
        },
        otpState: {
          purpose: 'login',
          provider: '',
          email: '',
          digits: ['', '', '', ''],
          expiresIn: 300,
          cooldown: 60,
          timer: null,
          errorMessage: '',
          successMessage: '',
          isVerifying: false,
          isResending: false
        },
        isLoading: false,
        googleLoading: false,
        biometricLoading: false,
        errorMessage: '',
        successMessage: '',
        showPassword: false,

        // Animation Video Player State
        showAnimationVideo: false,
        isVideoPlaying: true,
        isVideoMuted: true,
        videoProgress: 0,
        videoTimeText: '0:00 / 0:05',

        playIntroVideo() {
          this.showAnimationVideo = true;
          this.$nextTick(() => {
            const v = document.getElementById('crmWelcomeIntroVideo');
            if (v) {
              v.play().catch(() => {});
              this.isVideoPlaying = !v.paused;
            }
          });
        },

        toggleVideoPlay() {
          const v = document.getElementById('crmWelcomeIntroVideo');
          if (!v) return;
          if (v.paused) {
            v.play().catch(() => {});
            this.isVideoPlaying = true;
          } else {
            v.pause();
            this.isVideoPlaying = false;
          }
        },

        toggleVideoMute() {
          const v = document.getElementById('crmWelcomeIntroVideo');
          if (!v) return;
          v.muted = !v.muted;
          this.isVideoMuted = v.muted;
        },

        onVideoTimeUpdate(e) {
          const v = e.target;
          if (!v || !v.duration) return;
          this.videoProgress = (v.currentTime / v.duration) * 100;
          const cur = Math.floor(v.currentTime);
          const dur = Math.floor(v.duration) || 5;
          this.videoTimeText = '0:0' + cur + ' / 0:0' + dur;
          this.isVideoPlaying = !v.paused;
        },

        seekVideo(e) {
          const v = document.getElementById('crmWelcomeIntroVideo');
          if (!v || !v.duration) return;
          const rect = e.currentTarget.getBoundingClientRect();
          const clickX = e.clientX - rect.left;
          const pct = Math.max(0, Math.min(1, clickX / rect.width));
          v.currentTime = pct * v.duration;
        },

        init() {
          this.setupHistoryListeners();
          this.checkIntroPreference();
          this.checkUrlParams();
          if (typeof window !== 'undefined' && window.matchMedia) {
            const mql = window.matchMedia('(prefers-color-scheme: dark)');
            const authThemeHandler = (e) => {
              const pref = localStorage.getItem('crm_theme') || 'system';
              if (pref === 'system') {
                const isDark = e.matches;
                document.documentElement.classList.toggle('dark', isDark);
                document.documentElement.setAttribute('data-theme', isDark ? 'dark' : 'light');
                document.documentElement.style.colorScheme = isDark ? 'dark' : 'light';
              }
            };
            if (mql.addEventListener) mql.addEventListener('change', authThemeHandler);
            else if (mql.addListener) mql.addListener(authThemeHandler);
          }
          this.$nextTick(() => {
            const emailInput = document.getElementById('login_email_input');
            if (emailInput && !this.loginForm.email && this.authMode === 'login' && !this.showIntro) emailInput.focus();
          });
        },

        setupHistoryListeners() {
          const handleHistoryChange = () => {
            this.handleRouteState();
          };
          window.addEventListener('popstate', handleHistoryChange);
          window.addEventListener('hashchange', handleHistoryChange);
        },

        handleRouteState() {
          const hash = window.location.hash || '';
          const urlParams = new URLSearchParams(window.location.search);

          // If currently in OTP mode or URL indicates OTP step, preserve OTP view
          const isOtp = hash === '#otp' || urlParams.get('step') === 'otp_required';
          if (isOtp) {
            if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
            if (this.introProgressTimer) clearInterval(this.introProgressTimer);
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'otp';
            return;
          }

          const isLogin = hash === '#login' || urlParams.get('view') === 'login' || urlParams.has('login') || urlParams.has('auth_error');

          if (isLogin) {
            if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
            if (this.introProgressTimer) clearInterval(this.introProgressTimer);
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'login';
          } else if (hash === '' || hash === '#' || hash === '#intro') {
            // Browser Back button navigation to Welcome Screen
            if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
            if (this.introProgressTimer) clearInterval(this.introProgressTimer);
            this.showIntro = true;
            this.introStage = 2; // Return to Welcome Screen with Enter CRM visible
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            try { sessionStorage.removeItem('crm_active_screen'); } catch (e) {}
          }
        },

        checkIntroPreference() {
          const hash = window.location.hash || '';
          const urlParams = new URLSearchParams(window.location.search);
          const forceIntro = urlParams.has('intro') || urlParams.has('replay') || urlParams.has('replay_intro');
          const bypassIntro = urlParams.has('step') || urlParams.has('auth_error') || urlParams.has('login') || urlParams.has('skip_intro') || urlParams.has('code');
          const isLoginExplicit = hash === '#login' || urlParams.get('view') === 'login' || bypassIntro;
          const targetScreen = parseInt(urlParams.get('screen') || urlParams.get('stage') || '0', 10);
          
          // Clear any conflicting auto-skip in sessionStorage so fresh website visits always see the intro
          if (!isLoginExplicit && !forceIntro) {
            try { sessionStorage.removeItem('crm_active_screen'); } catch (e) {}
          }

          // If OTP verification requested or active in URL / hash:
          if (hash === '#otp' || urlParams.get('step') === 'otp_required') {
            if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
            if (this.introProgressTimer) clearInterval(this.introProgressTimer);
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'otp';
            const cachedEmail = urlParams.get('email') || (typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('crm_pending_otp_email') : '');
            if (cachedEmail) {
              this.otpState.email = cachedEmail;
              this.otpState.provider = urlParams.get('provider') || (typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('crm_pending_otp_provider') : 'google') || 'google';
              this.otpState.purpose = 'login';
            }
            return;
          }

          // If explicit login requested (#login on refresh, view=login, auth callback) and not forcing intro:
          if (isLoginExplicit && !forceIntro) {
            if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
            if (this.introProgressTimer) clearInterval(this.introProgressTimer);
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'login';
            return;
          }

          if (targetScreen === 1) {
            this.showIntro = true;
            this.introStage = 1;
            this.startLogoAnimation();
            return;
          }

          if (targetScreen === 2) {
            this.showIntro = true;
            this.introStage = 2;
            this.startWelcomeScreen();
            return;
          }

          if (forceIntro) {
            this.showIntro = true;
            this.introStage = 1;
            this.startLogoAnimation();
            return;
          }

          // Default when visiting root http://localhost/software_team/ directly:
          // ALWAYS display Welcome Animation first!
          this.showIntro = true;
          this.introStage = 1;
          this.startLogoAnimation();
        },

        startLogoAnimation() {
          if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
          if (this.introProgressTimer) clearInterval(this.introProgressTimer);

          // Respect prefers-reduced-motion
          const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
          const logoDuration = prefersReduced ? 500 : 3800;

          this.logoStageTimer = setTimeout(() => {
            this.goToStage(2);
          }, logoDuration);
        },

        skipLogo() {
          // Skipping logo animation advances immediately to Screen 2 (Welcome Screen)
          if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
          this.goToStage(2);
        },

        goToStage(stage) {
          if (stage === 2) {
            this.introStage = 2;
            this.startWelcomeScreen();
          } else if (stage === 3) {
            this.enterCRM();
          }
        },

        startWelcomeScreen() {
          if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
          if (this.introProgressTimer) clearInterval(this.introProgressTimer);
          this.introProgress = 0;
          this.introStepText = 'Initializing Workspace...';

          const totalDuration = 5000;
          const interval = 50;
          const step = 100 / (totalDuration / interval);

          this.introProgressTimer = setInterval(() => {
            this.introProgress = Math.min(100, this.introProgress + step);
            if (this.introProgress < 25) {
              this.introStepText = 'Initializing Workspace...';
            } else if (this.introProgress < 55) {
              this.introStepText = 'Loading Projects & Teams...';
            } else if (this.introProgress < 85) {
              this.introStepText = 'Connecting Secure Channels...';
            } else if (this.introProgress < 100) {
              this.introStepText = 'Finalizing System Setup...';
            } else {
              this.introStepText = 'Ready to Empower Teams!';
            }

            // When animation finishes: KEEP ENTER CRM BUTTON VISIBLE! Do not auto-navigate!
            if (this.introProgress >= 100) {
              clearInterval(this.introProgressTimer);
              this.introProgress = 100;
              this.introStepText = 'Ready to Empower Teams! Click Enter CRM to proceed.';
              // Do NOT call enterCRM() automatically!
            }
          }, interval);
        },

        startIntroAnimation() {
          this.startLogoAnimation();
        },

        enterCRM() {
          // Prevent duplicate navigation events
          if (this.isNavigatingToLogin) return;
          this.isNavigatingToLogin = true;

          // Pause video if playing
          try {
            const v = document.getElementById('crmWelcomeIntroVideo');
            if (v) v.pause();
          } catch (e) {}

          if (this.logoStageTimer) clearTimeout(this.logoStageTimer);
          if (this.introProgressTimer) clearInterval(this.introProgressTimer);

          if (this.introRememberChoice) {
            try { localStorage.setItem('crm_intro_auto_skip', 'true'); } catch (e) {}
          }
          try {
            sessionStorage.setItem('crm_active_screen', 'login');
            localStorage.setItem('crm_intro_seen', 'true');
          } catch (e) {}

          // Update browser history so refreshing keeps the user on login, and back/forward work!
          if (window.location.hash !== '#login') {
            try {
              if (window.history && window.history.pushState) {
                window.history.pushState({ page: 'login' }, 'Software CRM - Login', '#login');
              } else {
                window.location.hash = '#login';
              }
            } catch (e) {
              window.location.hash = '#login';
            }
          }

          // Smooth exit without displaying intro and login simultaneously
          this.introExiting = true;
          setTimeout(() => {
            if (<?= $isAuthenticated ? 'true' : 'false' ?>) {
              window.location.href = 'index.php';
              return;
            }
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'login';
            this.errorMessage = '';
            this.$nextTick(() => {
              const emailInput = document.getElementById('login_email_input');
              if (emailInput && this.authMode === 'login') emailInput.focus();
            });
          }, 200);
        },

        skipIntro() {
          // Skipping from welcome screen enters CRM login immediately
          this.enterCRM();
        },

        toggleTheme() {
          const isCurrentlyDark = document.documentElement.classList.contains('dark') || document.documentElement.getAttribute('data-theme') === 'dark';
          const targetTheme = isCurrentlyDark ? 'light' : 'dark';
          try { localStorage.setItem('crm_theme', targetTheme); } catch (e) {}
          document.documentElement.setAttribute('data-theme', targetTheme);
          if (targetTheme === 'dark') {
            document.documentElement.classList.add('dark');
            document.documentElement.style.colorScheme = 'dark';
          } else {
            document.documentElement.classList.remove('dark');
            document.documentElement.style.colorScheme = 'light';
          }
        },

        checkUrlParams() {
          const urlParams = new URLSearchParams(window.location.search);
          if (urlParams.has('step') && urlParams.get('step') === 'otp_required') {
            const email = urlParams.get('email') || '';
            const provider = urlParams.get('provider') || 'google';
            this.showIntro = false;
            this.introExiting = false;
            this.isNavigatingToLogin = false;
            this.authMode = 'otp';
            this.otpState.purpose = 'login';
            this.otpState.provider = provider;
            this.otpState.email = email;
            this.otpState.digits = ['', '', '', ''];
            this.otpState.errorMessage = '';
            this.otpState.cooldown = 60;
            this.otpState.expiresIn = 300;
            try {
              sessionStorage.setItem('crm_pending_otp_email', email);
              sessionStorage.setItem('crm_pending_otp_provider', provider);
            } catch (e) {}
            this.startTimer();
            if (window.history && window.history.replaceState) {
              window.history.replaceState({}, document.title, window.location.pathname + '#otp');
            }
            this.$nextTick(() => {
              const first = document.getElementById('otp_box_0');
              if (first) first.focus();
            });
            return;
          }

          if (urlParams.has('auth_error')) {
            const code = urlParams.get('auth_error');
            const msg = urlParams.get('msg') || '';
            const email = urlParams.get('email') || '';
            const errorMap = {
              'google_cancelled': 'Google sign-in was cancelled.',
              'google_not_configured': 'Google Sign-In is not configured yet. Please configure GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in .env.',
              'invalid_state': 'Security validation failed (invalid state token). Please try signing in again.',
              'missing_code': 'Google authentication failed: no authorization code received.',
              'token_exchange_failed': msg ? 'Google token exchange failed: ' + decodeURIComponent(msg) : 'Failed to exchange authorization code with Google.',
              'invalid_token': msg ? decodeURIComponent(msg) : 'Invalid Google identity token.',
              'google_process_failed': msg ? decodeURIComponent(msg) : 'Failed to process Google sign-in.',
              'domain_restricted': 'Google sign-in is restricted to authorized corporate domain accounts.',
              'account_suspended': 'Your employee account has been deactivated or suspended. Please contact your CRM administrator.',
              'employee_inactive': 'Your employee profile is currently marked as inactive in the company registry. Please contact your CRM administrator.',
              'unregistered_employee': email ? 'Your Google account (' + email + ') is not registered as an authorized employee in Software Team CRM. Please contact your CRM administrator to request employee access.' : (msg ? decodeURIComponent(msg) : 'Your Google account is not registered as an authorized employee in Software Team CRM. Please contact your CRM administrator.')
            };
            this.errorMessage = errorMap[code] || (msg ? decodeURIComponent(msg) : 'Authentication failed (' + code + '). Please try again.');
            this.authMode = 'login';
            this.showIntro = false;
            this.introExiting = false;
            if (window.history && window.history.replaceState) {
              window.history.replaceState({}, document.title, window.location.pathname + '#login');
            }
          }
        },

        async startGoogleLogin() {
          if (this.isLoading || this.googleLoading) return;
          this.googleLoading = true;
          this.errorMessage = '';

          try {
            const res = await fetch('api/auth.php?action=google_auth_init');
            const data = await res.json();

            if (!res.ok || !data.success || !data.auth_url) {
              this.googleLoading = false;
              this.errorMessage = (data && data.error)
                ? data.error
                : 'Google Sign-In is not configured yet. Please configure GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in .env.';
              return;
            }

            // Redirect user directly to Google OAuth 2.0 Account Chooser (prompt=select_account)
            window.location.href = data.auth_url;
          } catch (e) {
            this.googleLoading = false;
            this.errorMessage = 'Network connection error while connecting to Google. Please check your network and try again.';
          }
        },

        async startBiometricLogin() {
          if (this.isLoading || this.biometricLoading) return;
          this.errorMessage = '';

          const email = (this.loginForm.email || '').trim().toLowerCase();
          if (!email) {
            this.errorMessage = 'Please enter your registered email address above first.';
            const emailInput = document.getElementById('login_email_input');
            if (emailInput) emailInput.focus();
            return;
          }

          if (!window.PublicKeyCredential) {
            this.errorMessage = 'Biometric authentication is not supported by your browser. Please sign in with your password.';
            return;
          }

          this.biometricLoading = true;
          try {
            const result = await BiometricAuth.loginWithBiometrics(email);
            if (result && result.success && result.authenticated) {
              localStorage.setItem('software_crm_mobile_session', 'active');
              try { sessionStorage.removeItem('crm_active_screen'); } catch (e) {}
              window.location.href = 'index.php';
            } else {
              this.errorMessage = (result && result.error) ? result.error : 'Biometric verification failed.';
            }
          } catch (e) {
            this.errorMessage = BiometricAuth.formatError(e);
          } finally {
            this.biometricLoading = false;
          }
        },

        async submitLogin() {
          if (this.isLoading) return;
          this.errorMessage = '';

          if (!this.loginForm.email || !this.loginForm.password) {
            this.errorMessage = 'Please enter both your email and password.';
            return;
          }

          this.isLoading = true;

          try {
            const res = await fetch('api/auth.php?action=login_credentials', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(this.loginForm)
            });
            const data = await res.json();

            if (!res.ok || !data.success) {
              this.errorMessage = (data && data.error) ? data.error : 'Invalid credentials. Please verify your email and password.';
              this.isLoading = false;
              return;
            }

            // Credentials verified! Move to mandatory 4-digit OTP step
            this.isLoading = false;
            this.authMode = 'otp';
            this.otpState.purpose = 'login';
            this.otpState.email = this.loginForm.email;
            this.otpState.digits = ['', '', '', ''];
            this.otpState.errorMessage = '';
            this.otpState.cooldown = data.resend_cooldown || 60;
            this.otpState.expiresIn = data.expires_in || 300;
            this.startTimer();
            this.$nextTick(() => {
              const first = document.getElementById('otp_box_0');
              if (first) first.focus();
            });
          } catch (e) {
            this.isLoading = false;
            this.errorMessage = 'Network connection error during sign in. Please try again.';
          }
        },

        async submitRegister() {
          if (this.isLoading) return;
          this.errorMessage = '';

          if (!this.registerForm.name || this.registerForm.name.length < 2) {
            this.errorMessage = 'Please enter your full name (minimum 2 characters).';
            return;
          }
          if (!this.registerForm.email) {
            this.errorMessage = 'Please enter a valid work email address.';
            return;
          }
          if (this.registerForm.password.length < 8) {
            this.errorMessage = 'Password must be at least 8 characters long.';
            return;
          }
          if (this.registerForm.password !== this.registerForm.confirm_password) {
            this.errorMessage = 'Passwords do not match.';
            return;
          }
          if (!this.registerForm.terms_accepted) {
            this.errorMessage = 'You must agree to the Terms of Service & Privacy Policy.';
            return;
          }

          this.isLoading = true;

          try {
            const res = await fetch('api/auth.php?action=register', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(this.registerForm)
            });
            let data = null;
            try {
              data = await res.json();
            } catch (jsonErr) {
              const text = await res.text().catch(() => '');
              this.isLoading = false;
              this.errorMessage = (text && text.length < 200) ? text : 'Server returned status ' + res.status;
              return;
            }

            if (!res.ok || !data.success) {
              this.errorMessage = (data && data.error) ? data.error : 'Registration failed. Please check your details.';
              this.isLoading = false;
              return;
            }

            this.isLoading = false;
            this.authMode = 'otp';
            this.otpState.purpose = 'registration';
            this.otpState.email = this.registerForm.email;
            this.otpState.digits = ['', '', '', ''];
            this.otpState.errorMessage = '';
            this.otpState.cooldown = data.resend_cooldown || 60;
            this.otpState.expiresIn = data.expires_in || 300;
            this.startTimer();
            this.$nextTick(() => {
              const first = document.getElementById('otp_box_0');
              if (first) first.focus();
            });
          } catch (e) {
            this.isLoading = false;
            this.errorMessage = (e && e.message) ? e.message : 'Network error during registration. Please try again.';
          }
        },

        handleOtpDigitInput(e, idx) {
          const val = e.target.value.replace(/[^0-9]/g, '');
          if (val) {
            this.otpState.digits[idx] = val.slice(-1);
            if (idx < 3) {
              const next = document.getElementById('otp_box_' + (idx + 1));
              if (next) next.focus();
            }
          } else {
            this.otpState.digits[idx] = '';
          }

          if (this.otpState.digits.join('').length === 4) {
            this.submitVerifyOtp();
          }
        },

        handleOtpKeyDown(e, idx) {
          if (e.key === 'Backspace' && !this.otpState.digits[idx] && idx > 0) {
            const prev = document.getElementById('otp_box_' + (idx - 1));
            if (prev) {
              prev.focus();
              this.otpState.digits[idx - 1] = '';
            }
          }
        },

        handleOtpPaste(e) {
          e.preventDefault();
          const clip = (e.clipboardData || window.clipboardData).getData('text') || '';
          const clean = clip.replace(/[^0-9]/g, '').slice(0, 4);
          if (clean.length > 0) {
            const chars = clean.split('');
            for (let i = 0; i < 4; i++) {
              this.otpState.digits[i] = chars[i] || '';
            }
            const lastIdx = Math.min(chars.length, 3);
            const target = document.getElementById('otp_box_' + lastIdx);
            if (target) target.focus();

            if (clean.length === 4) {
              this.submitVerifyOtp();
            }
          }
        },

        async submitVerifyOtp() {
          const code = this.otpState.digits.join('');
          if (code.length !== 4 || this.otpState.isVerifying) {
            return;
          }

          this.otpState.isVerifying = true;
          this.otpState.errorMessage = '';

          try {
            const res = await fetch('api/auth.php?action=verify_otp', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                email: this.otpState.email,
                otp: code,
                purpose: this.otpState.purpose
              })
            });
            const data = await res.json();

            if (!res.ok || !data.success) {
              this.otpState.isVerifying = false;
              this.otpState.errorMessage = data.error || 'Invalid verification code.';
              this.otpState.digits = ['', '', '', ''];
              this.$nextTick(() => {
                const first = document.getElementById('otp_box_0');
                if (first) first.focus();
              });
              return;
            }

            // Authentication succeeded! Established secure server session.
            localStorage.setItem('software_crm_mobile_session', 'true');
            try {
              sessionStorage.removeItem('crm_active_screen');
              sessionStorage.removeItem('crm_pending_otp_email');
              sessionStorage.removeItem('crm_pending_otp_provider');
            } catch (e) {}
            
            // Redirect to enter protected dashboard
            window.location.href = 'index.php';
          } catch (e) {
            this.otpState.isVerifying = false;
            this.otpState.errorMessage = 'Network error verifying code.';
          }
        },

        async resendOtp() {
          if (this.otpState.cooldown > 0 || this.otpState.isResending) return;

          this.otpState.isResending = true;
          this.otpState.errorMessage = '';

          try {
            const res = await fetch('api/auth.php?action=resend_otp', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                email: this.otpState.email,
                purpose: this.otpState.purpose
              })
            });
            const data = await res.json();
            this.otpState.isResending = false;

            if (!res.ok || !data.success) {
              this.otpState.errorMessage = (data && data.error) ? data.error : 'Failed to resend code.';
              return;
            }

            this.otpState.successMessage = data.message || 'A new verification code has been dispatched.';
            setTimeout(() => { this.otpState.successMessage = ''; }, 5000);
            this.otpState.cooldown = data.resend_cooldown || 60;
            this.otpState.expiresIn = data.expires_in || 300;
            this.otpState.digits = ['', '', '', ''];
            this.startTimer();
          } catch (e) {
            this.otpState.isResending = false;
            this.otpState.errorMessage = 'Network error resending code.';
          }
        },

        startTimer() {
          if (this.otpState.timer) clearInterval(this.otpState.timer);
          this.otpState.timer = setInterval(() => {
            if (this.otpState.cooldown > 0) this.otpState.cooldown--;
            if (this.otpState.expiresIn > 0) this.otpState.expiresIn--;
            if (this.otpState.expiresIn === 0) {
              this.otpState.errorMessage = 'Verification code expired. Please request a new code.';
              clearInterval(this.otpState.timer);
            }
          }, 1000);
        },

        socialLoginNotice(provider) {
          if (provider === 'Google') {
            this.startGoogleLogin();
          } else {
            this.errorMessage = provider + ' enterprise sign-in is managed via your administrator directory. Please sign in with your email and password.';
          }
        }
      };
    }

    // -------------------------------------------------------------------------
    // AUTHENTICATED CRM CONTROLLER (Loaded only when session is active)
    // -------------------------------------------------------------------------
function softwareCRMApp(serverUser) {
      const initialUser = (serverUser && (serverUser.name || serverUser.email)) ? serverUser : {
        id: <?= json_encode((int)($currentUser['id'] ?? 0)) ?>,
        name: <?= json_encode($currentUserName) ?>,
