        async init() {
          this.setupSystemThemeListener();
          const urlTheme = typeof window !== 'undefined' ? (new URLSearchParams(window.location.search)).get('theme') : null;
          const storedTheme = typeof window !== 'undefined' ? localStorage.getItem('crm_theme') : null;
          this.applyTheme(urlTheme || storedTheme || this.settingsData?.preferences?.theme || 'system');
          if (typeof window !== 'undefined' && (new URLSearchParams(window.location.search)).get('notifications') === '1') {
            this.openNotificationsModal();
          }
          await this.loadUserProfile();
          await this.loadAllData();
          await this.loadBiometricDevices();
          await this.loadSettings();
          await this.loadDiagnostics();
        },

        computeInitials(name) {
          if (!name || typeof name !== 'string') return 'U';
          const parts = name.trim().split(/\s+/).filter(Boolean);
          if (parts.length === 0) return 'U';
          if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
          return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
        },

        getInitials(name) {
          return this.computeInitials(name);
        },

        formatDisplayDate(d) {
          if (!d) return '';
          if (typeof d === 'string' && d.includes(' ') && isNaN(Date.parse(d))) return d;
          try {
            const dt = new Date(d);
            if (isNaN(dt.getTime())) return d;
            return dt.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
          } catch(e) { return d; }
        },

        formatTaskDueSubline(t) {
          if (!t) return '';
          if (t.due_time && t.due_date) return t.due_time + ' • ' + this.formatDisplayDate(t.due_date);
          if (t.due_date) return 'Due ' + this.formatDisplayDate(t.due_date);
          if (t.due_time) return t.due_time;
          return 'No due date';
        },

        getProjectTasks(p) {
          if (!p || !p.id) return [];
          const pid = String(p.id);
          const pTitle = (p.title || '').trim().toLowerCase();
          return (this.tasks || []).filter(t => {
            if (t.project_id && String(t.project_id) === pid) return true;
            if (t.projectId && String(t.projectId) === pid) return true;
            if (pTitle && t.project_name && t.project_name.trim().toLowerCase() === pTitle) return true;
            return false;
          });
        },

        getProjectTeamMembers(p) {
          if (!p) return [];
          let names = [];
          if (Array.isArray(p.team_members)) {
            names = p.team_members;
          } else if (typeof p.team_members === 'string') {
            names = p.team_members.split(',').map(s => s.trim()).filter(Boolean);
          } else if (p.project_manager) {
            names = [p.project_manager];
          }
          if (names.length === 0) names = ['Rahul Sharma', 'Priya Verma'];
          
          return names.map(n => {
            const found = (this.teamMembers || []).find(m => m.name && m.name.toLowerCase() === n.toLowerCase());
            if (found) return found;
            return {
              id: 'tm_' + n.toLowerCase().replace(/[^a-z0-9]/g, '_'),
              name: n,
              initials: this.computeInitials(n),
              role: 'Team Member',
              colorClass: 'bg-blue-500'
            };
          });
        },

        openAddTaskForProject(p) {
          if (p && p.id) {
            this.activeProject = p;
            this.taskForm.project_id = p.id;
            this.taskForm.project_name = p.title || '';
          }
          this.openAddTaskScreen(p);
        },

        userGreeting() {
          const name = (this.currentUser && this.currentUser.name) ? this.currentUser.name.trim() : '';
          return name ? ('Good morning, ' + name + '!') : 'Good morning!';
        },

        async loadUserProfile() {
          try {
            const res = await fetch('api/auth.php?action=check_session');
            const data = await res.json();
            if (data && data.authenticated && data.user) {
              const u = data.user;
              const name = (u.name || '').trim();
              this.currentUser = {
                id: u.id || 0,
                name: name,
                email: u.email || '',
                role: u.role || 'user',
                avatar_url: u.avatar_url || '',
                initials: this.computeInitials(name)
              };
            } else if (data && data.authenticated === false) {
              localStorage.removeItem('software_crm_mobile_session');
              window.location.reload();
            }
          } catch (e) {
            // Keep server pre-rendered user
          }
        },

        showToast(msg, type = 'info') {
          this.toast = { show: true, message: msg, type: type };
          setTimeout(() => { this.toast.show = false; }, 3000);
        },

        navigateTo(view) {
          this.currentView = view;
          this.sideDrawerOpen = false;
          if (view === 'reports') {
            this.loadReports();
          }
          if (view === 'settings') {
            this.loadBiometricDevices();
            this.loadSettings();
            this.loadDiagnostics();
          }
          if (view === 'group_chart') {
            this.loadGroupChartData();
          }
        },

        // Settings & System Diagnostics Operations
        async loadSettings() {
          this.settingsLoading = true;
          try {
            const res = await fetch('api/settings.php?action=get_settings');
            const data = await res.json();
            if (data && data.success) {
              this.settingsData = data;
              if (data.csrf_token) {
                this.csrfToken = data.csrf_token;
              }
              if (data.preferences && data.preferences.theme) {
                const urlTheme = typeof window !== 'undefined' ? (new URLSearchParams(window.location.search)).get('theme') : null;
                const storedTheme = localStorage.getItem('crm_theme');
                const effectiveTheme = urlTheme || storedTheme || data.preferences.theme;
                this.settingsData.preferences.theme = effectiveTheme;
                this.applyTheme(effectiveTheme);
              }
              if (data.user && data.user.name) {
                this.currentUser.name = data.user.name;
              }
              this.editProfileForm = {
                name: data.user?.name || '',
                phone: data.profile?.phone || '',
                company: data.profile?.company || 'ABC Tech Solutions',
                department: data.profile?.department || 'Engineering',
                location: data.profile?.location || 'Bangalore, India',
                bio: data.profile?.bio || ''
              };
            }
          } catch (e) {
            console.error('Failed to load settings:', e);
          } finally {
            this.settingsLoading = false;
          }
        },

        async loadDiagnostics() {
          this.diagnosticsLoading = true;
          try {
            const res = await fetch('api/settings.php?action=diagnostics');
            const data = await res.json();
            if (data && data.success && data.diagnostics) {
              this.settingsDiagnostics = data.diagnostics;
            }
          } catch (e) {
            console.error('Failed to load diagnostics:', e);
          } finally {
            this.diagnosticsLoading = false;
          }
        },

        async syncData() {
          if (this.isSyncing) return;
          this.isSyncing = true;
          this.syncFeedback = null;
          try {
            const res = await fetch('api/settings.php?action=sync', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({ csrf_token: this.csrfToken })
            });
            const data = await res.json();
            if (data && data.success) {
              if (data.last_synced_at) {
                this.settingsData.last_synced_at = data.last_synced_at;
              }
              this.syncFeedback = {
                type: 'success',
                message: data.message || `Successfully synchronized ${data.synced_count || 0} employee records from Google Sheets.`
              };
              this.showToast(this.syncFeedback.message, 'success');
              await this.loadDiagnostics();
              if (typeof this.loadTeamMembers === 'function') {
                await this.loadTeamMembers();
              }
            } else {
              const errMsg = (data && data.error) || 'Failed to synchronize with Google Sheets.';
              this.syncFeedback = {
                type: 'error',
                message: errMsg,
                instructions: data.instructions || []
              };
              this.showToast(errMsg, 'error');
              await this.loadDiagnostics();
            }
          } catch (err) {
            const errMsg = err.message || 'Network error occurred during synchronization.';
            this.syncFeedback = {
              type: 'error',
              message: errMsg,
              instructions: ['Please check server network connection and retry.']
            };
            this.showToast(errMsg, 'error');
          } finally {
            this.isSyncing = false;
          }
        },

        openEditProfileModal() {
          this.editProfileForm = {
            name: this.settingsData.user?.name || this.currentUser.name || '',
            phone: this.settingsData.profile?.phone || '',
            company: this.settingsData.profile?.company || 'ABC Tech Solutions',
            department: this.settingsData.profile?.department || 'Engineering',
            location: this.settingsData.profile?.location || 'Bangalore, India',
            bio: this.settingsData.profile?.bio || ''
          };
          this.modalEditProfileOpen = true;
