        async saveProfile() {
          if (!this.editProfileForm.name || this.editProfileForm.name.trim().length < 2) {
            this.showToast('Please enter a valid full name (at least 2 characters)', 'error');
            return;
          }
          this.isUpdatingProfile = true;
          try {
            const res = await fetch('api/settings.php?action=update_profile', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({
                csrf_token: this.csrfToken,
                ...this.editProfileForm
              })
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast(data.message || 'Profile updated successfully', 'success');
              this.currentUser.name = this.editProfileForm.name.trim();
              if (this.settingsData.user) {
                this.settingsData.user.name = this.editProfileForm.name.trim();
              }
              if (this.settingsData.profile) {
                this.settingsData.profile = { ...this.editProfileForm };
              }
              this.modalEditProfileOpen = false;
            } else {
              this.showToast((data && data.error) || 'Failed to update profile', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Failed to update profile', 'error');
          } finally {
            this.isUpdatingProfile = false;
          }
        },

        openChangePasswordModal() {
          this.changePasswordForm = { current_password: '', new_password: '', confirm_password: '' };
          this.modalChangePasswordOpen = true;
        },

        async savePassword() {
          if (!this.changePasswordForm.current_password) {
            this.showToast('Current password is required', 'error');
