          if (this.changePasswordForm.new_password !== this.changePasswordForm.confirm_password) {
            this.showToast('New password and confirm password do not match', 'error');
            return;
          }
          this.isChangingPassword = true;
          try {
            const res = await fetch('api/settings.php?action=change_password', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({
                csrf_token: this.csrfToken,
                ...this.changePasswordForm
              })
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast(data.message || 'Password changed successfully', 'success');
              this.modalChangePasswordOpen = false;
              this.changePasswordForm = { current_password: '', new_password: '', confirm_password: '' };
            } else {
              this.showToast((data && data.error) || 'Failed to change password', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Failed to change password', 'error');
          } finally {
            this.isChangingPassword = false;
          }
        },

        async togglePreference(key) {
          const currentVal = !!this.settingsData.preferences[key];
          this.settingsData.preferences[key] = !currentVal;
          try {
            const res = await fetch('api/settings.php?action=update_preferences', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({
                csrf_token: this.csrfToken,
                ...this.settingsData.preferences
              })
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast('Preferences updated', 'info');
            }
          } catch (e) {
            console.error('Failed to update preference:', e);
          }
        },

        async setAppTheme(themeName) {
          if (!['light', 'dark', 'system'].includes(themeName)) {
            themeName = 'system';
          }
          if (!this.settingsData.preferences) {
            this.settingsData.preferences = {};
          }
          this.settingsData.preferences.theme = themeName;
          try {
            localStorage.setItem('crm_theme', themeName);
          } catch (e) {}

          // Apply theme immediately across the entire DOM without requiring page reload
          this.applyTheme(themeName);

          // Asynchronously persist to server database
          try {
            await fetch('api/settings.php?action=update_preferences', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({
                csrf_token: this.csrfToken,
                ...this.settingsData.preferences,
                theme: themeName
              })
            });
          } catch (e) {
            console.warn('Background theme sync warning:', e);
          }

          const label = themeName === 'system' ? 'System preference' : (themeName === 'dark' ? 'Dark theme' : 'Light theme');
          this.showToast(`Applied ${label}`, 'info');
        },

        applyTheme(themeName) {
          let resolved = themeName;
          if (themeName === 'system') {
            const isSystemDark = (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
            resolved = isSystemDark ? 'dark' : 'light';
          }

          const root = document.documentElement;
          if (resolved === 'dark') {
            root.classList.add('dark');
            root.setAttribute('data-theme', 'dark');
            root.style.colorScheme = 'dark';
          } else {
            root.classList.remove('dark');
            root.setAttribute('data-theme', 'light');
            root.style.colorScheme = 'light';
          }

          // Update theme-color meta tag for browser UI / mobile status bars
          const metaTheme = document.querySelector('meta[name="theme-color"]');
          if (metaTheme) {
            metaTheme.setAttribute('content', resolved === 'dark' ? '#140708' : '#FAF7F2');
          }

          // Dynamically adapt Chart.js labels, grid lines and legends if rendered
          if (typeof Chart !== 'undefined') {
            const isDark = (resolved === 'dark');
            Chart.defaults.color = isDark ? '#94a3b8' : '#64748b';
            Chart.defaults.borderColor = isDark ? '#24344d' : '#e2e8f0';
            if (window._crmCharts) {
              Object.values(window._crmCharts).forEach(chart => {
                if (chart && chart.options) {
                  if (chart.options.scales) {
                    Object.values(chart.options.scales).forEach(scale => {
                      if (scale.ticks) scale.ticks.color = isDark ? '#94a3b8' : '#64748b';
                      if (scale.grid) scale.grid.color = isDark ? '#24344d' : '#f1f5f9';
                    });
                  }
                  if (typeof chart.update === 'function') {
                    chart.update('none');
                  }
                }
              });
            }
          }
        },

        setupSystemThemeListener() {
          if (typeof window !== 'undefined' && window.matchMedia) {
            const mql = window.matchMedia('(prefers-color-scheme: dark)');
            const handler = (e) => {
              const currentPref = this.settingsData?.preferences?.theme || localStorage.getItem('crm_theme') || 'system';
              if (currentPref === 'system') {
                this.applyTheme('system');
              }
            };
            if (mql.addEventListener) {
              mql.addEventListener('change', handler);
            } else if (mql.addListener) {
              mql.addListener(handler);
            }
          }
        },

        async revokeSessions() {
          if (!confirm('Are you sure you want to revoke all other active sessions? You will stay logged in on this device.')) {
            return;
          }
          this.isRevokingSessions = true;
          try {
            const res = await fetch('api/settings.php?action=revoke_sessions', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken
              },
              body: JSON.stringify({ csrf_token: this.csrfToken })
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast(data.message || 'All other active sessions revoked', 'success');
            } else {
              this.showToast((data && data.error) || 'Failed to revoke sessions', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Failed to revoke sessions', 'error');
          } finally {
            this.isRevokingSessions = false;
          }
        },

        // Biometric & Device Security Operations
        async loadBiometricDevices() {
          this.biometricLoading = true;
          try {
            const res = await fetch('api/biometric_auth.php?action=list_devices');
            const data = await res.json();
            if (data && data.success && Array.isArray(data.devices)) {
              this.biometricDevices = data.devices;
            } else {
              this.biometricDevices = [];
            }
          } catch (e) {
            console.error('Failed to load biometric devices:', e);
            this.biometricDevices = [];
          } finally {
            this.biometricLoading = false;
          }
        },

        async enrollBiometricDevice() {
          if (!window.BiometricClient) {
            this.showToast('Biometric client library not loaded', 'error');
            return;
          }
          const isAvail = await window.BiometricClient.isAvailable();
          if (!isAvail) {
            this.showToast('This device does not support fingerprint or face recognition', 'error');
            return;
          }

          let defaultName = 'Mobile Phone';
          const ua = navigator.userAgent;
          if (/iPhone/i.test(ua)) defaultName = 'Apple iPhone';
          else if (/iPad/i.test(ua)) defaultName = 'Apple iPad';
          else if (/Android/i.test(ua)) defaultName = 'Android Smartphone';
          else if (/Macintosh/i.test(ua)) defaultName = 'MacBook Face/Touch ID';
          else if (/Windows/i.test(ua)) defaultName = 'Windows Hello Device';

          const deviceName = window.prompt('Enter a recognizable name for this device:', defaultName) || defaultName;

          this.isEnrollingDevice = true;
          try {
            const result = await window.BiometricClient.registerDevice(deviceName);
            if (result && result.success) {
              this.showToast(result.message || 'Device registered successfully with biometric security!', 'success');
              await this.loadBiometricDevices();
            } else {
              this.showToast((result && result.error) || 'Failed to enroll biometric device', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Biometric enrollment failed', 'error');
          } finally {
            this.isEnrollingDevice = false;
          }
        },

        promptRemoveDevice(dev) {
          this.deviceToRemove = dev;
          this.modalConfirmRemoveDeviceOpen = true;
        },

        async confirmRemoveDevice() {
          if (!this.deviceToRemove || !this.deviceToRemove.credential_id) return;
          this.isRemovingDevice = true;
          try {
            const res = await fetch('api/biometric_auth.php?action=remove_device', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ credential_id: this.deviceToRemove.credential_id })
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast(data.message || 'Device removed successfully', 'success');
              this.modalConfirmRemoveDeviceOpen = false;
              this.deviceToRemove = null;
              await this.loadBiometricDevices();
            } else {
              this.showToast((data && data.error) || 'Failed to remove device', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Failed to remove device', 'error');
          } finally {
            this.isRemovingDevice = false;
          }
        },

        promptDisableAllBiometrics() {
          this.modalConfirmDisableAllBiometricsOpen = true;
        },

        async confirmDisableAllBiometrics() {
          this.isDisablingAllBiometrics = true;
          try {
            const res = await fetch('api/biometric_auth.php?action=disable_biometrics', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({})
            });
            const data = await res.json();
            if (data && data.success) {
              this.showToast(data.message || 'Biometric login disabled for all devices', 'success');
              this.modalConfirmDisableAllBiometricsOpen = false;
              await this.loadBiometricDevices();
            } else {
              this.showToast((data && data.error) || 'Failed to disable biometrics', 'error');
            }
          } catch (err) {
            this.showToast(err.message || 'Failed to disable biometrics', 'error');
          } finally {
            this.isDisablingAllBiometrics = false;
          }
        },

        // API Data Loaders
        async loadAllData() {
          try {
            const resC = await fetch('api/pocket_api.php?action=get_contacts');
            const dataC = await resC.json();
            if (dataC && dataC.data) {
              this.contacts = dataC.data;
              if (this.activeContact) {
                const refreshed = this.contacts.find(c => c.id === this.activeContact.id);
                if (refreshed) this.activeContact = refreshed;
              } else if (this.contacts.length > 0) {
                this.activeContact = this.contacts[0];
              }
            }

            const resP = await fetch('api/software.php');
            const dataP = await resP.json();
            if (dataP && dataP.data) {
              this.projects = dataP.data;
              if (this.activeProject) {
                const refreshed = this.projects.find(p => p.id === this.activeProject.id);
                if (refreshed) this.activeProject = refreshed;
              } else if (this.projects.length > 0) {
                this.activeProject = this.projects[0];
              }
            }

            const resT = await fetch('api/tasks.php');
            const dataT = await resT.json();
            if (dataT && dataT.data) {
              this.tasks = dataT.data;
              if (this.activeTask) {
                const refreshed = this.tasks.find(x => x.id === this.activeTask.id);
                if (refreshed) this.activeTask = refreshed;
              } else if (this.tasks.length > 0) {
                this.activeTask = this.tasks[0];
              }
            }

            const resI = await fetch('api/ledger.php');
            const dataI = await resI.json();
            if (dataI && dataI.data) {
              this.invoices = dataI.data;
              if (dataI.summary && dataI.summary.total_revenue) {
                this.revenueTotal = dataI.summary.total_revenue;
              }
            }

            // Load Calendar Events
            await this.loadCalendarEvents();

            // Load Team Members
            await this.loadTeamMembers();

            // Load Companies
            await this.loadCompanies();

            // Load Groups & Team Structure
            await this.loadGroupChartData();

            // Load Notifications & Start Background Polling
            await this.loadNotifications();
            this.startNotificationsPolling();
          } catch (e) {
            console.error('Data load error:', e);
          }
        },

        // Computed Filters
        get filteredContacts() {
          return this.contacts.filter(c => {
            const matchesFilter = this.contactFilter === 'all' || (c.category && c.category.toLowerCase() === this.contactFilter.toLowerCase());
            const q = this.contactSearchQuery.toLowerCase();
            const matchesSearch = !q || (c.name && c.name.toLowerCase().includes(q)) || (c.company && c.company.toLowerCase().includes(q)) || (c.phone && c.phone.includes(q));
            return matchesFilter && matchesSearch;
          });
        },

        get filteredProjects() {
          if (this.projectFilter === 'all') return this.projects;
          const f = this.projectFilter.toLowerCase();
          return this.projects.filter(p => {
            const s = (p.status || '').toLowerCase();
            if (f === 'in progress' || f === 'active') {
              return s === 'in progress' || s === 'active';
            }
            if (f === 'completed') {
              return s === 'completed';
            }
            return s === f;
          });
        },

        get sortedCompanies() {
          let list = Array.isArray(this.companies) ? [...this.companies] : [];
          if (this.groupCompanySearch && this.groupCompanySearch.trim()) {
            const q = this.groupCompanySearch.trim().toLowerCase();
            list = list.filter(c => 
              (c.id === this.groupForm.company_id) ||
              (c.name && c.name.toLowerCase().includes(q)) || 
              (c.industry && c.industry.toLowerCase().includes(q))
            );
          }
          return list.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        },

        get filteredGroups() {
          const q = (this.groupSearchQuery || '').trim().toLowerCase();
          if (!q) return this.groups || [];
          return (this.groups || []).filter(g => {
            return (g.name && g.name.toLowerCase().includes(q)) ||
                   (g.description && g.description.toLowerCase().includes(q)) ||
                   (g.company_name && g.company_name.toLowerCase().includes(q)) ||
                   (g.leader_name && g.leader_name.toLowerCase().includes(q));
          });
        },

        get filteredAvailableEmployees() {
          const q = (this.employeeSearchQuery || '').trim().toLowerCase();
          if (!q) return this.availableGroupEmployees || [];
          return (this.availableGroupEmployees || []).filter(e => {
            return (e.name && e.name.toLowerCase().includes(q)) ||
                   (e.role && e.role.toLowerCase().includes(q)) ||
                   (e.department && e.department.toLowerCase().includes(q)) ||
                   (e.email && e.email.toLowerCase().includes(q));
          });
        },

        get filteredTaskAvailableMembers() {
          const q = (this.taskMemberSearchQuery || '').trim().toLowerCase();
          const list = this.teamMembers || [];
          if (!q) return list;
          return list.filter(m => {
            return (m.name && m.name.toLowerCase().includes(q)) ||
                   (m.email && m.email.toLowerCase().includes(q)) ||
                   (m.role && m.role.toLowerCase().includes(q)) ||
                   (m.department && m.department.toLowerCase().includes(q));
          });
        },

        get filteredChatChannels() {
          let list = [];
          // Groups
          if (this.chatChannelFilter === 'All' || this.chatChannelFilter === 'Groups') {
            for (const g of (this.groups || [])) {
              list.push({
                id: g.id,
                channel_type: 'group',
                name: g.name,
                description: g.description,
                color: g.color || '#590907',
                member_count: g.member_count || 0,
                icon: 'users',
                raw: g
              });
            }
          }
          // Projects
          if (this.chatChannelFilter === 'All' || this.chatChannelFilter === 'Projects') {
            for (const p of (this.projects || [])) {
              list.push({
                id: p.id,
                channel_type: 'project',
                name: p.title || p.name,
                description: p.description || p.category,
                color: '#10b981',
                member_count: 4,
                icon: 'folder',
                raw: p
              });
            }
          }
          if (this.chatSearchQuery && this.chatSearchQuery.trim()) {
            const sq = this.chatSearchQuery.toLowerCase().trim();
            list = list.filter(c => (c.name && c.name.toLowerCase().includes(sq)) || (c.description && c.description.toLowerCase().includes(sq)));
          }
          return list;
        },

        // Financial & Invoice Computed Getters (Exact Screen 1 Reference)
        get summaryTotalInvoiced() {
          return this.invoices.reduce((sum, inv) => sum + (Number(inv.amount) || 0), 0);
        },

        get summaryTotalPaid() {
          return this.invoices.reduce((sum, inv) => {
            const st = (inv.status || '').toLowerCase();
            const paid = Number(inv.paid_amount) || 0;
            if (st === 'paid' && paid <= 0) return sum + (Number(inv.amount) || 0);
            return sum + paid;
          }, 0);
        },

        get summaryTotalPending() {
          return this.invoices.reduce((sum, inv) => {
            const st = (inv.status || '').toLowerCase();
            if (st === 'paid') return sum;
            const amt = Number(inv.amount) || 0;
            const paid = Number(inv.paid_amount) || 0;
            const bal = Number(inv.balance_amount);
            const effBal = (!isNaN(bal) && bal !== null) ? bal : Math.max(0, amt - paid);
            // If overdue, don't double count in pending
            if (this.isInvoiceOverdue(inv)) return sum;
            return sum + effBal;
          }, 0);
        },

        get summaryTotalOverdue() {
          return this.invoices.reduce((sum, inv) => {
            const st = (inv.status || '').toLowerCase();
            if (st === 'paid') return sum;
            if (this.isInvoiceOverdue(inv)) {
              const amt = Number(inv.amount) || 0;
              const paid = Number(inv.paid_amount) || 0;
              const bal = Number(inv.balance_amount);
              return sum + ((!isNaN(bal) && bal !== null) ? bal : Math.max(0, amt - paid));
            }
            return sum;
          }, 0);
        },

        isInvoiceOverdue(inv) {
          if (!inv) return false;
          const st = (inv.status || '').toLowerCase();
          if (st === 'overdue') return true;
          if (st === 'paid') return false;
          const amt = Number(inv.amount) || 0;
          const paid = Number(inv.paid_amount) || 0;
          const bal = Number(inv.balance_amount);
          const remaining = (!isNaN(bal) && bal !== null) ? bal : Math.max(0, amt - paid);
          if (remaining <= 0) return false;
          if (inv.due_date) {
            const dueTs = Date.parse(inv.due_date);
            if (!isNaN(dueTs)) {
              const today = new Date();
              today.setHours(0, 0, 0, 0);
              return dueTs < today.getTime();
            }
          }
          return false;
        },

        get countAllInvoices() {
          return this.invoices.length;
        },

        get countPaidInvoices() {
          return this.invoices.filter(i => (i.status || '').toLowerCase() === 'paid').length;
        },

        get countPendingInvoices() {
          return this.invoices.filter(i => {
            const s = (i.status || '').toLowerCase();
            return (s === 'pending' || s === 'partially paid') && !this.isInvoiceOverdue(i);
          }).length;
        },

        get countOverdueInvoices() {
          return this.invoices.filter(i => this.isInvoiceOverdue(i)).length;
        },

        get filteredInvoices() {
          return this.invoices.filter(inv => {
            const f = (this.invoiceFilter || 'all').toLowerCase();
            const isOv = this.isInvoiceOverdue(inv);
            const st = (inv.status || '').toLowerCase();

            let matchesFilter = true;
            if (f === 'all') {
              matchesFilter = true;
            } else if (f === 'paid') {
              matchesFilter = (st === 'paid');
            } else if (f === 'pending') {
              matchesFilter = (st === 'pending' || st === 'partially paid') && !isOv;
            } else if (f === 'overdue') {
              matchesFilter = isOv;
            } else {
              matchesFilter = (st === f);
            }

            const q = (this.invoiceSearchQuery || '').toLowerCase().trim();
            const matchesSearch = !q ||
              (inv.invoice_no && inv.invoice_no.toLowerCase().includes(q)) ||
              (inv.customer_name && inv.customer_name.toLowerCase().includes(q)) ||
              (inv.title && inv.title.toLowerCase().includes(q)) ||
              (inv.id && inv.id.toLowerCase().includes(q));

            return matchesFilter && matchesSearch;
          });
        },

        get computedInvoiceSubtotal() {
          return (this.invoiceForm.items || []).reduce((sum, it) => sum + (Number(it.amount) || 0), 0);
        },

        get computedInvoiceDiscount() {
          const sub = this.computedInvoiceSubtotal;
          const disc = Number(this.invoiceForm.discount_percent) || 0;
          return Math.round(sub * (disc / 100) * 100) / 100;
        },

        get computedInvoiceTax() {
          const taxable = Math.max(0, this.computedInvoiceSubtotal - this.computedInvoiceDiscount);
          const tax = Number(this.invoiceForm.tax_percent) || 0;
          return Math.round(taxable * (tax / 100) * 100) / 100;
        },

        get computedInvoiceTotal() {
          const taxable = Math.max(0, this.computedInvoiceSubtotal - this.computedInvoiceDiscount);
          return Math.round((taxable + this.computedInvoiceTax) * 100) / 100;
        },

        get uniqueCompanies() {
          const q = (this.companySearchQuery || '').toLowerCase().trim();
          if (!this.companies || !Array.isArray(this.companies)) return [];
          return this.companies.filter(c => {
            if (!q) return true;
            return (c.name && c.name.toLowerCase().includes(q)) ||
                   (c.industry && c.industry.toLowerCase().includes(q)) ||
                   (c.email && c.email.toLowerCase().includes(q)) ||
                   (c.phone && c.phone.includes(q)) ||
                   (c.address && c.address.toLowerCase().includes(q));
          });
        },

        // Team Computed Getters
        get filteredTeamMembers() {
          return this.teamMembers.filter(m => {
            const matchesFilter = this.teamFilter === 'all' || (m.status && m.status.toLowerCase() === this.teamFilter.toLowerCase());
            const q = (this.teamSearchQuery || '').toLowerCase().trim();
            const matchesSearch = !q || 
              (m.name && m.name.toLowerCase().includes(q)) || 
              (m.role && m.role.toLowerCase().includes(q)) || 
              (m.department && m.department.toLowerCase().includes(q)) || 
              (m.email && m.email.toLowerCase().includes(q)) || 
              (m.phone && m.phone.includes(q)) || 
              (m.skills && m.skills.toLowerCase().includes(q));
            return matchesFilter && matchesSearch;
          });
        },

        get allTeamMembersCount() {
          return this.teamMembers.length;
        },

        get activeTeamMembersCount() {
          return this.teamMembers.filter(m => (m.status || '').toLowerCase() === 'active').length;
        },

        get inactiveTeamMembersCount() {
          return this.teamMembers.filter(m => (m.status || '').toLowerCase() === 'inactive').length;
        },

        // Task Computed Getters
        get uniqueTaskProjects() {
          const set = new Set();
          this.tasks.forEach(t => {
            if (t.project_name && t.project_name.trim()) set.add(t.project_name.trim());
          });
          this.projects.forEach(p => {
            if (p.title && p.title.trim()) set.add(p.title.trim());
          });
          return Array.from(set);
        },

        get completedTasksCount() {
          return this.tasks.filter(t => Number(t.completed) === 1).length;
        },

        get totalTasksCount() {
          return this.tasks.length;
        },

        get allTasksCount() {
          return this.tasks.length;
        },

        get myTasksCount() {
          const count = this.tasks.filter(t => !Number(t.completed) && (!t.assigned_staff || t.assigned_staff.includes('Rahul') || t.assigned_staff.includes('Akash'))).length;
          return count > 0 ? count : this.tasks.filter(t => !Number(t.completed)).length;
        },

        get overdueTasksCount() {
          return this.tasks.filter(t => !Number(t.completed) && this.isTaskOverdue(t)).length;
        },

        get taskCompletionPercentage() {
          if (!this.tasks || this.tasks.length === 0) return 0;
          return Math.round((this.completedTasksCount / this.tasks.length) * 100);
        },

        get filteredTasks() {
          return this.tasks.filter(t => {
            // 1. Tab filter
            if (this.taskFilter === 'my') {
              const isMy = !t.assigned_staff || t.assigned_staff.includes('Rahul') || t.assigned_staff.includes('Akash');
              if (!isMy) return false;
            } else if (this.taskFilter === 'overdue') {
              if (!this.isTaskOverdue(t)) return false;
            }

            // 2. Project filter dropdown
            if (this.taskProjectFilter && this.taskProjectFilter !== 'all') {
              const pFilter = this.taskProjectFilter.toLowerCase();
              const pName = (t.project_name || '').toLowerCase();
              const pId = (t.project_id || '').toString().toLowerCase();
              if (pName !== pFilter && pId !== pFilter && !pName.includes(pFilter)) return false;
            }

            // 3. Priority filter dropdown
            if (this.taskPriorityFilter && this.taskPriorityFilter !== 'all') {
              if ((t.priority || '').toLowerCase() !== this.taskPriorityFilter.toLowerCase()) return false;
            }

            // 4. Status filter dropdown
            if (this.taskStatusFilter && this.taskStatusFilter !== 'all') {
              const sFilter = this.taskStatusFilter.toLowerCase();
              const isComp = Number(t.completed) === 1 || (t.status || '').toLowerCase() === 'completed';
              if (sFilter === 'completed' && !isComp) return false;
              if (sFilter === 'in progress' && (isComp || (t.status || '').toLowerCase() === 'pending')) return false;
              if (sFilter === 'pending' && (isComp || (t.status || '').toLowerCase() === 'in progress')) return false;
            }

            // 5. Search query
            if (this.taskSearchQuery && this.taskSearchQuery.trim()) {
              const q = this.taskSearchQuery.toLowerCase().trim();
              const matchTitle = (t.title || '').toLowerCase().includes(q);
              const matchDesc = (t.description || '').toLowerCase().includes(q);
              const matchProj = (t.project_name || '').toLowerCase().includes(q);
              const matchStaff = (t.assigned_staff || '').toLowerCase().includes(q);
              if (!matchTitle && !matchDesc && !matchProj && !matchStaff) return false;
            }

            return true;
          });
        },

        // =====================================================================
        // CALENDAR COMPUTED GETTERS (Exact Reference Implementation)
        // =====================================================================
        get todayDateStr() {
          const now = new Date();
          const y = now.getFullYear();
          const m = String(now.getMonth() + 1).padStart(2, '0');
          const d = String(now.getDate()).padStart(2, '0');
          return `${y}-${m}-${d}`;
        },

        get calendarMonthTitle() {
          const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
          return `${months[this.calendarViewMonth]} ${this.calendarViewYear}`;
        },

        get calendarMonthSubTitle() {
          if (!this.selectedCalendarDate) return '';
          const parts = this.selectedCalendarDate.split('-');
          if (parts.length !== 3) return '';
          const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
          const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
          const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
          return `${weekdays[d.getDay()]}, ${months[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;
        },

        get selectedDateFormattedTitle() {
          return this.calendarMonthSubTitle;
        },

        get holidaysMap() {
          const y = this.calendarViewYear;
          const map = {
            [`${y}-01-01`]: { name: "New Year's Day", type: 'Public Holiday' },
            [`${y}-01-26`]: { name: 'Republic Day', type: 'Gazetted Holiday' },
            [`${y}-05-01`]: { name: 'Labour Day / Maharashtra Day', type: 'Public Holiday' },
            [`${y}-08-15`]: { name: 'Independence Day', type: 'Gazetted Holiday' },
            [`${y}-10-02`]: { name: 'Gandhi Jayanti', type: 'Gazetted Holiday' },
            [`${y}-12-25`]: { name: 'Christmas Day', type: 'Gazetted Holiday' }
          };

          // Confirmed Lunisolar / Festival Holidays by Year
          if (y === 2026) {
            map['2026-03-04'] = { name: 'Holi', type: 'Gazetted Holiday' };
            map['2026-03-20'] = { name: 'Eid-ul-Fitr', type: 'Gazetted Holiday' };
            map['2026-04-03'] = { name: 'Good Friday', type: 'Gazetted Holiday' };
            map['2026-05-27'] = { name: 'Bakrid / Eid ul-Adha', type: 'Gazetted Holiday' };
            map['2026-08-28'] = { name: 'Raksha Bandhan', type: 'Public Holiday' };
            map['2026-09-04'] = { name: 'Janmashtami', type: 'Gazetted Holiday' };
            map['2026-10-14'] = { name: 'Maha Navami', type: 'Gazetted Holiday' };
            map['2026-10-23'] = { name: 'Dussehra (Vijayadashami)', type: 'Gazetted Holiday' };
            map['2026-11-08'] = { name: 'Diwali (Deepavali)', type: 'Gazetted Holiday' };
            map['2026-11-24'] = { name: 'Guru Nanak Jayanti', type: 'Gazetted Holiday' };
          } else if (y === 2024) {
            map['2024-03-25'] = { name: 'Holi', type: 'Gazetted Holiday' };
            map['2024-03-29'] = { name: 'Good Friday', type: 'Gazetted Holiday' };
            map['2024-04-11'] = { name: 'Eid-ul-Fitr', type: 'Gazetted Holiday' };
            map['2024-10-12'] = { name: 'Dussehra', type: 'Gazetted Holiday' };
            map['2024-11-01'] = { name: 'Diwali', type: 'Gazetted Holiday' };
          } else if (y === 2025) {
            map['2025-03-14'] = { name: 'Holi', type: 'Gazetted Holiday' };
            map['2025-03-31'] = { name: 'Eid-ul-Fitr', type: 'Gazetted Holiday' };
            map['2025-04-18'] = { name: 'Good Friday', type: 'Gazetted Holiday' };
            map['2025-10-02'] = { name: 'Dussehra / Gandhi Jayanti', type: 'Gazetted Holiday' };
            map['2025-10-20'] = { name: 'Diwali', type: 'Gazetted Holiday' };
          } else if (y === 2027) {
            map['2027-03-22'] = { name: 'Holi', type: 'Gazetted Holiday' };
            map['2027-03-26'] = { name: 'Good Friday', type: 'Gazetted Holiday' };
            map['2027-10-11'] = { name: 'Dussehra', type: 'Gazetted Holiday' };
            map['2027-10-29'] = { name: 'Diwali', type: 'Gazetted Holiday' };
          }
          return map;
        },

        get calendarGridDays() {
          const y = this.calendarViewYear;
          const m = this.calendarViewMonth;

          const firstDay = new Date(y, m, 1).getDay();
          const daysInCurrentMonth = new Date(y, m + 1, 0).getDate();
          const daysInPrevMonth = new Date(y, m, 0).getDate();

          const prevMonthYear = m === 0 ? y - 1 : y;
          const prevMonthNum = m === 0 ? 12 : m;
          const nextMonthYear = m === 11 ? y + 1 : y;
          const nextMonthNum = m === 11 ? 1 : m + 2;

          const days = [];

          // 1. Previous month trailing days
          for (let i = firstDay - 1; i >= 0; i--) {
            const dNum = daysInPrevMonth - i;
            const dateStr = `${prevMonthYear}-${String(prevMonthNum).padStart(2, '0')}-${String(dNum).padStart(2, '0')}`;
            days.push(this.buildCalendarDay(dateStr, dNum, false));
          }

          // 2. Current month days
          for (let d = 1; d <= daysInCurrentMonth; d++) {
            const dateStr = `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            days.push(this.buildCalendarDay(dateStr, d, true));
          }

          // 3. Next month leading days to complete the 7-column grid
          const totalCells = days.length;
          const targetTotal = totalCells <= 35 ? 35 : 42;
          const nextDaysCount = targetTotal - totalCells;
          for (let d = 1; d <= nextDaysCount; d++) {
            const dateStr = `${nextMonthYear}-${String(nextMonthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            days.push(this.buildCalendarDay(dateStr, d, false));
          }

          return days;
        },

        get selectedDateAgendaItems() {
          const dStr = this.selectedCalendarDate;
          if (!dStr) return [];
          const items = [];

          // 1. Events from crm_calendar_events
          const evs = this.calendarEvents.filter(e => e.event_date === dStr);
          evs.forEach(e => {
            const cat = e.category || 'Meeting';
            let badgeClass = 'bg-blue-50 text-blue-700';
            if (cat === 'Call') badgeClass = 'bg-emerald-50 text-emerald-700';
            else if (cat === 'Review') badgeClass = 'bg-blue-50 text-blue-700';
            else if (cat === 'Deadline') badgeClass = 'bg-rose-50 text-rose-700';
            else if (cat === 'Task') badgeClass = 'bg-amber-50 text-amber-700';

            items.push({
              id: e.id,
              type: 'event',
              title: e.title,
              time: e.event_time || '10:00 AM',
              endTime: e.end_time || '',
              category: cat,
              color: e.color || (cat === 'Call' ? '#10b981' : cat === 'Task' ? '#f59e0b' : '#590907'),
              location: e.location || (e.description ? e.description : 'Conference Room'),
              description: e.description || '',
              badgeClass: badgeClass,
              badgeText: cat,
              raw: e
            });
          });

          // 2. Tasks due on this date
          const ts = this.tasks.filter(t => {
            if (t.due_date && t.due_date === dStr) return true;
            if (t.due_time && t.due_time.includes(dStr)) return true;
            return false;
          });
          ts.forEach(t => {
            items.push({
              id: 'task_' + t.id,
              type: 'task',
              title: t.title,
              time: t.due_time || '02:00 PM',
              endTime: '03:00 PM',
              category: 'Task',
              color: '#f59e0b',
              location: (t.project_name || 'Project') + ' • Discussion',
              description: t.description || '',
              badgeClass: 'bg-amber-50 text-amber-700',
              badgeText: 'Task',
              taskRaw: t
            });
          });

          // 3. Holidays
          const h = this.holidaysMap[dStr];
          if (h) {
            items.push({
              id: 'hol_' + dStr,
              type: 'holiday',
              title: h.name,
              time: 'All Day',
              endTime: '',
              category: 'Holiday',
              color: '#ef4444',
              location: h.type || 'Public Holiday',
              description: h.name,
              badgeClass: 'bg-rose-50 text-rose-700',
              badgeText: 'Holiday'
            });
          }

          // Sort: timed events first, All Day holidays last
          return items.sort((a, b) => {
            if (a.time === 'All Day') return 1;
            if (b.time === 'All Day') return -1;
            return a.time.localeCompare(b.time);
          });
        },

        get selectedDateCountsText() {
          const dStr = this.selectedCalendarDate;
          if (!dStr) return '0 Scheduled';
          const evCount = this.calendarEvents.filter(e => e.event_date === dStr).length;
          const taskCount = this.tasks.filter(t => (t.due_date && t.due_date === dStr) || (t.due_time && t.due_time.includes(dStr))).length;
          const holCount = this.holidaysMap[dStr] ? 1 : 0;

          const parts = [];
          if (evCount > 0) parts.push(`${evCount} ${evCount === 1 ? 'Event' : 'Events'}`);
          if (taskCount > 0) parts.push(`${taskCount} ${taskCount === 1 ? 'Task' : 'Tasks'}`);
          if (holCount > 0) parts.push(`${holCount} ${holCount === 1 ? 'Holiday' : 'Holidays'}`);

          if (parts.length === 0) return '0 Scheduled';
          return parts.join(' • ');
        },

