        getAssociatedProjects(c) {
          if (!c) return [];
          const cName = (c.name || '').trim().toLowerCase();
          const cCompany = (c.company || '').trim().toLowerCase();
          const cId = c.id;
          return this.projects.filter(p => {
            const pClient = (p.client_name || '').trim().toLowerCase();
            const pClientId = p.client_id;
            return (pClient && (pClient === cName || (cCompany && pClient === cCompany))) || (pClientId && pClientId == cId);
          });
