        getAssociatedInvoices(c) {
          if (!c) return [];
          const cName = (c.name || '').trim().toLowerCase();
          const cCompany = (c.company || '').trim().toLowerCase();
          const cId = c.id;
          return this.invoices.filter(inv => {
            const invClient = (inv.customer_name || '').trim().toLowerCase();
            const invClientId = inv.client_id;
            return (invClient && (invClient === cName || (cCompany && invClient === cCompany))) || (invClientId && invClientId == cId);
          });
