            country_code: parsedPhone.country_code,
            phone_number: parsedPhone.phone_number,
            phone: c.phone || '',
            email: c.email || '',
            location: c.location || c.address || '',
            category: c.category || 'Client',
            source: c.source || c.lead_from || 'Website',
            tags: tagsArr,
            notes: c.notes || ''
          };
          this.tagInput = '';
          this.contactFormError = '';
          this.contactFormDirty = false;
          this.initialContactFormJson = JSON.stringify(this.contactForm);
          this.modalContactOpen = true;
          this.modalContactMenuOpen = false;
          this.modalContactMoreActionsOpen = false;
        },

        openEditModal(c) {
          this.openEditContact(c);
        },

        parsePhoneNumber(fullPhone) {
          if (!fullPhone) return { country_code: '+91', phone_number: '' };
          fullPhone = String(fullPhone).trim();
          const knownCodes = ['+971', '+61', '+65', '+49', '+33', '+44', '+91', '+1', '+81'];
          for (const code of knownCodes) {
            if (fullPhone.startsWith(code)) {
              return {
                country_code: code,
                phone_number: fullPhone.substring(code.length).trim()
              };
            }
          }
          if (fullPhone.startsWith('+')) {
            const parts = fullPhone.split(' ');
            return { country_code: parts[0], phone_number: parts.slice(1).join(' ') };
          }
          return { country_code: '+91', phone_number: fullPhone };
        },

        addTag(tag) {
          tag = (tag || this.tagInput || '').trim();
          if (!tag) return;
          if (!this.contactForm.tags) this.contactForm.tags = [];
          if (!this.contactForm.tags.includes(tag)) {
            this.contactForm.tags.push(tag);
          }
          this.tagInput = '';
        },

        removeTag(index) {
          if (this.contactForm.tags) {
            this.contactForm.tags.splice(index, 1);
          }
        },

        closeContactModal() {
          if (JSON.stringify(this.contactForm) !== this.initialContactFormJson) {
            this.modalConfirmDiscardContactOpen = true;
            return;
          }
          this.modalContactOpen = false;
        },

        forceCloseContactModal() {
          this.modalConfirmDiscardContactOpen = false;
          this.modalContactOpen = false;
        },

        async submitContactForm() {
          this.contactFormError = '';
          const name = (this.contactForm.name || '').trim();
          const phoneNumber = (this.contactForm.phone_number || '').trim();
          const fullPhone = `${this.contactForm.country_code} ${phoneNumber}`.trim();

          if (!name) {
            this.contactFormError = 'Full Name is required.';
            return;
          }
          if (!phoneNumber) {
            this.contactFormError = 'Phone Number is required.';
            return;
          }
          if (this.contactForm.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.contactForm.email.trim())) {
            this.contactFormError = 'Please provide a valid email address.';
            return;
          }

          this.isSubmittingContact = true;
          const payload = {
            id: this.contactForm.id || '',
            name: name,
            company: (this.contactForm.company || '').trim(),
            position: (this.contactForm.position || '').trim(),
            phone: fullPhone,
            email: (this.contactForm.email || '').trim(),
            location: (this.contactForm.location || '').trim(),
            category: this.contactForm.category || 'Client',
            source: this.contactForm.source || 'Website',
            tags: this.contactForm.tags || [],
            notes: (this.contactForm.notes || '').trim()
          };

          try {
            const res = await fetch('api/pocket_api.php?action=save_contact', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });
            const data = await res.json();
            if (data.status === 'success') {
              this.modalContactOpen = false;
              this.showToast(this.contactForm.id ? 'Contact updated!' : 'Contact created!');
              await this.loadAllData();
              if (this.contactForm.id) {
                const updated = this.contacts.find(c => c.id === this.contactForm.id);
                if (updated) this.activeContact = updated;
              } else if (data.data && data.data.id) {
                const created = this.contacts.find(c => c.id === data.data.id);
                if (created) this.viewContactDetail(created);
              }
            } else {
              this.contactFormError = data.message || 'Failed to save contact';
            }
          } catch (e) {
            this.contactFormError = 'Network error saving contact. Please try again.';
          } finally {
            this.isSubmittingContact = false;
          }
        },

        async duplicateContact(c) {
          if (!c) return;
          this.modalContactMenuOpen = false;
          try {
            const res = await fetch('api/pocket_api.php?action=duplicate_contact', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ id: c.id })
            });
            const data = await res.json();
            if (data.status === 'success') {
              this.showToast('Contact duplicated successfully');
              await this.loadAllData();
              if (data.data && data.data.id) {
                const found = this.contacts.find(x => x.id === data.data.id);
                if (found) this.viewContactDetail(found);
              }
            } else {
              this.showToast(data.message || 'Error duplicating contact', 'error');
            }
          } catch (e) {
            this.showToast('Network error duplicating contact', 'error');
          }
        },

        openDeleteContactModal(c) {
          this.contactToDelete = c || this.activeContact;
          this.modalDeleteContactOpen = true;
          this.modalContactMenuOpen = false;
          this.modalContactMoreActionsOpen = false;
        },

        async executeDeleteContact() {
          if (!this.contactToDelete) return;
          this.isDeletingContact = true;
          try {
            const res = await fetch('api/pocket_api.php?action=delete_contact', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ id: this.contactToDelete.id })
            });
            const data = await res.json();
            if (data.status === 'success') {
              this.modalDeleteContactOpen = false;
              this.showToast('Contact deleted successfully');
              const delId = this.contactToDelete.id;
              this.contacts = this.contacts.filter(c => c.id !== delId);
              this.contactToDelete = null;
              if (this.currentView === 'contact_detail') {
                this.navigateTo('contacts');
              }
              await this.loadAllData();
            } else {
              this.showToast(data.message || 'Error deleting contact', 'error');
            }
          } catch (e) {
            this.showToast('Network error deleting contact', 'error');
          } finally {
            this.isDeletingContact = false;
          }
        },

        shareContact(c) {
          if (!c) return;
          this.modalContactMenuOpen = false;
          this.modalContactMoreActionsOpen = false;
          const shareText = `${c.name}\n${c.company ? c.company + '\n' : ''}Phone: ${c.phone || 'N/A'}\nEmail: ${c.email || 'N/A'}`;
          if (navigator.share) {
            navigator.share({
              title: c.name,
              text: shareText
            }).catch(() => {});
          } else if (navigator.clipboard) {
            navigator.clipboard.writeText(shareText).then(() => {
              this.showToast('Contact details copied to clipboard');
            }).catch(() => {
              this.showToast('Contact details copied');
            });
          } else {
            this.showToast('Contact: ' + c.name + ' (' + (c.phone || c.email) + ')');
          }
        },

