        openGlobalFolders() {
          if (!this.activeContact && this.contacts.length > 0) {
            this.activeContact = this.contacts[0];
          }
          this.contactDetailTab = 'media';
          this.mediaViewLevel = 'projects';
          this.selectedProject = null;
          this.selectedVersion = null;
          this.selectedCategory = null;
          this.navigateTo('contact_detail');
        },

        openProjectFolder(proj) {
          this.selectedProject = proj;
          this.selectedVersion = null;
          this.selectedCategory = null;
          this.mediaViewLevel = 'versions';
        },

        openVersionFolder(ver) {
          this.selectedVersion = ver;
          this.selectedCategory = null;
          this.mediaViewLevel = 'categories';
        },

        openCategoryFolder(catKey) {
          this.selectedCategory = catKey;
          this.mediaViewLevel = 'files';
        },

        goBackMedia() {
          if (this.mediaViewLevel === 'files') {
            this.mediaViewLevel = 'categories';
            this.selectedCategory = null;
          } else if (this.mediaViewLevel === 'categories') {
            this.mediaViewLevel = 'versions';
            this.selectedVersion = null;
          } else if (this.mediaViewLevel === 'versions') {
            this.mediaViewLevel = 'projects';
            this.selectedProject = null;
          }
        },

        getCategoryFileCount(catKey) {
          if (!this.selectedVersion || !this.selectedVersion.categories || !this.selectedVersion.categories[catKey]) {
            return 0;
          }
          return this.selectedVersion.categories[catKey].files ? this.selectedVersion.categories[catKey].files.length : 0;
        },

        getCategoryFiles() {
          if (!this.selectedVersion || !this.selectedVersion.categories || !this.selectedCategory) return [];
          const cat = this.selectedVersion.categories[this.selectedCategory];
          return (cat && Array.isArray(cat.files)) ? cat.files : [];
        },

        openFileViewer(file) {
          this.openTaskFileViewer(file);
        },

        uploadMediaFileToCurrentCategory(e) {
          const file = e.target.files[0];
          if (!file) return;
          const files = this.getCategoryFiles();
          files.unshift({
            name: file.name,
            size: (file.size / 1024 > 1024 ? (file.size / (1024 * 1024)).toFixed(1) + ' MB' : Math.round(file.size / 1024) + ' KB'),
            date: 'Just now',
            type: file.type.startsWith('image') ? 'image' : 'doc',
            url: URL.createObjectURL(file)
          });
          this.showToast('File added to folder!');
        },

        // =====================================================================
        // INVOICES, BILLING, PAYMENTS & RECEIPTS (Screens 1, 2, 3 Reference)
        // =====================================================================
        formatMoney(val) {
          if (val === undefined || val === null || isNaN(Number(val))) return '₹0';
          return '₹' + Number(val).toLocaleString('en-IN', { maximumFractionDigits: 2 });
        },

        getInvoiceEffectiveStatus(inv) {
          if (!inv) return 'Pending';
          if (this.isInvoiceOverdue(inv)) return 'Overdue';
          const st = inv.status || 'Pending';
          if (st.toLowerCase() === 'paid') return 'Paid';
          if (Number(inv.paid_amount) > 0 && Number(inv.balance_amount) > 0) return 'Partially Paid';
          return st;
        },

        getInvoiceStatusClass(inv) {
          const eff = this.getInvoiceEffectiveStatus(inv);
          if (eff === 'Paid') return 'bg-emerald-50 text-emerald-700 border border-emerald-200/60';
          if (eff === 'Pending') return 'bg-amber-50 text-amber-700 border border-amber-200/60';
          if (eff === 'Partially Paid') return 'bg-blue-50 text-blue-700 border border-blue-200/60';
          if (eff === 'Overdue') return 'bg-rose-50 text-rose-700 border border-rose-200/60';
          return 'bg-slate-100 text-slate-600 border border-slate-200';
        },

        async openInvoiceDetail(inv) {
          if (!inv) return;
          this.activeInvoice = inv;
          this.currentView = 'invoice_detail';
          try {
            const res = await fetch('api/ledger.php?id=' + encodeURIComponent(inv.id || inv.invoice_no));
            const data = await res.json();
            if (data && data.data) {
              this.activeInvoice = data.data;
            }
          } catch (e) {
            console.warn('Could not refresh full invoice record:', e);
          }
        },

        openInvoiceByNo(invNo) {
          const found = this.invoices.find(x => x.invoice_no === invNo || x.id === invNo);
          if (found) {
            this.openInvoiceDetail(found);
          } else {
            this.navigateTo('invoices');
          }
        },

        viewInvoiceReceipt(inv) {
          this.openInvoiceDetail(inv);
        },

        openInvoiceActionMenu(inv) {
          this.modalInvoiceActionMenuOpen = true;
        },

        openAddInvoiceModal() {
          this.invoiceForm = {
            id: '',
            title: 'Website & Platform Engineering',
            client_id: '',
            customer_name: '',
            project_id: '',
            project_name: '',
            issue_date: new Date().toISOString().split('T')[0],
            due_date: new Date(Date.now() + 14 * 86400000).toISOString().split('T')[0],
            status: 'Pending',
            category: 'Development',
            discount_percent: 5,
            tax_percent: 18,
            items: [
              { description: 'Requirements & planning', quantity: 1, rate: 5000, amount: 5000 },
              { description: 'UI/UX design', quantity: 1, rate: 8000, amount: 8000 },
              { description: 'Frontend development', quantity: 1, rate: 20000, amount: 20000 },
              { description: 'Backend/API integration', quantity: 1, rate: 25000, amount: 25000 },
              { description: 'Testing & deployment', quantity: 1, rate: 7000, amount: 7000 }
            ],
