        onInvoiceClientChange(e) {
          const cid = e.target.value;
          if (cid) {
            const found = this.contacts.find(c => c.id === cid);
            if (found) {
              this.invoiceForm.customer_name = found.name + (found.company ? ' (' + found.company + ')' : '');
            }
          }
        },

        addInvoiceLineItem() {
          this.invoiceForm.items.push({
            description: '',
            quantity: 1,
            rate: 1000,
            amount: 1000
          });
        },

        removeInvoiceLineItem(index) {
          if (this.invoiceForm.items.length <= 1) {
            this.showToast('Invoice must have at least one line item', 'info');
            return;
          }
          this.invoiceForm.items.splice(index, 1);
        },

        calculateInvoiceLine(item) {
          const q = Number(item.quantity) || 1;
          const r = Number(item.rate) || 0;
          item.amount = Math.round(q * r * 100) / 100;
        },

        async submitInvoiceForm() {
          if (!this.invoiceForm.customer_name.trim()) {
            this.showToast('Please specify a client name', 'error');
            return;
          }
          this.isCreatingInvoice = true;
          try {
            const payload = {
              action: 'create_invoice',
              customer_name: this.invoiceForm.customer_name.trim(),
              title: this.invoiceForm.title.trim(),
              client_id: this.invoiceForm.client_id,
              project_id: this.invoiceForm.project_id,
              issue_date: this.invoiceForm.issue_date,
              due_date: this.invoiceForm.due_date,
              status: this.invoiceForm.status,
              discount_percent: Number(this.invoiceForm.discount_percent) || 0,
              tax_percent: Number(this.invoiceForm.tax_percent) || 0,
              items: this.invoiceForm.items,
              notes: this.invoiceForm.notes,
              terms: this.invoiceForm.terms
            };

            const res = await fetch('api/ledger.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });
            const data = await res.json();
            if (data.status === 'success' || data.success) {
              this.modalInvoiceOpen = false;
              this.showToast('Invoice created successfully!');
              await this.loadAllData();
              if (data.id) {
                const created = this.invoices.find(x => x.id === data.id);
                if (created) this.openInvoiceDetail(created);
              }
            } else {
              this.showToast(data.message || 'Failed to create invoice', 'error');
            }
          } catch (e) {
            this.showToast('Network error creating invoice', 'error');
          } finally {
            this.isCreatingInvoice = false;
          }
        },

        openRecordPaymentModal(inv) {
          if (!inv) return;
          const total = Number(inv.amount) || 0;
          const paid = Number(inv.paid_amount) || 0;
          const bal = Number(inv.balance_amount);
          const balance = (!isNaN(bal) && bal !== null) ? bal : Math.max(0, total - paid);
          this.recordPaymentForm = {
            invoice_id: inv.id,
            invoice_no: inv.invoice_no || inv.id,
            customer_name: inv.customer_name || 'Client',
            amount: balance > 0 ? balance : total,
            balance_amount: balance,
            invoice_total: total,
            total_paid: paid,
            payment_date: new Date().toISOString().split('T')[0],
            payment_method: 'Credit Card',
            transaction_id: 'TXN' + Math.floor(1000000000 + Math.random() * 9000000000),
            reference: 'Payment for Invoice ' + (inv.invoice_no || inv.id),
            notes: 'Payment confirmed for ' + (inv.invoice_no || inv.id)
          };
          this.modalRecordPaymentOpen = true;
        },

        async submitRecordPayment() {
          const amt = Number(this.recordPaymentForm.amount);
          if (!amt || amt <= 0) {
            this.showToast('Please enter a valid payment amount', 'error');
            return;
          }
          if (amt > (Number(this.recordPaymentForm.balance_amount) + 0.05)) {
            this.showToast('Payment amount exceeds remaining balance', 'error');
            return;
          }
          this.isSubmittingPayment = true;
          try {
            const res = await fetch('api/ledger.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: 'record_payment',
                invoice_id: this.recordPaymentForm.invoice_id,
                amount: amt,
                payment_date: this.recordPaymentForm.payment_date,
                payment_method: this.recordPaymentForm.payment_method,
                transaction_id: this.recordPaymentForm.transaction_id,
                reference: this.recordPaymentForm.reference,
                notes: this.recordPaymentForm.notes
              })
            });
            const data = await res.json();
            if (data.status === 'success' || data.success) {
              this.modalRecordPaymentOpen = false;
              this.showToast('Payment recorded successfully!');
              await this.loadAllData();

              // Open Screen 3 Payment Receipt with real payment data!
              const payRecord = data.payment || (data.data && data.data.payment) || {
                receipt_no: data.receipt_no || ('REC-' + new Date().getFullYear() + '-' + Math.floor(100 + Math.random() * 900)),
                invoice_no: this.recordPaymentForm.invoice_no,
                customer_name: this.recordPaymentForm.customer_name,
                amount: amt,
                payment_date: this.recordPaymentForm.payment_date,
                payment_method: this.recordPaymentForm.payment_method,
                transaction_id: this.recordPaymentForm.transaction_id,
                reference: this.recordPaymentForm.reference,
                invoice_total: this.recordPaymentForm.invoice_total,
                total_paid: (this.recordPaymentForm.total_paid || 0) + amt,
                balance_amount: Math.max(0, (this.recordPaymentForm.balance_amount || 0) - amt),
                status: 'Paid'
              };

              this.activePaymentReceipt = payRecord;
              this.currentView = 'payment_receipt';
            } else {
              this.showToast(data.message || 'Failed to record payment', 'error');
            }
          } catch (e) {
            this.showToast('Network error recording payment', 'error');
          } finally {
            this.isSubmittingPayment = false;
          }
        },

        downloadInvoicePdf(inv) {
          if (!inv) return;
          const id = encodeURIComponent(inv.id || inv.invoice_no);
          window.open('api/ledger.php?action=print_invoice&id=' + id, '_blank');
