          } else {
            navigator.clipboard.writeText(shareText);
            this.showToast('Payment receipt copied to clipboard!');
          }
        },

        async promptDeleteInvoice(inv) {
          if (!inv) return;
          if (!confirm('Are you sure you want to delete invoice ' + (inv.invoice_no || inv.id) + '?')) return;
          try {
            const res = await fetch('api/ledger.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'delete_invoice', id: inv.id })
            });
            const data = await res.json();
            if (data.status === 'success' || data.success) {
              this.showToast('Invoice deleted');
              await this.loadAllData();
              this.navigateTo('invoices');
            } else {
              this.showToast(data.message || 'Failed to delete invoice', 'error');
            }
          } catch (e) {
            this.showToast('Error deleting invoice', 'error');
          }
        },

        // =====================================================================
        // TASKS MODULE IMPLEMENTATION (Screens 1 to 10 Exact Reference)
        // =====================================================================
        isTaskOverdue(t) {
          if (!t) return false;
          if (Number(t.completed) === 1 || (t.status || '').toLowerCase() === 'completed') return false;
          const dStr = (t.due_date || '').toLowerCase();
          const tStr = (t.due_time || '').toLowerCase();
          if (tStr.includes('overdue') || dStr.includes('overdue') || tStr.includes('yesterday')) return true;
          if (t.due_date && /^\d{4}-\d{2}-\d{2}$/.test(t.due_date)) {
            const today = new Date().toISOString().split('T')[0];
            return t.due_date < today;
          }
          return false;
        },

        async toggleTask(t) {
          if (!t || this.taskTogglingLock) return;
          this.taskTogglingLock = true;

          const prevCompleted = t.completed;
          const prevStatus = t.status;
          const newCompleted = Number(t.completed) === 1 ? 0 : 1;
          const newStatus = newCompleted === 1 ? 'Completed' : 'In Progress';

          // Optimistic local update
          t.completed = newCompleted;
          t.status = newStatus;
          if (this.activeTask && this.activeTask.id === t.id) {
            this.activeTask.completed = newCompleted;
            this.activeTask.status = newStatus;
          }

          // Trigger Screen 8 completion popup on newly completed
          if (newCompleted === 1) {
            this.completedModalTask = t;
            this.modalTaskCompletedOpen = true;
          }

          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'toggle', id: t.id })
            });
            const result = await res.json();
            if (result && result.success && result.data) {
              t.completed = Number(result.data.completed);
              t.status = result.data.status;
              if (this.activeTask && this.activeTask.id === t.id) {
                this.activeTask.completed = t.completed;
                this.activeTask.status = t.status;
              }
            } else if (result && !result.success) {
              // Rollback
              t.completed = prevCompleted;
              t.status = prevStatus;
              this.showToast('Failed to update task status', 'error');
            }
          } catch (e) {
            // Rollback
            t.completed = prevCompleted;
            t.status = prevStatus;
            this.showToast('Network error updating task', 'error');
          } finally {
            setTimeout(() => { this.taskTogglingLock = false; }, 250);
          }
        },

        async toggleTaskCompletion(id) {
          const t = this.tasks.find(x => x.id === id);
          if (t) {
            await this.toggleTask(t);
          } else {
            try {
              await fetch('api/tasks.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'toggle', id: id })
              });
            } catch(e) {}
          }
        },

        viewTaskDetail(t) {
          if (!t) return;
          if (typeof t === 'string' || typeof t === 'number') {
            const found = this.tasks.find(x => x.id == t);
            if (found) t = found;
          }
          this.activeTask = t;
          this.taskDetailTab = 'overview';
          this.loadTaskFiles(t);
          this.navigateTo('task_detail');
        },

        openAddTaskScreen(p) {
          const targetProj = p || (this.projects && this.projects[0] ? this.projects[0] : null);
          const defaultProj = targetProj ? (targetProj.title || '') : 'Cloud ERP Platform';
          const defaultProjId = targetProj ? (targetProj.id || '') : '';
          const defaultProjClient = targetProj ? (targetProj.client_name || '') : '';
          if (!this.teamMembers || this.teamMembers.length === 0) {
            this.loadTeamMembers();
          }
          this.taskForm = {
            id: '',
            title: '',
            description: '',
            project_id: defaultProjId,
            project_name: defaultProj,
            client_name: defaultProjClient,
            assigned_staff: '',
            assigned_member_ids: [],
            selected_members: [],
            priority: 'Medium',
            due_date: new Date().toISOString().split('T')[0],
            due_time: 'Today',
            status: 'In Progress'
          };
          this.navigateTo('task_add');
        },

        openEditTaskScreen(t) {
          if (!t) t = this.activeTask;
          if (!t) return;
          if (!this.teamMembers || this.teamMembers.length === 0) {
            this.loadTeamMembers();
          }
          let selectedMembers = [];
          let assignedIds = [];

          if (t.assigned_members && Array.isArray(t.assigned_members) && t.assigned_members.length > 0) {
            selectedMembers = [...t.assigned_members];
            assignedIds = t.assigned_members.map(m => String(m.id));
          } else if (t.assigned_member_ids && Array.isArray(t.assigned_member_ids) && t.assigned_member_ids.length > 0) {
            assignedIds = t.assigned_member_ids.map(id => String(id));
            selectedMembers = (this.teamMembers || []).filter(m => assignedIds.includes(String(m.id)));
          } else if (t.assigned_staff) {
            const names = t.assigned_staff.split(',').map(s => s.trim().toLowerCase());
            selectedMembers = (this.teamMembers || []).filter(m => names.includes((m.name || '').trim().toLowerCase()));
            assignedIds = selectedMembers.map(m => String(m.id));
          }

          this.taskForm = {
            id: t.id,
            title: t.title || '',
            description: t.description || '',
            project_id: t.project_id || '',
            project_name: t.project_name || '',
            client_name: t.client_name || '',
            assigned_staff: t.assigned_staff || selectedMembers.map(m => m.name).join(', '),
            assigned_member_ids: assignedIds,
            selected_members: selectedMembers,
            priority: t.priority || 'Medium',
            due_date: t.due_date || (new Date().toISOString().split('T')[0]),
            due_time: t.due_time || 'Today',
            status: t.status || (Number(t.completed) === 1 ? 'Completed' : 'In Progress')
          };
          this.navigateTo('task_edit');
        },

        openTaskAssigneesModal() {
          if (!this.teamMembers || this.teamMembers.length === 0) {
            this.loadTeamMembers();
          }
          this.tempSelectedMemberIds = Array.isArray(this.taskForm.assigned_member_ids)
            ? [...this.taskForm.assigned_member_ids.map(String)]
            : [];
          this.taskMemberSearchQuery = '';
          this.modalTaskAssigneesOpen = true;
        },

        closeTaskAssigneesModal() {
          this.modalTaskAssigneesOpen = false;
          this.taskMemberSearchQuery = '';
        },

        toggleTaskMemberSelection(memberId) {
          const id = String(memberId);
          const idx = this.tempSelectedMemberIds.indexOf(id);
          if (idx >= 0) {
            this.tempSelectedMemberIds.splice(idx, 1);
          } else {
            this.tempSelectedMemberIds.push(id);
          }
        },

        selectAllTaskMembers() {
          const currentFiltered = this.filteredTaskAvailableMembers;
          if (!currentFiltered || currentFiltered.length === 0) return;
          const idsToAdd = currentFiltered.map(m => String(m.id));
          const combined = new Set([...this.tempSelectedMemberIds, ...idsToAdd]);
          this.tempSelectedMemberIds = Array.from(combined);
        },

        clearAllTaskMembers() {
          this.tempSelectedMemberIds = [];
        },

        confirmSelectedTaskMembers() {
          const uniqueIds = Array.from(new Set(this.tempSelectedMemberIds.map(String)));
          this.taskForm.assigned_member_ids = uniqueIds;
          const staff = this.teamMembers || [];
          this.taskForm.selected_members = staff.filter(m => uniqueIds.includes(String(m.id)));
          if (this.taskForm.selected_members.length > 0) {
            this.taskForm.assigned_staff = this.taskForm.selected_members.map(m => m.name).join(', ');
          } else {
            this.taskForm.assigned_staff = '';
          }
          this.closeTaskAssigneesModal();
        },

        removeMemberFromTask(memberId) {
          const id = String(memberId);
          this.taskForm.assigned_member_ids = (this.taskForm.assigned_member_ids || []).filter(x => String(x) !== id);
          this.taskForm.selected_members = (this.taskForm.selected_members || []).filter(m => String(m.id) !== id);
          if (this.taskForm.selected_members.length > 0) {
            this.taskForm.assigned_staff = this.taskForm.selected_members.map(m => m.name).join(', ');
          } else {
            this.taskForm.assigned_staff = '';
          }
        },

        onProjectSelectChange(e) {
          const pName = e.target.value;
          this.taskForm.project_name = pName;
          const match = this.projects.find(p => p.title === pName);
          if (match) {
            this.taskForm.project_id = match.id;
            this.taskForm.client_name = match.client_name || '';
          }
        },

        closeAddTaskModal() {
          this.modalTaskOpen = false;
          this.taskFormError = '';
          this.isSubmittingTask = false;
        },

        async submitTaskForm() {
          if (this.isSubmittingTask) return;
          this.taskFormError = '';

          if (!this.taskForm.title || !this.taskForm.title.trim()) {
            this.taskFormError = 'Task Title is required';
            this.showToast('Please enter a task title', 'error');
            return;
          }

          if (this.taskForm.due_date && !this.taskForm.due_time) {
            this.taskForm.due_time = this.formatTaskShortDate(this.taskForm.due_date);
          }

          const isEditing = !!this.taskForm.id;
          const action = isEditing ? 'update' : 'create';
          this.isSubmittingTask = true;

          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: action,
                ...this.taskForm
              })
            });
            const result = await res.json();
            if (result && (result.success || result.status === 'success')) {
              this.closeAddTaskModal();
              await this.loadAllData();
              if (this.currentView === 'project_detail') {
                this.projectDetailTab = 'tasks';
                this.projectSuccessBanner = { show: true, message: 'Task added successfully!' };
              } else if (isEditing && this.taskForm.id) {
                const updated = this.tasks.find(x => x.id == this.taskForm.id);
                if (updated) this.activeTask = updated;
                this.navigateTo('task_detail');
                this.showToast('Task updated successfully!');
              } else {
                this.navigateTo('tasks');
                this.showToast('Task created successfully!');
              }
            } else {
              const errMsg = (result && (result.message || result.error)) || 'Failed to save task';
              this.taskFormError = errMsg;
              this.showToast(errMsg, 'error');
            }
          } catch (e) {
            this.taskFormError = 'Network error saving task';
            this.showToast('Network error saving task', 'error');
          } finally {
            this.isSubmittingTask = false;
          }
        },

        openTaskActionMenu(t) {
          this.actionTask = t || this.activeTask;
          this.modalTaskMenuOpen = true;
        },

        async changeTaskPriority(t, prio) {
          if (!t) return;
          t.priority = prio;
          if (this.activeTask && this.activeTask.id === t.id) this.activeTask.priority = prio;
          this.modalTaskMenuOpen = false;
          try {
            await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'update', id: t.id, priority: prio })
            });
            this.showToast('Priority changed to ' + prio);
          } catch(e) {
            this.showToast('Failed to change priority', 'error');
          }
        },

        async duplicateTask(t) {
          if (!t) return;
          this.modalTaskMenuOpen = false;
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'duplicate', id: t.id })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast('Task duplicated successfully!');
              await this.loadAllData();
            } else {
              this.showToast('Failed to duplicate task', 'error');
            }
          } catch(e) {
            this.showToast('Network error duplicating task', 'error');
          }
        },

        async deleteTask(t) {
          if (!t) return;
          this.modalTaskMenuOpen = false;
          const taskId = t.id;
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'delete', id: taskId })
            });
            const result = await res.json();
            if (result && result.success) {
              this.tasks = this.tasks.filter(x => x.id !== taskId);
              this.showToast('Task deleted successfully');
              if (this.currentView === 'task_detail' || this.currentView === 'task_edit') {
                this.navigateTo('tasks');
              }
            } else {
              this.showToast('Failed to delete task', 'error');
            }
          } catch(e) {
            this.showToast('Network error deleting task', 'error');
          }
        },

        // Bulk operations (Screen 7)
        enterBulkMode() {
          this.bulkMode = true;
          this.selectedTaskIds = [];
        },

        exitBulkMode() {
          this.bulkMode = false;
          this.selectedTaskIds = [];
        },

        toggleTaskSelection(id) {
          const idx = this.selectedTaskIds.indexOf(id);
          if (idx > -1) {
            this.selectedTaskIds.splice(idx, 1);
          } else {
            this.selectedTaskIds.push(id);
          }
        },

        async executeBulkComplete() {
          if (this.selectedTaskIds.length === 0) return;
          const count = this.selectedTaskIds.length;
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'bulk_complete', ids: this.selectedTaskIds })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast(`Marked ${count} tasks as completed!`);
              this.exitBulkMode();
              await this.loadAllData();
            } else {
              this.showToast('Failed to complete tasks', 'error');
            }
          } catch(e) {
            this.showToast('Network error updating tasks', 'error');
          }
        },

        async executeBulkDelete() {
          if (this.selectedTaskIds.length === 0) return;
          const count = this.selectedTaskIds.length;
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'bulk_delete', ids: this.selectedTaskIds })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast(`Deleted ${count} tasks`);
              this.exitBulkMode();
              await this.loadAllData();
            } else {
              this.showToast('Failed to delete tasks', 'error');
            }
          } catch(e) {
            this.showToast('Network error deleting tasks', 'error');
          }
        },

        openBulkAssignModal() {
          if (this.selectedTaskIds.length === 0) return;
          this.bulkAssignStaff = 'Rahul Sharma';
          this.modalBulkAssignOpen = true;
        },

        async executeBulkAssign(staff) {
          if (this.selectedTaskIds.length === 0 || !staff) return;
          const count = this.selectedTaskIds.length;
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'bulk_assign', ids: this.selectedTaskIds, assigned_staff: staff })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast(`Assigned ${count} tasks to ${staff}`);
              this.modalBulkAssignOpen = false;
              this.exitBulkMode();
              await this.loadAllData();
            } else {
              this.showToast('Failed to assign tasks', 'error');
            }
          } catch(e) {
            this.showToast('Network error assigning tasks', 'error');
          }
        },

        openBulkMoveModal() {
          if (this.selectedTaskIds.length === 0) return;
          this.bulkMoveProjectId = this.projects[0] ? this.projects[0].id : '';
          this.modalBulkMoveOpen = true;
        },

        async executeBulkMove(projectId) {
          if (this.selectedTaskIds.length === 0 || !projectId) return;
          const count = this.selectedTaskIds.length;
          const match = this.projects.find(p => p.id == projectId);
          const projectName = match ? match.title : '';
          try {
            const res = await fetch('api/tasks.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'bulk_move', ids: this.selectedTaskIds, project_id: projectId, project_name: projectName })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast(`Moved ${count} tasks to ${projectName || 'project'}`);
              this.modalBulkMoveOpen = false;
              this.exitBulkMode();
              await this.loadAllData();
            } else {
              this.showToast('Failed to move tasks', 'error');
            }
          } catch(e) {
            this.showToast('Network error moving tasks', 'error');
          }
        },

        // Task Detail Tabs Helpers
        getTaskComments(t) {
          if (!t) return [];
          const tid = t.id || 'default';
          if (!this.taskComments[tid]) {
            this.taskComments[tid] = [
              { id: 1, user: 'Rahul Sharma', time: '2 hours ago', text: 'Checked the requirements with client. Looking good to proceed with the core sprint.' },
              { id: 2, user: 'Priya Verma', time: 'Yesterday', text: 'Attached the latest design specifications and mobile mockups.' }
            ];
          }
          return this.taskComments[tid];
        },

        addCommentToTask(t) {
          if (!t || !this.newCommentText || !this.newCommentText.trim()) return;
          const comments = this.getTaskComments(t);
          comments.unshift({
            id: Date.now(),
            user: 'Rahul Sharma',
            time: 'Just now',
            text: this.newCommentText.trim()
          });
          this.newCommentText = '';
          this.showToast('Comment added');
        },

        loadTaskFiles(t) {
          if (!t || !t.id) return Promise.resolve([]);
          const tid = String(t.id);
          return fetch('api/tasks.php?action=get_files&task_id=' + encodeURIComponent(tid))
            .then(r => r.json())
            .then(data => {
              if (data && data.success && Array.isArray(data.files)) {
                if (!this.taskFiles) this.taskFiles = {};
                this.taskFiles[tid] = data.files;
                return data.files;
              }
              return [];
            })
            .catch(err => {
              console.error('Failed to load task files:', err);
              return [];
            });
        },

        getTaskFiles(t) {
          if (!t || !t.id) return [];
          const tid = String(t.id);
          if (!this.taskFiles) this.taskFiles = {};
          if (this.taskFiles[tid] === undefined) {
            this.taskFiles[tid] = [];
            this.loadTaskFiles(t);
          }
          return this.taskFiles[tid];
        },

        async uploadTaskFile(e, t) {
          const file = e.target.files && e.target.files[0];
          if (!file || !t || !t.id) return;
          
          this.isUploadingTaskFile = true;
          const formData = new FormData();
          formData.append('task_id', t.id);
          formData.append('file', file);

          try {
            const res = await fetch('api/tasks.php?action=upload_file', {
              method: 'POST',
              body: formData
            });
            const result = await res.json();
            if (result && result.success && result.file) {
              const tid = String(t.id);
              if (!this.taskFiles) this.taskFiles = {};
              if (!this.taskFiles[tid]) this.taskFiles[tid] = [];
              this.taskFiles[tid].unshift(result.file);
              this.showToast('File uploaded successfully');
            } else {
              this.showToast((result && result.error) ? result.error : 'Failed to upload file');
            }
          } catch (err) {
            console.error('Task file upload error:', err);
            this.showToast('Upload network error. Please try again.');
          } finally {
            this.isUploadingTaskFile = false;
            e.target.value = '';
          }
        },

        openTaskFileViewer(file) {
          if (!file) return;
          this.activeFileDoc = {
            id: file.id || null,
            name: file.name || file.original_name || 'Document',
            size: file.size || '',
            date: file.date || '',
            type: file.type || 'doc',
            mime_type: file.mime_type || '',
            url: file.view_url || file.url || ('api/tasks.php?action=view_file&id=' + (file.id || '')),
            download_url: file.download_url || ('api/tasks.php?action=view_file&download=1&id=' + (file.id || '')),
            text: file.text || null,
            rawFile: file
          };
          if (this.activeFileDoc.type === 'text' || (this.activeFileDoc.mime_type && this.activeFileDoc.mime_type.startsWith('text/'))) {
            this.activeFileDoc.text = 'Loading content...';
            fetch(this.activeFileDoc.url)
              .then(res => res.text())
              .then(txt => {
                if (this.activeFileDoc) {
                  this.activeFileDoc.text = txt;
                }
              })
              .catch(() => {
                if (this.activeFileDoc) {
                  this.activeFileDoc.text = 'Could not load text preview.';
                }
              });
          }
          this.viewNoteDocModalOpen = true;
        },

        promptDeleteTaskFile(file, task) {
          if (!file) return;
          this.taskFileToDelete = file;
          this.taskForFileDeletion = task || this.activeTask;
          this.modalConfirmDeleteTaskFileOpen = true;
        },

        deleteTaskFile(file, task) {
          this.promptDeleteTaskFile(file, task);
        },

        async confirmDeleteTaskFileAction() {
          if (!this.taskFileToDelete) return;
          const file = this.taskFileToDelete;
          const fileId = file.id;
          const task = this.taskForFileDeletion || this.activeTask;
          const taskId = task ? String(task.id) : (file.task_id ? String(file.task_id) : null);

          this.isDeletingTaskFile = true;
          try {
            const formData = new FormData();
            formData.append('action', 'delete_file');
            formData.append('id', fileId);
            if (taskId) formData.append('task_id', taskId);

            const res = await fetch('api/tasks.php', {
              method: 'POST',
              body: formData
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              // Optimistically update frontend reactive state
              if (taskId && this.taskFiles && Array.isArray(this.taskFiles[taskId])) {
                this.taskFiles[taskId] = this.taskFiles[taskId].filter(f => String(f.id) !== String(fileId));
              } else if (this.taskFiles) {
                Object.keys(this.taskFiles).forEach(key => {
                  if (Array.isArray(this.taskFiles[key])) {
                    this.taskFiles[key] = this.taskFiles[key].filter(f => String(f.id) !== String(fileId));
                  }
                });
              }

              // Close preview modal if currently previewing this file
              if (this.activeFileDoc && String(this.activeFileDoc.id) === String(fileId)) {
                this.viewNoteDocModalOpen = false;
                this.activeFileDoc = null;
              }

              this.modalConfirmDeleteTaskFileOpen = false;
              this.taskFileToDelete = null;
              this.taskForFileDeletion = null;
              this.showToast('File deleted successfully');

              // Refresh task attachments list from server for verified persistence
              if (task && task.id) {
                await this.loadTaskFiles(task);
              }
            } else {
              this.showToast((data && (data.error || data.message)) || 'Failed to delete file', 'error');
            }
          } catch (err) {
            console.error('Task file deletion error:', err);
            this.showToast('Network error while deleting file', 'error');
          } finally {
            this.isDeletingTaskFile = false;
          }
        },

        getTaskActivity(t) {
          if (!t) return [];
          const tid = t.id || 'default';
          if (!this.taskActivity[tid]) {
            this.taskActivity[tid] = [
              { title: 'Task created', description: 'Created and assigned to ' + (t.assigned_staff || 'Rahul Sharma'), user: 'Admin', time: '2 days ago' },
              { title: 'Priority updated', description: 'Set priority to ' + (t.priority || 'Medium'), user: 'Rahul Sharma', time: 'Yesterday' }
            ];
          }
          return this.taskActivity[tid];
        },

        // =====================================================================
        // CALENDAR METHODS & OPERATIONS (Exact Reference Implementation)
        // =====================================================================
        buildCalendarDay(dateStr, dayNum, isCurrentMonth) {
          const isToday = dateStr === this.todayDateStr;
          const isSelected = dateStr === this.selectedCalendarDate;

          // Events for this day
          const dayEvents = this.calendarEvents.filter(e => e.event_date === dateStr);
          const hasEvents = dayEvents.length > 0;

          // Tasks due for this day
          const dayTasks = this.tasks.filter(t => {
            if (t.due_date && t.due_date === dateStr) return true;
            if (t.due_time && t.due_time.includes(dateStr)) return true;
            return false;
          });
          const hasTasks = dayTasks.length > 0;

          // Holiday for this day
          const holiday = this.holidaysMap[dateStr] || null;
          const hasHoliday = !!holiday;

          return {
            dateStr,
            dayNum,
            isCurrentMonth,
            isToday,
            isSelected,
            hasEvents,
            hasTasks,
            hasHoliday,
            holidayName: holiday ? holiday.name : '',
            eventsCount: dayEvents.length,
            tasksCount: dayTasks.length
          };
        },

        prevCalendarMonth() {
          if (this.calendarViewMonth === 0) {
            this.calendarViewMonth = 11;
            this.calendarViewYear--;
          } else {
            this.calendarViewMonth--;
          }
        },

        nextCalendarMonth() {
          if (this.calendarViewMonth === 11) {
            this.calendarViewMonth = 0;
            this.calendarViewYear++;
          } else {
            this.calendarViewMonth++;
          }
        },

        jumpToToday() {
          const now = new Date();
          this.calendarViewYear = now.getFullYear();
          this.calendarViewMonth = now.getMonth();
          const y = now.getFullYear();
          const m = String(now.getMonth() + 1).padStart(2, '0');
          const d = String(now.getDate()).padStart(2, '0');
          this.selectedCalendarDate = `${y}-${m}-${d}`;
        },

        selectCalendarDate(dateStr) {
          if (!dateStr) return;
          this.selectedCalendarDate = dateStr;

          // If clicked date is in adjacent month, align calendar view
          const parts = dateStr.split('-');
          if (parts.length === 3) {
            const yr = parseInt(parts[0], 10);
            const mo = parseInt(parts[1], 10) - 1;
            if (this.calendarViewYear !== yr || this.calendarViewMonth !== mo) {
              this.calendarViewYear = yr;
              this.calendarViewMonth = mo;
            }
          }
        },

        openAddEventModal() {
          this.eventForm = {
            id: '',
            title: '',
            event_date: this.selectedCalendarDate || this.todayDateStr,
            event_time: '09:00 AM',
            end_time: '10:00 AM',
            category: 'Meeting',
            color: '#590907',
            location: 'Internal • Conference Room',
            description: ''
          };
          this.modalEventOpen = true;
        },

        openEventActionMenu(item) {
          this.actionCalendarItem = item;
          this.modalEventActionOpen = true;
        },

        async submitEventForm() {
          if (!this.eventForm.title || !this.eventForm.title.trim()) {
            this.showToast('Please enter an event title', 'error');
            return;
          }
          if (!this.eventForm.event_date) {
            this.eventForm.event_date = this.selectedCalendarDate || this.todayDateStr;
          }

          const isEditing = !!this.eventForm.id;
          const action = isEditing ? 'update' : 'create';

          try {
            const res = await fetch('api/calendar.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: action,
                ...this.eventForm
              })
            });
            const result = await res.json();
            if (result && (result.success || result.status === 'success')) {
              this.showToast(isEditing ? 'Event updated!' : 'Event scheduled successfully!');
              this.modalEventOpen = false;
              await this.loadCalendarEvents();
              this.selectCalendarDate(this.eventForm.event_date);
            } else {
              this.showToast(result.message || 'Failed to save event', 'error');
            }
          } catch (e) {
            this.showToast('Network error saving event', 'error');
          }
        },

        async deleteCalendarEvent(id) {
          if (!id) return;
          this.modalEventActionOpen = false;
          try {
            const res = await fetch('api/calendar.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'delete', id: id })
            });
            const result = await res.json();
            if (result && (result.success || result.status === 'success')) {
              this.calendarEvents = this.calendarEvents.filter(x => x.id != id);
              this.showToast('Event deleted successfully');
            } else {
              this.showToast(result.message || 'Failed to delete event', 'error');
            }
          } catch (e) {
            this.showToast('Network error deleting event', 'error');
          }
        },

        async loadCalendarEvents() {
          try {
            const res = await fetch('api/calendar.php');
            const data = await res.json();
            if (data && data.data) {
              this.calendarEvents = data.data;
            }
          } catch (e) {
            console.error('Error loading calendar events:', e);
          }
        },

        // Modals & Forms
        openAddModal(type) {
          if (type === 'contact') {
            this.contactForm = { id: '', name: '', phone: '', email: '', company: '', category: 'Client' };
            this.modalContactOpen = true;
          } else if (type === 'task') {
            this.openAddTaskForProject(this.activeProject);
          } else if (type === 'project') {
            if (!this.companies || this.companies.length === 0) {
              this.loadCompanies();
            }
            this.projectForm = {
              id: '',
              title: '',
              client_name: '',
              company_id: '',
              manual_company_override: false,
              auto_matched_company_name: '',
              progress: 0,
              status: 'In Progress',
              description: '',
              budget: '$12,000',
              project_manager: 'Rahul Sharma',
              start_date: new Date().toISOString().split('T')[0],
              deadline: ''
            };
            this.modalProjectOpen = true;
          } else if (type === 'invoice') {
            this.openAddInvoiceModal();
          } else if (type === 'note') {
            this.noteInputText = '';
            this.modalNoteOpen = true;
          }
        },

        async submitNoteForm() {
          if (!this.noteInputText.trim() || !this.activeContact) return;
          try {
            await fetch('api/pocket_api.php?action=add_history', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ contact_id: this.activeContact.id, note_text: this.noteInputText.trim() })
            });
            if (!this.activeContact.history) this.activeContact.history = [];
            this.activeContact.history.unshift({
              id: Date.now(),
              staff: 'Akash (Dev Lead)',
              time: 'Just now',
              note_text: this.noteInputText.trim()
            });
            this.modalNoteOpen = false;
            this.noteInputText = '';
            this.showToast('Note saved successfully');
          } catch(e) {
            this.showToast('Failed to save note', 'error');
          }
        },

// Handled in unified Contact Methods



        // =====================================================================
        // SCREEN 5B: PROJECT DETAILS & ACTIONS (Exact Reference Implementation)
        // =====================================================================
        viewProjectDetail(p) {
          if (!p) return;
          if (typeof p === 'string' || typeof p === 'number') {
            const found = this.projects.find(x => x.id == p);
            if (found) p = found;
          }
          this.activeProject = p;
          this.projectDetailTab = 'overview';
          this.loadProjectFiles(p);
          this.loadProjectActivity(p);
          this.navigateTo('project_detail');
        },

        viewTaskDetailFromProject(t) {
          this.taskReturnView = 'project_detail';
          this.viewTaskDetail(t);
        },

        viewTeamMemberDetailFromProject(tm) {
          this.teamMemberReturnView = 'project_detail';
          this.viewTeamMemberDetail(tm);
        },

        openProjectActionMenu(p) {
          this.actionProject = p || this.activeProject;
          this.modalProjectActionsOpen = true;
        },

        openEditProjectModal(p) {
          if (!p) p = this.activeProject || {};
          if (!this.companies || this.companies.length === 0) {
            this.loadCompanies();
          }
          this.projectForm = {
            id: p.id || '',
            title: p.title || '',
            client_name: p.client_name || '',
            company_id: p.company_id || '',
            manual_company_override: !!p.company_id,
            auto_matched_company_name: '',
            progress: p.progress !== undefined ? p.progress : 50,
            status: p.status || 'In Progress',
            description: p.description || '',
            budget: p.budget || '$22,000',
            project_manager: p.project_manager || 'Priya Verma',
            start_date: p.start_date || '2024-07-15',
            deadline: p.deadline || '2024-09-25'
          };
          this.modalProjectOpen = true;
        },

        normalizeProjectName(str) {
          if (!str) return '';
          return str.toString().replace(/\s+/g, ' ').trim().toLowerCase();
        },

        onProjectTitleInput() {
          if (this.projectForm.manual_company_override) return;
          const normTitle = this.normalizeProjectName(this.projectForm.title);
          if (!normTitle) {
            this.projectForm.company_id = '';
            this.projectForm.auto_matched_company_name = '';
            return;
          }

          const matchedComp = (this.companies || []).find(c => this.normalizeProjectName(c.name) === normTitle);
          if (matchedComp) {
            this.projectForm.company_id = matchedComp.id;
            this.projectForm.auto_matched_company_name = matchedComp.name;
            if (!this.projectForm.client_name || this.projectForm.client_name === 'Client' || (this.activeProject && this.activeProject.company_name === this.projectForm.client_name)) {
              this.projectForm.client_name = matchedComp.name;
            }
          } else {
            if (this.projectForm.auto_matched_company_name) {
              this.projectForm.company_id = '';
              this.projectForm.auto_matched_company_name = '';
            }
          }
        },

        onProjectCompanySelect() {
          this.projectForm.manual_company_override = true;
          this.projectForm.auto_matched_company_name = '';
          if (this.projectForm.company_id) {
            const found = (this.companies || []).find(c => c.id === this.projectForm.company_id);
            if (found) {
              this.projectForm.client_name = found.name;
            }
          }
        },

        viewCompanyFromProject(project) {
          if (!project) return;
          const targetId = project.company_id || (this.companies.find(k => this.normalizeProjectName(k.name) === this.normalizeProjectName(project.company_name || project.client_name || project.title)) || {}).id;
          if (targetId) {
            this.viewCompanyDetail(targetId);
          } else if (project.company_name || project.client_name) {
            this.showToast('Company record for ' + (project.company_name || project.client_name) + ' is not found in directory');
          }
        },

        async duplicateProject(p) {
          if (!p || !p.id) return;
          try {
            const res = await fetch('api/software.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'duplicate', id: p.id })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              this.showToast('Project duplicated: ' + (data.project ? data.project.title : 'Copy created'));
              await this.loadAllData();
              if (data.id) {
                const dup = this.projects.find(x => x.id == data.id);
                if (dup) this.viewProjectDetail(dup);
              }
            } else {
              this.showToast((data && data.error) || 'Failed to duplicate project', 'error');
            }
          } catch(e) {
            console.error(e);
            this.showToast('Error duplicating project', 'error');
          }
        },

        async archiveProject(p) {
          if (!p || !p.id) return;
          try {
            const res = await fetch('api/software.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'archive', id: p.id })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              const isArchived = !!data.archived;
              p.archived = isArchived;
              this.showToast(isArchived ? 'Project archived' : 'Project restored from archive');
              await this.loadAllData();
            } else {
              this.showToast((data && data.error) || 'Failed to archive project', 'error');
            }
          } catch(e) {
            console.error(e);
            this.showToast('Error archiving project', 'error');
          }
        },

        promptDeleteProject(p) {
          if (!p) p = this.activeProject;
          this.projectToDelete = p;
          this.modalConfirmDeleteProjectOpen = true;
        },

        async confirmDeleteProject() {
          if (!this.projectToDelete || !this.projectToDelete.id) return;
          const pid = this.projectToDelete.id;
          try {
            const res = await fetch('api/software.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'delete', id: pid })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              this.modalConfirmDeleteProjectOpen = false;
              this.showToast('Project deleted successfully');
              await this.loadAllData();
              this.navigateTo('projects');
            } else {
              this.showToast((data && data.error) || 'Failed to delete project', 'error');
            }
          } catch(e) {
            console.error(e);
            this.showToast('Error deleting project', 'error');
          }
        },

        shareProject(p) {
          if (!p) p = this.activeProject;
          const shareUrl = window.location.origin + window.location.pathname + '?project_id=' + encodeURIComponent(p ? p.id : '');
          if (navigator.clipboard) {
            navigator.clipboard.writeText(shareUrl).then(() => {
              this.showToast('Project link copied to clipboard!');
            }).catch(() => {
              this.showToast('Share: ' + shareUrl);
            });
          } else {
            this.showToast('Share link ready');
          }
        },

        exportProject(p) {
          if (!p) p = this.activeProject;
          if (!p) return;
          const exportData = {
            project: p,
            tasks: this.getProjectTasks(p),
            exported_at: new Date().toISOString()
          };
          const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = (p.title || 'Project').replace(/[^a-zA-Z0-9_\-]/g, '_') + '_Export.json';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          this.showToast('Project data exported successfully!');
        },

        // PROJECT FILES
        async loadProjectFiles(p) {
          if (!p || !p.id) return [];
          const pid = String(p.id);
          try {
            const res = await fetch('api/software.php?action=get_files&project_id=' + encodeURIComponent(pid));
            const data = await res.json();
            if (data && (data.success || data.status === 'success') && Array.isArray(data.data)) {
              if (!this.projectFiles) this.projectFiles = {};
              this.projectFiles[pid] = data.data;
              return data.data;
            }
          } catch (e) {
            console.error('Failed to load project files:', e);
          }
          return [];
        },

        getProjectFiles(p) {
          if (!p || !p.id) return [];
          const pid = String(p.id);
          if (!this.projectFiles) this.projectFiles = {};
          if (this.projectFiles[pid] === undefined) {
            this.projectFiles[pid] = [];
            this.loadProjectFiles(p);
          }
          return this.projectFiles[pid];
        },

        async uploadProjectFile(e) {
          const file = e.target.files && e.target.files[0];
          if (!file || !this.activeProject || !this.activeProject.id) return;

          this.isUploadingProjectFile = true;
          const formData = new FormData();
          formData.append('project_id', this.activeProject.id);
          formData.append('file', file);

          try {
            const res = await fetch('api/software.php?action=upload_file', {
              method: 'POST',
              body: formData
            });
            const result = await res.json();
            if (result && (result.success || result.status === 'success') && (result.file || result.data)) {
              const fileItem = result.file || result.data;
              const pid = String(this.activeProject.id);
              if (!this.projectFiles) this.projectFiles = {};
              if (!this.projectFiles[pid]) this.projectFiles[pid] = [];
              this.projectFiles[pid].unshift(fileItem);
              this.showToast('File uploaded successfully!');
              this.loadProjectActivity(this.activeProject);
            } else {
              this.showToast((result && result.error) || 'Failed to upload file', 'error');
            }
          } catch (err) {
            console.error('Project file upload error:', err);
            this.showToast('Network error uploading file', 'error');
          } finally {
            this.isUploadingProjectFile = false;
            e.target.value = '';
          }
        },

        openProjectFileViewer(file) {
          if (!file) return;
          this.activeProjectFileDoc = {
            name: file.name || file.original_name || 'Document',
            size: file.size || '',
            date: file.date || '',
            type: file.type || 'doc',
            mime_type: file.mime_type || '',
            url: file.view_url || file.url || ('api/software.php?action=view_file&id=' + (file.id || '')),
            download_url: file.download_url || ('api/software.php?action=view_file&download=1&id=' + (file.id || '')),
            text: file.text || null
          };

          if (this.activeProjectFileDoc.type === 'text' || (this.activeProjectFileDoc.mime_type && this.activeProjectFileDoc.mime_type.startsWith('text/')) || (this.activeProjectFileDoc.name && this.activeProjectFileDoc.name.match(/\.(txt|md|csv|json)$/i))) {
            this.activeProjectFileDoc.text = 'Loading file content...';
            fetch(this.activeProjectFileDoc.url)
              .then(res => res.text())
              .then(txt => {
                if (this.activeProjectFileDoc) {
                  this.activeProjectFileDoc.text = txt;
                }
              })
              .catch(() => {
                if (this.activeProjectFileDoc) {
                  this.activeProjectFileDoc.text = 'Could not load text preview.';
                }
              });
          }
          this.modalProjectFileViewerOpen = true;
        },

        // PROJECT ACTIVITY
        async loadProjectActivity(p) {
          if (!p || !p.id) return [];
          const pid = String(p.id);
          try {
            const res = await fetch('api/software.php?action=get_activity&project_id=' + encodeURIComponent(pid));
            const data = await res.json();
            if (data && (data.success || data.status === 'success') && Array.isArray(data.data)) {
              if (!this.projectActivity) this.projectActivity = {};
              this.projectActivity[pid] = data.data;
              return data.data;
            }
          } catch(e) {
            console.error('Failed to load project activity:', e);
          }
          return [];
        },

        getProjectActivity(p) {
          if (!p) return [];
          const pid = p.id || 'default';
          if (!this.projectActivity) this.projectActivity = {};
          if (this.projectActivity[pid] && this.projectActivity[pid].length > 0) {
            return this.projectActivity[pid];
          }
          // Matching reference items for rich timeline
          return [
            { title: 'Project updated', description: 'Project progress updated to ' + (p.progress !== undefined ? p.progress : 70) + '% by ' + (p.project_manager || 'Rahul Sharma') + ' • 2 hours ago', user: p.project_manager || 'Rahul Sharma', time: '2 hours ago' },
            { title: 'New task added', description: 'Design product listing page by Priya Verma • 5 hours ago', user: 'Priya Verma', time: '5 hours ago' },
            { title: 'Milestone reached', description: 'Sprint 2 deliverables verified and approved by Suresh Kumar • Yesterday', user: 'Suresh Kumar', time: 'Yesterday' },
            { title: 'Files uploaded', description: 'Added E-commerce Architecture Spec v2.1.pdf by Amit Patel • 3 days ago', user: 'Amit Patel', time: '3 days ago' },
            { title: 'Project kick-off', description: 'Project initialized with budget allocation by Admin • 01 Aug 2024', user: 'Admin', time: '01 Aug 2024' }
          ];
        },

        openAddProjectNoteModal() {
          this.projectNoteForm = {
            project_id: this.activeProject ? this.activeProject.id : '',
            title: '',
            description: '',
            activity_type: 'note'
          };
          this.modalAddProjectNoteOpen = true;
        },

