                title: this.projectNoteForm.title.trim(),
                description: this.projectNoteForm.description.trim(),
                activity_type: this.projectNoteForm.activity_type || 'note'
              })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              this.modalAddProjectNoteOpen = false;
              this.showToast('Note added to project activity!');
              await this.loadProjectActivity(this.activeProject);
            } else {
              this.showToast((data && data.error) || 'Failed to add note', 'error');
            }
          } catch(e) {
