            this.showToast('Network error adding note', 'error');
          }
        },

        async deleteProjectActivity(act) {
          if (!act || !act.id) return;
          try {
            const res = await fetch('api/software.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'delete_activity', id: act.id })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              this.showToast('Activity note removed');
              await this.loadProjectActivity(this.activeProject);
            }
          } catch(e) {
            console.error(e);
          }
        },

        async submitProjectForm() {
          try {
            if (!this.projectForm.title || !this.projectForm.title.trim()) {
              this.showToast('Project Name is required', 'error');
              return;
            }
            const res = await fetch('api/software.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: 'edit',
                ...this.projectForm
              })
            });
            const data = await res.json();
            if (data && (data.success || data.status === 'success')) {
              const isEditing = !!this.projectForm.id;
              const editedId = this.projectForm.id;
              this.modalProjectOpen = false;
              this.showToast(isEditing ? 'Project updated successfully!' : 'Project created successfully!');
              await this.loadAllData();
              if (isEditing && editedId) {
                const refreshed = this.projects.find(p => p.id == editedId);
                if (refreshed) this.activeProject = refreshed;
              }
            } else {
              this.showToast((data && data.error) || 'Failed to save project', 'error');
            }
          } catch (e) {
            console.error(e);
            this.showToast('Error saving project', 'error');
          }
        },



        // ===================================================================
        // NOTIFICATIONS SYSTEM (Bell, Slide-over Drawer, Filters & Real CRM Sync)
        // ===================================================================
        openNotificationsModal() {
          this.modalNotificationsOpen = true;
          this.loadNotifications(this.notificationsFilter);
        },

        closeNotificationsModal() {
          if (typeof window !== 'undefined' && (new URLSearchParams(window.location.search)).get('keep_open') === '1') return;
          this.modalNotificationsOpen = false;
        },

        setNotificationsFilter(filter) {
          this.notificationsFilter = filter;
          this.loadNotifications(filter);
        },

        async loadNotifications(filter = null) {
          const category = filter || this.notificationsFilter || 'all';
          if (!this.notifications || this.notifications.length === 0) {
            this.notificationsLoading = true;
          }
          this.notificationsError = '';
          try {
            const res = await fetch('api/notifications.php?action=get_notifications&category=' + encodeURIComponent(category));
            const data = await res.json();
            if (data && data.status === 'success') {
              this.notifications = data.data || [];
              this.unreadNotificationsCount = Number(data.unread_count || 0);
              if (data.counts) {
                this.notificationsCounts = {
                  all: Number(data.counts.all || 0),
                  unread: Number(data.counts.unread || 0),
                  invoices: Number(data.counts.invoices || 0),
                  clients: Number(data.counts.clients || 0),
                  tasks: Number(data.counts.tasks || 0),
                  system: Number(data.counts.system || 0)
                };
              }
            } else {
              this.notificationsError = data.message || 'Unable to load notifications';
            }
          } catch (e) {
            console.error('Failed to load notifications:', e);
            this.notificationsError = 'Connection error loading notifications';
          } finally {
            this.notificationsLoading = false;
          }
        },

        async pollNotifications() {
          try {
            const res = await fetch('api/notifications.php?action=get_unread_count');
            const data = await res.json();
            if (data && data.status === 'success') {
              this.unreadNotificationsCount = Number(data.unread_count || 0);
              if (this.modalNotificationsOpen) {
                const listRes = await fetch('api/notifications.php?action=get_notifications&category=' + encodeURIComponent(this.notificationsFilter));
                const listData = await listRes.json();
                if (listData && listData.status === 'success') {
                  this.notifications = listData.data || [];
                  if (listData.counts) this.notificationsCounts = listData.counts;
                }
              }
            }
          } catch (e) {
            // Silently ignore polling errors in background
          }
        },

        startNotificationsPolling() {
          if (!this.notificationsPollingTimer) {
            this.notificationsPollingTimer = setInterval(() => {
              this.pollNotifications();
            }, 30000);
          }
        },

        async markNotificationAsRead(id, event = null) {
          if (event && event.stopPropagation) {
            event.stopPropagation();
          }
          if (!id) return;

          // Optimistically update locally
          const found = this.notifications.find(n => n.id == id);
          const wasUnread = found && !found.is_read;
          if (found) {
            found.is_read = 1;
          }
          if (wasUnread && this.unreadNotificationsCount > 0) {
            this.unreadNotificationsCount--;
            if (this.notificationsCounts.unread > 0) this.notificationsCounts.unread--;
          }

          try {
            const res = await fetch('api/notifications.php?action=mark_read', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ id: id })
            });
            const data = await res.json();
            if (data && data.status === 'success') {
              this.unreadNotificationsCount = Number(data.unread_count || this.unreadNotificationsCount);
            }
          } catch (e) {
            console.error('Failed to mark notification read:', e);
          }
        },

        async markAllNotificationsAsRead() {
          this.isMarkingAllNotificationsRead = true;
          try {
            const res = await fetch('api/notifications.php?action=mark_all_read', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({})
            });
            const data = await res.json();
            if (data && data.status === 'success') {
              this.notifications.forEach(n => { n.is_read = 1; });
              this.unreadNotificationsCount = 0;
              this.notificationsCounts.unread = 0;
              this.showToast('All notifications marked as read');
              if (this.notificationsFilter === 'unread') {
                this.loadNotifications('unread');
              }
            } else {
              this.showToast(data.message || 'Could not mark all as read', 'error');
            }
          } catch (e) {
            console.error('Failed to mark all as read:', e);
            this.showToast('Error marking all as read', 'error');
          } finally {
            this.isMarkingAllNotificationsRead = false;
          }
        },

        handleNotificationClick(item) {
          if (!item) return;

          // 1. Mark as read if unread
          if (!item.is_read) {
            this.markNotificationAsRead(item.id);
          }

          // 2. Close notification drawer
          this.closeNotificationsModal();

          // 3. Navigate to related CRM entity
          const linkType = (item.link_type || '').toLowerCase();
          const linkId = item.link_id;

          if (linkType === 'invoice') {
            if (linkId) {
              const found = this.invoices.find(x => x.id == linkId || x.invoice_no == linkId);
              if (found) {
                this.openInvoiceDetail(found);
              } else {
                this.openInvoiceDetail({ id: linkId, invoice_no: (item.metadata && item.metadata.invoice_no) ? item.metadata.invoice_no : linkId });
              }
            } else {
              this.navigateTo('invoices');
            }
          } else if (linkType === 'task') {
            if (linkId) {
              const found = this.tasks.find(x => x.id == linkId);
              if (found) {
                this.viewTaskDetail(found);
              } else {
                this.navigateTo('tasks');
              }
            } else {
              this.navigateTo('tasks');
            }
          } else if (linkType === 'contact') {
            if (linkId) {
              const found = this.contacts.find(x => x.id == linkId);
              if (found) {
                this.viewContactDetail(found);
              } else {
                this.navigateTo('contacts');
              }
            } else {
              this.navigateTo('contacts');
            }
          } else if (linkType === 'project') {
            if (linkId) {
              const found = this.projects.find(x => x.id == linkId);
              if (found) {
                this.viewProjectDetail(found);
              } else {
                this.navigateTo('projects');
              }
            } else {
              this.navigateTo('projects');
            }
          } else {
            this.showToast(item.title);
          }
        },

