        async loadTeamMembers() {
          try {
            const res = await fetch('api/teams.php');
            const data = await res.json();
            if (data && data.data) {
              this.teamMembers = data.data;
              if (this.activeTeamMember) {
                const refreshed = this.teamMembers.find(m => m.id === this.activeTeamMember.id);
                if (refreshed) this.activeTeamMember = refreshed;
              } else if (this.teamMembers.length > 0) {
                this.activeTeamMember = this.teamMembers[0];
              }
            }
          } catch (e) {
            console.error('Failed to load team members:', e);
          }
        },

