        async submitTeamMemberForm() {
          if (!this.teamMemberForm.name || !this.teamMemberForm.role) {
            this.showToast('Please enter member name and role', 'error');
            return;
          }
          const isEdit = !!this.teamMemberForm.id;
          const action = isEdit ? 'update' : 'create';
          
          if (!this.teamMemberForm.initials) {
            const parts = this.teamMemberForm.name.trim().split(/\s+/);
            this.teamMemberForm.initials = parts.length >= 2 
              ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
              : parts[0].substring(0, 2).toUpperCase();
          }
          
          try {
            const res = await fetch('api/teams.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: action, ...this.teamMemberForm })
            });
            const result = await res.json();
            if (result && result.success) {
              this.modalEditMemberOpen = false;
              this.showToast(isEdit ? 'Member updated successfully' : 'Member added successfully');
              await this.loadTeamMembers();
              if (isEdit && this.activeTeamMember && this.activeTeamMember.id === this.teamMemberForm.id) {
                const refreshed = this.teamMembers.find(m => m.id === this.teamMemberForm.id);
                if (refreshed) this.activeTeamMember = refreshed;
              }
            } else {
              this.showToast(result.error || 'Failed to save member', 'error');
            }
          } catch(e) {
            this.showToast('Network error saving member', 'error');
          }
        },

        openMemberActionMenu(m) {
          this.activeTeamMember = m || this.activeTeamMember;
          this.modalMemberMenuOpen = true;
        },

        async toggleMemberStatus(m) {
          const member = m || this.activeTeamMember;
          if (!member) return;
          this.modalMemberMenuOpen = false;
          const newStatus = (member.status || '').toLowerCase() === 'active' ? 'Inactive' : 'Active';
          try {
            const res = await fetch('api/teams.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ action: 'status', id: member.id, status: newStatus })
            });
            const result = await res.json();
            if (result && result.success) {
              member.status = newStatus;
              if (this.activeTeamMember && this.activeTeamMember.id === member.id) {
                this.activeTeamMember.status = newStatus;
              }
              this.showToast(`Status updated to ${newStatus}`);
              await this.loadTeamMembers();
            } else {
              this.showToast('Failed to update status', 'error');
            }
          } catch(e) {
            this.showToast('Network error updating status', 'error');
          }
