        async confirmDeleteTeamMember() {
          if (!this.memberToDelete) return;
          const mId = this.memberToDelete.id;
          this.modalConfirmDeleteMemberOpen = false;
          try {
            const res = await fetch('api/teams.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
