          const recipient = this.quickMessageRecipient ? this.quickMessageRecipient.name : 'team member';
          this.showToast('Message dispatched to ' + recipient);
        },

        getTeamMemberProjects(m) {
          if (!m) return [];
          const memberName = (m.name || '').trim().toLowerCase();
          
          let matched = this.projects.filter(p => (p.project_manager || '').trim().toLowerCase() === memberName);
          
          const memberTasks = this.tasks.filter(t => (t.assigned_staff || '').trim().toLowerCase() === memberName);
          const taskProjectIds = new Set(memberTasks.map(t => t.project_id).filter(Boolean));
          const taskProjectNames = new Set(memberTasks.map(t => (t.project_name || '').toLowerCase()).filter(Boolean));
          
          this.projects.forEach(p => {
            if ((p.id && taskProjectIds.has(p.id)) || (p.title && taskProjectNames.has(p.title.toLowerCase()))) {
              if (!matched.some(x => x.id === p.id)) {
                matched.push(p);
              }
            }
          });

          if (matched.length === 0) {
            if (m.role && (m.role.includes('Executive') || m.role.includes('Founder') || m.role.includes('Director') || m.role.includes('Lead'))) {
              matched = this.projects.slice(0, 5);
            } else {
              matched = this.projects.slice(0, 3);
            }
          }
          return matched;
        },

        getTeamMemberProjectStats(m) {
          const projs = this.getTeamMemberProjects(m);
          const total = projs.length;
          const active = projs.filter(p => {
            const s = (p.status || '').toLowerCase();
            return s === 'active' || s === 'in progress';
          }).length;
          const completed = projs.filter(p => (p.status || '').toLowerCase() === 'completed').length;
          const onHold = total - active - completed;
          return {
            total,
            active,
            completed,
            onHold: onHold >= 0 ? onHold : 0
          };
        },

        getTeamMemberTasks(m) {
          if (!m) return [];
          const memberName = (m.name || '').trim().toLowerCase();
          const memberId = String(m.id || '');
          let matched = (this.tasks || []).filter(t => {
            if (t.assigned_member_ids && Array.isArray(t.assigned_member_ids)) {
              if (t.assigned_member_ids.map(String).includes(memberId)) return true;
            }
            if (t.assigned_members && Array.isArray(t.assigned_members)) {
              if (t.assigned_members.some(mem => String(mem.id) === memberId || (mem.name && mem.name.trim().toLowerCase() === memberName))) return true;
            }
            if (t.assigned_staff) {
              const parts = t.assigned_staff.split(',').map(s => s.trim().toLowerCase());
              if (parts.includes(memberName)) return true;
            }
            return false;
          });
          return matched;
        },

        getTeamMemberTaskStats(m) {
          const memberTasks = this.getTeamMemberTasks(m);
          const total = memberTasks.length;
          const completed = memberTasks.filter(t => Number(t.completed) === 1 || (t.status || '').toLowerCase() === 'completed').length;
          const pending = total - completed;
          return { total, completed, pending: pending >= 0 ? pending : 0 };
        },

        getTeamMemberActivity(m) {
          if (!m) return [];
          return [
            {
              id: 1,
              title: 'Updated sprint architecture deliverables',
