        // ===================================================================
        // GROUP CHART & TEAM STRUCTURE ACTIONS & APIS
        // ===================================================================
        async loadGroupChartData() {
          this.isGroupChartLoading = true;
          try {
            // 1. Fetch Summary Statistics
            const resSum = await fetch('api/groups.php?action=summary');
            const dataSum = await resSum.json();
            if (dataSum && dataSum.data) {
              this.groupSummary = dataSum.data;
            }

            // 2. Fetch Groups List
            const resList = await fetch('api/groups.php?action=list');
            const dataList = await resList.json();
            if (dataList && dataList.data) {
              this.groups = dataList.data;
              if (this.groups.length > 0) {
                // If activeGroup exists, refresh it; otherwise pick first group
                if (this.activeGroup && this.activeGroup.id) {
                  const found = this.groups.find(g => g.id === this.activeGroup.id);
                  await this.selectGroup(found ? found.id : this.groups[0].id, false);
                } else {
                  await this.selectGroup(this.groups[0].id, false);
                }
              } else {
                this.activeGroup = null;
              }
            }
          } catch (e) {
            console.error('Failed to load group chart data:', e);
          } finally {
            this.isGroupChartLoading = false;
          }
        },

        async selectGroup(groupId, showLoading = true) {
          if (!groupId) return;
          if (showLoading) this.isGroupChartLoading = true;
          try {
            const res = await fetch(`api/groups.php?id=${encodeURIComponent(groupId)}`);
            const data = await res.json();
            if (data && data.data) {
              this.activeGroup = data.data;
            }
          } catch (e) {
            console.error('Failed to fetch group details:', e);
          } finally {
            if (showLoading) this.isGroupChartLoading = false;
          }
        },

