        async submitGroupForm() {
          this.groupFormErrors = {};
          const name = (this.groupForm.name || '').trim();
          if (!name) {
            this.groupFormErrors.name = 'Group name is required';
            return;
          }
          if (name.length < 2) {
            this.groupFormErrors.name = 'Group name must be at least 2 characters';
            return;
          }

          if (!this.groupForm.company_id) {
            this.groupFormErrors.company_id = 'Please select a company';
            return;
          }

          this.isSubmittingGroupForm = true;
          const isEdit = this.isEditingGroup && this.groupForm.id;
          const action = isEdit ? 'update' : 'create';

          try {
            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: action,
                id: this.groupForm.id,
                name: name,
                company_id: this.groupForm.company_id,
                description: this.groupForm.description || '',
                leader_id: this.groupForm.leader_id || null,
                color: this.groupForm.color || '#590907',
                icon: this.groupForm.icon || 'users',
                member_ids: this.groupForm.selected_member_ids || [],
                csrf_token: this.csrfToken || ''
              })
            });

            const result = await res.json();
            if (result && result.success) {
              this.modalGroupFormOpen = false;
              this.showToast(result.message || (isEdit ? 'Group updated successfully' : 'Group created successfully'));
              await this.loadGroupChartData();
              if (result.data && result.data.id) {
                await this.selectGroup(result.data.id);
              }
            } else {
              this.groupFormErrors.general = result.message || 'Operation failed';
              this.showToast(result.message || 'Validation error', 'error');
            }
          } catch (e) {
            this.groupFormErrors.general = 'Network error saving group';
            this.showToast('Network error saving group', 'error');
          } finally {
            this.isSubmittingGroupForm = false;
          }
        },

