                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'add_members',
                group_id: this.activeGroup.id,
                employee_ids: this.selectedMemberIdsToAdd,
