              await this.loadGroupChartData();
              await this.selectGroup(this.activeGroup.id);
            } else {
              this.showToast(result.message || 'Failed to add members', 'error');
            }
          } catch (e) {
            this.showToast('Network error adding members', 'error');
          } finally {
            this.isSubmittingAddMembers = false;
          }
        },

