          this.modalConfirmDeleteGroupOpen = true;
        },

        async confirmDeleteGroup() {
          if (!this.groupToDelete) return;
          this.isSubmittingDeleteGroup = true;
          try {
            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'delete',
                id: this.groupToDelete.id,
                csrf_token: this.csrfToken || ''
              })
            });

            const result = await res.json();
            if (result && result.success) {
              this.modalConfirmDeleteGroupOpen = false;
              const deletedId = this.groupToDelete.id;
              this.groupToDelete = null;
              this.showToast(result.message || 'Group deleted successfully');
              if (this.activeGroup && this.activeGroup.id === deletedId) {
                this.activeGroup = null;
              }
              await this.loadGroupChartData();
            } else {
              this.showToast(result.message || 'Failed to delete group', 'error');
            }
          } catch (e) {
            this.showToast('Network error deleting group', 'error');
          } finally {
            this.isSubmittingDeleteGroup = false;
          }
        },

        async quickChangeGroupLeader(newLeaderId) {
          if (!this.activeGroup) return;
          try {
            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'change_leader',
                group_id: this.activeGroup.id,
                leader_id: newLeaderId || null,
                csrf_token: this.csrfToken || ''
              })
            });
            const result = await res.json();
            if (result && result.success) {
              this.showToast(result.message || 'Leader updated successfully');
              await this.loadGroupChartData();
              await this.selectGroup(this.activeGroup.id);
            } else {
              this.showToast(result.message || 'Failed to update leader', 'error');
            }
          } catch (e) {
            this.showToast('Network error updating leader', 'error');
          }
        },

        // ===================================================================
        // GROUP CHATS, WEBRTC CALLING & MEMBER CHARTS CONTROLLER
        // ===================================================================
        async openGroupChat(group = null) {
          if (!group) {
            const channels = this.filteredChatChannels;
            group = (this.activeGroup) ? this.activeGroup : (channels.length > 0 ? channels[0].raw || channels[0] : null);
          }
          if (group && group.raw) group = group.raw;
          this.activeChatGroup = group;
          this.modalTeamChatOpen = true;
          this.chatInputText = '';
          this.chatReplyTo = null;
          this.chatEditingMessage = null;
          this.chatOpenMessageMenuId = null;
          if (group && group.id) {
            await this.loadGroupChatMessages(group.id);
            this.startChatSync();
          }
        },

        closeGroupChat() {
          this.modalTeamChatOpen = false;
          this.chatOpenMessageMenuId = null;
          this.chatReplyTo = null;
          this.chatEditingMessage = null;
          if (!this.modalGroupCallOpen) {
            this.stopChatSync();
          }
        },

        async selectChatChannel(channel) {
          const group = channel.raw || channel;
          this.activeChatGroup = group;
          this.chatInputText = '';
          this.chatReplyTo = null;
          this.chatEditingMessage = null;
          this.chatOpenMessageMenuId = null;
          await this.loadGroupChatMessages(group.id);
        },

        async loadGroupChatMessages(groupId) {
          if (!groupId) return;
          try {
            const res = await fetch(`api/groups.php?action=messages&group_id=${groupId}`);
            const data = await res.json();
            if (data && data.success && Array.isArray(data.data)) {
              this.chatMessages = data.data;
              if (this.chatMessages.length > 0) {
                this.chatLastMsgId = Math.max(...this.chatMessages.map(m => Number(m.id) || 0));
              } else {
                this.chatLastMsgId = 0;
              }
              this.$nextTick(() => {
                this.scrollChatToBottom();
              });
            }
          } catch (e) {
            console.error('Failed to load group chat messages:', e);
          }
        },

        scrollChatToBottom() {
          const container = document.getElementById('chatMessagesContainer');
          if (container) {
            container.scrollTop = container.scrollHeight;
          }
        },

        startChatSync() {
          if (this.chatSyncTimer) clearInterval(this.chatSyncTimer);
          this.chatSyncTimer = setInterval(async () => {
            if (!this.activeChatGroup && !this.modalGroupCallOpen) return;
            const groupId = this.activeChatGroup ? this.activeChatGroup.id : (this.activeCall ? this.activeCall.group_id : 0);
            const callId = this.activeCall ? this.activeCall.id : 0;
            if (!groupId) return;
            try {
              const res = await fetch(`api/groups.php?action=chat_sync&group_id=${groupId}&last_msg_id=${this.chatLastMsgId}&call_id=${callId}&last_signal_id=${this.chatLastSignalId}`);
              const data = await res.json();
              if (data && data.success) {
                // 1. New Messages
                if (data.new_messages && data.new_messages.length > 0) {
                  for (const nm of data.new_messages) {
                    const exists = this.chatMessages.find(m => m.id === nm.id);
                    if (!exists) {
                      this.chatMessages.push(nm);
                      if (nm.id > this.chatLastMsgId) this.chatLastMsgId = nm.id;
                    }
                  }
                  this.$nextTick(() => { this.scrollChatToBottom(); });
                }
                // 2. Updated messages (receipts, edits, deletions)
                if (data.updated_messages && data.updated_messages.length > 0) {
                  for (const um of data.updated_messages) {
                    const idx = this.chatMessages.findIndex(m => m.id === um.id);
                    if (idx !== -1) {
                      this.chatMessages[idx] = Object.assign({}, this.chatMessages[idx], um);
                    }
                  }
                }
                // 3. Removed messages (delete for me)
                if (data.deleted_msg_ids && data.deleted_msg_ids.length > 0) {
                  this.chatMessages = this.chatMessages.filter(m => !data.deleted_msg_ids.includes(m.id));
                }
                // 4. Incoming call detection
                if (data.active_call && !this.modalGroupCallOpen) {
                  if (data.active_call.call_status === 'calling' || data.active_call.call_status === 'ringing') {
                    if (Number(data.active_call.initiator_id) !== Number(this.currentUser.id)) {
                      this.incomingCall = data.active_call;
                      this.incomingCallBanner = true;
                    }
                  }
                } else if (!data.active_call && this.incomingCallBanner) {
                  this.incomingCallBanner = false;
                  this.incomingCall = null;
                }
                // 5. Active call state sync when in call
                if (this.modalGroupCallOpen && data.active_call) {
                  this.activeCall = Object.assign({}, this.activeCall, data.active_call);
                  if (data.participants && Array.isArray(data.participants)) {
                    this.callParticipants = data.participants;
                  }
                  if (data.active_call.call_status === 'ended') {
                    this.leaveGroupCall(false);
                    this.showToast('Call has ended');
                  }
                }
              }
            } catch (e) {
              // sync error ignored
            }
          }, 2500);
        },

        stopChatSync() {
          if (this.chatSyncTimer) {
            clearInterval(this.chatSyncTimer);
            this.chatSyncTimer = null;
          }
        },

        async submitChatMessage() {
          const text = (this.chatInputText || '').trim();
          if (!text || !this.activeChatGroup) return;
          if (this.chatEditingMessage) {
            await this.saveEditedGroupMessage();
            return;
          }

          const tempId = 'temp_' + Date.now();
          const newMsg = {
            id: tempId,
            group_id: this.activeChatGroup.id,
            user_id: this.currentUser.id,
            user_name: this.currentUser.name || 'You',
            user_role: this.currentUser.role || 'Member',
            message_type: 'text',
            message: text,
            reply_to_id: this.chatReplyTo ? this.chatReplyTo.id : null,
            reply_to_name: this.chatReplyTo ? this.chatReplyTo.user_name : null,
            reply_to_text: this.chatReplyTo ? this.chatReplyTo.message : null,
            deletion_state: 'none',
            created_at: new Date().toISOString(),
            is_own: true,
            receipt_summary: 'sending',
            has_failed: false
          };

          this.chatMessages.push(newMsg);
          this.chatInputText = '';
          const savedReply = this.chatReplyTo;
          this.chatReplyTo = null;
          this.$nextTick(() => { this.scrollChatToBottom(); });

          try {
            this.chatIsSending = true;
            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'send_message',
                group_id: this.activeChatGroup.id,
                message: text,
                reply_to_id: savedReply ? savedReply.id : null,
                csrf_token: this.csrfToken || ''
              })
            });
            const data = await res.json();
            if (data && data.success && data.data) {
              const idx = this.chatMessages.findIndex(m => m.id === tempId);
              if (idx !== -1) {
                this.chatMessages[idx] = data.data;
                if (data.data.id > this.chatLastMsgId) {
                  this.chatLastMsgId = data.data.id;
                }
              }
            } else {
              const idx = this.chatMessages.findIndex(m => m.id === tempId);
              if (idx !== -1) {
                this.chatMessages[idx].receipt_summary = 'failed';
                this.chatMessages[idx].has_failed = true;
              }
              this.showToast(data.message || 'Failed to send message', 'error');
            }
          } catch (e) {
            const idx = this.chatMessages.findIndex(m => m.id === tempId);
            if (idx !== -1) {
              this.chatMessages[idx].receipt_summary = 'failed';
              this.chatMessages[idx].has_failed = true;
            }
            this.showToast('Network error sending message', 'error');
          } finally {
            this.chatIsSending = false;
          }
        },

        async retryChatMessage(msg) {
          if (!msg) return;
          msg.receipt_summary = 'sending';
          msg.has_failed = false;
          try {
            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'send_message',
                group_id: msg.group_id,
                message: msg.message,
                reply_to_id: msg.reply_to_id || null,
                csrf_token: this.csrfToken || ''
              })
            });
            const data = await res.json();
            if (data && data.success && data.data) {
              const idx = this.chatMessages.findIndex(m => m.id === msg.id);
              if (idx !== -1) {
                this.chatMessages[idx] = data.data;
              }
              this.showToast('Message sent successfully');
            } else {
              msg.receipt_summary = 'failed';
              msg.has_failed = true;
              this.showToast(data.message || 'Failed to retry sending message', 'error');
            }
          } catch (e) {
            msg.receipt_summary = 'failed';
            msg.has_failed = true;
            this.showToast('Network error on retry', 'error');
          }
        },

        replyToGroupMessage(msg) {
          this.chatReplyTo = msg;
          this.chatEditingMessage = null;
          this.chatOpenMessageMenuId = null;
          const input = document.getElementById('chatInputMessage');
          if (input) input.focus();
        },

        cancelChatReply() {
          this.chatReplyTo = null;
        },

        copyGroupMessage(msg) {
          if (!msg || !msg.message) return;
          if (navigator.clipboard) {
            navigator.clipboard.writeText(msg.message);
          }
          this.chatOpenMessageMenuId = null;
          this.showToast('Message copied to clipboard');
        },

        startEditGroupMessage(msg) {
          this.chatEditingMessage = msg;
          this.chatInputText = msg.message;
          this.chatReplyTo = null;
          this.chatOpenMessageMenuId = null;
          const input = document.getElementById('chatInputMessage');
          if (input) input.focus();
        },

        cancelEditGroupMessage() {
          this.chatEditingMessage = null;
          this.chatInputText = '';
        },

        async saveEditedGroupMessage() {
          if (!this.chatEditingMessage) return;
          const text = (this.chatInputText || '').trim();
          if (!text) return;
          try {
            const msgId = this.chatEditingMessage.id;
