              },
              body: JSON.stringify({
                action: 'edit_message',
                message_id: msgId,
                message: text,
                csrf_token: this.csrfToken || ''
              })
            });
            const data = await res.json();
            if (data && data.success && data.data) {
              const idx = this.chatMessages.findIndex(m => m.id === msgId);
              if (idx !== -1) {
                this.chatMessages[idx] = Object.assign({}, this.chatMessages[idx], data.data);
              }
              this.showToast('Message edited');
            } else {
              this.showToast(data.message || 'Failed to edit message', 'error');
            }
          } catch (e) {
            this.showToast('Network error editing message', 'error');
          } finally {
            this.chatEditingMessage = null;
            this.chatInputText = '';
          }
        },

