              }
              this.showToast('Message deleted for everyone');
              this.modalConfirmDeleteForEveryoneOpen = false;
              this.messageToDeleteForEveryone = null;
            } else {
              this.showToast(data.message || 'Failed to delete message for everyone', 'error');
            }
          } catch (e) {
