        },

        async openMessageInfo(msg) {
          if (!msg) return;
          this.chatOpenMessageMenuId = null;
          this.activeMessageInfo = null;
          this.isLoadingMessageInfo = true;
          this.modalMessageInfoOpen = true;
          try {
            const res = await fetch(`api/groups.php?action=get_message_info&message_id=${msg.id}`);
            const data = await res.json();
            if (data && data.success && data.data) {
