          }
        },

        closeMessageInfo() {
          this.modalMessageInfoOpen = false;
          this.activeMessageInfo = null;
        },

        // WebRTC Calling & Screen Sharing Methods
        async startGroupCall(type = 'audio') {
          if (!this.activeChatGroup) {
            this.showToast('Please select a group first', 'error');
            return;
          }
          this.callType = type;
          this.callStatus = 'calling';
          this.callDuration = 0;
          this.isCallMuted = false;
          this.isCallCameraOff = (type === 'audio');
          this.isCallScreenSharing = false;
          this.modalGroupCallOpen = true;

          try {
            try {
              if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
                this.localMediaStream = await navigator.mediaDevices.getUserMedia({
                  audio: true,
                  video: (type === 'video')
                });
                const localVideoEl = document.getElementById('localVideoFeed');
                if (localVideoEl && this.localMediaStream) {
                  localVideoEl.srcObject = this.localMediaStream;
                }
              }
            } catch (mediaErr) {
              console.warn('Microphone/Camera permission denied or unavailable:', mediaErr);
              this.showToast('Media devices not accessible, proceeding in signaling mode', 'info');
            }

            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'start_call',
                group_id: this.activeChatGroup.id,
                call_type: type,
                csrf_token: this.csrfToken || ''
              })
            });
            const data = await res.json();
            if (data && data.success && data.data) {
              this.activeCall = data.data;
              this.callParticipants = data.participants || [];
              this.callStatus = 'connected';
              this.startCallDurationTimer();
              this.startChatSync();
              this.showToast(`${type === 'video' ? 'Video' : 'Audio'} call started`);
            } else {
              this.callStatus = 'failed';
              this.showToast(data.message || 'Failed to start call', 'error');
            }
          } catch (e) {
            this.callStatus = 'failed';
            this.showToast('Network error starting call', 'error');
          }
        },

        async joinIncomingCall() {
          if (!this.incomingCall) return;
          const call = this.incomingCall;
          this.incomingCallBanner = false;
          this.incomingCall = null;
          this.callType = call.call_type || 'audio';
          this.callStatus = 'connecting';
          this.callDuration = 0;
          this.isCallMuted = false;
          this.isCallCameraOff = (this.callType === 'audio');
          this.isCallScreenSharing = false;
          this.modalGroupCallOpen = true;

          try {
            try {
              if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
                this.localMediaStream = await navigator.mediaDevices.getUserMedia({
                  audio: true,
                  video: (this.callType === 'video')
                });
                const localVideoEl = document.getElementById('localVideoFeed');
                if (localVideoEl && this.localMediaStream) {
                  localVideoEl.srcObject = this.localMediaStream;
                }
              }
            } catch (mediaErr) {
              console.warn('Microphone/Camera permission denied or unavailable:', mediaErr);
            }

            const res = await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'join_call',
                call_id: call.id,
                csrf_token: this.csrfToken || ''
              })
            });
            const data = await res.json();
            if (data && data.success && data.data) {
              this.activeCall = data.data;
              this.callParticipants = data.participants || [];
              this.callStatus = 'connected';
              this.startCallDurationTimer();
              this.startChatSync();
              this.showToast('Joined group call');
            } else {
              this.callStatus = 'failed';
              this.showToast(data.message || 'Failed to join call', 'error');
            }
          } catch (e) {
            this.callStatus = 'failed';
            this.showToast('Network error joining call', 'error');
          }
        },

        dismissIncomingCall() {
          this.incomingCallBanner = false;
          this.incomingCall = null;
        },

        async toggleCallMute() {
          this.isCallMuted = !this.isCallMuted;
          if (this.localMediaStream) {
            this.localMediaStream.getAudioTracks().forEach(track => {
              track.enabled = !this.isCallMuted;
            });
          }
          if (this.activeCall) {
            await this.updateCallMediaState();
          }
        },

        async toggleCallCamera() {
          this.isCallCameraOff = !this.isCallCameraOff;
          if (this.localMediaStream) {
            this.localMediaStream.getVideoTracks().forEach(track => {
              track.enabled = !this.isCallCameraOff;
            });
          }
          if (this.activeCall) {
            await this.updateCallMediaState();
          }
        },

        async toggleScreenShare() {
          if (this.isCallScreenSharing) {
            await this.stopScreenShare();
          } else {
            await this.startScreenShare();
          }
        },

        async startScreenShare() {
          if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) {
            this.showToast('Screen sharing is not supported by this browser/device', 'error');
            return;
          }
          try {
            this.screenShareStream = await navigator.mediaDevices.getDisplayMedia({
              video: { cursor: 'always' },
              audio: false
            });
            this.isCallScreenSharing = true;

            const screenVideoEl = document.getElementById('screenShareVideoFeed');
            if (screenVideoEl) {
              screenVideoEl.srcObject = this.screenShareStream;
            }

            this.screenShareStream.getVideoTracks()[0].addEventListener('ended', () => {
              this.stopScreenShare();
            });

            await this.updateCallMediaState();
            this.showToast('Screen presentation started');
          } catch (e) {
            console.warn('Screen sharing cancelled or denied:', e);
            this.isCallScreenSharing = false;
          }
        },

        async stopScreenShare() {
          if (this.screenShareStream) {
            this.screenShareStream.getTracks().forEach(track => track.stop());
            this.screenShareStream = null;
          }
          this.isCallScreenSharing = false;
          await this.updateCallMediaState();
          this.showToast('Screen presentation stopped');
        },

        async updateCallMediaState() {
          if (!this.activeCall) return;
          try {
            await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'update_call_media',
                call_id: this.activeCall.id,
                is_muted: this.isCallMuted ? 1 : 0,
                is_camera_off: this.isCallCameraOff ? 1 : 0,
                is_screen_sharing: this.isCallScreenSharing ? 1 : 0,
                csrf_token: this.csrfToken || ''
              })
            });
          } catch (e) {
            // ignored
          }
        },

        async leaveGroupCall(notifyServer = true) {
          if (this.screenShareStream) {
            this.screenShareStream.getTracks().forEach(track => track.stop());
            this.screenShareStream = null;
          }
          if (this.localMediaStream) {
            this.localMediaStream.getTracks().forEach(track => track.stop());
            this.localMediaStream = null;
          }
          this.stopCallDurationTimer();
          const callId = this.activeCall ? this.activeCall.id : null;
          this.modalGroupCallOpen = false;
          this.activeCall = null;
          this.callStatus = 'ended';
          this.isCallScreenSharing = false;

          if (notifyServer && callId) {
            try {
              await fetch('api/groups.php', {
                method: 'POST',
                headers: {
                  'Content-Type': 'application/json',
                  'X-CSRF-Token': this.csrfToken || ''
                },
                body: JSON.stringify({
                  action: 'leave_call',
                  call_id: callId,
                  csrf_token: this.csrfToken || ''
                })
              });
            } catch (e) {
              // ignored
            }
          }
        },

        async endGroupCallForEveryone() {
          if (!this.activeCall) return;
          if (this.screenShareStream) {
            this.screenShareStream.getTracks().forEach(track => track.stop());
            this.screenShareStream = null;
          }
          if (this.localMediaStream) {
            this.localMediaStream.getTracks().forEach(track => track.stop());
            this.localMediaStream = null;
          }
          this.stopCallDurationTimer();
          const callId = this.activeCall.id;
          this.modalGroupCallOpen = false;
          this.activeCall = null;
          this.callStatus = 'ended';
          this.isCallScreenSharing = false;

          try {
            await fetch('api/groups.php', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': this.csrfToken || ''
              },
              body: JSON.stringify({
                action: 'end_call',
                call_id: callId,
                csrf_token: this.csrfToken || ''
              })
            });
            this.showToast('Call ended for everyone');
          } catch (e) {
            this.showToast('Error ending call', 'error');
          }
        },

        startCallDurationTimer() {
          this.stopCallDurationTimer();
          this.callDuration = 0;
          this.callDurationFormatted = '00:00';
          this.callDurationTimer = setInterval(() => {
            this.callDuration++;
            const mins = Math.floor(this.callDuration / 60);
            const secs = this.callDuration % 60;
            this.callDurationFormatted = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
          }, 1000);
        },

        stopCallDurationTimer() {
          if (this.callDurationTimer) {
            clearInterval(this.callDurationTimer);
            this.callDurationTimer = null;
          }
        },

        // Member Workload Analytics & Charting Methods
        async openMemberChartModal(member) {
          if (!member) return;
          this.activeMemberForChart = member;
          this.memberChartData = null;
          this.isLoadingMemberChart = true;
          this.modalMemberChartOpen = true;

          try {
            const empId = member.id || member.employee_id;
            const grpId = this.activeGroup ? this.activeGroup.id : 0;
            const res = await fetch(`api/groups.php?action=member_chart_data&employee_id=${empId}&group_id=${grpId}`);
            const data = await res.json();
            if (data && data.success && data.data) {
              this.memberChartData = data.data;
            } else {
              this.showToast(data.message || 'Unable to load member chart data', 'error');
            }
          } catch (e) {
            this.showToast('Network error loading member chart', 'error');
          } finally {
            this.isLoadingMemberChart = false;
          }
        },

        closeMemberChartModal() {
          this.modalMemberChartOpen = false;
          this.activeMemberForChart = null;
          this.memberChartData = null;
        },

        // ===================================================================
        // COMPANY MANAGEMENT CONTROLLER (API Connected & Interactive)
        // ===================================================================
        async loadCompanies(selectedId = null) {
          try {
            this.companiesLoading = true;
            const res = await fetch('api/companies.php');
            const data = await res.json();
            if (data && data.success && Array.isArray(data.data)) {
              this.companies = data.data;
              if (selectedId) {
                const found = this.companies.find(c => c.id === selectedId);
                if (found) this.activeCompany = found;
              } else if (this.activeCompany && this.activeCompany.id) {
                const refreshed = this.companies.find(c => c.id === this.activeCompany.id);
                if (refreshed) {
                  this.activeCompany = { ...this.activeCompany, ...refreshed };
                }
              }
            }
          } catch (e) {
            console.error('Error loading companies:', e);
          } finally {
            this.companiesLoading = false;
          }
        },

        async viewCompanyDetail(compOrId) {
          try {
            const compId = typeof compOrId === 'object' && compOrId ? compOrId.id : compOrId;
            if (!compId) return;

            // Set immediate active company from list if available
            const localComp = typeof compOrId === 'object' && compOrId ? compOrId : this.companies.find(c => c.id === compId);
            if (localComp) {
              this.activeCompany = { ...localComp };
            }

            this.companyDetailTab = 'overview';
            this.navigateTo('company_detail');

            // Fetch complete company record with associated contacts, projects, and invoices
            const res = await fetch(`api/companies.php?id=${encodeURIComponent(compId)}`);
            const data = await res.json();
            if (data && data.success && data.data) {
              this.activeCompany = data.data;
            } else if (data && !data.success) {
              this.showToast(data.message || 'Company not found', 'error');
            }
          } catch (e) {
            console.error('Error loading company details:', e);
            this.showToast('Failed to load company details', 'error');
          }
        },

        openAddCompanyModal() {
          this.companyFormMode = 'create';
          this.companyForm = {
            id: '',
            name: '',
            industry: '',
            website: '',
            email: '',
            phone: '',
            address: '',
            description: ''
          };
          this.companyFormError = '';
          this.modalCompanyFormOpen = true;
        },

        openEditCompanyModal(comp = null) {
          const target = comp || this.activeCompany;
          if (!target) return;
          this.companyFormMode = 'edit';
          this.companyForm = {
            id: target.id || '',
            name: target.name || '',
            industry: target.industry || '',
            website: target.website || '',
            email: target.email || '',
            phone: target.phone || '',
            address: target.address || '',
            description: target.description || ''
          };
          this.companyFormError = '';
          this.modalCompanyFormOpen = true;
        },

        async saveCompanyForm() {
          this.companyFormError = '';
          const name = (this.companyForm.name || '').trim();
          if (!name) {
            this.companyFormError = 'Company name is required.';
            return;
          }

          this.isSavingCompany = true;
          try {
            const payload = {
              action: this.companyFormMode === 'create' ? 'create' : 'update',
              id: this.companyForm.id,
              name: name,
              industry: (this.companyForm.industry || '').trim(),
              website: (this.companyForm.website || '').trim(),
              email: (this.companyForm.email || '').trim(),
              phone: (this.companyForm.phone || '').trim(),
              address: (this.companyForm.address || '').trim(),
              description: (this.companyForm.description || '').trim()
            };

            const res = await fetch('api/companies.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });

            const data = await res.json();
            if (data && data.success) {
              this.modalCompanyFormOpen = false;
              this.showToast(this.companyFormMode === 'create' ? 'Company created!' : 'Company updated!');
              await this.loadCompanies();
              const savedId = (data.data && data.data.id) ? data.data.id : this.companyForm.id;
              if (this.modalGroupFormOpen && savedId) {
                this.groupForm.company_id = savedId;
                if (this.groupFormErrors) this.groupFormErrors.company_id = '';
              } else if (this.currentView === 'company_detail' || this.companyFormMode === 'create') {
                if (savedId) {
                  await this.viewCompanyDetail(savedId);
                }
              }
            } else {
              this.companyFormError = (data && data.message) ? data.message : 'Failed to save company';
            }
          } catch (e) {
            console.error('Save company error:', e);
            this.companyFormError = 'Network error saving company. Please try again.';
          } finally {
            this.isSavingCompany = false;
          }
        },

        promptDeleteCompany(comp = null) {
          const target = comp || this.activeCompany;
          if (!target) return;
          this.companyToDelete = target;
          this.modalConfirmDeleteCompanyOpen = true;
        },

        async confirmDeleteCompany() {
          if (!this.companyToDelete || !this.companyToDelete.id) return;
          this.isDeletingCompany = true;
          try {
            const res = await fetch('api/companies.php', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: 'delete',
                id: this.companyToDelete.id
              })
            });

            const data = await res.json();
            if (data && data.success) {
              this.modalConfirmDeleteCompanyOpen = false;
              this.showToast('Company deleted successfully');
              if (this.currentView === 'company_detail') {
                this.navigateTo('companies');
              }
              await this.loadCompanies();
              // Also refresh contacts to reflect unlinked company status
              const resC = await fetch('api/pocket_api.php?action=get_contacts');
              const dataC = await resC.json();
              if (dataC && dataC.data) {
                this.contacts = dataC.data;
              }
            } else {
              this.showToast((data && data.message) ? data.message : 'Failed to delete company', 'error');
            }
          } catch (e) {
            console.error('Delete company error:', e);
            this.showToast('Network error deleting company', 'error');
          } finally {
            this.isDeletingCompany = false;
          }
        },

        // =====================================================================
        // REPORTS & FINANCIAL DASHBOARD METHODS
        // =====================================================================
        async loadReports() {
          this.reportsState.loading = true;
          try {
            const params = new URLSearchParams();
            params.set('action', 'summary');
            params.set('period_type', this.reportsState.periodType);
            if (this.reportsState.periodType === 'month') {
              params.set('month', this.reportsState.selectedMonth);
            } else if (this.reportsState.periodType === 'year') {
              params.set('year', this.reportsState.selectedYear);
            } else if (this.reportsState.periodType === 'custom') {
              params.set('start_date', this.reportsState.customStartDate);
              params.set('end_date', this.reportsState.customEndDate);
            }

            const res = await fetch(`api/reports.php?${params.toString()}`);
            const json = await res.json();
            if (json && json.success && json.data) {
              this.reportsState.summary = json.data;
              this.reportsState.periodLabel = json.data.period.label;
            }

            // Also load payments for period
            params.set('action', 'payments');
            if (this.reportsState.paymentsMethodFilter !== 'all') {
              params.set('payment_method', this.reportsState.paymentsMethodFilter);
            }
            if (this.reportsState.paymentsStatusFilter !== 'all') {
              params.set('status', this.reportsState.paymentsStatusFilter);
            }
            if (this.reportsState.paymentsSearch) {
              params.set('search', this.reportsState.paymentsSearch);
            }
            params.set('sort_by', this.reportsState.paymentsSortBy);
            params.set('sort_order', this.reportsState.paymentsSortOrder);

            const pRes = await fetch(`api/reports.php?${params.toString()}`);
            const pJson = await pRes.json();
            if (pJson && pJson.success) {
              this.reportsState.payments = pJson.data || [];
              this.reportsState.paymentsTotal = pJson.total_amount || 0;
            }

            // Also load expenses for period
            params.set('action', 'expenses');
            params.delete('payment_method');
            params.delete('status');
            if (this.reportsState.expensesCategoryFilter !== 'all') {
              params.set('category', this.reportsState.expensesCategoryFilter);
            }
            if (this.reportsState.expensesMethodFilter !== 'all') {
              params.set('payment_method', this.reportsState.expensesMethodFilter);
            }
            if (this.reportsState.expensesSearch) {
              params.set('search', this.reportsState.expensesSearch);
            }
            params.set('sort_by', this.reportsState.expensesSortBy);
            params.set('sort_order', this.reportsState.expensesSortOrder);

            const eRes = await fetch(`api/reports.php?${params.toString()}`);
            const eJson = await eRes.json();
            if (eJson && eJson.success) {
              this.reportsState.expenses = eJson.data || [];
              this.reportsState.expensesTotal = eJson.total_amount || 0;
              this.reportsState.categoryTotals = eJson.category_totals || {};
            }

            // Render/Update charts
            this.$nextTick(() => {
              this.renderReportsCharts();
            });
          } catch (e) {
            console.error('Error loading reports:', e);
            this.showToast('Failed to load financial reports', 'error');
          } finally {
            this.reportsState.loading = false;
          }
        },

        changeReportMonth(delta) {
          const parts = this.reportsState.selectedMonth.split('-');
          let yr = parseInt(parts[0], 10);
          let mo = parseInt(parts[1], 10);
          mo += delta;
          if (mo < 1) {
            mo = 12;
            yr -= 1;
          } else if (mo > 12) {
            mo = 1;
            yr += 1;
          }
          this.reportsState.selectedMonth = `${yr}-${mo < 10 ? '0' + mo : mo}`;
          this.reportsState.periodType = 'month';
          this.loadReports();
        },

        applyCustomReportRange() {
          if (!this.reportsState.customStartDate || !this.reportsState.customEndDate) {
            this.showToast('Please select both Start Date and End Date', 'error');
            return;
          }
          this.reportsState.periodType = 'custom';
          this.reportsState.customRangePopoverOpen = false;
          this.loadReports();
        },

        resetReportMonth() {
          const now = new Date();
          const yr = now.getFullYear();
          const mo = now.getMonth() + 1;
          this.reportsState.selectedMonth = `${yr}-${mo < 10 ? '0' + mo : mo}`;
          this.reportsState.periodType = 'month';
          this.reportsState.customStartDate = '';
          this.reportsState.customEndDate = '';
          this.loadReports();
        },

        toggleReportsWideMode() {
          this.reportsState.wideMode = !this.reportsState.wideMode;
          this.$nextTick(() => {
            this.renderReportsCharts();
          });
        },

        downloadReport(format) {
          this.reportsState.exportMenuOpen = false;
          const params = new URLSearchParams();
          params.set('action', 'export');
          params.set('format', format);
          params.set('period_type', this.reportsState.periodType);
          if (this.reportsState.periodType === 'month') {
            params.set('month', this.reportsState.selectedMonth);
          } else if (this.reportsState.periodType === 'custom') {
            params.set('start_date', this.reportsState.customStartDate);
            params.set('end_date', this.reportsState.customEndDate);
          }
          const url = `api/reports.php?${params.toString()}`;
          if (format === 'print') {
            window.open(url, '_blank', 'width=1000,height=800');
          } else {
            window.location.href = url;
            this.showToast(`Generating ${format.toUpperCase()} report download...`);
          }
        },

        openAddExpenseModal() {
          this.expenseForm = {
            id: '',
            expense_date: new Date().toISOString().split('T')[0],
            category: 'Software & Tools',
            description: '',
            amount: '',
            payment_method: 'Bank Transfer',
            reference: '',
            notes: ''
          };
          this.modalExpenseOpen = true;
        },

        openEditExpenseModal(e) {
          this.expenseForm = {
            id: e.id,
            expense_date: e.expense_date,
            category: e.category,
            description: e.description,
            amount: e.amount,
            payment_method: e.payment_method,
            reference: e.reference || '',
            notes: e.notes || ''
          };
          this.modalExpenseOpen = true;
        },

        async submitExpenseForm() {
          if (!this.expenseForm.description || !this.expenseForm.amount || Number(this.expenseForm.amount) <= 0) {
            this.showToast('Please enter a valid description and amount greater than 0', 'error');
            return;
          }
          this.isSavingExpense = true;
          try {
            const action = this.expenseForm.id ? 'update_expense' : 'add_expense';
            const res = await fetch(`api/reports.php?action=${action}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(this.expenseForm)
            });
            const data = await res.json();
            if (data && data.success) {
              this.modalExpenseOpen = false;
              this.showToast(data.message || 'Expense recorded successfully!');
              await this.loadReports();
            } else {
              this.showToast(data.error || 'Failed to save expense', 'error');
            }
          } catch (e) {
            console.error('Error saving expense:', e);
            this.showToast('Network error saving expense', 'error');
          } finally {
            this.isSavingExpense = false;
          }
        },

        confirmDeleteExpense(e) {
          this.expenseToDelete = e;
          this.modalDeleteExpenseOpen = true;
        },

        async executeDeleteExpense() {
          if (!this.expenseToDelete || !this.expenseToDelete.id) return;
          this.isDeletingExpense = true;
          try {
            const res = await fetch(`api/reports.php?action=delete_expense&id=${encodeURIComponent(this.expenseToDelete.id)}`, {
              method: 'POST'
            });
            const data = await res.json();
            if (data && data.success) {
              this.modalDeleteExpenseOpen = false;
              this.showToast('Expense deleted successfully');
              await this.loadReports();
            } else {
              this.showToast(data.error || 'Failed to delete expense', 'error');
            }
          } catch (e) {
            console.error('Delete expense error:', e);
            this.showToast('Network error deleting expense', 'error');
          } finally {
            this.isDeletingExpense = false;
          }
        },

        viewPaymentDetail(p) {
          this.activePaymentDetail = p;
          this.modalPaymentDetailOpen = true;
        },

        renderReportsCharts() {
          if (typeof Chart === 'undefined') return;
          const chartsData = this.reportsState.summary && this.reportsState.summary.charts;
          if (!chartsData) return;

          const destroyIf = (id) => {
            if (window._crmCharts && window._crmCharts[id]) {
              window._crmCharts[id].destroy();
              delete window._crmCharts[id];
            }
          };
          if (!window._crmCharts) window._crmCharts = {};

          // 1. Revenue Trend Chart (Brand Palette: Deep Burgundy #590907 & Muted Sage #A5A79B)
          const revCtx = document.getElementById('chartRevenueTrend');
          if (revCtx) {
            destroyIf('chartRevenueTrend');
            const months = chartsData.revenue_trend || [];
            window._crmCharts['chartRevenueTrend'] = new Chart(revCtx, {
              type: 'line',
              data: {
                labels: months.map(m => m.label),
                datasets: [
                  {
                    label: 'Revenue Invoiced',
                    data: months.map(m => m.invoiced),
                    borderColor: '#590907',
                    backgroundColor: 'rgba(89, 9, 7, 0.12)',
                    fill: true,
                    tension: 0.35,
                    borderWidth: 2.5,
                    pointRadius: 4,
                    pointBackgroundColor: '#590907'
                  },
                  {
                    label: 'Cash Received',
                    data: months.map(m => m.payments),
                    borderColor: '#A5A79B',
                    backgroundColor: 'rgba(165, 167, 155, 0.20)',
                    fill: true,
                    tension: 0.35,
                    borderWidth: 2.5,
                    pointRadius: 4,
                    pointBackgroundColor: '#8C8E82'
                  }
                ]
              },
              options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'top', labels: { boxWidth: 12, font: { size: 10, weight: 'bold' } } }
                },
                scales: {
                  y: {
                    beginAtZero: true,
                    ticks: {
                      callback: v => '₹' + Number(v).toLocaleString('en-IN'),
                      font: { size: 9 }
                    },
                    grid: { color: 'rgba(229, 226, 216, 0.6)' }
                  },
                  x: { grid: { display: false }, ticks: { font: { size: 9.5 } } }
                }
              }
            });
          }

          // 2. Income vs Expenses Bar Chart (Deep Burgundy & Muted Sage)
          const incExpCtx = document.getElementById('chartIncomeVsExpenses');
          if (incExpCtx) {
            destroyIf('chartIncomeVsExpenses');
            const months = chartsData.revenue_trend || [];
            window._crmCharts['chartIncomeVsExpenses'] = new Chart(incExpCtx, {
              type: 'bar',
              data: {
                labels: months.map(m => m.label),
                datasets: [
                  {
                    label: 'Cash Inflow',
                    data: months.map(m => m.payments),
                    backgroundColor: '#590907',
                    borderRadius: 6
                  },
                  {
                    label: 'Expenses',
                    data: months.map(m => m.expenses),
                    backgroundColor: '#A5A79B',
                    borderRadius: 6
                  }
                ]
              },
              options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'top', labels: { boxWidth: 12, font: { size: 10, weight: 'bold' } } }
                },
                scales: {
                  y: {
                    beginAtZero: true,
                    ticks: { callback: v => '₹' + Number(v).toLocaleString('en-IN'), font: { size: 9 } },
                    grid: { color: 'rgba(229, 226, 216, 0.6)' }
                  },
                  x: { grid: { display: false }, ticks: { font: { size: 9.5 } } }
                }
              }
            });
          }

          // 3. Profit Trend Chart (Deep Burgundy with Warm Cream Beige Fill)
          const profCtx = document.getElementById('chartProfitTrend');
          if (profCtx) {
            destroyIf('chartProfitTrend');
            const months = chartsData.revenue_trend || [];
            window._crmCharts['chartProfitTrend'] = new Chart(profCtx, {
              type: 'line',
              data: {
                labels: months.map(m => m.label),
                datasets: [
                  {
                    label: 'Net Cashflow (Profit)',
                    data: months.map(m => m.net_profit),
                    borderColor: '#590907',
                    backgroundColor: 'rgba(232, 210, 181, 0.35)',
                    fill: true,
                    tension: 0.35,
                    borderWidth: 2.5,
                    pointRadius: 4,
                    pointBackgroundColor: '#75110E'
                  }
                ]
              },
              options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'top', labels: { boxWidth: 12, font: { size: 10, weight: 'bold' } } }
                },
                scales: {
                  y: {
                    ticks: { callback: v => '₹' + Number(v).toLocaleString('en-IN'), font: { size: 9 } },
                    grid: { color: 'rgba(229, 226, 216, 0.6)' }
                  },
                  x: { grid: { display: false }, ticks: { font: { size: 9.5 } } }
                }
              }
            });
          }

          // 4. Payment Status Distribution Donut Chart (Three-Colour Palette)
          const distCtx = document.getElementById('chartStatusDistribution');
          if (distCtx) {
            destroyIf('chartStatusDistribution');
            const dist = chartsData.payment_status_distribution || [];
            const brandDoughnutColors = ['#590907', '#A5A79B', '#E8D2B5', '#75110E', '#8C8E82', '#DCBE97'];
            window._crmCharts['chartStatusDistribution'] = new Chart(distCtx, {
              type: 'doughnut',
              data: {
                labels: dist.map(d => `${d.status} (${this.formatMoney(d.amount)})`),
                datasets: [
                  {
                    data: dist.map(d => d.amount),
                    backgroundColor: dist.map((d, i) => brandDoughnutColors[i % brandDoughnutColors.length]),
                    borderWidth: 2,
                    borderColor: '#ffffff'
                  }
                ]
              },
              options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 9 } } }
                },
                cutout: '68%'
              }
            });
          }

          // 5. Expense Breakdown by Category Chart (Three-Colour Palette)
          const expCtx = document.getElementById('chartExpenseBreakdown');
          if (expCtx) {
            destroyIf('chartExpenseBreakdown');
            const exps = chartsData.expense_breakdown || [];
            const brandExpenseColors = ['#590907', '#E8D2B5', '#A5A79B', '#75110E', '#DCBE97', '#8C8E82'];
            window._crmCharts['chartExpenseBreakdown'] = new Chart(expCtx, {
              type: 'doughnut',
              data: {
                labels: exps.map(e => `${e.category} (${e.percentage}%)`),
                datasets: [
                  {
                    data: exps.map(e => e.amount),
                    backgroundColor: exps.map((e, i) => brandExpenseColors[i % brandExpenseColors.length]),
                    borderWidth: 2,
                    borderColor: '#ffffff'
                  }
                ]
              },
              options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 9 } } }
                },
                cutout: '68%'
              }
            });
          }
        }
      }
    }
  
  </script>
</body>
</html>